t.guides["forever/alliance/30-40/04-stranglethorn-vale"] = (function() return {
		["Back south past Nesingwary: Panthers and Stranglethorn Raptors run in the clearings west of the camp toward the coast; the elder tigers hold the hills south-west."] = "Revenez vers le sud après Nesingwary : les Panthères et les Raptors de Strangleronce courent dans les clairières à l'ouest du camp vers la côte ; les anciens tigres tiennent les collines au sud-ouest.",
		["Both roam the grass around the camp and along the road north."] = "Les deux parcourent l'herbe autour du camp et le long de la route vers le nord.",
		["Careful: Troll camps are close to the tiger area, and trolls can join a fight if you pull carelessly.\nCareful: The raptor nest has young raptors that join the fight when you attack the adults."] = "Attention : des camps de trolls sont proches du territoire des tigres, et les trolls peuvent se joindre au combat si vous attirez sans précaution.\nAttention : le nid des raptors abrite de jeunes raptors qui se joignent au combat quand vous attaquez les adultes.",
		["Down to {area:35}"] = "Descente vers {area:35}",
		["Druid training"] = "Entraînement de druide",
		["Fly to {area:108}"] = "Prendre un vol pour {area:108}",
		["Fly to {area:415}"] = "Prendre un vol pour {area:415}",
		["Fly to {area:42}"] = "Prendre un vol pour {area:42}",
		["Fly to {zone:1453}"] = "Prendre un vol pour {zone:1453}",
		["Follow the main road south the length of the jungle, past the {object:3202} turn-off, to {area:35} on the southern cape."] = "Suivez la route principale vers le sud sur toute la longueur de la jungle, après l'embranchement de {object:3202}, jusqu'à {area:35}, sur le cap sud.",
		["From {zone:1431} take the road south into Stranglethorn; the hunters' tents stand just west of the road past the {area:99} turn-off."] = "Depuis {zone:1431}, prenez la route vers le sud jusqu'à Strangleronce ; les tentes des chasseurs se trouvent juste à l'ouest de la route, après l'embranchement de {area:99}.",
		["Gluggle, a rare murloc on the coast west of camp, drops the {item:4614}: take it if you meet him"] = "Gluggle, un murloc rare sur la côte à l'ouest du camp, laisse tomber le {item:4614} : prenez-le si vous le croisez",
		["Panthers, raptors and elder tigers"] = "Panthères, raptors et anciens tigres",
		["River Crocolisks swim the river by the {area:99}."] = "Les Crocilisques des rivières nagent dans la rivière près de {area:99}.",
		["River crocolisks"] = "Crocilisques des rivières",
		["Stranglethorn Tigers"] = "Tigres de Strangleronce",
		["The adult tigers prowl the hills just south and west of the camp."] = "Les tigres adultes rôdent dans les collines juste au sud et à l'ouest du camp.",
		["The elder tigers come later, on the way back from the {area:99}"] = "Les anciens tigres viendront plus tard, au retour de {area:99}",
		["The haunted island"] = "L'île hantée",
		["Young tigers and panthers"] = "Jeunes tigres et panthères",
		["{area:101}: kill these as you meet them"] = "{area:101} : tuez-les au passage",
		["{area:150} flight master"] = "Maître de vol du {area:150}",
		["{area:301}: kill these as you meet them"] = "{area:301} : tuez-les au passage",
		["{area:35} flight master"] = "Maître de vol de {area:35}",
		["{area:442} flight master"] = "Maître de vol d'{area:442}",
		["{item:190309}, north of {area:413}"] = "{item:190309}, au nord de {area:413}",
		["{item:2634}, from a {object:263} crate"] = "{item:2634}, dans une caisse de {object:263}",
		["{npc:2495}, by the bank; inside"] = "{npc:2495}, près de la banque ; à l'intérieur",
		["{npc:2495}, inside"] = "{npc:2495}, à l'intérieur",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496}, à l'étage de la taverne",
		["{npc:2498}, inside"] = "{npc:2498}, à l'intérieur",
		["{npc:2832}, in the {object:56910}; upstairs"] = "{npc:2832}, dans {object:56910} ; à l'étage",
		["{npc:469}, in the hut"] = "{npc:469}, dans la hutte",
		["{npc:6807}, {object:56910}; upstairs"] = "{npc:6807}, {object:56910} ; à l'étage",
		["{npc:715}, from {zone:1441}"] = "{npc:715}, depuis {zone:1441}",
		["{npc:716} collects the {item:2755}: the pages drop from almost every humanoid in the jungle. Turn the pages into chapters as you go."] = "{npc:716} collectionne {item:2755} : les pages tombent de presque tous les humanoïdes de la jungle. Assemblez les pages en chapitres au fur et à mesure.",
		["{npc:729} and the Lashtail raptors"] = "{npc:729} et les raptors flagellants",
		["{npc:729}, the great tiger, lairs on the hilltop south-west of the camp; Lashtail Raptors run south of it, along the way to {area:35}."] = "{npc:729}, le grand tigre, a son repaire au sommet de la colline au sud-ouest du camp ; les Raptors flagellants courent au sud, sur le chemin de {area:35}.",
		["{npc:737}, in the tavern"] = "{npc:737}, dans la taverne",
		["{npc:737}, upstairs"] = "{npc:737}, à l'étage",
		["{npc:773}, in the tavern; upstairs"] = "{npc:773}, dans la taverne ; à l'étage",
		["{npc:773}, upstairs"] = "{npc:773}, à l'étage",
		["{quest:201}: just look around the hunters' camp"] = "{quest:201} : faites simplement le tour du camp des chasseurs",
		["{zone:1434}: kill these as you meet them"] = "{zone:1434} : tuez-les au passage",
} end)()
t.guides["forever/alliance/30-40/04b-stranglethorn-vale"] = (function() return {
		["\"Sea Wolf\" MacKinley, on the top floor"] = "« Loup de mer » MacKinley, au dernier étage",
		["East to the {area:99}, on the way back to Nesingwary's camp."] = "À l'est vers {area:99}, sur le chemin du retour au camp de Nesingwary.",
		["East to {area:101}: Herod's records lie in a hut on its west side."] = "À l'est vers {area:101} : les registres d'Herod se trouvent dans une hutte du côté ouest.",
		["For Archmage Ansirem in {zone:1416}"] = "Pour l'archimage Ansirem dans {zone:1416}",
		["For characters of 35 to 36, but several quests here are level 37-41: on purpose, for their experience. {quest:205}'s Skullsplitter trolls are 39-42, so pull them one at a time."] = "Pour les personnages de niveau 35 à 36, mais plusieurs quêtes ici sont de niveau 37-41 : c'est voulu, pour leur expérience. Les trolls Skullsplitter de {quest:205} sont de niveau 39-42 : attirez-les un par un.",
		["Level 36"] = "Niveau 36",
		["North along the coast to the ruins on the hill: the last two tablets lie there. Pick up Green Hills pages as they drop."] = "Au nord le long de la côte vers les ruines sur la colline : les deux dernières tablettes s'y trouvent. Ramassez les pages des Collines verdoyantes à mesure qu'elles tombent.",
		["Skullsplitter trolls"] = "Trolls Skullsplitter",
		["Snapjaw Crocolisks"] = "Crocilisques Gueule d'acier",
		["South from the compound to {area:37}: the Venture Co. Geologists in the camps on its shore carry the Tumbled Crystals, and the Shadowmaw Panthers prowl stealthed in the jungle south and east of it."] = "Au sud du campement, vers {area:37} : les Géologues de la KapitalRisk dans les camps sur ses rives portent les Cristaux réduits, et les Panthères Ombregueule rôdent camouflées dans la jungle au sud et à l'est.",
		["The Skullsplitter trolls hold the ruins east of the road between Nesingwary and {object:3202}."] = "Les trolls Skullsplitter tiennent les ruines à l'est de la route entre Nesingwary et {object:3202}.",
		["The haunted island lies just off the shore west of the second tablet: the Lesser Water Elementals rise from the water around it."] = "L'île hantée se trouve juste au large de la côte, à l'ouest de la deuxième tablette : les Élémentaires d'eau inférieurs surgissent de l'eau tout autour.",
		["The jungle ruins"] = "Les ruines de la jungle",
		["The {area:102}"] = "{area:102}",
		["West across the jungle to the troll ruins: each holds one stone tablet of the troll legends, the first two in the ruins south-west of Nesingwary's camp, the last two on the hill in the north-west."] = "À l'ouest à travers la jungle vers les ruines trolls : chacune abrite une tablette de pierre des légendes trolls, les deux premières dans les ruines au sud-ouest du camp de Nesingwary, les deux dernières sur la colline au nord-ouest.",
		["{item:2006}: {object:58}; underwater"] = "{item:2006} : {object:58} ; sous l'eau",
		["{npc:2495}, inside"] = "{npc:2495}, à l'intérieur",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496}, à l'étage de la taverne",
		["{npc:2498}, inside"] = "{npc:2498}, à l'intérieur",
		["{npc:718}: the Shadowmaw Panthers prowl around {area:37}, after {area:101}"] = "{npc:718} : les Panthères Ombregueule rôdent autour de {area:37}, après {area:101}",
		["{npc:770}: for {npc:773} in {area:35}"] = "{npc:770} : pour {npc:773} à {area:35}",
		["{npc:773}, upstairs"] = "{npc:773}, à l'étage",
		["{npc:773}, upstairs: this optional quest needs four {item:4278}. Mine Lesser Bloodstone Deposits in {zone:1417} with {skill:186} 75, or buy the ore at the Auction House or ask a miner friend. The kobolds do not drop it; skip this quest if you cannot get the ore."] = "{npc:773}, à l'étage : cette quête facultative demande quatre {item:4278}. Minez des Gisements de pierre de sang inférieure dans {zone:1417} avec {skill:186} 75, ou achetez le minerai à l'hôtel des ventes, ou demandez à un ami mineur. Les kobolds ne le lâchent pas ; passez cette quête si vous ne pouvez pas obtenir le minerai.",
		["{npc:941}, below ground"] = "{npc:941}, sous terre",
		["{object:287}, upstairs"] = "{object:287}, à l'étage",
		["{object:288}, below ground"] = "{object:288}, sous terre",
		["{zone:1453} flight master"] = "Maître de vol de {zone:1453}",
} end)()
t.guides["forever/alliance/30-40/05-arathi-highlands"] = (function() return {
		["A {npc:2434} lurks stealthed on the edge of {area:271}, and few players find him. If you spot him, kill him and read the contract he carries: {npc:2276} takes it. Don't wait for him: the rest of this step doesn't need him."] = "Un {npc:2434} rôde, camouflé, en bordure d'{area:271}, et peu de joueurs le trouvent. Si vous le repérez, tuez-le et lisez le contrat qu'il porte : {npc:2276} le prend. Ne l'attendez pas : le reste de cette étape n'a pas besoin de lui.",
		["Back west through {zone:1430} to {area:42}."] = "Retournez vers l'ouest par le {zone:1430} jusqu'à {area:42}.",
		["Below ground"] = "Sous terre",
		["Careful: Syndicate Spies and Assassins can be stealthed. Assassins also poison you.\nCareful: About three stealthed Syndicate mobs are inside {npc:2320}'s house. {npc:2320} does not join when they are pulled, and a ranged attack through the doorway brings him out by himself."] = "Attention : les Espions et les Assassins du Syndicat peuvent être camouflés. Les Assassins vous empoisonnent aussi.\nAttention : environ trois membres du Syndicat camouflés se trouvent dans la maison de {npc:2320}. {npc:2320} ne se joint pas au combat quand vous les attirez, et une attaque à distance par la porte le fait sortir seul.",
		["Crushridge ogres"] = "Ogres Cassecrête",
		["Each key lies at one of the Highlands' standing-stone circles: east of the shards, near {area:320} and in the west. The {object:2702} stands west of {area:320}.\nCareful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East."] = "Chaque clé se trouve dans l'un des cercles de pierres levées des Hautes-terres : à l'est des éclats, près du {area:320} et à l'ouest. {object:2702} se dresse à l'ouest du {area:320}.\nAttention : chaque pierre centrale est gardée par environ trois élémentaires proches du niveau 39 qui attaquent ensemble si vous cliquez sur la pierre sans les avoir éliminés : Exilés ardents à l'ouest, Exilés foudroyants au cercle extérieur, Exilés grimpeurs à l'est.",
		["East along the road to the {area:76}. {npc:256028} mobs drop the crystals. {quest:1392} walks a long path through the ruins: if you meet him, kill him, his cudgel starts a quest for {npc:1776}. Don't wait for him."] = "Suivez la route vers l'est jusqu'à {area:76}. Les ennemis {npc:256028} laissent tomber les cristaux. {quest:1392} parcourt un long chemin à travers les ruines : si vous le croisez, tuez-le, son gourdin lance une quête pour {npc:1776}. Ne l'attendez pas.",
		["East from {quest:681} across the north of the Highlands; the shards glitter on the hill by the {area:333}, north of {area:314}."] = "À l'est de {quest:681}, traversez le nord des Hautes-terres ; les éclats scintillent sur la colline près de {area:333}, au nord de {area:314}.",
		["Fly to {area:271}"] = "Prenez un vol pour {area:271}",
		["Fly to {area:42}"] = "Prenez un vol pour {area:42}",
		["Fly to {zone:1453}"] = "Prenez un vol pour {zone:1453}",
		["Follow the road east out of {area:287} over {area:1057} to {area:320}."] = "Suivez la route vers l'est hors de {area:287}, par {area:1057}, jusqu'à {area:320}.",
		["Follow the road north out of {area:271} into the mountains. Mountain lions roam the slopes; the Syndicate in {area:280} wear the signet rings. {npc:2306} (40) turns up in one spot at a time: the cellar of {area:280}'s inn, or one of the Syndicate tent camps in the uplands north and north-west of the village."] = "Suivez la route vers le nord en sortant d'{area:271} jusque dans les montagnes. Des lions des montagnes parcourent les pentes ; les membres du Syndicat de {area:280} portent les chevalières. {npc:2306} (40) apparaît à un seul endroit à la fois : la cave de l'auberge d'{area:280}, ou l'un des camps de tentes du Syndicat sur les hauteurs au nord et au nord-ouest du village.",
		["Follow the road north to the draenei of the {area:657}."] = "Suivez la route vers le nord jusqu'aux draeneï du {area:657}.",
		["For {npc:1440} in {zone:1453}: keep it"] = "Pour {npc:1440} à {zone:1453} : gardez-la",
		["For {npc:2487} in {area:35}: keep it"] = "Pour {npc:2487} à {area:35} : gardez-la",
		["For {npc:2542} in {area:35}: keep it"] = "Pour {npc:2542} à {area:35} : gardez-la",
		["For {npc:2711} in {area:271}"] = "Pour {npc:2711} à {area:271}",
		["From {zone:1455} take the tunnel east through {zone:1426} into {zone:1432} and follow the road to {area:144}."] = "Depuis {zone:1455}, prenez le tunnel vers l'est à travers {zone:1426} jusqu'au {zone:1432} et suivez la route jusqu'à {area:144}.",
		["Inside"] = "À l'intérieur",
		["North-west out of the Witherbark valley; {npc:2712} and {npc:2713} camp in the hills just north of {area:314}."] = "Sortez de la vallée des Witherbark par le nord-ouest ; {npc:2712} et {npc:2713} campent dans les collines juste au nord de {area:314}.",
		["Only if Gluggle gave you the pendant in Stranglethorn"] = "Seulement si Gluggle vous a donné le pendentif à Strangleronce",
		["Phizzlethorpe"] = "Phizzlethorpe",
		["South from the {object:2691}, past {area:314}, to {area:317} in the hills: the Witch Doctors stand among the huts and the Shadow Hunters guard the far end of the valley. Every troll can drop a tusk."] = "Au sud de {object:2691}, au-delà de {area:314}, jusqu'à {area:317} dans les collines : les Sorciers-docteurs se tiennent parmi les huttes et les Chasseurs des ombres gardent le fond de la vallée. Chaque troll peut laisser tomber une défense.",
		["South-east along the loch to the dig site."] = "Longez le loch vers le sud-est jusqu'au site de fouilles.",
		["South-west to the Kirin Tor camp on the lake shore west of {area:279}, just over the border into {zone:1421}: the {npc:269127} stands there. Archmage Ansirem stands south-east of it, by the dome."] = "Allez au sud-ouest jusqu'au camp du Kirin Tor sur la rive du lac, à l'ouest de {area:279}, juste après la frontière de {zone:1421} : {npc:269127} s'y tient. L'archimage Ansirem se tient au sud-est, près du dôme.",
		["Stay with {npc:2713} while she sneaks into {area:314} and back; Horde orcs jump you on the way.\nCareful: Orcs that drop to low health run away. {npc:2713} follows them and can pull more mobs, so kill or slow runners fast."] = "Restez avec {npc:2713} pendant qu'elle se faufile dans {area:314} et en revient ; des orcs de la Horde vous attaquent en chemin.\nAttention : les orcs qui tombent à peu de vie s'enfuient. {npc:2713} les suit et peut attirer d'autres monstres : tuez ou ralentissez vite les fuyards.",
		["The Drywhisker kobolds dig in the gorge east of {area:321} (Horde); skirt the town to the north. They drop the Motes of Myzrael, not Krazek's ore. Lesser Bloodstone Deposits need {skill:186} 75: mine four ore, buy them at the Auction House, or ask a miner friend. The ore goal is optional; continue with Myzrael if you cannot get it. Careful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them."] = "Les kobolds Sèche-moustache creusent dans la gorge à l'est de {area:321} (Horde) ; contournez la ville par le nord. Ils lâchent les Poussières de Myzrael, pas le minerai de Krazek. Les Gisements de pierre de sang inférieure demandent {skill:186} 75 : minez quatre minerais, achetez-les à l'hôtel des ventes ou demandez à un ami mineur. L'objectif du minerai est facultatif ; continuez avec Myzrael si vous ne pouvez pas l'obtenir. Attention : chaque type de kobold s'enfuit chercher de l'aide quand sa vie est basse (les Kobolds à 30 %, les Géomètres et les Terrassiers à 15 %), ce qui peut en attirer d'autres.",
		["The courier walks the road from {area:314} west across the Highlands, as far as about 24,45, and back, with two guards: the arrow follows the road west until you meet him. Pull them off the road."] = "Le coursier parcourt la route depuis {area:314} vers l'ouest à travers les Hautes-terres, jusqu'à environ 24,45, puis revient, accompagné de deux gardes : la flèche suit la route vers l'ouest jusqu'à ce que vous le croisiez. Attirez-les hors de la route.",
		["The shards lie at the far end of {area:318}."] = "Les éclats se trouvent au fond de {area:318}.",
		["The two wrecks lie in the bay west of the cove. The charts and logs are inside them; the gems lie on the sea floor around them. Daggerspine naga swim the whole bay."] = "Les deux épaves reposent dans la baie à l'ouest de la crique. Les cartes et les journaux sont à l'intérieur ; les gemmes gisent au fond de la mer autour. Des nagas Daguéchine nagent dans toute la baie.",
		["The western swamp"] = "Le marais occidental",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:2417} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back.\n{npc:2417} walks from the arrow north-east through the ruins to about 40,47 and back: if he isn't at the arrow, follow his path."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:2417} est un élite de niveau 40 : la plupart des classes le battent seules au niveau 42, mais vous aurez peut-être besoin d'aide. Passez-le si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres.\n{npc:2417} marche depuis la flèche vers le nord-est à travers les ruines jusqu'à environ 40,47, puis revient : s'il n'est pas à la flèche, suivez son trajet.",
		["Tram to {zone:1455}"] = "Tram pour {zone:1455}",
		["Young crocolisks, Sorrow Spinners and Swamp Jaguars all roam the swamp around the road."] = "Jeunes crocilisques, Tisseuses des pleurs et Jaguars du marécage parcourent tous le marais autour de la route.",
		["from {quest:1392}: he walks a path through the ruins"] = "sur {quest:1392} : il parcourt un chemin à travers les ruines",
		["{area:280}: kill these as you meet them"] = "{area:280} : tuez-les au passage",
		["{area:281}: kill these as you meet them"] = "{area:281} : tuez-les au passage",
		["{area:318}: kill these as you meet them"] = "{area:318} : tuez-les au passage",
		["{area:320} flight master"] = "Maître de vol du {area:320}",
		["{area:328}: kill these as you meet them"] = "{area:328} : tuez-les au passage",
		["{area:35} flight master"] = "Maître de vol de {area:35}",
		["{item:3658}: Crushridge ogres"] = "{item:3658} : ogres Cassecrête",
		["{item:3659}: the {object:1760}; inside"] = "{item:3659} : {object:1760} ; à l'intérieur",
		["{item:4492}; underwater"] = "{item:4492} ; sous l'eau",
		["{item:4525}; below ground"] = "{item:4525} ; sous terre",
		["{item:5040}; below ground"] = "{item:5040} ; sous terre",
		["{npc:1141}, {area:17203} road"] = "{npc:1141}, route de {area:17203}",
		["{npc:12336}, Cathedral of Light"] = "{npc:12336}, Cathedral of Light",
		["{npc:1440}, the Royal Library in the keep"] = "{npc:1440}, la Royal Library du donjon",
		["{npc:1470}, below ground"] = "{npc:1470}, sous terre",
		["{npc:185335}, at the same circle"] = "{npc:185335}, sur le même cercle",
		["{npc:217412}: three critters to catch in Arathi, {zone:1443} and Stranglethorn"] = "{npc:217412} : trois bestioles à capturer en Arathi, en {zone:1443} et à Strangleronce",
		["{npc:2276}, inside"] = "{npc:2276}, à l'intérieur",
		["{npc:2434}, if you spot him"] = "{npc:2434}, si vous le repérez",
		["{npc:2595}, underwater"] = "{npc:2595}, sous l'eau",
		["{npc:2596}, underwater"] = "{npc:2596}, sous l'eau",
		["{npc:2712} and {npc:2713}"] = "{npc:2712} et {npc:2713}",
		["{npc:2713}'s errand"] = "La mission de {npc:2713}",
		["{npc:5391} is caged at the north end of the sanctuary. Free him and keep him alive on the walk out; his strongbox waits by the road afterwards."] = "{npc:5391} est enfermé dans une cage au nord du sanctuaire. Libérez-le et gardez-le en vie pendant la sortie ; son coffre vous attend ensuite au bord de la route.",
		["{npc:6122} binds the incubus to you"] = "{npc:6122} vous lie l'incube",
		["{npc:6122} waits in the {object:2164}'s cellar, in the {object:2101}. Use the {item:6913} at the summoning circle there and defeat the succubus it calls. If you took {quest:65602}, hand him the {item:190309} too, place it at the same circle and defeat the incubus."] = "{npc:6122} attend dans la cave de {object:2164}, dans {object:2101}. Utilisez le {item:6913} sur le cercle d'invocation et vainquez la succube invoquée. Si vous avez pris {quest:65602}, donnez-lui aussi la {item:190309}, placez-la sur le même cercle et vainquez l'incube.",
		["{object:2707}; underwater"] = "{object:2707} ; sous l'eau",
		["{object:2708}; underwater"] = "{object:2708} ; sous l'eau",
		["{object:2709}; underwater"] = "{object:2709} ; sous l'eau",
		["{object:2710}; underwater"] = "{object:2710} ; sous l'eau",
		["{quest:65602}, if you took it"] = "{quest:65602}, si vous l'avez prise",
		["{zone:1455} flight master"] = "Maître de vol de {zone:1455}",
} end)()
t.guides["forever/alliance/30-40/06-badlands"] = (function() return {
		["A {npc:217590} crawls about the {area:596}: catch one with the tool from {npc:217412}'s Entomology Starter Kit."] = "Un {npc:217590} rampe dans {area:596} : attrapez-en un avec l'outil du kit d'entomologiste débutant de {npc:217412}.",
		["Fly to Theramore"] = "Volez jusqu'à Theramore",
		["Fly to {area:150}"] = "Prendre un vol pour {area:150}",
		["Follow the road north to {area:608}: {npc:5396} stands at its south end, {npc:5638} in the middle, {npc:1182} to the north."] = "Suivez la route vers le nord jusqu'à {area:608} : {npc:5396} se tient à l'extrémité sud, {npc:5638} au milieu, {npc:1182} au nord.",
		["Follow the road south to {area:2407}."] = "Suivez la route vers le sud jusqu'à {area:2407}.",
		["Follow the road west across the north of {zone:1443} to the ruins of {area:2405}. {npc:11863}'s tower stands on the hill there, on the way to the wreck."] = "Suivez la route vers l'ouest à travers le nord de {zone:1443} jusqu'aux ruines d'{area:2405}. La tour d'{npc:11863} se dresse sur la colline, sur le chemin de l'épave.",
		["Head back west to the road and follow it south out of {zone:1432} through the pass into the {zone:1418}. {npc:2910} and {npc:2860} camp side by side at the dig."] = "Retournez vers l'ouest jusqu'à la route et suivez-la vers le sud hors du {zone:1432}, par le col, jusqu'aux {zone:1418}. {npc:2910} et {npc:2860} campent côte à côte au site de fouilles.",
		["Head north-east to the abandoned dig; the supply crate lies there among the Dustbelcher ogres."] = "Allez au nord-est jusqu'au site de fouilles abandonné ; la caisse de ravitaillement s'y trouve, parmi les ogres Crache-poussières.",
		["Head north-east to the dwarven ruins in the north of the {zone:1418}; the chest sits among the Shadowforge dwarves. {npc:2745} nearby is elite: give him room."] = "Allez au nord-est jusqu'aux ruines naines au nord des {zone:1418} ; le coffre se trouve parmi les nains Ombreforge. {npc:2745}, tout près, est un élite : gardez vos distances.",
		["Head south to {area:345}."] = "Allez au sud jusqu'à {area:345}.",
		["Head west into the {area:1878}; {npc:2921} works by his machines in the middle of it."] = "Allez vers l'ouest dans {area:1878} ; {npc:2921} travaille près de ses machines, au milieu.",
		["Into {zone:1418}"] = "Vers les {zone:1418}",
		["Lesser Rock Elementals"] = "Elémentaires de roche inférieurs ({npc:2735})",
		["Maraudine centaurs"] = "Centaures maraudine",
		["Rackmore's chest lies just south-east of the {object:177673}."] = "Le coffre de Rackmore se trouve juste au sud-est de la {object:177673}.",
		["Rock Elementals"] = "Elémentaires de roche",
		["Ryedol's next errand goes into {area:1517}: skip it."] = "La mission suivante de Ryedol mène à {area:1517} : passez-la.",
		["The Maraudine centaurs hold the {area:607} west of the graveyard; every kind drops the totems."] = "Les centaures maraudine tiennent {area:607}, à l'ouest du cimetière ; tous lâchent les totems.",
		["The Rock Elementals roam south-east of {npc:2921}; Giant Buzzards and Elder Crag Coyotes share the plain to their west."] = "Les Elémentaires de roche ({npc:92}) errent au sud-est de {npc:2921} ; Busards géants ({npc:2831}) et Anciens coyotes des rochers ({npc:2729}) se partagent la plaine à leur ouest.",
		["The Shadowforge dwarves camp just north of the digsite; the crumpled map lies among their tents. Tunnelers and Darkweavers carry Ryedol's pick. Crag Coyotes roam the slopes around it."] = "Les nains Ombreforge campent juste au nord du site de fouilles ; la carte froissée se trouve parmi leurs tentes. Les Tunneliers Ombreforge et les Tisseurs d'ombre Ombreforge portent la pioche de Ryedol. Des Coyotes des rochers parcourent les pentes alentour.",
		["The Slitherblade naga hold the north-west coast north of {npc:11863}'s tower; Karnitol's satchel lies on the sea floor off it, and any naga can drop Rackmore's golden key. Swim out to {area:2406} off the far northern tip and use the {item:15766} on the {object:177673}: {npc:12369} (38) rises; kill him for the {quest:6027}."] = "Les nagas Ondulame tiennent la côte nord-ouest au nord de la tour d'{npc:11863} ; la sacoche de Karnitol gît au fond de la mer, au large, et n'importe quel naga peut lâcher la clé en or de Rackmore. Nagez jusqu'à {area:2406}, au large de la pointe nord, et utilisez la {item:15766} sur la {object:177673} : {npc:12369} (38) surgit ; tuez-le pour le {quest:6027}.",
		["The battered skeleton lies just east of the ogres, at the edge of the Stonevault trogg camp; the Bonesnappers and Shamans around it drop the flakes. Theldurin sits by the ruined camp further south."] = "Le squelette abîmé se trouve juste à l'est des ogres, en bordure du camp des troggs Cavepierre ; les Briseurs d'os et les Chamans alentour lâchent les éclats. Theldurin est assis près du camp en ruine plus au sud.",
		["The clams lie on Stranglethorn's north-west coast, in the next guide: keep it"] = "Les palourdes se trouvent sur la côte nord-ouest de Strangleronce, dans le guide suivant : gardez-la",
		["The demons gather at the {area:602} in southern {zone:1443}: felhounds (Mana Eaters, Mage and Ley Hunters), Nether Maidens and Sisters, and Doomwarder Captains around the pit.\nCareful: Most of the mobs here walk patrol routes, so you can easily pull extra mobs."] = "Les démons se rassemblent au {area:602}, dans le sud de {zone:1443} : des chiens corrompus (Mange-mana, Chasseurs de mages et Chasseurs Ley), des Vierges du néant et des Sœurs du néant, et des Capitaines de la Garde funeste autour de la fosse.\nAttention : la plupart des monstres ici suivent des trajets de patrouille : vous pouvez facilement attirer des monstres en plus.",
		["The excavation crate"] = "La caisse d'excavation",
		["The next guide starts in Theramore."] = "Le guide suivant commence à Theramore.",
		["The wrecked ship's chest lies just south-west of {npc:11863}'s tower."] = "Le coffre du navire échoué se trouve juste au sud-ouest de la tour d'{npc:11863}.",
		["The {area:2657}"] = "{area:2657}",
		["The {object:126260}"] = "{object:126260}",
		["Theramore flight master"] = "Maître de vol de Theramore",
		["To {area:2101}"] = "Vers {area:2101}",
		["Undead Ravagers roam the bone fields south of the Magram village, east of the Coven; at the far south-east, use the {item:15848} to draw the Magrami Spectres."] = "Des Ravageurs morts-vivants parcourent les champs d'ossements au sud du Village des Magram, à l'est du Convent de Mannoroc ; à l'extrême sud-est, utilisez la {item:15848} pour attirer les Spectres magrami.",
		["Underwater"] = "Sous l'eau",
		["escort {npc:12277} back toward the graveyard"] = "escortez {npc:12277} jusqu'au cimetière",
		["for {npc:2786} in {zone:1455}: keep it"] = "pour {npc:2786} à {zone:1455} : gardez-la",
		["for {npc:3980} in {area:271}: keep it"] = "pour {npc:3980} à {area:271} : gardez-la",
		["for {npc:5637} in {zone:1455}: keep it"] = "pour {npc:5637} à {zone:1455} : gardez-la",
		["{area:144} flight master"] = "Maître de vol de {area:144}",
		["{area:345}: kill these as you meet them"] = "{area:345} : tuez-les au passage",
		["{area:346}: kill these as you meet them"] = "{area:346} : tuez-les au passage",
		["{area:598}: kill these as you meet them"] = "{area:598} : tuez-les au passage",
		["{item:15766}, on the {object:177673}"] = "{item:15766}, sur la {object:177673}",
		["{item:15881}, from the Slitherblade naga"] = "{item:15881}, sur les nagas Ondulame",
		["{item:4631}; below ground"] = "{item:4631} ; sous terre",
		["{npc:12277} is held in the centaur camp west of the graveyard. Free her and keep her alive on the walk out; she stops by the graveyard.\nCareful: The scripted groups are linked and only appear during the escort, so you cannot clear them in advance or pull them one at a time. Clearing the normal centaurs on the path before you start does help."] = "{npc:12277} est retenue dans le camp de centaures à l'ouest du cimetière. Libérez-la et gardez-la en vie pendant la sortie ; elle s'arrête près du cimetière.\nAttention : les groupes scriptés sont liés et n'apparaissent que pendant l'escorte : vous ne pouvez ni les éliminer à l'avance ni les attirer un par un. Éliminer les centaures normaux sur le chemin avant de commencer aide quand même.",
		["{npc:1470}, in the inn; below ground"] = "{npc:1470}, dans l'auberge ; sous terre",
		["{npc:2920}, beside {npc:2921}"] = "{npc:2920}, à côté de {npc:2921}",
		["{npc:4618} and {npc:2817} camp together in the {area:1877}, in the middle of the {zone:1418}."] = "{npc:4618} et {npc:2817} campent ensemble dans {area:1877}, au milieu des {zone:1418}.",
		["{npc:5638}, if 30-40/02 didn't take it: the wreck lies below {npc:11863}'s tower"] = "{npc:5638}, si 30-40/02 ne l'a pas prise : l'épave se trouve sous la tour d'{npc:11863}",
		["{npc:6019} stands at the edge of the {area:596}, south-west of {area:2407}; {object:176751} lie among the skeletons."] = "{npc:6019} se tient en bordure de {area:596}, au sud-ouest de {area:2407} ; des {object:176751} gisent parmi les squelettes.",
		["{object:177787} lies beside {object:35251}. His silver key drops from the Drysnap crabs around the wreck; the golden one comes from the Slitherblade naga on the north-west coast, next."] = "{object:177787} se trouve à côté de {object:35251}. Sa clé en argent est lâchée par les crabes Claquesec autour de l'épave ; la clé en or provient des nagas Ondulame de la côte nord-ouest, ensuite.",
} end)()
t.guides["forever/alliance/40-50/01-stranglethorn-vale"] = (function() return {
		["\"Sea Wolf\" MacKinley, on the top floor"] = "« Loup de mer » MacKinley, au dernier étage",
		["\"Stinky\" Ignatz"] = "Ignatz \"Puant\"",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. Skyborne learn it from {npc:265756}, the stablemaster and riding trainer at the {area:17684} in {area:16638} on Zephras Isle, who also sells the Galestriders: the skyboat to the isle leaves the north side of {area:279} about every five minutes. Collectibles, Mounts · Level 40 lists the Galestriders."] = "Au niveau 40, avec 100 pièces d'or, vous pouvez apprendre la monte, ce qui vous donne une monture. Les Éolides l'apprennent auprès de {npc:265756}, maître des écuries et maître de monte aux {area:17684} à {area:16638}, sur l'île de Zéphras, qui vend aussi les Trotteurs des trombes : l'aéronef pour l'île part du côté nord de {area:279} toutes les cinq minutes environ. Objets de collection, Montures · Niveau 40 liste les Trotteurs des trombes.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4732} teaches Humans at {area:88} in eastern {zone:1429}, beside {npc:384}'s horses. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "Au niveau 40, avec 100 po, vous pouvez apprendre à monter, et l'apprendre vous donne une monture. {npc:4732} l'enseigne aux humains à {area:88}, dans l'est de {zone:1429}, à côté des chevaux de {npc:384}. Forever permet peut-être à toutes les races d'apprendre auprès de n'importe quel maître de monte (non confirmé). Collection, Montures · Niveau 40 liste toutes les couleurs.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4753} teaches Night Elves in {zone:1457}, beside {npc:4730}'s sabers: the boat from {area:17203} to {area:442}, then the flight to {area:702}. Forever may let any race learn from any riding trainer (unconfirmed), such as {npc:4732} at {area:88} in {zone:1429}. Collectibles, Mounts · Level 40 lists every colour."] = "Au niveau 40, avec 100 po, vous pouvez apprendre à monter, et l'apprendre vous donne une monture. {npc:4753} l'enseigne aux elfes de la nuit à {zone:1457}, à côté des sabres de {npc:4730} : le bateau de {area:17203} pour {area:442}, puis le vol pour {area:702}. Forever permet peut-être à toutes les races d'apprendre auprès de n'importe quel maître de monte (non confirmé), comme {npc:4732} à {area:88}, dans {zone:1429}. Collection, Montures · Niveau 40 liste toutes les couleurs.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4772} teaches Dwarves at {area:803}, east of {area:131} on the road to {zone:1432}, beside {npc:1261}'s rams. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "Au niveau 40, avec 100 po, vous pouvez apprendre à monter, et l'apprendre vous donne une monture. {npc:4772} l'enseigne aux nains à {area:803}, à l'est de {area:131} sur la route du {zone:1432}, à côté des béliers de {npc:1261}. Forever permet peut-être à toutes les races d'apprendre auprès de n'importe quel maître de monte (non confirmé). Collection, Montures · Niveau 40 liste toutes les couleurs.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:7954} teaches Gnomes at {area:189}, just east of {area:131}, beside {npc:7955}'s mechanostriders. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "Au niveau 40, avec 100 po, vous pouvez apprendre à monter, et l'apprendre vous donne une monture. {npc:7954} l'enseigne aux gnomes à {area:189}, juste à l'est de {area:131}, à côté des mécanotrotteurs de {npc:7955}. Forever permet peut-être à toutes les races d'apprendre auprès de n'importe quel maître de monte (non confirmé). Collection, Montures · Niveau 40 liste toutes les couleurs.",
		["Bloodsail camp"] = "Camp de la Voile sanglante",
		["Boat to {area:150}"] = "Bateau pour {area:150}",
		["Boat to {area:17203}"] = "Bateau pour {area:17203}",
		["Boat to {area:35}"] = "Bateau pour {area:35}",
		["Cortello's scroll"] = "Le parchemin de Cortello",
		["Defeat the challengers and {npc:6238}"] = "Vainquez les adversaires et {npc:6238}",
		["Every Bloodsail drops Snuff and one of them carries {npc:2493}'s eye; the Swashbucklers walk the shore just north of town. The charts and orders lie in the pirate camp on the {area:43}, south of {area:35}."] = "Tous les pirates de la Voile sanglante laissent tomber du Tabac à priser et l'un d'eux porte l'œil de {npc:2493} ; les Bretteurs arpentent le rivage juste au nord de la ville. Les cartes et les ordres se trouvent dans le camp pirate de {area:43}, au sud de {area:35}.",
		["Every Zanzil follower can drop the mixture; {npc:2537} walks the south of the camp."] = "Tout disciple de Zanzil peut laisser tomber le mélange ; {npc:2537} arpente le sud du camp.",
		["Fly to {area:144}"] = "Prendre un vol pour {area:144}",
		["Fly to {area:35}"] = "Prendre un vol pour {area:35}",
		["Fly to {area:42}"] = "Prendre un vol pour {area:42}",
		["Fly to {area:442}"] = "Prendre un vol pour {area:442}",
		["Fly to {area:702}"] = "Prendre un vol pour {area:702}",
		["Fly to {zone:1453}"] = "Prendre un vol pour {zone:1453}",
		["Follow the road east back to Theramore. The officers are in {area:514}."] = "Suivez la route vers l'est pour revenir à Theramore. Les officiers sont à {area:514}.",
		["Follow the road north-west out of Theramore to the watchtower at {area:503}. Mudrock Burrowers roam the marsh around it.\n{npc:4967} waits at the foot of the tower: once you have looked around, hand the quest in to him there, not in Theramore."] = "Suivez la route vers le nord-ouest en sortant de Theramore jusqu'à la tour de guet de {area:503}. Des Creuseuses Rochefange parcourent le marais alentour.\n{npc:4967} attend au pied de la tour : une fois que vous avez regardé autour, rendez-lui la quête sur place, pas à Theramore.",
		["Gorilla hills"] = "Collines des gorilles",
		["Hand in the fangs and stay: three waves of gorillas come, {npc:1514} last. Fight at full health."] = "Rendez les crocs et restez : trois vagues de gorilles arrivent, {npc:1514} en dernier. Combattez avec toute votre vie.",
		["Inside"] = "À l'intérieur",
		["Jungle Stalkers"] = "Traqueurs de la jungle",
		["Leave town by the tunnel and follow the coast north; the letter lies in the Bloodsail camp on the beach, where \"Pretty Boy\" Duncan walks."] = "Quittez la ville par le tunnel et suivez la côte vers le nord ; la lettre se trouve dans le camp de la Voile sanglante sur la plage, où se promène Duncan \"le Beau garçon\".",
		["Level 42.46"] = "Niveau 42.46",
		["MacKinley's next task sends you after elite ogres: skip it."] = "La tâche suivante de MacKinley vous envoie contre des ogres élites : passez-la.",
		["Mirefin murlocs"] = "Murlocs Aileron boueux",
		["Naga Explorers"] = "Explorateurs nagas",
		["On the ride north to {area:392}, {area:720} lies off the {area:391} south of the town: wade over the sand bar shallows. {npc:6236} sends four challengers and then {npc:6238} (level 33) at you, one at a time."] = "En remontant vers {area:392}, {area:720} se trouve au large de {area:391}, au sud de la ville : traversez à gué les hauts-fonds du banc de sable. {npc:6236} vous envoie quatre adversaires puis {npc:6238} (niveau 33), un à la fois.",
		["On the top floor"] = "Au dernier étage",
		["Optional: Cortello's scroll lies inside one of the three Bloodsail ships anchored off the coast just south of {area:35}, on a middle or lower deck, and is not always on the same ship. Their crews are 42-45 pirates: clear your way from the edge, one at a time, and leave the captains (45-48), whom the route comes back for at 48."] = "Facultatif : le parchemin de Cortello se trouve dans l'un des trois navires de la Voile sanglante ancrés au large, juste au sud de {area:35}, sur un pont intermédiaire ou inférieur, et pas toujours sur le même navire. Leurs équipages sont des pirates de niveau 42-45 : frayez-vous un chemin depuis le bord, un à la fois, et laissez les capitaines (45-48), pour lesquels l'itinéraire revient au niveau 48.",
		["Paladin: {quest:1661}"] = "Paladin : {quest:1661}",
		["Ride back down to town; Shaky stands at the tunnel mouth."] = "Redescendez en ville ; Phillippe le Chancelant se tient à l'entrée du tunnel.",
		["Ride east; the Tangled Horrors along the way also drop the essays. Search the edge of the {area:74}, where the temple's ruins break the water."] = "Chevauchez vers l'est ; les Horreurs enchevêtrées en chemin laissent aussi tomber les essais. Fouillez le bord de {area:74}, là où les ruines du temple émergent de l'eau.",
		["Ride inland to the Mistvale gorilla hills. Elder Mistvale Gorillas drop the giblets; {npc:1449} sits among them."] = "Chevauchez vers l'intérieur jusqu'aux collines des gorilles de Valbrume. Les Anciens gorilles de Valbrume laissent tomber les abats ; {npc:1449} est assis parmi eux.",
		["Ride north to the hills west of the road. {npc:2535} and {npc:2536} stand together just north of Zanzil's village."] = "Chevauchez vers le nord jusqu'aux collines à l'ouest de la route. {npc:2535} et {npc:2536} se tiennent ensemble juste au nord du village de Zanzil.",
		["Ride north-west from the mine to the bay on the north-west coast. The Giant Clams lie on its floor and hold the pearls; {npc:2624} swims among them and drops the {item:4034}."] = "Chevauchez vers le nord-ouest depuis la mine jusqu'à la baie de la côte nord-ouest. Les Palourdes géantes reposent au fond et contiennent les perles ; {npc:2624} nage parmi elles et laisse tomber la {item:4034}.",
		["Ride south out of {zone:1432} through the pass into the {zone:1418}; {npc:2860} camps at the dig."] = "Partez au sud hors du {zone:1432}, par le col, jusqu'aux {zone:1418} ; {npc:2860} campe sur le site de fouilles.",
		["Ride south to the giant's hut in the middle of the marsh."] = "Chevauchez vers le sud jusqu'à la hutte du géant au milieu du marais.",
		["Riding and Galestriders: {npc:265756}, at the {area:17684} in {area:16638} on Zephras Isle."] = "Monte et Trotteurs des trombes : {npc:265756}, aux {area:17684} à {area:16638}, sur l'île de Zéphras.",
		["Riding at 40"] = "Monte au niveau 40",
		["Seahorn's next errand goes back to Arathi: skip it."] = "La course suivante de Seahorn ramène en Arathi : passez-la.",
		["Skyboat to Zephras Isle: the north side of {area:279}, about every five minutes."] = "Aéronef pour l'île de Zéphras : côté nord de {area:279}, toutes les cinq minutes environ.",
		["Stinky waits west of the manor, in the marsh below {area:504}. Lead him to his Bogbean leaves and keep the swamp creatures off him."] = "Puant attend à l'ouest du manoir, dans le marais sous {area:504}. Menez-le à ses feuilles de fève des marais et tenez les créatures du marais à l'écart.",
		["Stormwind City"] = "Cité de Hurlevent",
		["The Darkmist spiders nest around the cavern in the north-west of the marsh; every spider drops eyes.\nCareful: Darkmist Lurkers move about stealthed and use poison once in combat. The spiders stand close together, so adds are common; pulling single targets from the outer edge cuts down on them."] = "Les araignées Sombrebrume nichent autour de la caverne au nord-ouest du marais ; toutes lâchent des yeux.\nAttention : les Rôdeuses de Sombrebrume se déplacent camouflées et empoisonnent une fois en combat. Les araignées se tiennent près les unes des autres, les renforts sont donc fréquents ; attirer des cibles isolées depuis la bordure les limite.",
		["The Mirefin murlocs crowd the north coast past {area:497}."] = "Les murlocs Aileron boueux se pressent sur la côte nord après {area:497}.",
		["The Skullsplitter trolls hold the ruins just east of the mine; any of them can drop tusks, their panthers always do.\nFollow the road north-east to the Venture Co. camp at the {area:310}; the miners, surveyors and foremen drop the crystals.\nCareful: Stealthed Shadowmaw Panthers and Stranglethorn Tigresses roam the area around the camp."] = "Les trolls Fendcrâne tiennent les ruines juste à l'est de la mine ; n'importe lequel peut lâcher des défenses, leurs panthères en lâchent toujours.\nSuivez la route vers le nord-est jusqu'au camp de la KapitalRisk à la {area:310} ; les mineurs, les géomètres et les contremaîtres lâchent les cristaux.\nAttention : des Panthères Ombregueule camouflées et des Tigresses de Strangleronce rôdent autour du camp.",
		["The burned inn stands on the road west, toward the {zone:1413}; the guard's badge lies in the ashes."] = "L'auberge incendiée se trouve sur la route vers l'ouest, en direction de {zone:1413} ; l'insigne du garde est dans les cendres.",
		["The deserters camp south of the road, west of {npc:4503}'s hut."] = "Les déserteurs campent au sud de la route, à l'ouest de la hutte de {npc:4503}.",
		["The driftwood washes up along the eastern shore."] = "Le bois flotté s'échoue le long de la rive est.",
		["The naga comb the beaches north of the Bloodsail camp; they drop the reeds."] = "Les nagas fouillent les plages au nord du camp de la Voile sanglante ; ils laissent tomber les roseaux.",
		["The north-west coast"] = "La côte nord-ouest",
		["The scroll lies in the marsh north of Biggs. The Swampwalkers north of it can drop Khadgar's essays."] = "Le parchemin se trouve dans le marais au nord de Biggs. Les Maraistreurs au nord peuvent laisser tomber les essais de Khadgar.",
		["The sunken temple"] = "Le temple englouti",
		["Theramore"] = "Theramore",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:728} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:728} est un élite de niveau 40 : la plupart des classes le battent seules au niveau 42, mais vous aurez peut-être besoin d'aide. Passez-le si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:730} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:730} est un élite de niveau 43 : la plupart des classes le battent seules au niveau 45, mais vous aurez peut-être besoin d'aide. Passez-le si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:731} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nCareful: Tigers and stealthed shadowmaw panthers roam close to him. Clear them before you pull him. When he is pulled, {npc:731} calls for help from creatures within 20 yd."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:731} est un élite de niveau 43 : la plupart des classes le battent seules au niveau 45, mais vous aurez peut-être besoin d'aide. Passez-le si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres.\nAttention : des tigres et des panthères Ombregueule camouflées rôdent près de lui. Éliminez-les avant de l'attirer. Quand vous l'attirez, {npc:731} appelle à l'aide les créatures dans un rayon de 20 m.",
		["Tram to {zone:1455}"] = "Tram pour {zone:1455}",
		["Unbagwa's ritual"] = "Le rituel d'Unbagwa",
		["Upstairs"] = "À l'étage",
		["Warlock: {quest:3631}"] = "Démoniste : {quest:3631}",
		["Zanzil's village"] = "Le village de Zanzil",
		["for Stoley in {zone:1446}: keep it; on the top floor"] = "pour Stoley à {zone:1446} : gardez-le ; au dernier étage",
		["for the flight back to {npc:6251} at 43"] = "pour le vol de retour vers {npc:6251} au niveau 43",
		["for the {zone:1435} later"] = "pour {zone:1435}, plus tard",
		["for {area:1438}: keep it"] = "pour {area:1438} : gardez-la",
		["for {npc:2616} in Theramore: keep it"] = "pour {npc:2616} à Theramore : gardez-la",
		["for {npc:5635} at {area:348}: keep it"] = "pour {npc:5635} à {area:348} : gardez-la",
		["for {npc:770} at the {area:99}, on the northern loop"] = "pour {npc:770} à {area:99}, lors de la boucle nord",
		["grind on {npc:667}"] = "tuez en boucle : {npc:667}",
		["grind on {npc:690}"] = "tuez en boucle : {npc:690}",
		["grind on {npc:766}"] = "tuez en boucle : {npc:766}",
		["only if you carry a {item:3853} (a blacksmith's craft)"] = "seulement si vous avez une {item:3853} (fabriquée par un forgeron)",
		["with the spices from Theramore"] = "avec les épices de Theramore",
		["{area:103}: kill these as you meet them"] = "{area:103} : tuez-les au passage",
		["{area:150} flight master"] = "Maître de vol du {area:150}",
		["{area:35} flight master"] = "Maître de vol de {area:35}",
		["{area:42} flight master"] = "Maître de vol de {area:42}",
		["{area:43}: kill these as you meet them"] = "{area:43} : tuez-les au passage",
		["{area:442} flight master"] = "Maître de vol d'{area:442}",
		["{area:702} flight master"] = "Maître de vol du {area:702}",
		["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}, pour « Œil-des-marais » Jarl",
		["{item:4611}; underwater"] = "{item:4611} ; sous l'eau",
		["{npc:1141} cooks in the {object:2169}; {npc:5384} is in the {object:28027}."] = "{npc:1141} cuisine au {object:2169} ; {npc:5384} est dans {object:28027}.",
		["{npc:1261}: other colours, 20g"] = "{npc:1261} : autres couleurs, 20 po",
		["{npc:1440}, the Royal Library in {object:2117}"] = "{npc:1440}, la bibliothèque royale de {object:2117}",
		["{npc:1449}, inside {area:1742}"] = "{npc:1449}, à l'intérieur de {area:1742}",
		["{npc:1470}, below ground"] = "{npc:1470}, sous terre",
		["{npc:217412}: {quest:93176}, from 30-40/05-arathi-highlands"] = "{npc:217412} : {quest:93176}, depuis 30-40/05-arathi-highlands",
		["{npc:2487}, top floor"] = "{npc:2487}, dernier étage",
		["{npc:2488}, on the top floor"] = "{npc:2488}, au dernier étage",
		["{npc:2498}'s next Zanzil errand starts in {zone:1441}: skip it."] = "La course suivante de {npc:2498} concernant Zanzil commence à {zone:1441} : passez-la.",
		["{npc:2535} and {npc:2536}"] = "{npc:2535} et {npc:2536}",
		["{npc:2542}, upstairs"] = "{npc:2542}, à l'étage",
		["{npc:2624} swims off the north-west coast, on the northern loop"] = "{npc:2624} nage au large de la côte nord-ouest, lors de la boucle nord",
		["{npc:2888} camps by himself in {area:1898}, south-east of the digsite."] = "{npc:2888} campe seul dans {area:1898}, au sud-est du site de fouilles.",
		["{npc:384}: other colours, 20g"] = "{npc:384} : autres couleurs, 20 po",
		["{npc:461}, in the {object:2164}: {npc:6251} in {area:392} takes it at the end of the next guide"] = "{npc:461}, à {object:2164} : {npc:6251} à {area:392} la prend à la fin du guide suivant",
		["{npc:4730}: other colours, 20g"] = "{npc:4730} : autres couleurs, 20 po",
		["{npc:4794}, inside"] = "{npc:4794}, à l'intérieur",
		["{npc:4944}, on the top floor"] = "{npc:4944}, au dernier étage",
		["{npc:4948}, on the top floor"] = "{npc:4948}, au dernier étage",
		["{npc:4966} holds the tower with a few deserters. He turns on you: beat him until he yields.\nCareful: Hendel has two guards who join the fight when he turns hostile. The guards flee once he surrenders.\n{npc:4967} and {npc:4968} wait beside the tower: once he yields, hand in to both on the spot."] = "{npc:4966} tient la tour avec quelques déserteurs. Il se retourne contre vous : battez-le jusqu'à ce qu'il se rende.\nAttention : Hendel a deux gardes qui se joignent au combat quand il devient hostile. Les gardes s'enfuient dès qu'il se rend.\n{npc:4967} et {npc:4968} attendent à côté de la tour : une fois qu'il s'est rendu, rendez les quêtes aux deux sur place.",
		["{npc:4967}, at the tower"] = "{npc:4967}, à la tour",
		["{npc:4968}, on the top floor"] = "{npc:4968}, au dernier étage",
		["{npc:5476} stands by the road junction in the west of the swamp."] = "{npc:5476} se tient près du carrefour à l'ouest du marais.",
		["{npc:6171}, in the Cathedral of Light"] = "{npc:6171}, dans la cathédrale de la Lumière",
		["{npc:6236} offers The Windwatcher next (1791): the Whirlwind weapon chain, with an elite at the end, is in the Warrior class guide Whirlwind Weapon."] = "{npc:6236} propose ensuite La Vigie des vents (1791) : la suite de l'arme Tourbillon, avec un élite à la fin, se trouve dans le guide de classe Guerrier Arme Tourbillon.",
		["{npc:737}, upstairs"] = "{npc:737}, à l'étage",
		["{npc:773}, upstairs"] = "{npc:773}, à l'étage",
		["{npc:773}: for {quest:2864} in {zone:1446}, keep it"] = "{npc:773} : pour {quest:2864} en {zone:1446}, gardez-la",
		["{npc:7955}: other colours, 20g"] = "{npc:7955} : autres couleurs, 20 po",
		["{quest:1260} stands near the inn; {npc:4897}, a trade supplier a few steps south, sells the spices Jarl wants."] = "{quest:1260} se tient près de l'auberge ; {npc:4897}, une marchande à quelques pas au sud, vend les épices que veut Jarl.",
		["{quest:1260}, inside"] = "{quest:1260}, à l'intérieur",
		["{zone:1453} flight master"] = "Maître de vol de {zone:1453}",
		["{zone:1453} has no shaman trainer"] = "{zone:1453} n'a pas de maître des chamans",
		["{zone:1455} flight master"] = "Maître de vol de {zone:1455}",
} end)()
t.guides["forever/alliance/40-50/02-badlands"] = (function() return {
		["Fly to {area:150}"] = "Prendre un vol pour {area:150}",
		["Fly to {area:271}"] = "Prendre un vol pour {area:271}",
		["Inside {area:498}"] = "À l'intérieur de {area:498}",
		["Into {zone:1418}"] = "Vers les {zone:1418}",
		["Into {zone:1432}"] = "Vers le {zone:1432}",
		["Raleigh's next errand is in the {area:796}: skip it."] = "La mission suivante de Raleigh se déroule au {area:796} : passez-la.",
		["Ride back east to {area:1898}."] = "Revenez à l'est jusqu'à {area:1898}.",
		["Ride back north to Ironband's camp."] = "Revenez vers le nord jusqu'aux Excavations de Baguefer.",
		["Ride north-east out of {area:271} on the road into the {zone:1425}; {area:348} sits just past the border. {npc:5635} holds court at the top, {quest:1450} tends the aviary and {npc:7884} stands by the inn."] = "Partez au nord-est hors d'{area:271} par la route des {zone:1425} ; {area:348} se trouve juste après la frontière. {npc:5635} tient sa cour au sommet, {quest:1450} s'occupe de la volière et {npc:7884} se tient près de l'auberge.",
		["Talonaxe's next task waits for a later {zone:1425} guide."] = "La tâche suivante de Talonaxe attend un guide des {zone:1425} ultérieur.",
		["The Scalding Whelps nest in the ravine east of {npc:2888}; leave the Scorched Guardians (elite) alone. The {item:4612} drops rarely: take it if it comes while you grind."] = "Les Dragonnets flamboyants nichent dans le ravin à l'est de {npc:2888} ; laissez tranquilles les Gardiens des terres brûlées (élites). Le {item:4612} tombe rarement : prenez-le s'il tombe pendant que vous tuez des monstres.",
		["The first two cages stand together in the Witherbark village south of {npc:5634}; the third is in the next village to the east. Every Witherbark troll can drop a necklace."] = "Les deux premières cages se trouvent ensemble dans le village de Fanécorce au sud de {npc:5634} ; la troisième est dans le village suivant, à l'est. Chaque troll Witherbark peut lâcher un collier.",
		["The {area:1517} dig"] = "Les fouilles d'{area:1517}",
		["Theramore"] = "Theramore",
		["Theramore flight master"] = "Maître de vol de Theramore",
		["Warlock: {quest:3631}"] = "Démoniste : {quest:3631}",
		["Witherbark villages"] = "Villages de Fanécorce",
		["{area:144} flight master"] = "Maître de vol de {area:144}",
		["{area:348} flight master"] = "Maître de vol du {area:348}",
		["{item:8047}; below ground"] = "{item:8047} ; sous terre",
		["{npc:1470}, below ground"] = "{npc:1470}, sous terre",
		["{npc:2616} stands on the docks where the boat lands."] = "{npc:2616} se tient sur les quais où accoste le bateau.",
		["{npc:2817}'s next quest pays no experience: skip it."] = "La quête suivante de {npc:2817} ne rapporte pas d'expérience : passez-la.",
		["{npc:2888}'s next task is an elite hunt: skip it."] = "La tâche suivante de {npc:2888} est une chasse élite : passez-la.",
		["{npc:2944} does not stay at {area:342}: he walks a long loop around the {zone:1418} with his guards, from the camp in the west along the south of the zone to about 61,69, north to about 49,49 and back west to the camp. The arrow follows his loop west from here until you meet him."] = "{npc:2944} ne reste pas au {area:342} : il parcourt une longue boucle à travers les {zone:1418} avec ses gardes, du camp à l'ouest le long du sud de la zone jusque vers 61,69, puis au nord jusque vers 49,49 et de retour à l'ouest jusqu'au camp. La flèche suit sa boucle vers l'ouest à partir d'ici jusqu'à ce que vous le rencontriez.",
		["{npc:3980}, upstairs"] = "{npc:3980}, à l'étage",
		["{npc:4794}, inside"] = "{npc:4794}, à l'intérieur",
		["{npc:4944}, on the top floor"] = "{npc:4944}, au dernier étage",
		["{npc:4968}, on the top floor"] = "{npc:4968}, au dernier étage",
		["{npc:5634} camps on the road east of {area:348}."] = "{npc:5634} campe sur la route à l'est de {area:348}.",
		["{npc:5636}, beside the flight master at the top; inside"] = "{npc:5636}, à côté du maître de vol au sommet ; à l'intérieur",
		["{npc:7744}; below ground"] = "{npc:7744} ; sous terre",
		["{npc:7884}, inside"] = "{npc:7884}, à l'intérieur",
		["{object:2743}; below ground"] = "{object:2743} ; sous terre",
		["{quest:1450}, inside"] = "{quest:1450}, à l'intérieur",
} end)()
t.guides["forever/alliance/40-50/03-feralas"] = (function() return {
		["Back to the {area:1117}. Every Hatecrest naga there can drop scales."] = "Retournez aux {area:1117}. Tous les nagas Hainecrête qui s'y trouvent peuvent laisser tomber des écailles.",
		["Boat to {area:1108}"] = "Bateau pour {area:1108}",
		["Boat to {area:1116}"] = "Bateau pour {area:1116}",
		["Feathermoon flight master"] = "Maître de vol de Plumelune",
		["Fly to {area:489}"] = "Prendre un vol pour {area:489}",
		["Gordunni ogres"] = "Les ogres Gordunni",
		["Grimtotem camp"] = "Le camp Totem sinistre",
		["Grimtotem tauren"] = "Taurens Totem sinistre",
		["Grind to 45"] = "Farmer jusqu'au niveau 45",
		["Hatecrest naga"] = "Nagas Hainecrête",
		["Into {zone:1413}"] = "Vers les {zone:1413}",
		["Ride back to the {area:1108}; the goblin stands by the dock."] = "Revenez à la {area:1108} ; le gobelin se tient près du quai.",
		["Ride east to the Gordunni camp in the hills south-east of the yeti valley: Warlocks and Shaman hold the camp, Brutes wander the slopes around it and further north."] = "Chevauchez vers l'est jusqu'au camp Gordunni dans les collines au sud-est de la vallée des yétis : des Démonistes Gordunni et des Chamans Gordunni tiennent le camp, des Brutes Gordunni errent sur les pentes alentour et plus au nord.",
		["Ride north into the yeti valley. Every Feral Scar yeti can drop a thick hide; {npc:5346} (level 48) prowls the middle."] = "Chevauchez vers le nord dans la vallée des yétis. Tout Yéti Griffe farouche peut laisser tomber une peau épaisse ; {npc:5346} (niveau 48) rôde au milieu.",
		["Ride north-east to the night elf outpost on the {zone:1441} border."] = "Chevauchez au nord-est jusqu'à l'avant-poste elfe de la nuit à la frontière de {zone:1441}.",
		["Ride south-east to the Woodpaw gnolls; the courier's backpacks lie in their southern camp, and a parcel inside them starts a delivery to {area:489}. The Zukk'ash hive is just south: fight down to the pod that holds Raschal, free him and keep him alive on the way out."] = "Chevauchez au sud-est jusqu'aux gnolls Griffebois ; les sacs à dos du messager se trouvent dans leur camp sud, et un colis à l'intérieur lance une livraison pour {area:489}. La ruche Zukk'ash est juste au sud : descendez jusqu'à l'Alvéole de Zukk'ash qui retient Raschal, libérez-le et gardez-le en vie à la sortie.",
		["Shore Striders, Deep Striders and Wave Striders (elite giants) wade along the coast north of the dock: zap one with {item:18904} and kill the shrunken giant. Sea Elementals and Sea Sprays drift in the same surf."] = "Des Marcheurs des rivages, des Marcheurs des profondeurs et des Marcheurs des vagues (géants élites) arpentent la côte au nord du quai : frappez-en un avec l'{item:18904} et tuez le géant rétréci. Des Elémentaires marins et des Embruns dérivent dans les mêmes vagues.",
		["Take the boat to the {area:1108} and follow the shore south to the wrecked row boat on the beach."] = "Prenez le bateau pour la {area:1108} et suivez la rive vers le sud jusqu'à la barque échouée sur la plage.",
		["The courier's boat"] = "Le bateau du messager",
		["The {area:1121} is the island just south of {area:1120}: swim over. Hatecrest Serpent Guards and Sorceresses hold it; {npc:8136} (level 47) waits in the cave at its south end. Pull his guards first."] = "L'{area:1121} est l'île juste au sud de l'{area:1120} : traversez à la nage. Des Gardes-serpents Hainecrête et des Ensorceleuses la tiennent ; {npc:8136} (niveau 47) attend dans la grotte à son extrémité sud. Attirez d'abord ses gardes.",
		["Walk south along the island to the naga ruins; the gazebo stands among them."] = "Marchez vers le sud sur l'île jusqu'aux ruines nagas ; le belvédère se trouve parmi elles.",
		["for Tyrande in {zone:1457}: the route takes you there at 47"] = "pour Tyrande Whisperwind à {zone:1457} : l'itinéraire vous y mène au niveau 47",
		["grind on {npc:5292} at {area:1105}, {zone:1444}"] = "farmez les {npc:5292} au {area:1105}, {zone:1444}",
		["{area:1108}: kill these as you meet them"] = "{area:1108} : tuez-les au passage",
		["{area:1136}: kill these as you meet them"] = "{area:1136} : tuez-les au passage",
		["{area:489} flight master"] = "Maître de vol de {area:489}",
		["{item:11463}, from the backpacks"] = "{item:11463}, dans les sacs à dos",
		["{item:9248}; below ground"] = "{item:9248} ; sous terre",
		["{npc:14637}'s refills are level 55: skip them."] = "Les recharges de {npc:14637} Fandazzle sont de niveau 55 : passez-les.",
		["{npc:3936} then asks you to carry news to {zone:1457}: skip it, {area:976} sends you there instead."] = "{npc:3936} vous demande ensuite de porter des nouvelles à {zone:1457} : passez, {area:976} vous y envoie à la place.",
		["{npc:3936}, beside him"] = "{npc:3936}, à côté de lui",
		["{npc:4048} walks around {area:489}: look inside the circle on the map"] = "{npc:4048} se promène autour de {area:489} : cherchez dans le cercle sur la carte",
		["{npc:7764}: his answer waits in {area:702}, later"] = "{npc:7764} : sa réponse attend au {area:702}, plus tard",
		["{npc:7877}, at the top of the stronghold"] = "{npc:7877}, au sommet du bastion",
		["{npc:7879}, upstairs"] = "{npc:7879}, à l'étage",
		["{npc:8136} waits for the end of the mainland loop."] = "{npc:8136} attend la fin de la boucle sur le continent.",
		["{object:164954}, inside"] = "{object:164954}, à l'intérieur",
} end)()
t.guides["forever/alliance/40-50/04-tanaris"] = (function() return {
		["Boat to {area:150}"] = "Bateau pour {area:150}",
		["Careful: Thieves cast Disarm. Rogues stay hidden with Sneak. Assassins use Execute when your health is at 20% or lower."] = "Attention : les Larrons lancent Désarmement. Les Voleurs restent cachés grâce à Camouflage. Les Assassins utilisent Exécution quand votre vie est à 20 % ou moins.",
		["Fly to Theramore"] = "Vol pour Theramore",
		["Fly to {area:348}"] = "Prendre un vol pour {area:348}",
		["Follow the coast south to the pirate cove. Southsea pirates crowd the beach and the boats: work along the edge and pull one at a time. {npc:7883} stands on the far side; {npc:7881}'s stolen cargo lies in the camp.\nCareful: Two or three pirates stand with {npc:7883}, and many more pirates from the town join the fight once it starts."] = "Suivez la côte vers le sud jusqu'à la crique des pirates. Les pirates des Mers du Sud envahissent la plage et les bateaux : progressez par le bord et attirez-les un par un. {npc:7883} se tient de l'autre côté ; la cargaison volée de {npc:7881} se trouve dans le camp.\nAttention : deux ou trois pirates se tiennent avec {npc:7883}, et beaucoup d'autres pirates de la ville se joignent au combat dès qu'il commence.",
		["Gives the {item:8585}"] = "Donne le {item:8585}",
		["Pool by {area:979}"] = "Bassin près de {area:979}",
		["Ride back west toward {area:976}. The Wastewander bandits and thieves hold the dunes on the way; any of them can carry a water pouch.\nCareful: Wastewander Rogues (level 43-44) move stealthed, so they can approach unseen."] = "Retournez vers l'ouest en direction de {area:976}. Les bandits et les larrons Bat-le-désert tiennent les dunes sur le chemin ; n'importe lequel peut porter une outre d'eau.\nAttention : les Voleurs Bat-le-désert (niveau 43-44) se déplacent camouflés et peuvent donc approcher sans être vus.",
		["Ride east across the dunes to the goblin harbour on the north-east coast."] = "Chevauchez vers l'est à travers les dunes jusqu'au Port Gentepression sur la côte nord-est.",
		["Ride north-west to the Centipaar hive in the dunes. Any Centipaar can drop insect parts.\nCareful: Centipaar Swarmers cast {npc:4196} both in and out of combat, which brings small adds that interrupt you."] = "Chevauchez vers le nord-ouest jusqu'à la ruche Centipaar dans les dunes. N'importe quel Centipaar peut lâcher des morceaux d'insecte.\nAttention : les Traînards Centipaar lancent {npc:4196} en combat comme hors combat, ce qui fait venir de petits renforts qui vous interrompent.",
		["Ride north-west to the Sandfury troll camp at {area:979}. Use the {item:8584} at the edge of its pool; the trolls stand close, so pull the nearest first."] = "Chevauchez au nord-ouest jusqu'au camp des trolls Sandfury à {area:979}. Utilisez le {item:8584} au bord de son bassin ; les trolls sont proches, attirez d'abord le plus près.",
		["Ride south into {quest:3362}. The Dew Collectors drop the glands; only some are full, so keep the Laden one. Gnarled Thistleshrubs and Rootshapers share the valley. The Thistleshrubs are 48-50, above you: pull one at a time.\nCareful: The other thistleshrub mobs in the area are level 49-50 and wander a lot, so you can easily pull extra mobs."] = "Chevauchez vers le sud jusqu'à {quest:3362}. Les Chardonniers collecteurs de rosée lâchent les glandes ; seules certaines sont remplies, gardez donc celles-là. Les Chardonniers noueux et les Chardonniers taille-racines partagent la vallée. Les Chardonniers noueux sont de niveau 48-50, au-dessus du vôtre : attirez-les un par un.\nAttention : les autres chardonniers du secteur sont de niveau 49-50 et errent beaucoup : vous pouvez facilement en attirer d'autres.",
		["Ride south past the {area:1938} to the {area:981}, the Hazzali tunnels; Scrimshank's gear lies deep inside.\nCareful: One bug guards the gear. Many bugs patrol the tunnels, some of them level 50, so fights often pull extra adds."] = "Chevauchez vers le sud après le {area:1938} jusqu'au {area:981}, les tunnels Hazzali ; l'équipement de Scrimshank se trouve tout au fond.\nAttention : un insecte garde l'équipement. De nombreux insectes patrouillent dans les tunnels, certains de niveau 50, et les combats attirent souvent des renforts.",
		["Ride south to the dig camp at the {area:1938}. {npc:7771} hands you a detector helm: wear it to see the {quest:3161} mounds, which lie thick in the sand around the camp and south-west toward the ogres."] = "Chevauchez vers le sud jusqu'au camp de fouilles du {area:1938}. {npc:7771} Rivetseeker vous remet un casque détecteur : portez-le pour voir les monticules de {quest:3161}, nombreux dans le sable autour du camp et au sud-ouest vers les ogres.",
		["Ride south-east off the {area:439} into {zone:1446}. {area:976} is just inside the border."] = "Chevauchez au sud-est hors des {area:439} jusqu'en {zone:1446}. {area:976} est juste après la frontière.",
		["Ride south-east to {area:985}. {npc:7847} stands in the middle of the southern Wastewander camp: clear around him first.\nCareful: Two stealthed Wastewander Rogues travel with him wherever he goes. At his spawn camp, two shadowmages and their minions are close enough to join a fight with him. Out by the towers you can fight him without them."] = "Chevauchez vers le sud-est jusqu'au {area:985}. {npc:7847} se tient au milieu du camp sud des Bat-le-désert : faites d'abord le ménage autour de lui.\nAttention : deux Voleurs Bat-le-désert camouflés l'accompagnent partout où il va. À son camp d'apparition, deux mages de l'ombre et leurs serviteurs sont assez proches pour se joindre au combat. Près des tours, vous pouvez l'affronter sans eux.",
		["Ride south-west to the ogre compound. Brutes and Enforcers (46-48) fill it; {npc:12046} (49) stands in the middle with guards around him: clear them first."] = "Chevauchez au sud-ouest jusqu'à la Base des Cognedunes. Des Brutes Cognedune et des Massacreurs Cognedune (46-48) la remplissent ; {npc:12046} (49) se tient au centre entouré de gardes : éliminez-les d'abord.",
		["The Wanted poster beside him"] = "L'affiche Avis de recherche à côté de lui",
		["The little turtle {npc:5955} hides at the north end of the valley. Lead him home to his wife {npc:6015}, by the water just east of {area:977}: he walks slowly and the desert's beasts go for him, so keep him alive."] = "La petite tortue {npc:5955} se cache à l'extrémité nord de la vallée. Ramenez-la chez sa femme {npc:6015}, au bord de l'eau juste à l'est de {area:977} : elle avance lentement et les bêtes du désert l'attaquent, gardez-la en vie.",
		["The pool by {area:979}"] = "Le bassin près de {area:979}",
		["The same poster: {npc:7847} comes much later, after {area:976}"] = "La même affiche : {npc:7847} vient bien plus tard, après {area:976}",
		["The tougher Wastewander rogues, shadow mages and assassins camp south-east of {area:976}, south of the bandits. Leave {npc:7847} in the middle of the southern camp for later.\nCareful: Wastewander Rogues keep Sneak up while out of combat, so hidden rogues can join a fight you start at a camp."] = "Les voleurs, mages de l'ombre et assassins Bat-le-désert plus coriaces campent au sud-est de {area:976}, au sud des bandits. Laissez {npc:7847}, au milieu du camp sud, pour plus tard.\nAttention : les Voleurs Bat-le-désert restent camouflés hors combat : des voleurs cachés peuvent se joindre à un combat que vous engagez dans un camp.",
		["The {area:1938}"] = "{area:1938}",
		["The {area:2240} lies on the {area:439} in south-east {zone:1441}: {npc:4454} is in the gnomes' camp beside the track, Zamek by the goblin camp."] = "{area:2240} se trouve sur les {area:439}, dans le sud-est des {zone:1441} : {npc:4454} est dans le camp des gnomes à côté de la piste, Zamek près du camp gobelin.",
		["Underwater"] = "Sous l'eau",
		["for {zone:1457}: the route takes you there at 47"] = "pour {zone:1457} : l'itinéraire vous y mène au niveau 47",
		["grind on {npc:5474}"] = "tuez en boucle : {npc:5474}",
		["{area:1336}: kill these as you meet them"] = "{area:1336} : tuez-les au passage",
		["{area:150} flight master"] = "Maître de vol du {area:150}",
		["{area:1937}: kill these as you meet them"] = "{area:1937} : tuez-les au passage",
		["{area:976} flight master"] = "Maître de vol de {area:976}",
		["{item:8593}; below ground"] = "{item:8593} ; sous terre",
		["{npc:12046}, below ground"] = "{npc:12046}, sous terre",
		["{npc:5594}, inside"] = "{npc:5594}, à l'intérieur",
		["{npc:5955}'s escort"] = "L'escorte de {npc:5955}",
		["{npc:7407}, by the water tower"] = "{npc:7407}, près du château d'eau",
		["{npc:7408}, next to him"] = "{npc:7408}, à côté de lui",
		["{npc:7763}: his crate goes to {area:702}, later"] = "{npc:7763} : sa caisse va au {area:702}, plus tard",
		["{npc:7881}, in the port's tavern; inside"] = "{npc:7881}, dans la taverne du port ; à l'intérieur",
		["{npc:7881}, inside"] = "{npc:7881}, à l'intérieur",
		["{npc:7882}, inside"] = "{npc:7882}, à l'intérieur",
		["{npc:7884}, inside"] = "{npc:7884}, à l'intérieur",
		["{quest:2864}, north side of town"] = "{quest:2864}, au nord de la ville",
		["{quest:2873}; upstairs"] = "{quest:2873} ; à l'étage",
		["{quest:3362}: kill these as you meet them"] = "{quest:3362} : tuez-les au passage",
} end)()
t.guides["forever/alliance/40-50/05-the-hinterlands"] = (function() return {
		["\"Sea Wolf\" MacKinley, on the top floor"] = "« Loup de mer » MacKinley, au dernier étage",
		["Boat to {area:17203}"] = "Bateau pour {area:17203}",
		["Class trainer"] = "Maître de classe",
		["Fly to {area:144}"] = "Prendre un vol pour {area:144}",
		["Fly to {area:150}"] = "Prendre un vol pour {area:150}",
		["Fly to {area:1537}"] = "Prendre un vol pour {area:1537}",
		["Fly to {area:35}"] = "Prendre un vol pour {area:35}",
		["Fly to {area:442}"] = "Prendre un vol pour {area:442}",
		["Fly to {area:69}"] = "Prendre un vol pour {area:69}",
		["Inside"] = "À l'intérieur",
		["Portal to {zone:1438}"] = "Portail vers {zone:1438}",
		["Ride north to {area:351} in the middle of the {zone:1425}. Green Sludges and Jade Oozes crawl all around it.\nCareful: Panthers move around the area in stealth."] = "Chevauchez vers le nord jusqu'à {area:351}, au milieu des {zone:1425}. Des Limaces vertes et des Limons de jade rampent tout autour.\nAttention : des panthères se déplacent camouflées dans le secteur.",
		["Ride on east along the road to the keep first: the {item:6091} expires an hour after {area:42}, and the bloodmages' beasts take longer than that."] = "Continuez d'abord vers l'est par la route jusqu'au donjon : la {item:6091} expire une heure après {area:42}, et les bêtes des mages de sang prennent plus de temps que ça.",
		["Ride south-east to the {area:355}, the stepped Vilebranch temple in the south of the {zone:1425}, and climb to the top. Qiaga and {npc:8636} (elite, 50) stand up there: touch the top and come straight back down.\nCareful: Elite trolls guard the top platform, including {npc:7996} and {npc:8636}, along with several Vilebranch Soothsayers. The soothsayers cast spells and are linked to the rest of the group."] = "Chevauchez vers le sud-est jusqu'à l'{area:355}, le temple à degrés des Vilebranch au sud des {zone:1425}, et montez au sommet. Qiaga et {npc:8636} (élite, niveau 50) s'y tiennent : touchez le sommet et redescendez aussitôt.\nAttention : des trolls élites gardent la plate-forme du sommet, dont {npc:7996} et {npc:8636}, ainsi que plusieurs Devins Vilebranch. Les devins lancent des sorts et sont liés au reste du groupe.",
		["Ride west: Starving Snickerfangs roam the dry hills just south of the bloodmages' camp; Scorpok Stingers (level 50) scuttle across the middle of the north. {npc:5982} vultures circle over all of it. Pull one at a time.\nAshmane Boars and Redstone Basilisks share the slopes south-west of the keep. Keep clear of the Helboars further south: they are level 52.\nCareful: Scorpok Stingers use {spell:5416}; {npc:8301} adds Knockdown."] = "Chevauchez vers l'ouest : des Raillecrocs affamées parcourent les collines arides juste au sud du camp des mages de sang ; des Aiguillonneurs scorpoks (niveau 50) trottinent au milieu du nord. Des {npc:5982} (des vautours) tournoient au-dessus de tout cela. Attirez-les un par un.\nDes Sangliers cendrés et des Basilics Rougepierre partagent les pentes au sud-ouest du donjon. Évitez les Sangliers infernaux plus au sud : ils sont de niveau 52.\nAttention : les Aiguillonneurs scorpoks utilisent {spell:5416} ; {npc:8301} y ajoute Renversement.",
		["Step through the portal into {zone:1457}. The Temple of the Moon is in the south of the city."] = "Franchissez le portail vers {zone:1457}. Le Temple de la Lune se trouve au sud de la cité.",
		["Temple of the Moon"] = "Temple de la Lune",
		["The Bloodsail captains"] = "Les capitaines de la Voile sanglante",
		["The bloodmages"] = "Les mages de sang",
		["The bloodmages' camp is the first stop beside the road into the {zone:1419}, north-west of {area:1438}."] = "Le camp des mages de sang est la première étape au bord de la route qui entre dans les {zone:1419}, au nord-ouest du {area:1438}.",
		["The bloodmages' second tier pays for the same parts with a buff item and no experience: skip it."] = "Le second palier des mages de sang paie les mêmes morceaux avec un objet d'amélioration et sans expérience : passez-le.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:1494} (level 52 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:1494} (élite de niveau 52) demande un groupe de 2. Passez-le si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:8552} needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {quest:8552} demande un groupe de 2. Passez-la si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres.",
		["Tram to {zone:1453}"] = "Tram pour {zone:1453}",
		["for {quest:2990} at {area:1438}, later"] = "pour {quest:2990} au {area:1438}, plus tard",
		["the book on her table"] = "le livre sur sa table",
		["the soil comes from {zone:1449}, later"] = "la terre vient du {zone:1449}, plus tard",
		["{area:1438} flight master"] = "Maître de vol du {area:1438}",
		["{area:144} flight master"] = "Maître de vol de {area:144}",
		["{area:2418} flight master"] = "Maître de vol de la {area:2418}",
		["{area:348} flight master"] = "Maître de vol du {area:348}",
		["{area:702} flight master"] = "Maître de vol du {area:702}",
		["{npc:2487}, top floor"] = "{npc:2487}, dernier étage",
		["{npc:3516}, at the top of the tree"] = "{npc:3516}, au sommet de l'arbre",
		["{npc:5385}, upstairs"] = "{npc:5385}, à l'étage",
		["{npc:5636}, inside"] = "{npc:5636}, à l'intérieur",
		["{npc:7740}, beside her"] = "{npc:7740}, à côté d'elle",
		["{npc:7907}'s next errand goes to {zone:1446}: skip it."] = "La course suivante de {npc:7907} Lightwind mène en {zone:1446} : passez-la.",
		["{npc:7916}: keep it, the feathers come at the end of the {zone:1428} guide"] = "{npc:7916} : gardez-la, les plumes viennent à la fin du guide des {zone:1428}",
		["{npc:8022}' next task, {item:9471}, is a {area:978} quest: skip it."] = "La tâche suivante de {npc:8022} Grimshade, {item:9471}, est une quête de {area:978} : passez-la.",
		["{quest:2990}, at the top of the keep"] = "{quest:2990}, au sommet du donjon",
		["{zone:1419}: kill these as you meet them"] = "{zone:1419} : tuez-les au passage",
		["{zone:1453} flight master"] = "Maître de vol de {zone:1453}",
} end)()
t.guides["forever/alliance/40-50/06-searing-gorge"] = (function() return {
		["Below ground"] = "Sous terre",
		["Carry the {object:149047} south along the rim of the Cauldron and light the four Sentry Braziers, from the south-west round to the south-east."] = "Portez la {object:149047} vers le sud le long du rebord du Chaudron et allumez les quatre Braseros de sentinelle, du sud-ouest jusqu'au sud-est.",
		["Class trainer"] = "Maître de classe",
		["Fly to {area:1537}"] = "Prendre un vol pour {area:1537}",
		["For {npc:8256} in {zone:1455}, at the end of this guide"] = "Pour {npc:8256} à {zone:1455}, à la fin de ce guide",
		["Four rune rubbings in {zone:1447}: keep it"] = "Quatre estampages de runes en {zone:1447} : gardez-la",
		["Golems and elementals"] = "Golems et élémentaires",
		["Greater Lava Spiders"] = "Araignées de lave incendiaires",
		["Into {zone:1427}"] = "Vers la {zone:1427}",
		["Level 48.27"] = "Niveau 48.27",
		["Level 48.66"] = "Niveau 48.66",
		["Level 48.98"] = "Niveau 48.98",
		["Listen to {npc:8479}'s story once more."] = "Écoutez encore une fois l'histoire de {npc:8479}.",
		["Sentry Braziers"] = "Braseros de sentinelle",
		["The Grimesilt outhouse"] = "Les toilettes de Crasseboue",
		["The night elf stands alone west of {area:1446}. Hear his story."] = "L'elfe de la nuit Zamael Lunthistle se tient seul à l'ouest du {area:1446}. Écoutez son histoire.",
		["The prisoner's next task, Ledger from {zone:1446}, sends you to the {zone:1435} and {zone:1445}: skip it."] = "La tâche suivante du prisonnier, Grand livre de {zone:1446}, vous envoie au {zone:1435} et au {zone:1445} : passez-la.",
		["The {object:149502} it gives holds a {item:10575}: keep it for {npc:9459} in the {zone:1428}"] = "Le {object:149502} qu'elle vous donne contient une {item:10575} : gardez-la pour {npc:9459} dans les {zone:1428}",
		["The {object:179827} board"] = "Le panneau {object:179827}",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:14621} is a level 50 elite: most classes solo it at level 52, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:14621} est un élite de niveau 50 : la plupart des classes le battent seules au niveau 52, mais vous aurez peut-être besoin d'aide. Passez-le si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:5860} (level 50 elite) needs a group of 3. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:5860} (élite de niveau 50) demande un groupe de 3. Passez-le si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:3181} needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {quest:3181} demande un groupe de 2. Passez-la si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres.",
		["To {area:2101}"] = "Vers {area:2101}",
		["Xiggs waits in the {object:32359}."] = "Xiggs attend dans le {object:32359}.",
		["grind on {npc:5839}"] = "tuez en boucle : {npc:5839}",
		["grind on {npc:5844}"] = "tuez en boucle : {npc:5844}",
		["grind on {npc:9318}"] = "tuez en boucle : {npc:9318}",
		["{area:1443} opens in the north of the Cauldron. The Secret Plans lie on its upper ledge; Incendosaurs swim in the lava pools further in, so pull them to the edge. Stay clear of {npc:14621} and his elite guards deep inside."] = "{area:1443} s'ouvre au nord du Chaudron. Les Plans secrets : Flux embrasé se trouvent sur sa corniche supérieure ; les Incendosaures nagent dans les bassins de lave plus loin, attirez-les vers le bord. Restez loin de {npc:14621} et de ses gardes élites au fond.",
		["{area:1446} flight master"] = "Maître de vol de {area:1446}",
		["{item:18922}; below ground"] = "{item:18922} ; sous terre",
		["{npc:8509} and the dragonflight's hoard are beside {npc:8479}, on the rim south of {area:1446}."] = "{npc:8509} et le trésor du Vol draconique se trouvent à côté de {npc:8479}, sur le rebord au sud du {area:1446}.",
		["{npc:9616}: the oozes are in {zone:1448}, keep it"] = "{npc:9616} : les limons sont au {zone:1448}, gardez-la",
		["{quest:3453} lies on the ground at {npc:8479}'s feet; {quest:3462} stands beside him."] = "{quest:3453} se trouve par terre aux pieds de {npc:8479} ; {quest:3462} se tient à côté de lui.",
		["{quest:3462}: hand it in on the way back to {area:1446}"] = "{quest:3462} : rendez-la sur le chemin du retour vers le {area:1446}",
		["{zone:1427}: kill these as you meet them"] = "{zone:1427} : tuez-les au passage",
} end)()
t.guides["forever/alliance/40-50/07-un-goro-crater"] = (function() return {
		["Below ground"] = "Sous terre",
		["Bones and equipment"] = "Os et équipement",
		["Dinosaur Bones lie on the ground in the south-west, among the stegodons: those are elite, pick the bones up around them and take the rest from Diemetradons. The expedition's {item:11112} lies in the south-west jungle."] = "Les Os de dinosaure jonchent le sol au sud-ouest, parmi les stégodons : ceux-ci sont élites, ramassez les os autour d'eux et prenez le reste sur les Dimeurtrodons. L'{item:11112} de l'expédition se trouve dans la jungle sud-ouest.",
		["Eastern Pylon"] = "Le Pylône est",
		["Ends with {npc:9298} in {zone:1452}: keep it"] = "Se termine auprès de {npc:9298} au {zone:1452} : gardez-la",
		["Fly to {area:150}"] = "Prendre un vol pour {area:150}",
		["Fly to {area:1537}"] = "Prendre un vol pour {area:1537}",
		["Fly to {area:415}"] = "Prendre un vol pour {area:415}",
		["Fly to {area:976}"] = "Prendre un vol pour {area:976}",
		["For characters of 49 to 50, but most quests here are level 51-53: on purpose, for their experience. The crater's beasts are 48-55 and the Gorishi silithids 51-54, so pull them one at a time."] = "Pour les personnages de niveau 49 à 50, mais la plupart des quêtes ici sont de niveau 51-53 : c'est voulu, pour leur expérience. Les bêtes du cratère sont de niveau 48-55 et les silithides Gorishi 51-54 : attirez-les un par un.",
		["For {npc:7775} in {zone:1444}: keep it"] = "Pour {npc:7775} en {zone:1444} : gardez-la",
		["Lar'korwi Mates and the raft"] = "Compagnes de Lar'korwi ({npc:9683}) et le radeau",
		["Level 49.51"] = "Niveau 49.51",
		["Level 50.4"] = "Niveau 50.4",
		["Northern Pylon"] = "Le Pylône nord",
		["Pterrordax"] = "Pterreurdactyles",
		["Ride east to {area:1943}, where the robot stands among the gorillas. Stay out of the deep cave there."] = "Chevauchez vers l'est jusqu'à {area:1943}, où le robot se tient parmi les gorilles. N'entrez pas dans la grotte profonde.",
		["Ride north along the western jungle back to the refuge."] = "Remontez vers le nord par la jungle ouest jusqu'au refuge.",
		["Ride south to {area:537} in the middle of the crater, then east into the eastern jungle. Crystal clusters stand all over the crater, many of them around {area:537}: take a few extra of each colour. Bloodpetal Lashers and Threshers drop the petals; the expedition's {item:11113} sits at an abandoned camp in the eastern jungle."] = "Chevauchez vers le sud jusqu'à {area:537}, au milieu du cratère, puis vers l'est dans la jungle orientale. Des amas de cristaux se dressent partout dans le cratère, beaucoup autour de {area:537} : prenez-en quelques-uns de plus de chaque couleur. Les Flagellants ({npc:6509}) et Batteurs Pétale-de-sang lâchent les pétales ; {item:11113} de l'expédition se trouve dans un camp abandonné de la jungle orientale.",
		["Ride west back to the refuge.\nGive the elite devilsaurs and stegodons a wide berth. Pick up every Power Crystal and {object:157936} you pass from here on."] = "Retournez vers l'ouest jusqu'au refuge.\nGardez vos distances avec les diablosaures et les stégodons élites. Ramassez désormais chaque Cristal de puissance et chaque {object:157936} que vous croisez.",
		["Ride west out of {area:976} to the long ramp down into {zone:1449}. {npc:9619} camps at the foot of the ramp, in the south-east corner of the crater."] = "Chevauchez vers l'ouest hors de {area:976} jusqu'à la longue rampe qui descend dans {zone:1449}. {npc:9619} campe au pied de la rampe, dans le coin sud-est du cratère.",
		["The Gorishi hive"] = "La ruche Gorishi",
		["The Lar'korwi Mates prowl the jungle west of {npc:9619}. The wrecked raft lies on the shore of the lake there; the small pack sits in the water beside it. Keep the compass, map and key for {npc:8737}. Any beast in the crater may drop {item:11116}: right-click it."] = "Les Compagnes de Lar'korwi ({npc:9683}) rôdent dans la jungle à l'ouest de {npc:9619}. Le radeau échoué gît sur la rive du lac là-bas ; le petit paquetage est dans l'eau à côté. Gardez la boussole, la carte et la clé pour {npc:8737}. N'importe quelle bête du cratère peut lâcher {item:11116} : faites un clic droit dessus.",
		["The dead Threshadon lies by the water north of {npc:9619}."] = "Le battrodon mort se trouve au bord de l'eau au nord de {npc:9619}.",
		["The gorillas on {area:1943} carry the pelts: keep it for the second Un'Goro visit, around 56"] = "Les gorilles du {area:1943} portent les peaux : gardez-la pour la deuxième visite d'Un'Goro, vers le niveau 56",
		["The pylon stands on the eastern cliffs."] = "Le pylône se dresse sur les falaises est.",
		["The pylon stands on the slope east of the refuge. Pterrordax circle the slopes around it: they count for Spraggle and drop {npc:9998}'s scales."] = "Le pylône se dresse sur la pente à l'est du refuge. Des Pterreurdactyles tournoient sur les pentes alentour : ils comptent pour Spraggle et lâchent les écailles de {npc:9998}.",
		["The pylon stands on the western cliffs. {npc:9167} fly over the whole west side."] = "Le pylône se dresse sur les falaises ouest. Les {npc:9167} volent au-dessus de tout le côté ouest.",
		["The {zone:1455} quests were taken at the end of the {zone:1427} guide: fly straight on to {zone:1440} for {zone:1447}."] = "Les quêtes de {zone:1455} ont été prises à la fin du guide de la {zone:1427} : prenez directement un vol pour {zone:1440} afin de rejoindre {zone:1447}.",
		["Theramore flight master"] = "Maître de vol de Theramore",
		["To {area:2101}"] = "Vers {area:2101}",
		["Western Pylon"] = "Le Pylône ouest",
		["grind on Pterrordax"] = "tuez des Pterreurdactyles en boucle",
		["grind on {npc:6116}"] = "tuez en boucle : {npc:6116}",
		["grind on {npc:9164}"] = "tuez en boucle : {npc:9164}",
		["grind on {npc:9167}"] = "tuez en boucle : {npc:9167}",
		["{area:144} flight master"] = "Maître de vol de {area:144}",
		["{area:442} flight master"] = "Maître de vol d'{area:442}",
		["{area:537} and the eastern jungle"] = "{area:537} et la jungle de l'est",
		["{area:541} flight master"] = "Maître de vol du {area:541}",
		["{npc:11406}: for Ogtinc in {zone:1447}, keep it"] = "{npc:11406} : pour Ogtinc en {zone:1447}, gardez-la",
		["{npc:8737}, at the back of the refuge"] = "{npc:8737}, au fond du refuge",
		["{npc:9117}, at the back of the cave; below ground"] = "{npc:9117}, au fond de la grotte ; sous terre",
		["{npc:9117}, below ground"] = "{npc:9117}, sous terre",
		["{npc:9618} stands just outside the refuge."] = "{npc:9618} se tient juste devant le refuge.",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}, à l'entrée du refuge",
		["{npc:9998}, at the refuge's entrance"] = "{npc:9998}, à l'entrée du refuge",
		["{object:161504}, underwater"] = "{object:161504}, sous l'eau",
		["{zone:1455} flight master"] = "Maître de vol de {zone:1455}",
} end)()
t.guides["forever/alliance/50-60/01-burning-steppes"] = (function() return {
		["Archesonus stands beside King Magni in the {object:171709}."] = "Archesonus se tient à côté du roi Magni dans {object:171709}.",
		["Archesonus stands beside King Magni in the {object:171709}: the relics you read in the Steppes are his."] = "Archesonus se tient à côté du roi Magni dans {object:171709} : les reliques que vous avez lues dans les Steppes sont pour lui.",
		["Ardalan is inside {area:1438}."] = "Ardalan se trouve à l'intérieur de {area:1438}.",
		["Below ground"] = "Sous terre",
		["Climb to the top of {area:249} and plant the head in the soft dirt mound."] = "Montez au sommet de {area:249} et plantez la tête dans le monticule de terre meuble.",
		["Ends with {quest:4808} in {area:2255}, {zone:1452}: keep it"] = "Se termine auprès de {quest:4808} à {area:2255}, {zone:1452} : gardez-la",
		["Fly to {area:1438}"] = "Prendre un vol pour {area:1438}",
		["Fly to {area:150}"] = "Prendre un vol pour {area:150}",
		["Fly to {area:1537}"] = "Prendre un vol pour {area:1537}",
		["Fly to {area:2418}"] = "Prendre un vol pour {area:2418}",
		["Fly to {area:271}"] = "Prendre un vol pour {area:271}",
		["Fly to {area:348}"] = "Prendre un vol pour {area:348}",
		["Fly to {area:702}"] = "Prendre un vol pour {area:702}",
		["Follow the road west, then climb north to the goblin camp on {area:251}."] = "Suivez la route vers l'ouest, puis montez vers le nord jusqu'au camp gobelin de {area:251}.",
		["For {zone:1453}: keep it"] = "Pour {zone:1453} : gardez-la",
		["Kum'isha waits at the {area:2517}, the hill south-west of the keep. The {zone:1419} mobs on the way drop the Imperfect Draenethyst Fragments; bring her what you have.\nCareful: Felcular, {npc:7664} and Ilifar are all level 60 elites. Razelikh casts {spell:2691}, {spell:8255} and Decimate, and as its health drops it adds {object:141891}, {spell:10854} and then Enrage at 15%."] = "Kum'isha attend à {area:2517}, la colline au sud-ouest du donjon. Les monstres des {zone:1419} sur le chemin lâchent les Fragments de draenéthyste imparfaits ; apportez-lui ce que vous avez.\nAttention : Felcular, {npc:7664} et Ilifar sont tous des élites de niveau 60. Razelikh lance {spell:2691}, {spell:8255} et Décimer, et à mesure que sa vie baisse il ajoute Larme de Razelikh, {spell:10854} puis Enrager à 15 %.",
		["Level 52"] = "Niveau 52",
		["Level 52.08"] = "Niveau 52.08",
		["Listen to his tale, then ride back south to Kum'isha."] = "Écoutez son récit, puis revenez vers le sud jusqu'à Kum'isha.",
		["Mosshoof Coursers"] = "Coursiers Sabots-de-mousse",
		["Open the {item:10569} from {zone:1427} for its {item:10575}, then tell {npc:9459} you bring proof of your deeds: no drake to fight."] = "Ouvrez le {item:10569} de {zone:1427} pour en récupérer la {item:10575}, puis dites à {npc:9459} que vous apportez la preuve de vos exploits : aucun drake à combattre.",
		["Portal to {zone:1438}"] = "Portail vers {zone:1438}",
		["Ride back east along the road to the Vigil."] = "Revenez vers l'est par la route jusqu'à la Veille.",
		["Ride back south to the camp."] = "Retournez au camp, au sud.",
		["Ride north out of the {zone:1419} into the {zone:1435}: the {npc:10996} stands by the road from the {zone:1419}. Keep clear of {area:75}, the Horde town to the north-east."] = "Chevauchez vers le nord hors des {zone:1419} jusqu'au {zone:1435} : le {npc:10996} se tient au bord de la route qui vient des {zone:1419}. Restez à l'écart de {area:75}, la ville de la Horde au nord-est.",
		["Ride north-east from the shrine: {npc:8405} camps at the {area:1224}, in the hills above the road."] = "Chevauchez vers le nord-est depuis le sanctuaire : {npc:8405} campe à {area:1224}, dans les collines au-dessus de la route.",
		["Skeletal Flayers and Slavering Ghouls roam the fields north of the camp; all the Scourge here drop Scourgestones.\nCareful: These undead notice you from far away, and other undead nearby join the fight when one is pulled.\nCareful: The {npc:10411} (3 spawns, 15 min respawn) turns invisible when out of combat and calls in Rockwing Gargoyles once a fight starts."] = "Des Écorcheurs squelettes et des Goules écumantes parcourent les champs au nord du camp ; tout le Fléau ici laisse tomber des Pierres du Fléau.\nAttention : ces morts-vivants vous repèrent de loin, et les autres morts-vivants proches se joignent au combat quand vous en attirez un.\nAttention : l'{npc:10411} (3 apparitions, réapparition en 15 min) devient invisible hors combat et appelle des Gargouilles Aile-de-roc dès qu'un combat commence.",
		["Swim to the small island off the southern tip of {zone:1447}. If {npc:8392} isn't there, fire your {item:10444} to signal him, and wait for him to land."] = "Nagez jusqu'au petit îlot au large de la pointe sud d'{zone:1447}. Si {npc:8392} n'est pas là, tirez avec votre {item:10444} pour lui faire signe, et attendez qu'il atterrisse.",
		["The Firegut ogres hold the great rock north of the Vigil, with the Brutes on its east side."] = "Les ogres Brûlentrailles tiennent le grand rocher au nord de la Veille, avec les Brutes sur son flanc est.",
		["The Highborne ghosts haunt the ruins around the shrine; the Haldarr satyrs hold the camp just north of it."] = "Les fantômes bien-nés hantent les ruines autour du sanctuaire ; les satyres Haldarr tiennent le Campement des Haldarr juste au nord.",
		["The Spitelash naga of the {area:1221} carry {item:13815}. {npc:8507}'s four runes stand among the ruins: use his {item:10445} on each."] = "Les nagas Fouette-bile de {area:1221} portent {item:13815}. Les quatre runes de {npc:8507} se dressent parmi les ruines : utilisez son {item:10445} sur chacune.",
		["The Wildkin Feathers lie on the ground across the {zone:1425}, south and east of {area:348}, where the owlbeasts roam; the mobs here are well below you now."] = "Les Plumes d'Indomptable jonchent le sol des {zone:1425}, au sud et à l'est du {area:348}, là où rôdent les chouettards ; les monstres d'ici sont désormais bien en dessous de votre niveau.",
		["The nearest Mosshoof Coursers graze the hills north-east of the {area:1224}, toward the {area:1219}; a larger herd roams the open ground to the south."] = "Les Coursiers Sabots-de-mousse les plus proches paissent dans les collines au nord-est de {area:1224}, vers {area:1219} ; un troupeau plus grand parcourt les terres dégagées au sud.",
		["The portal in {area:702} leads up to {zone:1457}: {npc:9047} waits in the {area:1658}, in the north of the city."] = "Le portail de {area:702} mène à {zone:1457} : {npc:9047} attend à {area:1658}, au nord de la cité.",
		["The relics are in the {zone:1428}: keep it"] = "Les reliques sont dans {zone:1428} : gardez-la",
		["The relics are the carved stones scattered through the {area:250} around {area:251}: click them until the information is recovered.\nRead the tablet in the {object:147516} camp among the ruins, south-west of {area:251}, to copy the transcript.\nUse the {item:12284} on a {npc:7047} on the slopes east of {area:251} just before it dies, then loot the essence it leaves."] = "Les reliques sont les pierres sculptées éparpillées dans les {area:250} autour de {area:251} : cliquez dessus jusqu'à récupérer les informations.\nLisez la tablette dans le camp {object:147516} parmi les ruines, au sud-ouest de {area:251}, pour en copier la transcription.\nUtilisez le {item:12284} sur un {npc:7047} sur les pentes à l'est de {area:251} juste avant qu'il meure, puis ramassez l'essence qu'il laisse.",
		["The shrine lies in the south-west corner of {zone:1447}, south of {area:3137}."] = "Le Sanctuaire de Shadowsong se trouve dans le coin sud-ouest d'{zone:1447}, au sud de {area:3137}.",
		["The wildkin are in {zone:1452}: keep it"] = "Les Indomptables sont au {zone:1452} : gardez-la",
		["The {area:1221}"] = "{area:1221}",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:7977} (level 48 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back.\n{npc:7977} walks the {zone:1425} shore below the {area:307}, from the arrow south to about 75,66 and north to about 82,52: if she isn't at the arrow, follow the shore."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:7977} (élite de niveau 48) demande un groupe de 2. Passez-la si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres.\n{npc:7977} arpente le rivage des {zone:1425} au pied des {area:307}, de la flèche jusqu'à environ 75,66 au sud et 82,52 au nord : si elle n'est pas à la flèche, suivez le rivage.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:9461} is a level 54 elite: most classes solo it at level 56, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:9461} est un élite de niveau 54 : la plupart des classes le battent seules au niveau 56, mais vous aurez peut-être besoin d'aide. Passez-le si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres.",
		["To {area:2101}"] = "Vers {area:2101}",
		["Upstairs"] = "À l'étage",
		["Wildkin feathers"] = "Plumes d'Indomptable",
		["grind on {npc:6196}"] = "tuez en boucle : {npc:6196}",
		["grind on {npc:6375}"] = "tuez en boucle : {npc:6375}",
		["grind on {npc:7034}"] = "tuez en boucle : {npc:7034}",
		["grind on {npc:9690}"] = "tuez en boucle : {npc:9690}",
		["{area:144} flight master"] = "Maître de vol de {area:144}",
		["{area:197}: kill these as you meet them"] = "{area:197} : tuez-les au passage",
		["{area:199} cauldron"] = "Chaudron de {area:199}",
		["{area:2418} flight master"] = "Maître de vol de la {area:2418}",
		["{area:2418} sits in the south-east of the Steppes, at the top of the pass up from Redridge."] = "{area:2418} se trouve au sud-est des Steppes, en haut du col qui monte depuis les Carmines.",
		["{area:250}: kill these as you meet them"] = "{area:250} : tuez-les au passage",
		["{area:3197} flight master"] = "Maître de vol de {area:3197}",
		["{area:348} flight master"] = "Maître de vol du {area:348}",
		["{area:442} flight master"] = "Maître de vol d'{area:442}",
		["{item:10575}, from the hoard"] = "{item:10575}, dans le trésor",
		["{item:11467}; inside"] = "{item:11467} ; à l'intérieur",
		["{item:7972}: the {npc:7864}, about 10%"] = "{item:7972} : les {npc:7864}, environ 10 %",
		["{npc:10778}'s ghost wanders by the farmhouse of {area:199}, west of {area:200}; her parcel lies inside."] = "Le fantôme de {npc:10778} erre près de la ferme de {area:199}, à l'ouest de {area:200} ; son colis est à l'intérieur.",
		["{npc:11075} guards the cauldron in {area:199}, west of Andorhal."] = "{npc:11075} garde le chaudron de {area:199}, à l'ouest d'Andorhal.",
		["{npc:7034}, below ground"] = "{npc:7034}, sous terre",
		["{npc:7363} walks around here: look inside the circle on the map"] = "{npc:7363} se promène par ici : cherchez dans le cercle sur la carte",
		["{npc:8395} wants two Undamaged Hippogryph Feathers from the Thunderhead hippogryphs around his camp, the ones you top up on here: about one in three carries one."] = "{npc:8395} veut deux Plumes d'hippogryphe sans défaut des hippogryphes Cogne-tonnerre autour de son camp, ceux sur lesquels vous complétez votre niveau ici : environ un sur trois en porte une.",
		["{npc:8420} camps at the {area:1219} in the north; his equipment lies all over the {area:1220} just south-east of him."] = "{npc:8420} campe à {area:1219}, au nord ; son équipement est éparpillé dans tout {area:1220}, juste au sud-est.",
		["{npc:9047}, in the {area:1658}"] = "{npc:9047}, à {area:1658}",
		["{npc:9176} and the Blackrock orcs hold the camps and the stronghold at the foot of {area:254}, west of {area:251}. Pull them one at a time; every orc and worg may drop a medallion, so kill them until you have fifty.\nCareful: {npc:9176} has a guard linked to him that joins the fight, and a second soldier patrols close by; clear the patrol before pulling."] = "{npc:9176} et les orcs Blackrock tiennent les camps et la forteresse au pied du {area:254}, à l'ouest de {area:251}. Attirez-les un par un ; chaque orc et chaque worg peut lâcher un médaillon, tuez-les donc jusqu'à en avoir cinquante.\nAttention : {npc:9176} a un garde lié qui se joint au combat, et un second soldat patrouille tout près ; éliminez la patrouille avant de l'attirer.",
		["{npc:9177}: the Blackrock orcs drop the medallions, keep it open all through the Steppes"] = "{npc:9177} : les orcs Blackrock laissent tomber les médaillons, gardez-la ouverte dans toutes les Steppes",
		["{object:175894}, inside"] = "{object:175894}, à l'intérieur",
		["{zone:1447}: kill these as you meet them"] = "{zone:1447} : tuez-les au passage",
		["{zone:1455} flight master"] = "Maître de vol de {zone:1455}",
		["{zone:1455} has no druid trainer"] = "{zone:1455} n'a pas de maître des druides",
} end)()
t.guides["forever/alliance/50-60/02-felwood"] = (function() return {
		["Below ground"] = "Sous terre",
		["Ends in the {zone:1413}: keep it"] = "Se termine dans {zone:1413} : gardez-la",
		["First crater"] = "Premier cratère",
		["Fly to {area:415}"] = "Prendre un vol pour {area:415}",
		["Follow the road north to the cave mouth of {area:1769}; {npc:15395} guards it."] = "Suivez la route vers le nord jusqu'à l'entrée de la grotte de {area:1769} ; {npc:15395} la garde.",
		["Follow the road north to the cratered vale and walk to each crater, killing the Entropic Beasts and Horrors between them."] = "Suivez la route vers le nord jusqu'au val criblé de cratères et rendez-vous à chaque cratère, en tuant les Bêtes d'entropie et les Horreurs entre eux.",
