} end)()
t.guides["forever/class/priest/priest-robes-alliance"] = (function() return {
		["A free uncommon robe at 5: heal and fortify a wounded guard near your first town."] = "Une robe inhabituelle gratuite au niveau 5 : soignez et fortifiez un garde blessé près de votre première ville.",
		["At 5, {npc:3595}, the priest trainer on the second level of {area:256}, the great tree in {area:188}, sends you to {npc:3600} in {area:186}. Train {spell:613} (Rank 2) from her while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "Au niveau 5, {npc:3595}, la maîtresse des prêtres au deuxième niveau d'{area:256}, le grand arbre de {area:188}, vous envoie voir {npc:3600} à {area:186}. Apprenez {spell:613} (rang 2) auprès d'elle pendant que vous y êtes : il est disponible au niveau 4 pour 1 pa, et la quête suivante demande exactement ce rang.",
		["At 5, {npc:375}, the priest trainer inside {area:24}, sends you to {npc:377} in {area:87}. Train {spell:613} (Rank 2) from Anetta while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "Au niveau 5, {npc:375}, la maîtresse des prêtres dans l'{area:24}, vous envoie voir {npc:377} à {area:87}. Apprenez {spell:613} (rang 2) auprès d'Anetta pendant que vous y êtes : il est disponible au niveau 4 pour 1 pa, et la quête suivante demande exactement ce rang.",
		["At 5, {npc:837}, the priest trainer inside {area:77} in {area:132}, sends you to {npc:1226} in {area:131}. Train {spell:613} (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "Au niveau 5, {npc:837}, le maître des prêtres dans {area:77}, dans la {area:132}, vous envoie voir {npc:1226} à {area:131}. Apprenez {spell:613} (rang 2) auprès de lui pendant que vous y êtes : il est disponible au niveau 4 pour 1 pa, et la quête suivante demande exactement ce rang.",
		["Back at the north edge of {area:186}: {npc:3600} gives you the {item:16604}."] = "De retour au bord nord de {area:186} : {npc:3600} vous donne la {item:16604}.",
		["Back inside the {area:2102}: {npc:1226} gives you {item:16605}."] = "De retour dans la {area:2102} : {npc:1226} vous donne la {item:16605}.",
		["Back upstairs in the Lion's Pride Inn: Josetta gives you {item:16605}."] = "Remontez à l'étage de l'auberge de la Fierté du lion : Josetta vous donne la {item:16605}.",
		["Follow the road south out of {area:9} to {area:87}. {npc:377} is upstairs in the Lion's Pride Inn."] = "Suivez la route vers le sud en sortant de la {area:9} jusqu'à {area:87}. {npc:377} est à l'étage de l'auberge de la Fierté du lion.",
		["Heal and fortify {npc:12423}"] = "Soignez et fortifiez {npc:12423}",
		["Heal and fortify {npc:12427}"] = "Soignez et fortifiez {npc:12427}",
		["Heal and fortify {npc:12429}"] = "Soignez et fortifiez {npc:12429}",
		["Leave {area:188} by the ramp and follow the road south-west to {area:186}. {npc:3600} is in the building at the north edge of the village."] = "Quittez {area:188} par la rampe et suivez la route vers le sud-ouest jusqu'à {area:186}. {npc:3600} est dans le bâtiment au bord nord du village.",
		["Priest Robes at 5 (Alliance)"] = "Robe de prêtre au niveau 5 (Alliance)",
		["Take the tunnel north-east out of {area:132} and follow the road east to {area:131}. {npc:1226} is inside the {area:2102}."] = "Prenez le tunnel au nord-est pour sortir de la {area:132} et suivez la route vers l'est jusqu'à {area:131}. {npc:1226} est dans la {area:2102}.",
		["{npc:12423} kneels by a tree on the lake shore east of {area:87}, off the road: walk along the shore, the minimap misses him from the road. Cast {spell:613} (Rank 2) on him first, then {spell:1243}. Rank 1 of {spell:613} does not count; drag Rank 2 onto your bar from the spellbook (or cast both from the spellbook if an action bar addon gets in the way). He walks off once both land and is back in about 3 minutes."] = "{npc:12423} est agenouillé près d'un arbre sur la rive du lac à l'est de {area:87}, à l'écart de la route : longez la rive, la minicarte ne le montre pas depuis la route. Lancez d'abord {spell:613} (rang 2) sur lui, puis {spell:1243}. Le rang 1 de {spell:613} ne compte pas ; faites glisser le rang 2 depuis le grimoire vers votre barre (ou lancez les deux depuis le grimoire si un addon de barres d'action vous gêne). Il s'en va une fois les deux sorts reçus et revient en 3 minutes environ.",
		["{npc:12427} kneels on a ridge between two low walls just south of {area:131}, across the road from the hunter pet trainer: if the road starts going downhill, you have passed him. Cast {spell:613} (Rank 2) on him first, then {spell:1243}; he speaks after each spell. Rank 1 of {spell:613} does not count."] = "{npc:12427} est agenouillé sur une crête entre deux murets juste au sud de {area:131}, de l'autre côté de la route par rapport au maître des familiers : si la route commence à descendre, vous l'avez dépassé. Lancez d'abord {spell:613} (rang 2) sur lui, puis {spell:1243} ; il parle après chaque sort. Le rang 1 de {spell:613} ne compte pas.",
		["{npc:12429} kneels on the rocks at the edge of {area:259}, about 100 yards south of {area:186}, with no quest mark over her. Cast {spell:613} (Rank 2) on her first, then {spell:1243}; she runs off toward the lake once both land and is back in about 5 minutes. Rank 1 of {spell:613} does not count."] = "{npc:12429} est agenouillée sur les rochers au bord du {area:259}, à une centaine de mètres au sud de {area:186}, sans marque de quête au-dessus d'elle. Lancez d'abord {spell:613} (rang 2) sur elle, puis {spell:1243} ; elle court vers le lac une fois les deux sorts reçus et revient en 5 minutes environ. Le rang 1 de {spell:613} ne compte pas.",
		["{spell:613} (Rank 2), if Anetta did not teach it yet"] = "{spell:613} (rang 2), si Anetta ne vous l'a pas encore appris",
		["{spell:613} (Rank 2), if {npc:3595} did not teach it yet"] = "{spell:613} (rang 2), si {npc:3595} ne vous l'a pas encore appris",
		["{spell:613} (Rank 2), if {npc:837} did not teach it yet"] = "{spell:613} (rang 2), si {npc:837} ne vous l'a pas encore appris",
} end)()
t.guides["forever/class/priest/priest-robes-horde"] = (function() return {
		["A free uncommon robe at 5: heal and fortify a wounded guard near your first town."] = "Une robe inhabituelle gratuite au niveau 5 : soignez et fortifiez un garde blessé près de votre première ville.",
		["At 5, {npc:2123}, the priest trainer in the chapel of {area:154}, sends you to {npc:2129} in {area:159}. Train {spell:613} (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "Au niveau 5, {npc:2123}, le maître des prêtres dans la chapelle de {area:154}, vous envoie voir {npc:2129} à {area:159}. Apprenez {spell:613} (rang 2) auprès de lui pendant que vous y êtes : il est disponible au niveau 4 pour 1 pa, et la quête suivante demande exactement ce rang.",
		["At 5, {npc:3707}, the priest trainer in the Den in the middle of the {area:363}, sends you to {npc:3706} in {area:362}. Train {spell:613} (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "Au niveau 5, {npc:3707}, le maître des prêtres dans la Tanière, au milieu de la {area:363}, vous envoie voir {npc:3706} à {area:362}. Apprenez {spell:613} (rang 2) auprès de lui pendant que vous y êtes : il est disponible au niveau 4 pour 1 pa, et la quête suivante demande exactement ce rang.",
		["Back in the {area:362} barracks: {npc:3706} gives you the {item:16606}."] = "De retour à la caserne de {area:362} : {npc:3706} vous donne la {item:16606}.",
		["Back upstairs in the {area:159} inn: Beryl gives you the {item:16607}."] = "Remontez à l'étage de l'auberge de {area:159} : Beryl vous donne la {item:16607}.",
		["Follow the road east out of {area:154} to {area:159}. {npc:2129} is upstairs in the inn, {area:2119}."] = "Suivez la route vers l'est en sortant de {area:154} jusqu'à {area:159}. {npc:2129} est à l'étage de l'auberge, la {area:2119}.",
		["Follow the road out of the {area:363} north-east to {area:362}. {npc:3706} is inside the barracks, the first building on the right as you come into town."] = "Suivez la route qui sort de la {area:363} vers le nord-est jusqu'à {area:362}. {npc:3706} est dans la caserne, le premier bâtiment à droite en entrant dans la ville.",
		["Heal and fortify {npc:12428}"] = "Soignez et fortifiez {npc:12428}",
		["Heal and fortify {npc:12430}"] = "Soignez et fortifiez {npc:12430}",
		["Priest Robes at 5 (Horde)"] = "Robe de prêtre au niveau 5 (Horde)",
		["{npc:12428} kneels, half-dead, beside the north gate of {area:159}'s graveyard, a short walk north of the inn. Cast {spell:613} (Rank 2) on him first, then {spell:1243}: Fortitude first does not count, nor does Rank 1 of {spell:613}. If an addon gets in the way, cast both from the spellbook."] = "{npc:12428} est agenouillé, à moitié mort, près de la porte nord du cimetière de {area:159}, à quelques pas au nord de l'auberge. Lancez d'abord {spell:613} (rang 2) sur lui, puis {spell:1243} : Robustesse d'abord ne compte pas, pas plus que le rang 1 de {spell:613}. Si un addon vous gêne, lancez les deux depuis le grimoire.",
		["{npc:12430} kneels behind a group of rocks just off the road, a short walk south of {area:362}. Cast {spell:613} (Rank 2) on her first, then {spell:1243}. Rank 1 of {spell:613} does not count; drag Rank 2 onto your bar from the spellbook. She leaves once both land and is back in about 5 minutes."] = "{npc:12430} est agenouillée derrière un groupe de rochers juste à côté de la route, à quelques pas au sud de {area:362}. Lancez d'abord {spell:613} (rang 2) sur elle, puis {spell:1243}. Le rang 1 de {spell:613} ne compte pas ; faites glisser le rang 2 depuis le grimoire vers votre barre. Elle s'en va une fois les deux sorts reçus et revient en 5 minutes environ.",
		["{spell:613} (Rank 2), if Duesten did not teach it yet"] = "{spell:613} (rang 2), si Duesten ne vous l'a pas encore appris",
		["{spell:613} (Rank 2), if {npc:3707} did not teach it yet"] = "{spell:613} (rang 2), si {npc:3707} ne vous l'a pas encore appris",
} end)()
t.guides["forever/class/priest/starshards-and-elunes-grace"] = (function() return {
		["At 10 in {zone:1426}, {npc:1226}, the priest trainer inside the {area:2102} in {area:131}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "Au niveau 10 en {zone:1426}, {npc:1226}, le maître des prêtres dans la {area:2102} à {area:131}, vous remet {quest:5628}, une lettre pour {npc:11401} à {zone:1457}.",
		["At 10 in {zone:1429}, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "Au niveau 10 dans la {zone:1429}, {npc:377}, à l'étage de l'auberge de la Fierté du lion à {area:87}, vous remet {quest:5628}, une lettre pour {npc:11401} à {zone:1457}.",
		["At 10 in {zone:1453}, {npc:5489} at the altar of the Cathedral of Light hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}. {npc:11397} in the Park has the same letter."] = "Au niveau 10 à {zone:1453}, {npc:5489}, à l'autel de la cathédrale de la Lumière, vous remet {quest:5628}, une lettre pour {npc:11401} à {zone:1457}. {npc:11397}, dans le Parc, a la même lettre.",
		["At 10 in {zone:1455}, {npc:5142} in the {object:32386} ({object:32362}) hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "Au niveau 10 à {zone:1455}, {npc:5142}, dans la salle des Mystères ({object:32362}), vous remet {quest:5628}, une lettre pour {npc:11401} à {zone:1457}.",
		["At 10, go to {npc:11401} on the upper balcony of the Temple of the Moon, at the south end of {zone:1457}: take the ramp up from the temple floor; she stands beside {npc:7999}. {quest:5627} is given and taken back at once and teaches {spell:10797}. No letter needed. Forever made {spell:10797} hit much harder, on a 30-second cooldown."] = "Au niveau 10, allez voir {npc:11401} sur le balcon supérieur du temple de la Lune, à l'extrémité sud de {zone:1457} : prenez la rampe qui monte depuis le sol du temple ; elle se tient à côté de {npc:7999}. {quest:5627} est donnée et reprise aussitôt et vous apprend {spell:10797}. Pas besoin de lettre. Forever a rendu {spell:10797} bien plus puissant, avec un temps de recharge de 30 secondes.",
		["At 10, {npc:3600}, the priest trainer in the building at the north edge of {area:186}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}. {area:186} is on the road west to {zone:1457}."] = "Au niveau 10, {npc:3600}, la maîtresse des prêtres dans le bâtiment au bord nord de {area:186}, vous remet {quest:5628}, une lettre pour {npc:11401} à {zone:1457}. {area:186} est sur la route qui mène à l'ouest à {zone:1457}.",
		["At 20 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you an {spell:2651} letter for {npc:11401} in {zone:1457}. {npc:11397} in the Park has the same letter."] = "Au niveau 20 à {zone:1453}, {npc:376}, à l'autel de la cathédrale de la Lumière, vous remet une lettre {spell:2651} pour {npc:11401} à {zone:1457}. {npc:11397}, dans le Parc, a la même lettre.",
		["At 20 in {zone:1455}, {npc:11406} in the {object:32386} ({object:32362}) hands you an {spell:2651} letter for {npc:11401} in {zone:1457}."] = "Au niveau 20 à {zone:1455}, {npc:11406}, dans la salle des Mystères ({object:32362}), vous remet une lettre {spell:2651} pour {npc:11401} à {zone:1457}.",
		["At 20, {npc:11401} on the upper balcony of the Temple of the Moon, beside {npc:7999}, teaches {quest:5672} with a quest she gives and takes back at once. In Forever, {quest:5672} halves the chance for melee and ranged attacks to hit you for 15 seconds or until three attacks miss."] = "Au niveau 20, {npc:11401}, sur le balcon supérieur du temple de la Lune à côté de {npc:7999}, vous apprend {quest:5672} avec une quête qu'elle donne et reprend aussitôt. Dans Forever, {quest:5672} réduit de moitié les chances des attaques de mêlée et à distance de vous toucher pendant 15 secondes ou jusqu'à ce que trois attaques vous ratent.",
		["Hand Laurena's letter to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "Remettez la lettre de Laurena à {npc:11401}, sur le balcon supérieur du temple de la Lune à {zone:1457}, à côté de {npc:7999} : le bateau du {area:17203} (ou de {area:150}) pour {area:442}, puis le bateau pour le {area:702}, et enfin le portail qui monte à {zone:1457}.",
		["Hand Nara's letter to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "Remettez la lettre de Nara à {npc:11401}, sur le balcon supérieur du temple de la Lune à {zone:1457}, à côté de {npc:7999} : le bateau du {area:17203} (ou de {area:150}) pour {area:442}, puis le bateau pour le {area:702}, et enfin le portail qui monte à {zone:1457}.",
		["Hand Rohan's letter to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "Remettez la lettre de Rohan à {npc:11401}, sur le balcon supérieur du temple de la Lune à {zone:1457}, à côté de {npc:7999} : le bateau du {area:17203} (ou de {area:150}) pour {area:442}, puis le bateau pour le {area:702}, et enfin le portail qui monte à {zone:1457}.",
		["Take the road west from {area:186} into {zone:1457} and go up to the upper balcony of the Temple of the Moon, beside {npc:7999}: {npc:11401} takes {quest:5629} and teaches {spell:10797}."] = "Prenez la route vers l'ouest depuis {area:186} jusqu'à {zone:1457} et montez au balcon supérieur du temple de la Lune, à côté de {npc:7999} : {npc:11401} prend {quest:5629} et vous apprend {spell:10797}.",
		["The Night Elf priest spells: {spell:10797} at 10, {spell:2651} at 20. Free, no objectives."] = "Les sorts de prêtre elfe de la nuit : {spell:10797} au niveau 10, {spell:2651} au niveau 20. Gratuits, sans objectif.",
		["{npc:11406}: take his {spell:2651} letter"] = "{npc:11406} : prenez sa lettre {spell:2651}",
		["{npc:1226}: take {quest:5628}"] = "{npc:1226} : acceptez {quest:5628}",
		["{npc:3600}: take {quest:5628}"] = "{npc:3600} : acceptez {quest:5628}",
		["{npc:376}: take her {spell:2651} letter"] = "{npc:376} : prenez sa lettre {spell:2651}",
		["{npc:377}: take {quest:5628}"] = "{npc:377} : acceptez {quest:5628}",
		["{npc:5142}: take {quest:5628}"] = "{npc:5142} : acceptez {quest:5628}",
		["{npc:5489}: take {quest:5628}"] = "{npc:5489} : acceptez {quest:5628}",
		["{quest:5628} goes to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: take the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "{quest:5628} va à {npc:11401}, sur le balcon supérieur du temple de la Lune à {zone:1457}, à côté de {npc:7999} : prenez le bateau du {area:17203} (ou de {area:150}) pour {area:442}, puis le bateau pour le {area:702}, et enfin le portail qui monte à {zone:1457}.",
		["{quest:5630} goes to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: take the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "{quest:5630} va à {npc:11401}, sur le balcon supérieur du temple de la Lune à {zone:1457}, à côté de {npc:7999} : prenez le bateau du {area:17203} (ou de {area:150}) pour {area:442}, puis le bateau pour le {area:702}, et enfin le portail qui monte à {zone:1457}.",
		["{quest:5631} goes to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: take the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "{quest:5631} va à {npc:11401}, sur le balcon supérieur du temple de la Lune à {zone:1457}, à côté de {npc:7999} : prenez le bateau du {area:17203} (ou de {area:150}) pour {area:442}, puis le bateau pour le {area:702}, et enfin le portail qui monte à {zone:1457}.",
		["{quest:5632} goes to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: take the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "{quest:5632} va à {npc:11401}, sur le balcon supérieur du temple de la Lune à {zone:1457}, à côté de {npc:7999} : prenez le bateau du {area:17203} (ou de {area:150}) pour {area:442}, puis le bateau pour le {area:702}, et enfin le portail qui monte à {zone:1457}.",
		["{quest:5633} goes to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: take the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "{quest:5633} va à {npc:11401}, sur le balcon supérieur du temple de la Lune à {zone:1457}, à côté de {npc:7999} : prenez le bateau du {area:17203} (ou de {area:150}) pour {area:442}, puis le bateau pour le {area:702}, et enfin le portail qui monte à {zone:1457}.",
		["{quest:5673}: Laurena's letter"] = "{quest:5673} : la lettre de Laurena",
		["{quest:5674}: Nara's letter"] = "{quest:5674} : la lettre de Nara",
		["{quest:5675}: Rohan's letter"] = "{quest:5675} : la lettre de Rohan",
		["{spell:10797} and {spell:2651}"] = "{spell:10797} et {spell:2651}",
		["{spell:10797}: Josetta's letter"] = "{spell:10797} : la lettre de Josetta",
		["{spell:10797}: Joshua's letter"] = "{spell:10797} : la lettre de Joshua",
