} end)()
t.guides["forever/class/priest/touch-of-weakness-and-dark-sacrifice"] = (function() return {
		["At 10 in {zone:1411}, {npc:3706}, the priest trainer inside the barracks of {area:362}, hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}."] = "Au niveau 10 en {zone:1411}, {npc:3706}, le maître des prêtres dans la caserne de {area:362}, vous remet une lettre {spell:2652} pour {npc:4606} à {zone:1458}.",
		["At 10 in {zone:1412}, {npc:11407}, just south-west of {area:222}, hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}."] = "Au niveau 10 en {zone:1412}, {npc:11407}, juste au sud-ouest du {area:222}, vous remet une lettre {spell:2652} pour {npc:4606} à {zone:1458}.",
		["At 10 in {zone:1454}, {npc:6018} in the {object:172961} hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}. The zeppelin to {zone:1420} leaves from the tower outside {zone:1454}'s front gate."] = "Au niveau 10 à {zone:1454}, {npc:6018}, dans {object:172961}, vous remet une lettre {spell:2652} pour {npc:4606} à {zone:1458}. Le zeppelin pour {zone:1420} part de la tour devant la porte principale d'{zone:1454}.",
		["At 10 in {zone:1456}, {npc:3044}, the priest trainer in the cave under {area:1640}, hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}."] = "Au niveau 10 aux {zone:1456}, {npc:3044}, le maître des prêtres dans la grotte sous la {area:1640}, vous remet une lettre {spell:2652} pour {npc:4606} à {zone:1458}.",
		["At 10, go to {npc:4606}, the priest trainer in the {zone:1458}'s {object:36070}: she gives {quest:5658} and takes it back at once. No letter needed. From {area:159}, follow the road south to the ruined city of Lordaeron; the {zone:1458}'s lifts are at the back of the throne room. {quest:5658} strikes the next melee attacker for Shadow damage and lowers its melee attack power for 2 minutes."] = "Au niveau 10, allez voir {npc:4606}, la maîtresse des prêtres du {object:36070} de {zone:1458} : elle donne {quest:5658} et la reprend aussitôt. Pas besoin de lettre. Depuis {area:159}, suivez la route vers le sud jusqu'à la ville en ruine de Lordaeron ; les ascenseurs de {zone:1458} sont au fond de la salle du trône. {quest:5658} frappe le prochain attaquant de mêlée de dégâts d'Ombre et réduit sa puissance d'attaque en mêlée pendant 2 minutes.",
		["At 20 in {zone:1454}, {npc:6018} in the {object:172961} hands you a {quest:5644} letter for {npc:4606} in the {zone:1458}."] = "Au niveau 20 à {zone:1454}, {npc:6018}, dans {object:172961}, vous remet une lettre {quest:5644} pour {npc:4606} à {zone:1458}.",
		["At 20 in {zone:1456}, {npc:3044} in the cave under {area:1640} hands you a {quest:5644} letter for {npc:4606} in the {zone:1458}."] = "Au niveau 20 aux {zone:1456}, {npc:3044}, dans la grotte sous la {area:1640}, vous remet une lettre {quest:5644} pour {npc:4606} à {zone:1458}.",
		["At 20, {npc:4606} in the {object:36070} teaches {quest:5644} with a quest she gives and takes back at once (its text still speaks of {spell:2944}, which every priest now learns from the trainer)."] = "Au niveau 20, {npc:4606}, dans le {object:36070}, vous apprend {quest:5644} avec une quête qu'elle donne et reprend aussitôt (son texte parle encore de {spell:2944}, que tous les prêtres apprennent désormais auprès de leur maître).",
		["Hand the letter to {npc:4606} in the {zone:1458}'s {object:36070}: the zeppelin from the tower outside {zone:1454} lands in {zone:1420}, a short walk from the {zone:1458}."] = "Remettez la lettre à {npc:4606} dans le {object:36070} de {zone:1458} : le zeppelin qui part de la tour devant {zone:1454} se pose dans les {zone:1420}, à quelques pas de {zone:1458}.",
		["Hand the letter to {npc:4606} in the {zone:1458}'s {object:36070}: the zeppelin from the tower outside {zone:1454} lands in {zone:1420}."] = "Remettez la lettre à {npc:4606} dans le {object:36070} de {zone:1458} : le zeppelin qui part de la tour devant {zone:1454} se pose dans les {zone:1420}.",
		["Hand the letter to {npc:4606} in the {zone:1458}'s {object:36070}: travel to {zone:1454} and take the zeppelin to {zone:1420}."] = "Remettez la lettre à {npc:4606} dans le {object:36070} de {zone:1458} : rendez-vous à {zone:1454} et prenez le zeppelin pour les {zone:1420}.",
		["The Undead priest spells: {spell:2652} at 10, {quest:5644} (new in Forever) at 20. Free, no objectives."] = "Les sorts de prêtre mort-vivant : {spell:2652} au niveau 10, {quest:5644} (nouveau dans Forever) au niveau 20. Gratuits, sans objectif.",
		["{npc:11407}: take the {spell:2652} letter"] = "{npc:11407} : prenez la lettre {spell:2652}",
		["{npc:3044}: take his {quest:5644} letter"] = "{npc:3044} : prenez sa lettre {quest:5644}",
		["{npc:3044}: take his {spell:2652} letter"] = "{npc:3044} : prenez sa lettre {spell:2652}",
		["{npc:3706}: take his {spell:2652} letter"] = "{npc:3706} : prenez sa lettre {spell:2652}",
		["{npc:6018}: take his {quest:5644} letter"] = "{npc:6018} : prenez sa lettre {quest:5644}",
		["{npc:6018}: take his {spell:2652} letter"] = "{npc:6018} : prenez sa lettre {spell:2652}",
		["{quest:5644}: {npc:3044}'s letter"] = "{quest:5644} : la lettre de {npc:3044}",
		["{quest:5646}: {npc:6018}'s letter"] = "{quest:5646} : la lettre de {npc:6018}",
		["{quest:5660}: {npc:3706}'s letter"] = "{quest:5660} : la lettre de {npc:3706}",
		["{quest:5661}: {npc:11407}'s letter"] = "{quest:5661} : la lettre de {npc:11407}",
		["{quest:5662}: {npc:6018}'s letter"] = "{quest:5662} : la lettre de {npc:6018}",
		["{quest:5663}: {npc:3044}'s letter"] = "{quest:5663} : la lettre de {npc:3044}",
		["{spell:2652} and {quest:5644}"] = "{spell:2652} et {quest:5644}",
} end)()
t.guides["forever/class/rogue/blade-of-cunning-alliance"] = (function() return {
		["A dagger at 10 from your home town's rogue quests."] = "Une dague au niveau 10, tirée des quêtes de voleur de votre ville natale.",
		["At 10 {npc:1234}, the rogue trainer in the {area:2102} in {area:131}, sends you to {npc:5165} in {zone:1455}."] = "Au niveau 10, {npc:1234}, le maître des voleurs de {area:2102} à {area:131}, vous envoie voir {npc:5165} à {zone:1455}.",
		["At 10 {npc:3599}, the rogue trainer in the {area:186} inn, gives you a rose for {npc:4163} in {zone:1457}. If you lose the rose, abandon the quest and take it again."] = "Au niveau 10, {npc:3599}, le maître des voleurs de l'auberge de {area:186}, vous remet une rose pour {npc:4163} à {zone:1457}. Si vous perdez la rose, abandonnez la quête et reprenez-la.",
		["At 10 {npc:917}, the rogue trainer upstairs in the Lion's Pride Inn in {area:87}, gives you a package for {npc:332} in {zone:1453}. Train {spell:921} if you lack it: this chain needs it."] = "Au niveau 10, {npc:917}, le maître des voleurs à l'étage de l'auberge de la Fierté du lion à {area:87}, vous remet un paquet pour {npc:332} à {zone:1453}. Apprenez {spell:921} si vous ne l'avez pas : cette suite en a besoin.",
		["Back to Mathias Shaw"] = "Retour auprès de Mathias Shaw",
		["Back to {npc:4163}"] = "Retour auprès de {npc:4163}",
		["Back to {npc:5165}"] = "Retour auprès de {npc:5165}",
		["Head north to {zone:1453}. Shaw stands upstairs in the SI:7 building in {object:2100} (the quest says the Barracks; it means SI:7)."] = "Dirigez-vous vers le nord jusqu'à {zone:1453}. Shaw se tient à l'étage du bâtiment du SI:7, dans la {object:2100} (la quête parle de la caserne ; il s'agit du SI:7).",
		["Head west to {area:133}. Beside the road to its entrance stands a wooden spiral tower: {npc:6886} waits stealthed on the top platform, next to a level 10 {npc:1211}, so you only see him up close."] = "Dirigez-vous vers l'ouest jusqu'à {area:133}. Au bord de la route qui mène à l'entrée se dresse une tour en spirale en bois : {npc:6886} attend camouflé sur la plate-forme du sommet, à côté d'un {npc:1211} de niveau 10 ; vous ne le voyez donc que de près.",
		["Head west to {zone:1457}. {npc:4163} is below ground in the {area:1658}: the way down is the opening at the foot of the split tree left of the Arch Druid's tree, near the nightsaber trainer. Her map marker shows above ground."] = "Dirigez-vous vers l'ouest jusqu'à {zone:1457}. {npc:4163} est sous terre dans l'{area:1658} : l'accès est l'ouverture au pied de l'arbre fendu à gauche de l'arbre de l'archidruide, près du maître des sabres-de-nuit. Son marqueur sur la carte s'affiche à la surface.",
		["The {npc:6846} (level 10, a goblin) works in the dock house at {area:797}, on the river at Elwynn's southern edge, south of {area:87}. Stealth in and {spell:921} him from behind: the schedule never drops from his corpse. Do not open with {spell:2070} or a fight: he calls in three waves of bodyguards. Keep away from the fireplaces in the house; they burn you out of stealth. He is back 2 to 5 minutes after a death."] = "Le {npc:6846} (niveau 10, un gobelin) travaille dans la maison du quai, au {area:797}, sur la rivière à la limite sud de la forêt d'Elwynn, au sud de {area:87}. Entrez camouflé et utilisez {spell:921} sur lui par-derrière : le programme ne tombe jamais de son cadavre. N'ouvrez pas avec {spell:2070} ni par un combat : il appelle trois vagues de gardes du corps. Tenez-vous loin des cheminées de la maison ; elles vous font sortir du camouflage. Il revient 2 à 5 minutes après sa mort.",
		["{item:7298} (Alliance)"] = "{item:7298} (Alliance)",
		["{npc:332}, SI:7"] = "{npc:332}, SI:7",
		["{npc:5165} is in the {object:32383}, the rogue quarter in the north of {zone:1455}: go into the building with a shady dealer outside and down the stairs."] = "{npc:5165} est dans {object:32383}, le quartier des voleurs au nord de {zone:1455} : entrez dans le bâtiment devant lequel se tient un marchand louche et descendez l'escalier.",
		["{npc:6909} (level 12 satyr) lives out on a great branch north of the {area:264}: go through the V-shaped gap in the wall north of the glade and out along the branch. Pick his pocket for the journal; killing him does not give it, and a fight brings out three Minions of Sethir. He walks between the main branch and a side branch: wait stealthed at the far end of the main branch and pick him from behind when he comes back. Then {spell:2983} away. He is back 8 1/2 minutes after a death."] = "{npc:6909} (satyre de niveau 12) vit au bout d'une grande branche au nord de la {area:264} : passez par la brèche en V dans le mur au nord de la clairière et avancez le long de la branche. Faites-lui les poches pour le journal ; le tuer ne le donne pas, et un combat fait sortir trois Serviteurs de Sethir. Il fait des allers-retours entre la branche principale et une branche latérale : attendez camouflé au bout de la branche principale et volez-le par-derrière quand il revient. Puis utilisez {spell:2983} pour fuir. Il revient 8 minutes et demie après sa mort.",
} end)()
t.guides["forever/class/rogue/blade-of-cunning-horde"] = (function() return {
		["A dagger at 10 from your home town's rogue quests."] = "Une dague au niveau 10, grâce aux quêtes de voleur de votre ville natale.",
		["At 10 {npc:2130}, the rogue trainer upstairs in the {area:2119} in {area:159}, sends you to {quest:1885} in the {zone:1458}."] = "Au niveau 10, {npc:2130}, la maîtresse des voleurs à l'étage de la {area:2119} à {area:159}, vous envoie voir {quest:1885} à {zone:1458}.",
		["At 10 {npc:3170}, the rogue trainer in {area:362}, sends you to {quest:1859} in {zone:1454}. It is only a pointer: an Orc already in {zone:1454} can skip it and take {quest:1963} from {quest:1859} straight away."] = "Au niveau 10, {npc:3170}, le maître des voleurs de {area:362}, vous envoie voir {quest:1859} à {zone:1454}. Ce n'est qu'une indication : un orc déjà à {zone:1454} peut la passer et accepter directement {quest:1963} auprès de {quest:1859}.",
		["Back to {npc:6446}"] = "Retour auprès de {npc:6446}",
		["Back to {npc:6467}"] = "Retour auprès de {npc:6467}",
		["The {object:36073}"] = "Le {object:36073}",
		["{item:7209}, once you have the key"] = "{item:7209}, une fois la clé en main",
		["{item:7295}, from the satchel"] = "{item:7295}, dans la sacoche",
		["{item:7298} (Horde)"] = "{item:7298} (Horde)",
		["{npc:6446}'s reward"] = "Récompense de {npc:6446}",
		["{npc:6467} and {npc:2425}"] = "{npc:6467} et {npc:2425}",
		["{npc:6467} sends the ledger on to {npc:2425}, the big demon in the middle of the Hall of the Dark Lady in the {object:36126}, past its elite guards; the way in is the passage off the Apothecarium. If you lose the ledger, take another from {npc:6522}'s bookshelf."] = "{npc:6467} transmet le registre à {npc:2425}, le grand démon au milieu de la salle de la Dame noire, dans le {object:36126}, après ses gardes élites ; l'accès est le passage qui part de l'Apothicarium. Si vous perdez le registre, prenez-en un autre sur la bibliothèque de {npc:6522}.",
		["{npc:6494} (level 13, not elite) is a troll pirate on the {area:391} south of {area:392}: he walks the fenced hill path between the lower pirate camp by the beached ship and the upper camp by a big tree. Fight him at the foot of the hill, away from the camps. He always drops his satchel and is back 4 1/2 minutes after a death; one satchel per kill, so two rogues need two kills. Hand the satchel in unopened: picking its lock now destroys it and you must kill him again."] = "{npc:6494} (niveau 13, non élite) est un pirate troll sur la {area:391}, au sud de {area:392} : il arpente le chemin clôturé de la colline entre le camp pirate du bas, près du navire échoué, et le camp du haut, près d'un grand arbre. Combattez-le au pied de la colline, loin des camps. Il laisse toujours tomber sa sacoche et revient 4 minutes et demie après sa mort ; une sacoche par victoire, donc deux voleurs doivent le tuer deux fois. Rendez la sacoche sans l'ouvrir : la crocheter maintenant la détruit et vous devez le tuer à nouveau.",
		["{npc:6497} (level 13) walks the road between the {area:228} and the {zone:1458}, north of the {area:228}. He looks like a friendly traveller with no quest mark. Talk to him and pick both of his answers: he turns hostile. Kill him for the letter (it always drops). Fight him away from guards, who can take the kill and leave no loot; only one rogue per kill gets the letter. He is back 5 minutes after a death."] = "{npc:6497} (niveau 13) arpente la route entre le {area:228} et {zone:1458}, au nord du {area:228}. Il ressemble à un voyageur amical sans marque de quête. Parlez-lui et choisissez ses deux réponses : il devient hostile. Tuez-le pour la lettre (elle tombe toujours). Combattez-le loin des gardes, qui peuvent le tuer à votre place et ne rien laisser à fouiller ; un seul voleur par victoire obtient la lettre. Il revient 5 minutes après sa mort.",
		["{npc:6522} is in the Apothecarium, in its biggest room, where two huge guards watch a small bridge. His ledger is on the bookshelf in the back room behind him, not the shelf on the wall next to him."] = "{npc:6522} est dans l'Apothicarium, dans sa plus grande salle, où deux énormes gardes surveillent un petit pont. Son registre est sur la bibliothèque de la salle du fond derrière lui, pas sur l'étagère murale à côté de lui.",
		["{quest:1859} hands the satchel back: now open it. {npc:6466} (level 12) kneels by the innkeeper in the inn in the {object:172982}; stealth up and pick his pocket for {item:7208} (do not kill him: the key almost never drops). Players often kill him, so you may wait up to 5 minutes for him. Then use the key on {item:7209} in your bags. If you have trained {spell:1804}, you can pick the satchel's lock instead."] = "{quest:1859} vous rend la sacoche : ouvrez-la maintenant. {npc:6466} (niveau 12) est agenouillé près de l'aubergiste, dans l'auberge de {object:172982} ; camouflez-vous et faites-lui les poches pour obtenir {item:7208} (ne le tuez pas : la clé ne tombe presque jamais). Les joueurs le tuent souvent, vous devrez donc peut-être l'attendre jusqu'à 5 minutes. Utilisez ensuite la clé sur {item:7209} dans vos sacs. Si vous avez appris {spell:1804}, vous pouvez plutôt crocheter la serrure de la sacoche.",
		["{quest:1859} stands in the {object:172960}, the canyon under the {object:172982}. Trolls: take {quest:1963} from him at 10."] = "{quest:1859} se tient dans la {object:172960}, le canyon sous la {object:172982}. Trolls : prenez {quest:1963} auprès de lui au niveau 10.",
		["{quest:1885} stands in the {object:36073}."] = "{quest:1885} se tient dans le {object:36073}.",
} end)()
t.guides["forever/class/rogue/certificate-of-thievery"] = (function() return {
		["At 16 {npc:1234} in the {area:2102} in {area:131} sends you to {npc:5165} in {zone:1455}'s {object:32383}."] = "Au niveau 16, {npc:1234}, dans la {area:2102} à {area:131}, vous envoie voir {npc:5165} dans {object:32383} de {zone:1455}.",
		["At 16 {npc:3599} in the {area:186} inn sends you to {quest:2259} in {zone:1457}."] = "Au niveau 16, {npc:3599}, dans l'auberge de {area:186}, vous envoie voir {quest:2259} à {zone:1457}.",
		["At 16 {npc:917}, the rogue trainer upstairs in the Lion's Pride Inn in {area:87}, sends you to {npc:6946} in {zone:1453}. Taking it shuts out the other towns' breadcrumbs."] = "Au niveau 16, {npc:917}, le maître des voleurs à l'étage de l'auberge de la Fierté du lion à {area:87}, vous envoie voir {npc:6946} à {zone:1453}. L'accepter vous ferme les quêtes d'orientation des autres villes.",
		["Back to {npc:6966}"] = "Retournez voir {npc:6966}",
		["Head east through {zone:1429} into Redridge, or fly to {area:69}. {npc:6966} stands on a crate on one of the {area:69} docks, south of town; he gives you {item:5060} with the job ({npc:3090} in {area:69} sells more). {spell:1804} does not work without the tools in your bags."] = "Traversez la {zone:1429} vers l'est jusqu'aux Carmines, ou volez jusqu'à {area:69}. {npc:6966} se tient sur une caisse sur l'un des quais de {area:69}, au sud de la ville ; il vous remet des {item:5060} avec le travail ({npc:3090} à {area:69} en vend d'autres). {spell:1804} ne fonctionne pas sans les outils dans vos sacs.",
		["Your first lockpicking job at 16: {npc:6966}'s lockbox at {quest:2282}, for {quest:2300}."] = "Votre premier crochetage au niveau 16 : le coffret de {npc:6966} à {quest:2282}, pour le {quest:2300}.",
		["{npc:4214} stands in the {area:1658}. Then the boat from {area:702} to {area:442}, and the boat from {area:442} to {area:17203}."] = "{npc:4214} se tient dans l'{area:1658}. Prenez ensuite le bateau du {area:702} à {area:442}, puis le bateau d'{area:442} au {area:17203}.",
		["{npc:5165} is in the house with a shady dealer outside, in the {object:32383}, down the stairs. Then fly or take the {area:2257} to {zone:1453}."] = "{npc:5165} est dans la maison devant laquelle se tient un marchand louche, dans {object:32383}, en bas de l'escalier. Prenez ensuite un vol ou le {area:2257} jusqu'à {zone:1453}.",
		["{npc:6946} stands upstairs in the {quest:2300} building in {object:2100}, behind the rogue trainers. Before you leave: if you lack {spell:1804}, {npc:13283} in the {quest:2300} building teaches it; Lockpicking is the test of the next quest."] = "{npc:6946} se tient à l'étage du bâtiment du {quest:2300}, dans la {object:2100}, derrière les maîtres des voleurs. Avant de partir : si vous n'avez pas {spell:1804}, {npc:13283}, dans le bâtiment du {quest:2300}, vous l'apprend ; le crochetage est l'épreuve de la quête suivante.",
		["{quest:2282} stands east of {area:69}, up off the road; Blackrock orcs roam near it. Inside, the Practice Lockboxes come back almost at once: pick them until {object:121264} opens for you (about 25 Lockpicking). Your Lockpicking cap rises 5 per level, so a low character may stall. Some boxes are trapped (a frost trap, for one); the skill still goes up. On Forever level 20 spiders wander near the boxes: clear them first or bring a friend. The lockbox always holds the token and is back two seconds after use. Practise on while it still gives skill: the next class quest needs about 75."] = "{quest:2282} se dresse à l'est de {area:69}, en hauteur, à l'écart de la route ; des orcs Blackrock rôdent tout près. À l'intérieur, les coffrets d'entraînement reviennent presque aussitôt : crochetez-les jusqu'à ce que le {object:121264} s'ouvre pour vous (environ 25 en Crochetage). Votre maximum en Crochetage augmente de 5 par niveau, un personnage de bas niveau peut donc bloquer. Certains coffrets sont piégés (un piège de givre, par exemple) ; la compétence augmente quand même. Sur Forever, des araignées de niveau 20 errent près des coffrets : éliminez-les d'abord ou venez avec un ami. Le coffret contient toujours le jeton et revient deux secondes après usage. Continuez à vous entraîner tant que cela fait monter la compétence : la quête de classe suivante demande environ 75.",
} end)()
t.guides["forever/class/rogue/plundering-the-plunderers"] = (function() return {
		["At 16 {npc:3170}, the rogue trainer in {area:362}, sends you to {npc:3401} in {zone:1454}."] = "Au niveau 16, {npc:3170}, le maître des voleurs de {area:362}, vous envoie voir {npc:3401} à {zone:1454}.",
		["At 16 {npc:6467} in the {object:36073} sends you to {npc:3401} in {zone:1454}. Take {quest:1998} from him too; it is done in {zone:1421} at the end of this guide."] = "Au niveau 16, {npc:6467}, dans {object:36073}, vous envoie voir {npc:3401} à {zone:1454}. Prenez aussi {quest:1998} auprès de lui ; elle se termine en {zone:1421} à la fin de ce guide.",
		["Back to {npc:6467}"] = "Retour auprès de {npc:6467}",
		["Back to {npc:7161}"] = "Retour auprès de {npc:7161}",
		["Fly or walk to {area:392} on the {zone:1413} coast. {npc:7161} stands in a small shed near the bank, up the hill to the left before the docks. His Gizmotronic Apparatus beside him hands out what the job needs: take an {item:7970} and {item:5060} ({spell:1804} does not work without the tools in your bags)."] = "Volez ou marchez jusqu'à {area:392}, sur la côte des {zone:1413}. {npc:7161} se tient dans une petite cabane près de la banque, en haut de la colline à gauche avant les quais. Son appareil gizmotronique, à côté de lui, distribue ce dont le travail a besoin : prenez un {item:7970} et des {item:5060} ({spell:1804} ne fonctionne pas sans les outils dans vos sacs).",
		["Follow the coast south from {area:392} to the first beached pirate ship, the Tide Razor, and climb aboard up its bow. On the middle deck the Buccaneer's Strongboxes come back fast: pick them until your Lockpicking is about 30 (a few are trapped with a frost nova or turn you into a rat; picking still works as a rat). Keep picking while they still give skill: the poisons job at 20 ends at a lockbox that needs about 75, and these boxes are the closest practice. Then go down to the bottom hold and pick the lock of {object:123462}: it is empty, but opening it calls a giant level 50 {npc:7168} into the next room. Stay stealthed, put the {item:7970} on your action bar, target {npc:7168} and use it: the parrot shrinks to level 18. Kill it for the {item:7968}."] = "Suivez la côte vers le sud depuis {area:392} jusqu'au premier navire pirate échoué, le Tide Razor, et montez à bord par la proue. Sur le pont du milieu, les Coffres du boucanier reviennent vite : crochetez-les jusqu'à environ 30 en Crochetage (quelques-uns sont piégés d'une nova de givre ou vous transforment en rat ; on peut toujours crocheter sous forme de rat). Continuez tant qu'ils font monter la compétence : le travail des poisons au niveau 20 se termine par un coffret qui demande environ 75, et ces coffres sont l'entraînement le plus proche. Descendez ensuite dans la cale du fond et crochetez la serrure du Joyau des mers du Sud : il est vide, mais l'ouvrir fait venir un {npc:7168} géant de niveau 50 dans la salle voisine. Restez camouflé, placez le {item:7970} dans votre barre d'action, ciblez {npc:7168} et utilisez-le : le perroquet rétrécit au niveau 18. Tuez-le pour le {item:7968}.",
		["If you have no {item:5060} left, ask {npc:6566}, the outfitter in the {object:36073}."] = "S'il ne vous reste plus de {item:5060}, demandez-en à {npc:6566}, la marchande d'équipement du {object:36073}.",
		["Take the zeppelin from {zone:1454} to the {zone:1458} and head south into Silverpine. {quest:1998} (level 16) stands alone on the old ferry dock on {area:1338}, north-east of the {area:228}. His Uppercut knocks you back, so do not fight him at the dock's edge. He always drops his head and is back 4 1/2 minutes after a death."] = "Prenez le zeppelin d'{zone:1454} à {zone:1458} et dirigez-vous vers le sud dans la forêt des Pins-Argentés. {quest:1998} (niveau 16) se tient seul sur l'ancien quai du bac, au bord du {area:1338}, au nord-est du {area:228}. Son Uppercut vous projette en arrière : ne le combattez donc pas au bord du quai. Il laisse toujours tomber sa tête et revient 4 minutes et demie après sa mort.",
		["Ten {item:7676}, the rogue energy drink, from the Horde lockpicking jobs at 16."] = "Dix {item:7676}, la boisson d'énergie des voleurs, grâce aux missions de crochetage de la Horde au niveau 16.",
		["The Kirin Tor keep their reports in walled {area:233}, in south-east Silverpine. Facing the town hall, take the building on the right: the {object:103815} is in a corner room upstairs (any Lockpicking opens it; the {item:5060} must be in your bags). Three casters of level 19-20 guard that floor and see through stealth, one walking in and out of the strongbox room: time it or fight them one at a time."] = "Le Kirin Tor garde ses rapports dans la ville fortifiée d'{area:233}, dans le sud-est de la forêt des Pins-Argentés. Face à l'hôtel de ville, prenez le bâtiment de droite : le {object:103815} est dans une pièce d'angle à l'étage (n'importe quel niveau de Crochetage l'ouvre ; les {item:5060} doivent être dans vos sacs). Trois lanceurs de sorts de niveau 19-20 gardent cet étage et voient à travers le camouflage, l'un entrant et sortant de la pièce du coffre : choisissez le bon moment ou combattez-les un par un.",
		["Undead take the zeppelin from the towers outside the {zone:1458} to {zone:1411}. {npc:3401} and {quest:2379} stand in the {object:172960}, the canyon under the {object:172982}. Train {spell:1804} from {npc:3401} (or any rogue trainer) now if you lack it: this job is a lockpicking test."] = "Les morts-vivants prennent le zeppelin depuis les tours devant {zone:1458} jusqu'en {zone:1411}. {npc:3401} et {quest:2379} se tiennent dans {object:172960}, le canyon sous {object:172982}. Apprenez {spell:1804} auprès de {npc:3401} (ou de n'importe quel maître des voleurs) dès maintenant si vous ne l'avez pas : ce travail est une épreuve de crochetage.",
		["{item:7968}: {npc:7168}, after the {item:7970}"] = "{item:7968} : {npc:7168}, après le {item:7970}",
		["{npc:3401} and {quest:2379}"] = "{npc:3401} et {quest:2379}",
		["{npc:7161}: ten {item:7676}"] = "{npc:7161} : dix {item:7676}",
} end)()
t.guides["forever/class/rogue/poisons-alliance"] = (function() return {
		["/lay with the Doc targeted"] = "/lay en ciblant le docteur",
		["At 20 {npc:332}, upstairs in the SI:7 building in {object:2100}, sends you to {npc:7024} in {zone:1436}. This chain is how you learn Poisons on Forever, so do not skip it."] = "Au niveau 20, {npc:332}, à l'étage du bâtiment du SI:7 dans la {object:2100}, vous envoie voir {npc:7024} en {zone:1436}. C'est par cette suite que vous apprenez les poisons sur Forever : ne la passez pas.",
		["Back to {npc:7207}"] = "Retour auprès de {npc:7207}",
		["Forever teaches Poisons through this chain, not the trainer; the {item:7676} recipe comes with it."] = "Sur Forever, les poisons s'apprennent par cette suite de quêtes, pas auprès du maître ; la recette du {item:7676} vient avec.",
		["Get the key first. The {npc:7051} (level 23, not elite) starts at the tower entrance and walks a loop around the outside; it is the spiky-haired one trailing yellow sparkles. Stealth up and {spell:921} it from behind: it always has the key. It hits hard: if stealth breaks, {spell:2983} away. Watch for the pair of Defias Drones that also patrol."] = "Prenez d'abord la clé. Le {npc:7051} (niveau 23, non élite) part de l'entrée de la tour et fait une boucle autour de l'extérieur ; c'est celui aux cheveux hérissés qui laisse une traînée d'étincelles jaunes. Camouflez-vous et utilisez {spell:921} sur lui par-derrière : il a toujours la clé. Il frappe fort : si votre camouflage tombe, fuyez avec {spell:2983}. Méfiez-vous des deux Pantins défias qui patrouillent aussi.",
		["Head north through Elwynn to {zone:1453}; Mathias Shaw is upstairs in SI:7. He teaches Poisons and gives you the {item:7676} recipe. Poisons are made, not bought: each batch of {spell:8681} takes a {item:2928} and an {item:3371}, which {npc:1325} and {npc:1326} sell in {object:2100} next to SI:7. Buy a stack of each, open Poisons from your spellbook to make them, then use a poison on your weapon."] = "Remontez vers le nord à travers la forêt d'Elwynn jusqu'à {zone:1453} ; Mathias Shaw est à l'étage du SI:7. Il vous apprend les poisons et vous donne la recette du {item:7676}. Les poisons se fabriquent, ils ne s'achètent pas : chaque fournée de {spell:8681} demande une {item:2928} et une {item:3371}, que {npc:1325} et {npc:1326} vendent dans la {object:2100}, à côté du SI:7. Achetez une pile de chaque, ouvrez Poisons depuis votre grimoire pour les fabriquer, puis appliquez un poison sur votre arme.",
		["Kearnen hides stealthed against the west side of a big tree with two small trees in front of it, just north of {npc:7053}'s Defias tower in the far east of {zone:1436}, by the {zone:1431} border. Read {item:8046} for the tower's layout if you like."] = "Kearnen se cache, camouflé, contre le côté ouest d'un grand arbre devant lequel poussent deux petits arbres, juste au nord de la tour défias de {npc:7053}, tout à l'est de la {zone:1436}, près de la frontière du {zone:1431}. Lisez le {item:8046} pour connaître la disposition de la tour si vous le souhaitez.",
		["Klaven's journal"] = "Le journal de Klaven",
		["Poisons (Alliance)"] = "Poisons (Alliance)",
		["Sneak up the tower. Defias Tower Patrollers (23) and Sentries (24) guard the floors; an Ambush with a dagger kills them outright if you would rather clear them. {npc:7053}, a level 26 elite, waits on the top floor: Sap him, or bring a friend. The {object:123214} beside his desk needs Lockpicking of about 70-75 (practise on the boxes at {area:97} in Redridge first). A trick: while the Sentries are away, jump from the chair to the lamp to the bookshelf above the chest, step out of stealth and open the chest from there. Opening it poisons you with the {spell:9810}, which stops your stealth for a while and lets the drone see you; that is why the key comes first. Then get out."] = "Montez la tour en douce. Des Patrouilleurs défias (23) et des Sentinelles (24) gardent les étages ; une Embuscade avec une dague les tue d'un coup si vous préférez les éliminer. {npc:7053}, un élite de niveau 26, attend au dernier étage : assommez-le, ou venez avec un ami. Le {object:123214} à côté de son bureau demande environ 70-75 en Crochetage (entraînez-vous d'abord sur les coffrets d'{area:97}, dans les Carmines). Une astuce : pendant que les Sentinelles sont loin, sautez de la chaise à la lampe puis à la bibliothèque au-dessus du coffre, sortez du camouflage et ouvrez le coffre de là. L'ouvrir vous empoisonne avec le {spell:9810}, qui empêche votre camouflage un moment et permet au pantin de vous voir ; c'est pour cela qu'on prend la clé d'abord. Puis sortez.",
		["The cure's ingredients"] = "Les ingrédients du remède",
		["The {item:7923}"] = "La {item:7923}",
		["{item:7908}: the {object:123214}, top floor"] = "{item:7908} : le {object:123214}, dernier étage",
		["{npc:332}: Poisons"] = "{npc:332} : Poisons",
		["{quest:2607} still sits on you. {npc:7207} works in the cellar of the SI:7 building: the stairs down are under the stairs to the upper floor, behind {npc:1325}. Target him and type /lay (nothing after it) to be examined, then wait. If he does nothing, abandon the quest, take it again and wait until he asks you to lie down."] = "{quest:2607} pèse toujours sur vous. {npc:7207} travaille dans la cave du bâtiment du SI:7 : l'escalier qui descend est sous l'escalier qui monte à l'étage, derrière {npc:1325}. Ciblez-le et tapez /lay (rien après) pour être examiné, puis attendez. S'il ne fait rien, abandonnez la quête, reprenez-la et attendez qu'il vous demande de vous allonger.",
} end)()
t.guides["forever/class/rogue/poisons-horde"] = (function() return {
		["/salute {npc:3401}"] = "/saluer {npc:3401}",
		["Back to {npc:3401}"] = "Retour auprès de {npc:3401}",
		["Fly back to {zone:1454} ({area:392} or the Crossroads; dying at the tower and taking the spirit healer's way back to the Crossroads is quicker). Keep {item:8072} afterwards. Before you leave the {area:263}, buy {item:2928} and Empty Vials from Rekkul: once Hinott teaches Poisons, each batch of {spell:8681} takes one of each."] = "Retournez en vol à {zone:1454} (depuis {area:392} ou la Croisée ; mourir à la tour et prendre le chemin de l'esprit gardien jusqu'à la Croisée est plus rapide). Gardez la {item:8072} ensuite. Avant de quitter la {area:263}, achetez de la {item:2928} et des Fioles vides à Rekkul : une fois que Hinott vous aura appris les poisons, chaque fournée de {spell:8681} en demande une de chaque.",
		["Forever teaches Poisons through this chain, not the trainer; the {item:7676} recipe comes with it."] = "Sur Forever, les poisons s'apprennent par cette suite de quêtes, pas auprès du maître ; la recette du {item:7676} vient avec.",
		["Inside, floor by floor (everything comes back after 4 1/2 minutes): the Mutated Venture Co. Drones (level 25) on the ground floor die to one Ambush with a dagger; the Patrollers on the second floor take half their health from a one-point {spell:1943}; the Lookouts on the open third floor from a one-point {spell:2098}. {npc:7288} waits on the top floor: a level 23 elite, back 10 minutes after a kill. Open with Ambush (about half his health), then {spell:1776}, {spell:5277}, a healing potion and {item:7676}; a friend makes it easy. One head per kill. Then pick {object:129127} beside him for the cache: it poisons you with the {spell:9810}, which weakens your stealth and agility until {npc:2391} cures it."] = "À l'intérieur, étage par étage (tout revient au bout de 4 minutes et demie) : les Pantins mutés de la KapitalRisk (niveau 25) du rez-de-chaussée meurent d'une seule Embuscade avec une dague ; les Patrouilleurs du deuxième étage perdent la moitié de leur vie avec un {spell:1943} à un point ; les Sentinelles du troisième étage, à ciel ouvert, avec un {spell:2098} à un point. {npc:7288} attend au dernier étage : un élite de niveau 23, qui revient 10 minutes après sa mort. Ouvrez avec Embuscade (environ la moitié de sa vie), puis {spell:1776}, {spell:5277}, une potion de soins et du {item:7676} ; un ami rend la chose facile. Une tête par victoire. Crochetez ensuite le {object:129127} à côté de lui pour la cache : il vous empoisonne avec le {spell:9810}, qui affaiblit votre camouflage et votre agilité jusqu'à ce que {npc:2391} vous en guérisse.",
		["Keep {item:8066} in your bags and use it on him every time you come near, or he turns hostile. {npc:7287} (level 22) walks by the tower: hug the wall, stealth up behind him and {spell:921} the key. Killing him does not give it; if his pockets are empty, kill him and wait 4 1/2 minutes for him to come back."] = "Gardez le {item:8066} dans vos sacs et utilisez-le sur lui chaque fois que vous vous approchez, sinon il devient hostile. {npc:7287} (niveau 22) marche près de la tour : longez le mur, camouflez-vous derrière lui et utilisez {spell:921} pour la clé. Le tuer ne la donne pas ; si ses poches sont vides, tuez-le et attendez 4 minutes et demie qu'il revienne.",
		["Lockpicking about 75: pick the Buccaneer's Strongboxes on the Tide Razor"] = "Crochetage à environ 75 : crochetez les Coffres du boucanier du Tide Razor",
		["Lockpicking practice"] = "Entraînement au crochetage",
		["Poisons (Horde)"] = "Poisons (Horde)",
		["Take the zeppelin from {zone:1454} to the {zone:1458} and follow the road south through {zone:1421} into {area:287}, to {area:272}. {npc:2391} works in the building next to the flight path, beside {npc:2216}, a wagon outside. If you lost the Sample of Zanzil's Mixture, abandon and retake from {npc:3401}. Stay beside him for about a minute while he brews the cure; if it never finishes, abandon and retake from him. Then open Poisons from your spellbook to make {spell:8681} from Rekkul's dust and vials, and use it on your weapon."] = "Prenez le zeppelin d'{zone:1454} à {zone:1458} et suivez la route vers le sud à travers la {zone:1421} jusqu'à {area:287}, à {area:272}. {npc:2391} travaille dans le bâtiment à côté du maître de vol, à côté d'{npc:2216}, un chariot devant. Si vous avez perdu l'échantillon du mélange de Zanzil, abandonnez la quête et reprenez-la auprès de {npc:3401}. Restez à côté de lui environ une minute pendant qu'il prépare le remède ; s'il ne finit jamais, abandonnez la quête et reprenez-la auprès de lui. Ouvrez ensuite Poisons depuis votre grimoire pour fabriquer du {spell:8681} avec la poudre et les fioles de Rekkul, et appliquez-le sur votre arme.",
		["The Venture Co. tower"] = "La tour de la KapitalRisk",
		["Tide Razor"] = "Tide Razor",
		["Wait for the cure"] = "Attendez le remède",
		["{item:8051}, twice, at Fizzule"] = "{item:8051}, deux fois, sur Fizzule",
		["{item:8074}: {npc:7288} (elite)"] = "{item:8074} : {npc:7288} (élite)",
		["{item:8095}: clears the {spell:9810}"] = "{item:8095} : dissipe le {spell:9810}",
		["{npc:2391}: Poisons"] = "{npc:2391} : Poisons",
		["{npc:3401} stands in the {object:172960}, the canyon under the {object:172982}. Take the quest and wait: he speaks three lines and salutes you. After his third line, target him and type /salute. If it does not count, abandon the quest and take it again. The tower job ahead is built around Ambush, which needs a dagger: if you have none, Kareth, the blade merchant in the {object:172960}, sells a Jambiya."] = "{npc:3401} se tient dans {object:172960}, le canyon sous {object:172982}. Acceptez la quête et attendez : il prononce trois répliques et vous salue. Après sa troisième réplique, ciblez-le et tapez /salute. Si cela ne compte pas, abandonnez la quête et reprenez-la. Le travail de la tour qui suit repose sur Embuscade, qui demande une dague : si vous n'en avez pas, Kareth, le marchand de lames de {object:172960}, vend une Jambiya.",
		["{object:129127} at the end of the tower job needs Lockpicking of about 70-75. Train {spell:1804} from Gest or {npc:3401} in the {object:172960} if you lack it, carry {item:5060}, and pick the Buccaneer's Strongboxes on the middle deck of the Tide Razor, the beached pirate ship south of {area:392}: they come back fast. Your cap rises 5 per level."] = "Le {object:129127}, à la fin du travail de la tour, demande environ 70-75 en Crochetage. Apprenez {spell:1804} auprès de Gest ou de {npc:3401} dans {object:172960} si vous ne l'avez pas, emportez des {item:5060}, et crochetez les Coffres du boucanier sur le pont du milieu du Tide Razor, le navire pirate échoué au sud de {area:392} : ils reviennent vite. Votre maximum augmente de 5 par niveau.",
		["{quest:2458}: keep the {item:8051}"] = "{quest:2458} : gardez {item:8051}",
} end)()
t.guides["forever/class/rogue/ravenholdt"] = (function() return {
		["At 24 any capital's rogue trainer ({npc:332} or {npc:918} in {zone:1453}, Gest or Ormok in {zone:1454}, and the others) has an {item:17126} from {npc:13936} for you: ask for it in their talk window. Open it: the quest gives you the {item:17125} for {npc:6707}. Learn {spell:1846} from your trainer first if you have not; the way in is a test of it."] = "Au niveau 24, le maître des voleurs de n'importe quelle capitale ({npc:332} ou {npc:918} à {zone:1453}, Gest ou Ormok à {zone:1454}, et les autres) a pour vous une {item:17126} de {npc:13936} : demandez-la dans sa fenêtre de dialogue. Ouvrez-la : la quête vous donne le {item:17125} pour {npc:6707}. Apprenez d'abord {spell:1846} auprès de votre maître si ce n'est pas fait ; l'accès en est une épreuve.",
		["Back to {npc:13085}"] = "Retour auprès de {npc:13085}",
		["Back to {npc:13085}; the report sends you after the Perenolde heirlooms. Two towers stand among the {area:281}, in the middle of the {zone:1416}, held by ogres: the shield lies in the northern tower, the sword in the southern one, which elite ogres ring and watch from far off. Stay stealthed; nothing guards the heirlooms inside."] = "Retournez voir {npc:13085} ; le rapport vous lance sur la piste des reliques des Perenolde. Deux tours se dressent parmi les {area:281}, au milieu des {zone:1416}, tenues par des ogres : le bouclier se trouve dans la tour nord, l'épée dans la tour sud, entourée d'ogres élites qui guettent de loin. Restez camouflé ; rien ne garde les reliques à l'intérieur.",
		["Falconcrest's men make the handoff at the southern end of {area:1057}, the old wall between Arathi and {area:287}. Kill the two guarding the box and take the {item:275882}. Keep the {item:275706}: {npc:13085} wants it back with the shipment."] = "Les hommes de Falconcrest font l'échange à l'extrémité sud du {area:1057}, le vieux mur entre Arathi et {area:287}. Tuez les deux qui gardent la caisse et prenez la {item:275882}. Gardez l'{item:275706} : {npc:13085} le veut en retour avec la cargaison.",
		["Horde fly to {area:272}, Alliance to {area:271}. The trail to the manor is hard to see: it starts behind the plateau north of {area:275}, east of {area:272}, climbs into the hills and bends twice to a small tunnel. A chest sits in the tunnel: do not open it. Cast {spell:1846} near it and walk up close; that is the Rite of Cunning (it comes back after 5 minutes). Opening the chest calls Milton, an elite rogue of about level 32. Through the tunnel lies {area:3486}: {npc:6707} is upstairs inside. Do not attack anyone at the manor: it costs {npc:13936} reputation."] = "Horde : volez jusqu'à {area:272} ; Alliance : jusqu'à {area:271}. Le sentier vers le manoir est difficile à voir : il part derrière le plateau au nord du {area:275}, à l'est de {area:272}, grimpe dans les collines et tourne deux fois jusqu'à un petit tunnel. Un coffre se trouve dans le tunnel : ne l'ouvrez pas. Lancez {spell:1846} près de lui et approchez-vous ; c'est le Rite de la ruse (il revient au bout de 5 minutes). Ouvrir le coffre fait venir Milton, un voleur élite d'environ niveau 32. Au-delà du tunnel se trouve le {area:3486} : {npc:6707} est à l'étage, à l'intérieur. N'attaquez personne au manoir : cela coûte de la réputation auprès de {npc:13936}.",
		["In your mid 30s {npc:13085} has two more jobs; take both. Barton leads a Syndicate scouting party at {area:280}, in the east of the {zone:1416}, inside one of the houses with stealthed Syndicate around him. Pick his pocket for the report and do not kill him: he does not drop it. If you are lower than him he sees through stealth; Master of Deception helps, or Distract him, Vanish and come in from behind. {spell:921} can miss several times in a row."] = "Vers le milieu de la trentaine, {npc:13085} a deux autres travaux ; acceptez les deux. Barton mène une équipe d'éclaireurs du Syndicat à {area:280}, dans l'est des {zone:1416}, dans l'une des maisons, entouré de membres du Syndicat camouflés. Faites-lui les poches pour le rapport et ne le tuez pas : il ne le laisse pas tomber. Si vous êtes de plus bas niveau que lui, il voit à travers le camouflage ; le talent Maître de l'illusion aide, ou bien utilisez Distraction sur lui, puis Disparition, et revenez par-derrière. {spell:921} peut rater plusieurs fois de suite.",
		["Opens {area:3486}, the hidden rogue house in the Alterac hills, and {npc:13085}'s jobs against the Syndicate."] = "Ouvre le {area:3486}, la maison cachée des voleurs dans les collines d'Alterac, et les travaux de {npc:13085} contre le Syndicat.",
		["Rite of Cunning: {spell:1846} beside the tunnel chest"] = "Rite de la ruse : {spell:1846} près du coffre du tunnel",
		["She will not talk without something to bargain with. Her stash is upstairs in a house close to the keep: take the {item:275709}. If it is already open, wait for it to come back."] = "Elle ne parlera pas sans monnaie d'échange. Sa cachette est à l'étage d'une maison proche du donjon : prenez les {item:275709}. Si elle est déjà ouverte, attendez qu'elle revienne.",
		["Stromgarde's Syndicate Prowlers and Conjurors are elite (level 35-36): a rogue of 36 can slip past them, but fighting one alone is hard, so stay hidden or bring a friend. Put on the {item:275706} ({quest:96784} hands it to you at the footlocker) to pass as one of them; stealth or suspicious acts can break it. If the footlocker gave you no uniform, Anastasia hands you one with {quest:96785}. {npc:266847} is not inside the keep: she stands on a ledge on the outside of the castle wall. Jump across to it from the roof of the house beside the ledge."] = "Les Rôdeurs et Conjurateurs du Syndicat de Stromgarde sont élites (niveau 35-36) : un voleur de niveau 36 peut se glisser entre eux, mais en combattre un seul est difficile, alors restez caché ou venez avec un ami. Mettez l'{item:275706} ({quest:96784} vous le remet à la cantine) pour passer pour l'un des leurs ; le camouflage ou des actes suspects peuvent rompre le déguisement. Si la cantine ne vous a pas donné d'uniforme, Anastasia vous en remet un avec {quest:96785}. {npc:266847} n'est pas à l'intérieur du donjon : elle se tient sur une corniche à l'extérieur du mur du château. Sautez-y depuis le toit de la maison à côté de la corniche.",
		["The {item:17126}"] = "{item:17126}",
		["{area:324} in western Arathi is a Syndicate stronghold; to get in you need a uniform. {area:313}, in north-western Arathi, is held by Syndicate Highwaymen, Pathstalkers and Mercenaries (level 30-32): find the {object:656157} there and take the uniform; that ends {quest:96783}."] = "Le {area:324}, dans l'ouest d'Arathi, est une place forte du Syndicat ; pour y entrer, il vous faut un uniforme. Le {area:313}, dans le nord-ouest d'Arathi, est tenu par des Malandrins, des Éclaireurs et des Mercenaires du Syndicat (niveau 30-32) : trouvez-y la cantine du Syndicat et prenez l'uniforme ; cela termine {quest:96783}.",
		["{item:275635}, in the southern tower"] = "{item:275635}, dans la tour sud",
		["{item:275636}, in the northern tower"] = "{item:275636}, dans la tour nord",
		["{item:275709}: Anastasia's Stash"] = "{item:275709} : la cachette d'Anastasia",
		["{npc:13085}: 70 silver, 300 {npc:13936} reputation"] = "{npc:13085} : 70 pa, 300 points de réputation auprès de {npc:13936}",
		["{npc:13936} reputation"] = "Réputation {npc:13936}",
		["{npc:266216} is inside {area:275}, the Syndicate fortress south of the manor; he can stand in any of fifteen spots in the keep, so search. Quick and quiet, says {npc:13085}. Pick the pockets of the level 20-21 Syndicate Rogues, Shadow Mages and Watchmen on your way: they carry {quest:6701} for the guards' repeatable reputation quest."] = "{npc:266216} est à l'intérieur du {area:275}, la forteresse du Syndicat au sud du manoir ; il peut se tenir à l'un de quinze endroits du donjon, alors cherchez bien. Vite et sans bruit, dit {npc:13085}. Faites les poches des Voleurs, Mages de l'ombre et Sentinelles du Syndicat de niveau 20-21 sur votre chemin : ils portent des {quest:6701} pour la quête de réputation répétable des gardes.",
		["{quest:96784}: the {item:275706}"] = "{quest:96784} : l'{item:275706}",
} end)()
t.guides["forever/class/rogue/the-azure-key"] = (function() return {
		["Alliance fly to {area:3137}, Horde to {area:1237}. Only the level 50-51 Timbermaw Shamans in the furbolg hills of northern {zone:1447} carry the bag (the level 47-49 furbolgs further south do not): about one kill in thirty drops it. {spell:921} them instead and you lose no Timbermaw reputation; if you are Unfriendly or better with {area:1769}, mark them At War in your reputation panel first. They cast {spell:403} and {spell:6535}, heal each other and run at low health."] = "Alliance : volez jusqu'à {area:3137} ; Horde : jusqu'à {area:1237}. Seuls les Chamans Grumegueule de niveau 50-51, dans les collines des furbolgs du nord d'{zone:1447}, portent le sac (les furbolgs de niveau 47-49 plus au sud ne l'ont pas) : environ une victime sur trente le laisse tomber. Utilisez plutôt {spell:921} sur eux et vous ne perdez aucune réputation auprès des Grumegueules ; si vous êtes Inamical ou mieux avec le {area:1769}, cochez d'abord En guerre dans votre fenêtre de réputation. Ils lancent {spell:403} et {spell:6535}, se soignent entre eux et fuient quand leur vie est basse.",
		["At 50 {npc:3328} in the {object:172960} has it; so does {npc:4583} in the {zone:1458}'s {object:36073}."] = "Au niveau 50, {npc:3328}, dans {object:172960}, la propose ; {npc:4583}, dans {object:36073} de {zone:1458}, aussi.",
		["At 50 {npc:918} in {zone:1453}'s {object:2100} has it; so do Syurna in {zone:1457} and {npc:5165} in {zone:1455}."] = "Au niveau 50, {npc:918}, dans la {object:2100} de {zone:1453}, la propose ; tout comme Syurna à {zone:1457} et {npc:5165} à {zone:1455}.",
		["Back to Xylem"] = "Retour auprès de Xylem",
		["Look at the reward window before you hand in: Classic offered the {item:19982}, the {item:19984} or the {item:20255}, and Forever's notes say the choice may be gone."] = "Regardez la fenêtre des récompenses avant de rendre la quête : Classic proposait le {item:19982}, le {item:19984} ou les {item:20255}, et les notes de Forever disent que ce choix a peut-être disparu.",
		["Lord Ravenholdt"] = "Seigneur Ravenholdt",
		["Morphaz in the {area:1417}"] = "Morphaz dans {area:1417}",
		["Morphaz, a level 52 elite green drake, lives deep in the {area:1417}: a group of five, level 50-54. The temple stands in the {area:74}; climb into the sunken building, swim down through it and follow the passage to the portal. Horde: fly to {area:75}; Alliance: fly to {area:1438} and ride on. He is not there when you arrive: first kill the six troll guardians (elites of 50-52) on the platforms around the upper ring, which opens the way down (the left-hand ramp from the entrance) to {npc:5710} in the Pit of Sacrifice. Jammal'an's death brings out two drakes, Weaver and Dreamscythe; when both are dead, Morphaz and Hazzas appear together and fight as a pair. Their {spell:12533} is nature damage: nature protection potions help; poisons and {spell:2094} do not work on them. The key always drops. Hunters, Priests and Mages of 50 need Morphaz too: one clear serves them all."] = "Morphaz, un drake vert élite de niveau 52, vit au fond du {area:1417} : un groupe de cinq, niveau 50-54. Le temple se dresse dans l'{area:74} ; montez dans le bâtiment englouti, plongez à travers et suivez le passage jusqu'au portail. Horde : volez jusqu'à {area:75} ; Alliance : volez jusqu'au {area:1438} et continuez à monture. Il n'est pas là à votre arrivée : tuez d'abord les six gardiens trolls (élites de niveau 50-52) sur les plates-formes autour de l'anneau supérieur, ce qui ouvre la descente (la rampe de gauche depuis l'entrée) vers {npc:5710} dans la Fosse du sacrifice. La mort de Jammal'an fait sortir deux drakes, Tisserand et Fauche-rêve ; quand les deux sont morts, Morphaz et Hazzas apparaissent ensemble et combattent en duo. Leur {spell:12533} inflige des dégâts de nature : les potions de protection contre la nature aident ; les poisons et {spell:2094} ne fonctionnent pas sur eux. La clé tombe toujours. Les chasseurs, prêtres et mages de niveau 50 ont aussi besoin de Morphaz : une seule expédition sert à tous.",
		["Ravenholdt reputation"] = "Réputation Ravenholdt",
		["Ravenholdt reputation and experience at 50; Classic's item choice may be gone on Forever."] = "Réputation auprès de Ravenholdt et expérience au niveau 50 ; le choix d'objet de Classic a peut-être disparu sur Forever.",
		["The Forest Oozes (level 52-53, {spell:6907} up close) drop a fragment four times in five: the biggest group, seven of them, is in the {area:2497} hills of north-eastern {zone:1447}, four more south-east of {area:1237}. Pick their pockets before the kill for an extra fragment or two. Killing the Mistwing Ravagers and hippogryphs that share their spots makes more oozes appear."] = "Les Limons forestiers (niveau 52-53, {spell:6907} au corps à corps) laissent tomber un fragment quatre fois sur cinq : le plus grand groupe, sept d'entre eux, se trouve dans les collines des {area:2497}, au nord-est d'{zone:1447}, et quatre autres au sud-est de {area:1237}. Faites-leur les poches avant de les tuer pour un fragment ou deux de plus. Tuer les Ravageurs Brumaile et les hippogryphes qui partagent leurs emplacements fait apparaître davantage de limons.",
		["{area:3486} hides in the hills east of {area:272}. Horde fly to {area:272}, Alliance to {area:271}. The trail starts behind the plateau north of {area:275}, climbs into the hills and runs through a small tunnel into the {zone:1416}; Lord Jorach is inside the manor. Do not attack anyone at the manor: lost Ravenholdt reputation makes him refuse to speak to you."] = "Le {area:3486} se cache dans les collines à l'est de {area:272}. Horde : volez jusqu'à {area:272} ; Alliance : jusqu'à {area:271}. Le sentier part derrière le plateau au nord du {area:275}, grimpe dans les collines et passe par un petit tunnel jusque dans les {zone:1416} ; le seigneur Jorach est à l'intérieur du manoir. N'attaquez personne au manoir : une perte de réputation auprès de Ravenholdt le pousse à refuser de vous parler.",
		["{item:20022}: Morphaz, inside the temple"] = "{item:20022} : Morphaz, dans le temple",
		["{npc:8395}, camped below the cliffs just east of {area:1237}, teleports you up (dismount first); a trail leads to Xylem's tower."] = "{npc:8395}, qui campe au pied des falaises juste à l'est de {area:1237}, vous téléporte en haut (descendez d'abord de monture) ; un sentier mène à la tour de Xylem.",
		["{quest:8233} (Alliance)"] = "{quest:8233} (Alliance)",
		["{quest:8233} (Horde)"] = "{quest:8233} (Horde)",
} end)()
t.guides["forever/class/rogue/the-eye-of-bhossca"] = (function() return {
		["Back to the dead drop"] = "Retour à la boîte aux lettres",
		["C's dead drop"] = "La boîte aux lettres de C",
		["Place the eye in the {object:410369} near Pyrewood. Check a capital mailbox for C's payment letter on your next planned city visit, then return here for the reward quest. The payment may not be available immediately; do not repeat the infiltration just because the reward has not appeared."] = "Déposez l'œil dans la {object:410369} près de Bois-du-Bûcher. Vérifiez une boîte aux lettres de capitale pour la lettre de paiement de C lors de votre prochaine visite prévue en ville, puis revenez ici pour la quête de récompense. Le paiement peut ne pas être disponible tout de suite ; ne refaites pas l'infiltration simplement parce que la récompense n'est pas encore apparue.",
		["Solo route: Graveyard key, Library letter, Graveyard benches and coffer, then Library reliquary for the eye. Read the letter before the bench puzzle; check the disguise each time you change wings."] = "Itinéraire en solo : clé au Cimetière, lettre à la Bibliothèque, bancs et coffre au Cimetière, puis reliquaire de la Bibliothèque pour l'œil. Lisez la lettre avant l'énigme des bancs ; vérifiez le déguisement à chaque changement d'aile.",
		["The monastery stands in the far north-east of {zone:1420}. Go in alone, out of any group. Before entering, take the {spell:427592} from the Supply Locker in the stables behind the monastery and wear it; stealth and suspicious actions remove it, so put it back on after each wing change. In the Graveyard, in the Chamber of Atonement (the first big room), {spell:921} a {npc:4293} or Scarlet Crier for the {item:210963}. In the Library, open the Personal Letterbox in the Athenaeum with it and read the Confidential Message. It sends you back to sit on both benches between the two statues in the Graveyard. Watch for the mechanism's messages, then take the {item:210968} from the stone coffer: an elite stands by the coffer with a patrol behind it, but from beside the northern mausoleum you can turn the camera until the box shows and click it through the wall (an interact key works too). An elite ghost walks near the mausoleum; the broken piece at its edge keeps you out of its path. Then return to the Library for the locked reliquary and the eye. Avoid fighting through the instance."] = "Le monastère se dresse tout au nord-est des {zone:1420}. Entrez seul, hors de tout groupe. Avant d'entrer, prenez l'{spell:427592} dans le casier de fournitures des écuries derrière le monastère et portez-le ; le camouflage et les actes suspects le retirent, remettez-le donc après chaque changement d'aile. Au Cimetière, dans la salle de l'Expiation (la première grande salle), utilisez {spell:921} sur un {npc:4293} ou un Crieur écarlate pour obtenir la {item:210963}. À la Bibliothèque, ouvrez avec elle la boîte aux lettres personnelle de l'Athenaeum et lisez le message confidentiel. Il vous renvoie vous asseoir sur les deux bancs entre les deux statues du Cimetière. Surveillez les messages du mécanisme, puis prenez la {item:210968} dans le coffre de pierre : un élite se tient près du coffre avec une patrouille derrière lui, mais depuis le côté du mausolée nord vous pouvez tourner la caméra jusqu'à voir la boîte et cliquer dessus à travers le mur (une touche d'interaction fonctionne aussi). Un fantôme élite marche près du mausolée ; le morceau cassé à son bord vous tient hors de son chemin. Retournez ensuite à la Bibliothèque pour le reliquaire verrouillé et l'œil. Évitez de vous battre à travers l'instance.",
		["The {area:796}"] = "Le {area:796}",
		["The {item:277246}, C's payment for a solo job inside the {area:796}."] = "{item:277246}, le paiement de C pour une mission en solo dans le {area:796}.",
} end)()
t.guides["forever/class/rogue/the-horn-of-xelthos"] = (function() return {
		["Back to the dead drop"] = "Retour à la boîte aux lettres morte",
		["C's dead drop"] = "La boîte aux lettres morte de C",
		["Go in alone and use the {item:210186} at the courtyard gate. Players also report a freed prisoner opening the courtyard door for you: if you die while he is opening it, stay dead until it is open; it stays open once you release. If you know Vanish, bring {item:5140} and check its cooldown before entering; keep it ready for a failed approach. Pickpocket the sister in the dining hall for the {item:210213}, then the brother in the room reached by turning right at the top of the stairs for the {item:210212} (a level 20 rogue without Vanish may need ranks in Master of Deception to reach the second one unseen). Combine them somewhere safe: this breaks stealth. Free a bag slot first: opening the chest with full bags can use up the key without giving the horn. Return to the courtyard stables and use the combined key on the chest for the horn. Stay clear of the nearby elites; the minimum quest level does not guarantee a safe approach."] = "Entrez seul et utilisez la {item:210186} à la porte de la cour. Des joueurs signalent aussi qu'un prisonnier libéré vous ouvre la porte de la cour : si vous mourez pendant qu'il l'ouvre, restez mort jusqu'à ce qu'elle soit ouverte ; elle reste ouverte une fois que vous libérez votre esprit. Si vous connaissez Disparition, emportez de la {item:5140} et vérifiez son temps de recharge avant d'entrer ; gardez-la prête en cas d'approche ratée. Faites les poches de la sœur dans la salle à manger pour la {item:210213}, puis du frère dans la pièce à laquelle on accède en tournant à droite en haut de l'escalier pour la {item:210212} (un voleur de niveau 20 sans Disparition aura peut-être besoin de rangs dans le talent Maître de l'illusion pour atteindre le second sans être vu). Assemblez-les dans un endroit sûr : cela rompt le camouflage. Libérez d'abord un emplacement de sac : ouvrir le coffre avec des sacs pleins peut consommer la clé sans donner le cor. Retournez aux écuries de la cour et utilisez la clé assemblée sur le coffre pour obtenir le cor. Tenez-vous loin des élites voisins ; le niveau minimum de la quête ne garantit pas une approche sans danger.",
		["Place the horn in the {object:410369} near Pyrewood. The payment may not appear immediately: check a capital mailbox for C's follow-up letter on your next planned city visit, then return to this chest for the reward quest. Do not repeat the dungeon just because the payment is not yet offered."] = "Déposez le cor dans la {object:410369} près de Bois-du-Bûcher. Le paiement peut ne pas apparaître tout de suite : vérifiez une boîte aux lettres de capitale pour la lettre suivante de C lors de votre prochaine visite prévue en ville, puis revenez à ce coffre pour la quête de récompense. Ne refaites pas le donjon simplement parce que le paiement n'est pas encore proposé.",
		["The {item:277210}, C's payment for a solo job inside {area:236}."] = "La {item:277210}, le paiement de C pour une mission en solo dans le {area:236}.",
		["The {object:410369} is a chest in a house just outside {area:204} in southern Silverpine, south of {area:236}. Open it and read C's note: the job has to be done alone, out of any group."] = "La {object:410369} est un coffre dans une maison juste à l'extérieur du {area:204}, dans le sud de la forêt des Pins-Argentés, au sud du {area:236}. Ouvrez-le et lisez le message de C : le travail doit se faire seul, hors de tout groupe.",
		["{item:210183}, inside {area:236}"] = "{item:210183}, dans le {area:236}",
} end)()
t.guides["forever/class/shaman/call-of-air-alliance"] = (function() return {
		["At 30 {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:259023} in {zone:1417}. Your level 30 air totems (Grounding, {spell:10596}) need the {item:5178} he gives."] = "Au niveau 30, {npc:258098}, le maître des chamans de {zone:1455}, vous envoie voir {npc:259023} dans les {zone:1417}. Vos totems d'air du niveau 30 (Glèbe, {spell:10596}) ont besoin du {item:5178} qu'il vous donne.",
		["Five Twisted Air Totems. The Maraudine centaurs (level 36-40) north and north-east of {area:2408} in western {zone:1443} carry them; the Scouts drop one nearly every other kill. Wranglers Net and Disarm, Windchasers heal, Stormers throw {spell:9654}: pull one at a time. Respawn about five minutes."] = "Cinq Totems d'air tordus. Les centaures Maraudine (niveau 36-40) au nord et au nord-est du {area:2408}, dans l'ouest de {zone:1443}, en portent ; les Éclaireurs en laissent tomber un presque une fois sur deux. Les Querelleurs utilisent Filet et Désarmement, les Chasse-vent soignent, les Légion-tempête lancent {spell:9654} : attirez-les un par un. Réapparition en cinq minutes environ.",
		["Five Twisted Earth Totems. The Lost Ones (murlocs, level 34-39) north and north-east of {area:75} in the {zone:1435} carry them; most run for help when hurt."] = "Cinq Totems de terre tordus. Les Introuvables (murlocs, niveau 34-39) au nord et au nord-est de {area:75}, dans le {zone:1435}, en portent ; la plupart fuient chercher de l'aide quand ils sont blessés.",
		["Five Twisted Fire Totems. The Stonevault troggs (Skullthumpers, Bonesnappers and Shamans, level 37-41) south of {area:338} in the {zone:1418} carry them; the Shamans drop Fire Nova Totems and a {npc:3560}, the Bonesnappers run for help when hurt. Respawn about five minutes."] = "Cinq Totems de feu tordus. Les troggs Cavepierre (Skullthumpers, Bonesnappers et Chamans, niveau 37-41) au sud de la {area:338}, dans les {zone:1418}, en portent ; les Chamans posent des Totems Nova de feu et un {npc:3560}, les Bonesnappers fuient chercher de l'aide quand ils sont blessés. Réapparition en cinq minutes environ.",
		["Five Twisted Water Totems. The Mirefin murlocs (level 35-38) north-east of {area:496} in northern {zone:1445} carry them."] = "Cinq Totems d'eau tordus. Les murlocs Aileron boueux (niveau 35-38) au nord-est du {area:496}, dans le nord du {zone:1445}, en portent.",
		["The steam pools"] = "Les bassins de vapeur",
		["The {item:5178} that lets you place air totems, then a weapon of your choice at 40."] = "Le {item:5178} qui vous permet de poser des totems d'air, puis une arme de votre choix au niveau 40.",
		["Twisted Air Totems"] = "Totems d’air tordus",
		["Twisted Earth Totems"] = "Totems de terre tordus",
		["Twisted Fire Totems"] = "Totems de feu tordus",
		["Twisted Water Totems"] = "Totems d’eau tordus",
		["{area:1717} is a five-player dungeon at the southern edge of the {zone:1413} (the arrow points at its entrance); {npc:4421} (level 33 elite) is its last boss. She casts {spell:8292}, {spell:139} on her allies and Purity; the {item:274463} drops only from her."] = "{area:1717} est un donjon à cinq joueurs à la limite sud des {zone:1413} (la flèche pointe vers son entrée) ; {npc:4421} (élite de niveau 33) en est le dernier boss. Elle lance {spell:8292}, {spell:139} sur ses alliés et Pureté ; la {item:274463} ne tombe que sur elle.",
		["{item:212792}, from the {npc:216474}"] = "{item:212792}, sur la {npc:216474}",
		["{item:274463}, from {npc:4421}"] = "{item:274463}, sur {npc:4421}",
		["{npc:259023} camps in the hills just west of {area:321}, the Horde town in the north-east of Arathi: mind its guards. Fly to {area:320} and head north-east."] = "{npc:259023} campe dans les collines juste à l'ouest de {area:321}, la ville de la Horde au nord-est d'Arathi : méfiez-vous de ses gardes. Volez jusqu'au {area:320} et dirigez-vous vers le nord-est.",
		["{npc:259023} hands you the {item:268582}. {zone:1441} is far: the boat to Theramore and the road west, or fly to {area:489} on the {zone:1444} border and head east into the canyon. Place the {item:268582} at the steam pools north-west of {area:484} to call the corrupted elementals and then the {npc:216474}; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The {item:212792} drops about every other kill, and every group member can loot it."] = "{npc:259023} vous remet les {item:268582}. Les {zone:1441} sont loin : le bateau pour Theramore puis la route vers l'ouest, ou volez jusqu'à {area:489}, à la frontière de {zone:1444}, et dirigez-vous vers l'est dans le canyon. Placez les {item:268582} aux bassins de vapeur au nord-ouest du {area:484} pour appeler les élémentaires corrompus puis la {npc:216474} ; des huttiers Tranchecrins se joignent au combat pendant le rituel. Une quête de groupe : venez avec au moins un ou deux amis. L'{item:212792} tombe environ une fois sur deux, et chaque membre du groupe peut la ramasser.",
		["{npc:259023}: your {item:5178}"] = "{npc:259023} : votre {item:5178}",
		["{npc:6176} camps in the ruins in the east of {zone:1416}: from {area:272} follow the river east of town north into the hills. Pick your weapon: {item:280607}, {item:280605} or {item:280604}."] = "{npc:6176} campe dans les ruines à l'est des {zone:1416} : depuis {area:272}, suivez vers le nord, dans les collines, la rivière qui passe à l'est de la ville. Choisissez votre arme : {item:280607}, {item:280605} ou {item:280604}.",
		["{npc:6176}: the {item:280696} and your weapon"] = "{npc:6176} : la {item:280696} et votre arme",
		["{quest:94789} and the Tempest's Weapons (Alliance)"] = "{quest:94789} et les armes de la Tempête (Alliance)",
} end)()
t.guides["forever/class/shaman/call-of-air-horde"] = (function() return {
		["At 30 Skyborne shamans get their own {quest:96136}. {npc:259119} waits where the airship from Zephras Isle lands, in northern {zone:1412} beside {zone:1456}. Your level 30 air totems need the Air Totem Prate Cloudseer gives. If she has nothing for you, head up to {npc:5906} in {zone:1456} (next step): the trainers' {quest:96136} is open to Skyborne and gives the same totem."] = "Au niveau 30, les chamans éolides ont leur propre {quest:96136}. {npc:259119} attend là où se pose l'aéronef venu de l'Île de Zéphras, au nord de {zone:1412}, à côté des {zone:1456}. Vos totems d'air du niveau 30 exigent le Totem d'air que donne Prate Cherchenuée. Si elle n'a rien pour vous, montez voir {npc:5906} aux {zone:1456} (étape suivante) : la quête {quest:96136} des maîtres est ouverte aux Éolides et donne le même totem.",
		["At 30 {npc:5892} in the {object:172957} sends you to {npc:5905} in {zone:1441}. Your level 30 air totems (Grounding, {spell:10596}) need the {item:5178} she gives."] = "Au niveau 30, {npc:5892}, dans la {object:172957}, vous envoie voir {npc:5905} dans {zone:1441}. Vos totems d'air du niveau 30 (Glèbe, {spell:10596}) exigent le {item:5178} qu'elle donne.",
		["At 30 {npc:5906}, a shaman trainer on {area:1640} in {zone:1456}, sends you to {npc:5905} in {zone:1441}. Your level 30 air totems (Grounding, {spell:10596}) need the Air Totem Prate gives. Already carry {npc:5892}'s {quest:1531} from {zone:1454}? It goes to {npc:5905} too: skip {npc:5906}."] = "Au niveau 30, {npc:5906}, maître des chamans sur la {area:1640} aux {zone:1456}, vous envoie voir {npc:5905} dans {zone:1441}. Vos totems d'air du niveau 30 (Glèbe, {spell:10596}) exigent le Totem d'air que donne Prate. Vous avez déjà la quête {quest:1531} de {npc:5892}, venue d'{zone:1454} ? Elle mène aussi à {npc:5905} : passez {npc:5906}.",
		["Five Twisted Air Totems. The Maraudine centaurs (level 36-40) north and north-east of {area:2408} in western {zone:1443} carry them; the Scouts drop one nearly every other kill. Wranglers Net and Disarm, Windchasers heal, Stormers throw {spell:9654}: pull one at a time. Respawn about five minutes."] = "Cinq Totems d'air tordus. Les centaures Maraudine (niveau 36-40) au nord et au nord-est du {area:2408}, dans l'ouest de {zone:1443}, en portent ; les Éclaireurs en lâchent un presque une fois sur deux. Les Dresseurs lancent Filet et Désarmement, les Chasse-vent soignent, les Tempêtes lancent {spell:9654} : attirez-les un par un. Réapparition en cinq minutes environ.",
		["Five Twisted Earth Totems. The Lost Ones (murlocs, level 34-39) north and north-east of {area:75} in the {zone:1435} carry them; most run for help when hurt."] = "Cinq Totems de terre tordus. Les Introuvables (des murlocs, niveau 34-39) au nord et au nord-est de {area:75}, dans le {zone:1435}, en portent ; la plupart fuient chercher de l'aide quand ils sont blessés.",
		["Five Twisted Fire Totems. The Stonevault troggs (Skullthumpers, Bonesnappers and Shamans, level 37-41) south of {area:338} in the {zone:1418} carry them; the Shamans drop Fire Nova Totems and a {npc:3560}, the Bonesnappers run for help when hurt. Respawn about five minutes."] = "Cinq Totems de feu tordus. Les troggs de la Voûte de pierre (Cogne-crânes, Brise-os et Chamans, niveau 37-41) au sud de la {area:338}, dans les {zone:1418}, en portent ; les Chamans posent des totems Nova de feu et une {npc:3560}, les Brise-os fuient chercher de l'aide quand ils sont blessés. Réapparition en cinq minutes environ.",
		["Five Twisted Water Totems. The Mirefin murlocs (level 35-38) north-east of {area:496} in northern {zone:1445} carry them."] = "Cinq Totems d'eau tordus. Les murlocs Aileboue (niveau 35-38) au nord-est du {area:496}, dans le nord du {zone:1445}, en portent.",
		["Fly to {area:484}. {npc:5905} stands on a ledge above a cave mouth in the canyon wall north-east of the post, not inside the cave: climb the slope beside it. She also gives you an hour of faster attacks and running."] = "Volez jusqu'au {area:484}. {npc:5905} se tient sur une corniche au-dessus de l'entrée d'une grotte, dans la paroi du canyon au nord-est du poste, pas dans la grotte : montez la pente à côté. Elle vous donne aussi une heure d'attaques et de course plus rapides.",
		["The steam pools"] = "Les bassins de vapeur",
		["The {item:5178} that lets you place air totems, then a weapon of your choice at 40."] = "{item:5178}, qui permet de poser les totems d'air, puis une arme de votre choix au niveau 40.",
		["Twisted Air Totems"] = "Twisted Air Totems",
		["Twisted Earth Totems"] = "Twisted Earth Totems",
		["Twisted Fire Totems"] = "Twisted Fire Totems",
		["Twisted Water Totems"] = "Twisted Water Totems",
		["{area:1717} is a five-player dungeon at the southern edge of the {zone:1413} (the arrow points at its entrance); {npc:4421} (level 33 elite) is its last boss. She casts {spell:8292}, {spell:139} on her allies and Purity; the {item:274463} drops only from her."] = "{area:1717} est un donjon à cinq joueurs à la lisière sud des {zone:1413} (la flèche montre son entrée) ; {npc:4421} (élite de niveau 33) en est le dernier boss. Elle lance {spell:8292}, {spell:139} sur ses alliés et Purification ; la {item:274463} ne tombe que sur elle.",
		["{item:212792}, from the {npc:216474}"] = "{item:212792}, sur {npc:216474}",
		["{item:274463}, from {npc:4421}"] = "{item:274463}, sur {npc:4421}",
		["{npc:4722} stands at {area:484}."] = "{npc:4722} se tient au {area:484}.",
		["{npc:5905} hands you the {item:268582}. Place the {item:268582} at the steam pools north-west of {area:484} to call the corrupted elementals and then the {npc:216474}; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The {item:212792} drops about every other kill, and every group member can loot it."] = "{npc:5905} vous remet les {item:268582}. Posez les {item:268582} près des bassins de vapeur au nord-ouest du {area:484} pour appeler les élémentaires corrompus, puis la {npc:216474} ; des hurans Tranchecrin se joignent au combat pendant le rituel. Quête de groupe : venez avec au moins un ou deux amis. L'{item:212792} tombe environ une fois sur deux, et chaque membre du groupe peut la ramasser.",
		["{npc:5905}: your {item:5178}"] = "{npc:5905} : votre {item:5178}",
		["{npc:6176} camps in the ruins in the east of {zone:1416}: from {area:272} follow the river east of town north into the hills. Pick your weapon: {item:280607}, {item:280605} or {item:280604}; the {item:280696} shield comes with it."] = "{npc:6176} campe dans les ruines à l'est des {zone:1416} : depuis {area:272}, suivez vers le nord, dans les collines, la rivière à l'est du village. Choisissez votre arme : {item:280607}, {item:280605} ou {item:280604} ; le bouclier {item:280696} l'accompagne.",
		["{npc:6176}: the {item:280696} and your weapon"] = "{npc:6176} : le {item:280696} et votre arme",
		["{quest:1531} and the Tempest's Weapons (Horde)"] = "{quest:1531} et les armes de la Tempête (Horde)",
} end)()
t.guides["forever/class/shaman/call-of-earth-alliance"] = (function() return {
		["Back to Teo inside {area:77}. He hands you the {item:6635}: do not drink it yet."] = "Retournez voir Teo à l'intérieur d'{area:77}. Il vous remet le {item:6635} : ne le buvez pas encore.",
		["Bring the {item:6656} back to Teo inside {area:77}. Keep the {item:5175} in your bags for good: every earth totem needs it."] = "Rapportez le {item:6656} à Teo, à l'intérieur d'{area:77}. Gardez le {item:5175} dans vos sacs pour de bon : chaque totem de terre en a besoin.",
		["Iceclaw Bear Pendants"] = "Pendentifs d'ours griffeglace",
		["Lost the {quest:94472}?"] = "Vous avez perdu le {quest:94472} ?",
		["Only if the {quest:94472} is gone from your bags (drunk away from the stone, or sold): Teo gives you another."] = "Seulement si le {quest:94472} n'est plus dans vos sacs (bu loin de la pierre, ou vendu) : Teo vous en donne un autre.",
		["The Frostmane Troll Whelps (level 3-4) hold the snowy slopes west and south-west of {area:77}, and the Frostmane Novices (level 3-4, they throw Frostbolts from range) camp south of it. Both carry the pendants; they respawn in about three minutes."] = "Les Jeunes trolls Frostmane (niveau 3-4) occupent les pentes enneigées à l'ouest et au sud-ouest d'{area:77}, et les Novices Frostmane (niveau 3-4, ils lancent des Éclairs de givre à distance) campent au sud. Les deux portent les pendentifs ; ils réapparaissent en trois minutes environ.",
		["The Spirit Stone"] = "La Pierre de l'esprit",
		["The Spirit Stone stands on a snowy ridge north-west of {area:77}. The trail is easy to miss: it climbs the hill from the valley floor; at the small camp near the top turn left and the stone comes into view. Stand beside it, drink the {item:6635} and speak to the {npc:5891} before it fades."] = "La Pierre de l'esprit se dresse sur une crête enneigée au nord-ouest d'{area:77}. Le sentier est facile à manquer : il gravit la colline depuis le fond de la vallée ; au petit camp près du sommet, tournez à gauche et la pierre apparaît. Placez-vous à côté, buvez le {item:6635} et parlez à la {npc:5891} avant qu'elle ne disparaisse.",
		["Your {item:5175}: without it no earth totem can be cast. {spell:8071} comes with it at level 4."] = "Votre {item:5175} : sans lui, aucun totem de terre ne peut être posé. {spell:8071} vient avec, au niveau 4.",
		["it hands you the {item:6656}: keep it"] = "elle vous remet le {item:6656} : gardez-le",
		["the level 4 shaman spells"] = "les sorts de chaman du niveau 4",
		["{item:6635}, beside the Spirit Stone"] = "{item:6635}, à côté de la Pierre de l'esprit",
		["{npc:257446} trains shamans inside {area:77}, the hall at the south end of {area:132}. The quest opens at level 4. Never took it and now 10 or more? {npc:258098} in {zone:1455} or {npc:258113} in {area:131} gives you {quest:94373}, a pointer back to Teo: take it for the experience on the way."] = "{npc:257446} forme les chamans à l'intérieur d'{area:77}, la grande salle au sud de la {area:132}. La quête s'ouvre au niveau 4. Vous ne l'avez jamais prise et vous avez 10 ou plus ? {npc:258098} à {zone:1455} ou {npc:258113} à {area:131} vous donne {quest:94373}, qui vous renvoie vers Teo : prenez-la pour l'expérience en chemin.",
		["{npc:257446}: a new {quest:94472}"] = "{npc:257446} : un nouveau {quest:94472}",
		["{npc:257446}: {spell:8071} and your {item:5175}"] = "{npc:257446} : {spell:8071} et votre {item:5175}",
		["{quest:94373} (Alliance)"] = "{quest:94373} (Alliance)",
} end)()
t.guides["forever/class/shaman/call-of-earth-horde"] = (function() return {
		["Any Al'Aketh cultist can carry the {item:251924}: the Converts (level 2-3) around the standing stones just east of the village, or the Brutes and Neophytes (level 4) in the camp beyond {npc:252095}, south-west of the village. Keep killing until one drops it."] = "N'importe quel sectateur d'Al'Aketh peut porter le {item:251924} : les Convertis (niveau 2-3) autour des pierres levées juste à l'est du village, ou les Brutes et les Néophytes (niveau 4) dans le camp au-delà de {npc:252095}, au sud-ouest du village. Tuez-en jusqu'à ce que l'un d'eux le lâche.",
		["Back to Boro in {area:16635}. He hands you the {quest:1462}: do not drink it yet."] = "Retournez voir Boro à {area:16635}. Il vous remet le {quest:1462} : ne le buvez pas encore.",
		["Back to the Seer in {area:221}. She hands you the {quest:1462}: do not drink it yet."] = "Retournez voir la Prophétesse au {area:221}. Elle vous remet le {quest:1462} : ne le buvez pas encore.",
		["Back to {npc:5887} outside the Den. She hands you the {quest:1462}: do not drink it yet."] = "Retournez voir {npc:5887} devant l'Antre. Elle vous remet le {quest:1462} : ne le buvez pas encore.",
		["Bring the {item:6656} back to Boro. Keep the {item:5175} in your bags for good: every earth totem needs it."] = "Rapportez le {item:6656} à Boro. Gardez le {item:5175} dans vos sacs pour de bon : chaque totem de terre en a besoin.",
		["Bring the {item:6656} back to the Seer. Keep the {item:5175} in your bags for good: every earth totem needs it."] = "Rapportez le {item:6656} à la Prophétesse. Gardez le {item:5175} dans vos sacs pour de bon : chaque totem de terre en a besoin.",
		["Bring the {item:6656} back to {npc:5887} outside the Den. Keep the {item:5175} she gives you in your bags for good: every earth totem needs it."] = "Rapportez le {item:6656} à {npc:5887} devant l'Antre. Gardez dans vos sacs pour de bon le {item:5175} qu'elle vous donne : chaque totem de terre en a besoin.",
		["Felstalker Hooves"] = "Sabots de traqueur corrompu",
		["Felstalkers (level 3-4) prowl the slope below the {area:365}, the cave in the north of the valley, and just inside its mouth among the Vile Familiars. Nearly every {npc:3102} drops a hoof (four kills in five); they respawn in a little over three minutes."] = "Les Traqueurs corrompus (niveau 3-4) rôdent sur la pente sous le {area:365}, la grotte au nord de la vallée, et juste à l'entrée parmi les Vils quasits. Presque chaque {npc:3102} lâche un sabot (quatre fois sur cinq) ; ils réapparaissent en un peu plus de trois minutes.",
		["Lost the {quest:1462}?"] = "Vous avez perdu le {quest:1462} ?",
		["Lost the {quest:1463}?"] = "Vous avez perdu le {quest:1463} ?",
		["Only if the {quest:1462} is gone from your bags: the Seer gives you another."] = "Seulement si le {quest:1462} n'est plus dans vos sacs : la Prophétesse vous en donne un autre.",
		["Only if the {quest:1463} is gone from your bags (drunk away from the rock, or sold): {npc:5887} gives you another."] = "Seulement si le {quest:1463} n'est plus dans vos sacs (bu loin du rocher, ou vendu) : {npc:5887} vous en donne un autre.",
		["The Bristleback Shamans (level 3-4) stand among the quilboar huts of {area:358}, east of the camp, and throw the odd {spell:403}. Four kills in five drop a salve; they respawn in about four minutes."] = "Les Chamans Dos-hirsute (niveau 3-4) se tiennent parmi les huttes des hurans du {area:358}, à l'est du camp, et lancent de temps en temps un {spell:403}. Quatre fois sur cinq, ils lâchent un onguent ; ils réapparaissent en quatre minutes environ.",
		["The {area:16988}"] = "Le {area:16988}",
		["The {area:16988} is the hilltop shrine north-east of Boro: the path up starts on the hill just above the clearing where the flies were. Drink the {item:6635} beside the shrine and speak to the {npc:251166} before it fades."] = "Le {area:16988} est le sanctuaire au sommet de la colline, au nord-est de Boro : le chemin qui y monte part de la colline juste au-dessus de la clairière où se trouvaient les mouches. Buvez le {item:6635} à côté du sanctuaire et parlez à la {npc:251166} avant qu'elle ne disparaisse.",
		["Your {item:5175}: without it no earth totem can be cast. {spell:8071} comes with it at level 4."] = "Votre {item:5175} : sans lui, aucun totem de terre ne peut être posé. {spell:8071} vient avec, au niveau 4.",
		["it hands you the {item:6656}: keep it"] = "elle vous remet le {item:6656} : gardez-le",
		["the level 4 shaman spells"] = "les sorts de chaman du niveau 4",
		["{area:637} is a small pillar on a low mound due east of {npc:2991}'s well, east of the camp; it only shows from about fifteen yards away, and hostile boars graze around it. Stand beside it and drink the {item:6635}, then speak to the {npc:5891} before it fades (drink again if it does)."] = "Le {area:637} est un petit pilier sur un monticule bas, plein est du puits de {npc:2991}, à l'est du camp ; il n'apparaît qu'à une quinzaine de mètres, et des sangliers hostiles paissent autour. Placez-vous à côté et buvez le {item:6635}, puis parlez à la {npc:5891} avant qu'elle ne disparaisse (buvez de nouveau si c'est le cas).",
		["{area:639} sits on a ledge in the hills just south of the Den. The {area:638} up starts at the foot of the hills south-west of the Den, between two idle peons; it climbs south-west into the hills, then bends back east to the rock. Stand right beside the stone and drink the {item:6635}: the {npc:5891} appears for a short while, so speak to it at once (walk almost under it if it does not answer). Coming back, you can drop down the ledge towards the Den instead of walking the path."] = "Le {area:639} se trouve sur une corniche dans les collines, juste au sud de l'Antre. Le {area:638} qui y monte part du pied des collines au sud-ouest de l'Antre, entre deux péons oisifs ; il grimpe vers le sud-ouest dans les collines, puis repart vers l'est jusqu'au rocher. Placez-vous tout contre la pierre et buvez le {item:6635} : la {npc:5891} apparaît peu de temps, parlez-lui donc aussitôt (avancez presque sous elle si elle ne répond pas). Au retour, vous pouvez sauter de la corniche vers l'Antre au lieu de reprendre le sentier.",
		["{item:6635}, beside the shrine"] = "{item:6635}, à côté du sanctuaire",
		["{item:6635}, beside {area:637}"] = "{item:6635}, à côté du {area:637}",
		["{item:6635}, beside {area:639}"] = "{item:6635}, à côté du {area:639}",
		["{npc:251374}, the shaman trainer, stands in {area:16635}. The quest opens at level 3."] = "{npc:251374}, le maître des chamans, se tient à {area:16635}. La quête s'ouvre au niveau 3.",
		["{npc:251374}: {spell:8071} and your {item:5175}"] = "{npc:251374} : {spell:8071} et votre {item:5175}",
		["{npc:5887} stands just outside the Den, the cave in the middle of the {area:363}. The quest opens at level 4."] = "{npc:5887} se tient juste devant l'Antre, la grotte au milieu de la {area:363}. La quête s'ouvre au niveau 4.",
		["{npc:5887}: a new {quest:1463}"] = "{npc:5887} : un nouveau {quest:1463}",
		["{npc:5887}: {spell:8071} and your {item:5175}"] = "{npc:5887} : {spell:8071} et votre {item:5175}",
		["{npc:5888} stands in {area:221}. She may show no quest mark over her head: speak to her anyway. The quest opens at level 4."] = "{npc:5888} se tient au {area:221}. Elle n'affiche parfois aucun point d'exclamation au-dessus de la tête : parlez-lui quand même. La quête s'ouvre au niveau 4.",
		["{npc:5888}: a new {quest:1462}"] = "{npc:5888} : un nouveau {quest:1462}",
		["{npc:5888}: {spell:8071} and your {item:5175}"] = "{npc:5888} : {spell:8071} et votre {item:5175}",
		["{quest:1516} (Horde)"] = "{quest:1516} (Horde)",
} end)()
t.guides["forever/class/shaman/call-of-fire-alliance"] = (function() return {
		["At 10 {npc:258113}, the shaman trainer in {area:131}, or {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:257597}."] = "Au niveau 10, {npc:258113}, maîtresse des chamans à {area:131}, ou {npc:258098}, maître des chamans à {zone:1455}, vous envoie voir {npc:257597}.",
		["Back through the South Gate tunnel and up the trail to {npc:257597}' cave. Keep the {item:5176} in your bags for good: every fire totem needs it."] = "Retraversez le tunnel de la porte Sud et remontez le sentier jusqu'à la grotte de {npc:257597}. Gardez le {item:5176} dans vos sacs pour de bon : chaque totem de feu en a besoin.",
		["Back up the trail to {npc:257808}. He makes the {item:6636} from the tar and the pouch: keep it with the torch."] = "Remontez le sentier jusqu'à {npc:257808}. Il prépare le {item:6636} avec le goudron et la bourse : gardez-le avec la torche.",
		["Click the {object:61934} atop the shrine with the torch in your bags to place the ember, then click it again for the next quest: the lit {item:277329}."] = "Cliquez sur le {object:61934}, au sommet du sanctuaire, avec la torche dans vos sacs pour y déposer la braise, puis cliquez de nouveau dessus pour la quête suivante : la {item:277329} allumée.",
		["Climb on past {npc:257808} to the peak. Drink the {item:6636} beside the rock statue there to see the {npc:5893} (level 12): it waits until you strike, but grows stronger the longer it is left, and it is immune to fire. Open at once with {spell:8017} and {spell:8042}. Its {item:6655} drops every time."] = "Grimpez au-delà de {npc:257808} jusqu'au pic. Buvez le {item:6636} à côté de la statue de pierre pour voir la {npc:5893} (niveau 12) : elle attend que vous frappiez, mais devient plus forte à mesure qu'on la laisse, et elle est insensible au feu. Ouvrez aussitôt avec {spell:8017} et {spell:8042}. Sa {item:6655} tombe à chaque fois.",
		["Follow the road east to the tunnel towards {area:806}. Out of the first tunnel, keep left past {npc:1959} and the tower: a slim trail, hard to see but shown on the minimap, winds up the mountain to {npc:257597}' cave above the farm. He hands you the {item:6653}: keep it until the end of the chain."] = "Suivez la route vers l'est jusqu'au tunnel qui mène à l'{area:806}. À la sortie du premier tunnel, restez à gauche après {npc:1959} et la tour : un sentier étroit, difficile à voir mais indiqué sur la minicarte, serpente dans la montagne jusqu'à la grotte de {npc:257597}, au-dessus de la ferme. Il vous remet la {item:6653} : gardez-la jusqu'à la fin de la chaîne.",
		["From {npc:257597}' ledge you can drop carefully down the mountain into {zone:1432}, or walk back through the tunnel. {npc:257808} keeps the shrine on the peak just south of {area:144}: a hidden trail along a cliff ledge, marked by stone totems, climbs to it from the road north of the peak."] = "Depuis la corniche de {npc:257597}, vous pouvez descendre prudemment la montagne jusqu'au {zone:1432}, ou revenir par le tunnel. {npc:257808} garde le sanctuaire sur le pic juste au sud de {area:144} : un sentier caché le long d'une corniche, balisé de totems de pierre, y monte depuis la route au nord du pic.",
		["Lost the {quest:94473}?"] = "Vous avez perdu le {quest:94473} ?",
		["Only if the {quest:94473} is gone from your bags: {npc:257808} gives you another."] = "Seulement si le {quest:94473} n'est plus dans vos sacs : {npc:257808} vous en donne un autre.",
		["The Shrine of Eternal Flame"] = "L'autel de la Flamme éternelle",
		["The Stonesplinter Seers (level 13-14) stand among the troggs of {area:923} in the south of the loch, and in the trogg camps north-east of {area:144}. They throw {spell:1245113} from 40 yards and run for help when hurt: pull one at a time. Respawn about five minutes."] = "Les Prophètes Brisepierre (niveau 13-14) se tiennent parmi les troggs de la {area:923}, au sud du loch, et dans les camps de troggs au nord-est de {area:144}. Ils lancent des {spell:1245113} à 40 mètres et fuient chercher de l'aide quand ils sont blessés : attirez-les un par un. Réapparition en cinq minutes environ.",
		["The Tunnel Rat Geomancers (level 12-13) work only inside the {area:149} at the north end of the loch, past {area:144}. They cast {spell:2136} behind a {spell:134} and run for help at low health."] = "Les Géomanciens Rat des tunnels (niveau 12-13) ne travaillent qu'à l'intérieur de la {area:149}, au nord du loch, après {area:144}. Ils lancent {spell:2136} derrière un {spell:134} et fuient chercher de l'aide quand leur vie est basse.",
		["The {object:61934}"] = "Le {object:61934}",
		["Your {item:5176} for every fire totem, {spell:3599} with it, and Forever's {item:263412}."] = "Votre {item:5176} pour chaque totem de feu, {spell:3599} avec, et le {item:263412} propre à Forever.",
		["{item:6636}, beside the statue"] = "{item:6636}, à côté de la statue",
		["{npc:257597}: {spell:3599}, your {item:5176} and the {item:263412}"] = "{npc:257597} : {spell:3599}, votre {item:5176} et le {item:263412}",
		["{npc:257808}: a new {quest:94473}"] = "{npc:257808} : un nouveau {quest:94473}",
		["{npc:258113}, {area:131}; or {npc:258098}, {zone:1455}"] = "{npc:258113}, {area:131} ; ou {npc:258098}, {zone:1455}",
		["{quest:94449} (Alliance)"] = "{quest:94449} (Alliance)",
} end)()
t.guides["forever/class/shaman/call-of-fire-horde"] = (function() return {
		["At 10 {npc:252382}, the shaman trainer beside {npc:251968} in {area:16638}, hands you the {item:6653} ({npc:254082} offers the same quest). Already left the isle? A {quest:97243} sends you back to them: take the skycutter from the cliffs south of {area:17045}, north of {zone:1456}. Learn {spell:8050} from her now: {npc:268605}, later in the chain, only takes fire damage."] = "Au niveau 10, {npc:252382}, maîtresse des chamans à côté de {npc:251968} à {area:16638}, vous remet la {item:6653} ({npc:254082} propose la même quête). Vous avez déjà quitté l'île ? Une quête {quest:97243} vous renvoie vers eux : prenez le brise-ciel depuis les falaises au sud du {area:17045}, au nord des {zone:1456}. Apprenez {spell:8050} auprès d'elle maintenant : {npc:268605}, plus loin dans la chaîne, ne subit que les dégâts de feu.",
		["At 10 {npc:3066}, the shaman trainer in {area:222}, sends you to {npc:5907} in the {zone:1413}. Already carry {npc:5906}'s letter from {zone:1456}? It goes to {npc:5907} too: skip Narm."] = "Au niveau 10, {npc:3066}, maître des chamans au {area:222}, vous envoie voir {npc:5907} dans les {zone:1413}. Vous avez déjà la lettre de {npc:5906}, venue des {zone:1456} ? Elle mène aussi à {npc:5907} : passez Narm.",
		["At 10 {npc:3173}, the shaman trainer on the east side of {area:362}, sends you to {npc:5907} in the {zone:1413}. Already carry {npc:5892}'s letter from {zone:1454}? It goes to {npc:5907} too: skip {npc:3173}."] = "Au niveau 10, {npc:3173}, maître des chamans du côté est de {area:362}, vous envoie voir {npc:5907} dans les {zone:1413}. Vous avez déjà la lettre de {npc:5892}, venue d'{zone:1454} ? Elle mène aussi à {npc:5907} : passez {npc:3173}.",
		["Back east over the bridge, then south along the {zone:1411} bank of the river to where the mountains meet the water. The trail up starts at the foot of the mountain beside a small dark stone carved with symbols, near the quilboar camp; it is narrow, and a slip costs fall damage. {npc:5900} keeps the shrine at the top."] = "Repassez le pont vers l'est, puis longez vers le sud la rive de {zone:1411} jusqu'à l'endroit où les montagnes rejoignent l'eau. Le sentier qui monte part du pied de la montagne, à côté d'une petite pierre sombre gravée de symboles, près du camp des hurans ; il est étroit, et une glissade coûte des dégâts de chute. {npc:5900} garde le sanctuaire au sommet.",
		["Back to {npc:268592} at the Shrine of Flames."] = "Retournez voir {npc:268592} au sanctuaire des Flammes.",
		["Back to {npc:268592}. Accept the last quest, then wait by the {npc:268762} while he performs the ritual; when the fire spirits light the {object:148418}, hold the torch to it. From then you have six minutes: carry the flame straight to the {npc:268679} beside {npc:252382} in {area:16638}, with no detours or fights. Timer out? Abandon the quest and take it again from {npc:268592}."] = "Retournez voir {npc:268592}. Acceptez la dernière quête, puis attendez près du {npc:268762} pendant qu'il accomplit le rituel ; quand les esprits du feu allument la {object:148418}, tendez-y la torche. Vous avez alors six minutes : portez la flamme tout droit jusqu'au {npc:268679}, à côté de {npc:252382} à {area:16638}, sans détour ni combat. Temps écoulé ? Abandonnez la quête et reprenez-la auprès de {npc:268592}.",
		["Back up the trail to {npc:5900}. He makes the {quest:1464} from the tar and the pouch and hands it to you with the torch: keep both."] = "Remontez le sentier jusqu'à {npc:5900}. Il prépare le {quest:1464} avec le goudron et la bourse et vous le remet avec la torche : gardez les deux.",
		["Click the {object:61934} on the plateau with the torch in your bags to place the ember, then click it a second time: the next quest does not open by itself. It gives you the lit {item:277329}."] = "Cliquez sur le {object:61934} du plateau avec la torche dans vos sacs pour y déposer la braise, puis cliquez une deuxième fois : la quête suivante ne s'ouvre pas d'elle-même. Elle vous donne la {item:277329} allumée.",
		["Down the trail, back over the bridge to {npc:5907} by his tower. Keep the {item:5176} in your bags for good: every fire totem needs it."] = "Redescendez le sentier et repassez le pont jusqu'à {npc:5907}, près de sa tour. Gardez le {item:5176} dans vos sacs pour de bon : chaque totem de feu en a besoin.",
		["Drink the {item:6636} beside the {object:63674}, the big grey stone just below the summit, then climb to the plateau. Of the fire elementals there only the one in the middle can be attacked: it is level 12, immune to fire and grows stronger the longer the fight lasts, so open at once with {spell:8017} and {spell:8042} and leave the others alone. Its {item:6655} drops every time."] = "Buvez le {item:6636} à côté du sanctuaire chaman, la grande pierre grise juste sous le sommet, puis montez sur le plateau. Parmi les élémentaires de feu qui s'y trouvent, seul celui du milieu peut être attaqué : il est de niveau 12, insensible au feu et devient plus fort à mesure que le combat dure ; ouvrez donc aussitôt avec {spell:8017} et {spell:8042} et laissez les autres tranquilles. Sa {item:6655} tombe à chaque fois.",
		["Keep the {item:5176} in your bags for good: every fire totem needs it."] = "Gardez le {item:5176} dans vos sacs pour de bon : chaque totem de feu en a besoin.",
		["Lost the {quest:1464}?"] = "Vous avez perdu le {quest:1464} ?",
		["Only if the {quest:1464} is gone from your bags: {npc:5900} gives you another."] = "Seulement si le {quest:1464} n'est plus dans vos sacs : {npc:5900} vous en donne un autre.",
		["The Burning Blade Cultists (level 10-11, they call imps and cast {spell:348}) live deep in {area:371} north of {area:362}: climb the ramp just north-east of town and stay on the high ground above the ravines. The orcs at the cave mouth are not cultists; the cultists are further in, off to the left. Three kills in four drop a pouch. {area:817} by {zone:1454} is the wrong cave."] = "Les Sectateurs de la Lame ardente (niveau 10-11, ils appellent des diablotins et lancent {spell:348}) vivent au fond de la {area:371}, au nord de {area:362} : montez la rampe juste au nord-est du village et restez en hauteur au-dessus des ravins. Les orcs à l'entrée de la grotte ne sont pas des sectateurs ; les sectateurs sont plus loin, sur la gauche. Trois fois sur quatre, ils lâchent une bourse. Le {area:817}, près d'{zone:1454}, n'est pas la bonne grotte.",
		["The Shrine of Flames hides on the island's outer rim south-west of {area:16638}, just south-east of {area:16663}: {npc:268592} keeps it."] = "Le sanctuaire des Flammes se cache sur le bord extérieur de l'île, au sud-ouest de {area:16638}, juste au sud-est du {area:16663} : {npc:268592} le garde.",
		["The {npc:5893}"] = "La {npc:5893}",
		["The {object:148418}"] = "La {object:148418}",
		["The {object:61934}"] = "Le {object:61934}",
		["Your {item:5176} for every fire totem, {spell:3599} with it, and Forever's {item:263412}."] = "Votre {item:5176} pour chaque totem de feu, {spell:3599} avec, et le {item:263412} propre à Forever.",
		["the ritual, then the {npc:268679} in {area:16638}"] = "le rituel, puis le {npc:268679} à {area:16638}",
		["{item:6636}, beside the {object:63674}"] = "{item:6636}, à côté du sanctuaire chaman",
		["{npc:252382}: {spell:3599}, your {item:5176} and the {item:263412}"] = "{npc:252382} : {spell:3599}, votre {item:5176} et le {item:263412}",
		["{npc:268602} (level 10, a turncoat Windshaper with a single spawn) holds the farm north-east past {area:16638}, just south of the {area:16629}, on the hill west of the falls north of the {area:17675}. Kill him and take his heart."] = "{npc:268602} (niveau 10, un Façonneur-de-vent renégat qui n'apparaît qu'en un seul exemplaire) tient la ferme au nord-est après {area:16638}, juste au sud du {area:16629}, sur la colline à l'ouest des chutes au nord de la {area:17675}. Tuez-le et prenez son cœur.",
		["{npc:5900}: a new {quest:1464}"] = "{npc:5900} : un nouveau {quest:1464}",
		["{npc:5907} hands you the {item:6653}: keep it until the end of the chain."] = "{npc:5907} vous remet la {item:6653} : gardez-la jusqu'à la fin de la chaîne.",
		["{npc:5907}: {npc:3066}'s letter"] = "{npc:5907} : la lettre de {npc:3066}",
		["{npc:5907}: {npc:3173}'s letter"] = "{npc:5907} : la lettre de {npc:3173}",
		["{npc:5907}: {npc:5892}'s letter"] = "{npc:5907} : la lettre de {npc:5892}",
		["{npc:5907}: {npc:5906}'s letter"] = "{npc:5907} : la lettre de {npc:5906}",
		["{npc:5907}: {spell:3599}, your {item:5176} and the {item:263412}"] = "{npc:5907} : {spell:3599}, votre {item:5176} et le {item:263412}",
		["{object:660848} is the twisted stump on the hilltop by the Shen'dar Highlands Anchor Pylon, west of {area:16638}, in the hills south of the Windsong Crawlers' lakes. Knock on it to call {npc:268605} (level 10). The spirit shrugs off most magic: only fire hurts it, so keep {spell:8050} on it. Take its wooden mask."] = "La souche de Kuramaa est la souche tordue au sommet de la colline près du pylône d'ancrage des Hautes-terres de Shen'dar, à l'ouest de {area:16638}, dans les collines au sud des lacs des Clampants chantevent. Frappez dessus pour appeler {npc:268605} (niveau 10). L'esprit ignore presque toute la magie : seul le feu le blesse, maintenez donc {spell:8050} sur lui. Prenez son masque de bois.",
		["{object:660848}: knock on the bark"] = "La souche de Kuramaa : frappez sur l'écorce",
		["{quest:1522} (Horde)"] = "{quest:1522} (Horde)",
} end)()
t.guides["forever/class/shaman/call-of-water-alliance"] = (function() return {
		["At 20 {npc:258098}, the shaman trainer in {zone:1455}'s {object:32362}, sends you to {npc:258043} in {zone:1432}."] = "Au niveau 20, {npc:258098}, maître des chamans dans {object:32362} de {zone:1455}, vous envoie voir {npc:258043} au {zone:1432}.",
		["Back to {npc:258043} by {area:146} with the {item:7810}. He hands you the {item:6637} and the {item:7811}: keep both for {zone:1436}."] = "Retournez voir {npc:258043} près du {area:146} avec la {item:7810}. Il vous remet le {item:6637} et les {item:7811} : gardez les deux pour la {zone:1436}.",
		["Back to {npc:258043} with the {item:7813}. Keep the {item:5177} in your bags for good: every water totem needs it."] = "Retournez voir {npc:258043} avec l'{item:7813}. Gardez le {item:5177} dans vos sacs pour de bon : chaque totem d'eau en a besoin.",
		["Fill the {item:265732} at the bottom of the waterfalls below {npc:258203}'s cave, where the fresh water meets the brackish. {object:147516} dwarves roam near the falls."] = "Remplissez l'{item:265732} au pied des chutes sous la grotte de {npc:258203}, là où l'eau douce rencontre l'eau saumâtre. Des nains {object:147516} rôdent près des chutes.",
		["Fly to {area:108} and head south to {area:20}: {area:919} and the {object:619896} lie just north of it. Drink the {item:6637} by the shrine to see the {npc:5894} (level 22, {spell:8056} and {spell:122}; one spawn, back three minutes after a kill), defeat it for its bracers (always dropped), then place them and the {item:7811} on the {object:619896} (this, not {npc:258043}, ends the quest). Click the shrine again: the {npc:5895} rises beside it; speak to it before you walk off (if it is gone, abandon and take the quest again at the shrine). It gives you the {item:7813}."] = "Volez jusqu'à la {area:108} et allez au sud jusqu'à {area:20} : l'{area:919} et le {object:619896} se trouvent juste au nord. Buvez le {item:6637} près du sanctuaire pour voir la {npc:5894} (niveau 22, {spell:8056} et {spell:122} ; une seule apparition, de retour trois minutes après sa mort), vainquez-la pour ses brassards (toujours lâchés), puis posez-les avec les {item:7811} sur le {object:619896} (c'est cela, et non {npc:258043}, qui termine la quête). Cliquez de nouveau sur le sanctuaire : la {npc:5895} s'élève à côté ; parlez-lui avant de vous éloigner (si elle a disparu, abandonnez la quête et reprenez-la au sanctuaire). Elle vous donne l'{item:7813}.",
		["Lost the {quest:94616}?"] = "Vous avez perdu le {quest:94616} ?",
		["Only if the {quest:94616} is gone from your bags: {npc:258043} gives you another before you leave for {zone:1436}."] = "Seulement si le {quest:94616} n'est plus dans vos sacs : {npc:258043} vous en donne un autre avant votre départ pour la {zone:1436}.",
		["Take the boat from {area:150} to {area:442} (it stops in {area:271} on the way), then fly or walk south through {zone:1439} to {area:415} in {zone:1440}. Fill the {item:265772} in the lake around the town, then the boat back to Menethil."] = "Prenez le bateau de {area:150} à {area:442} (il fait escale à {area:271} en chemin), puis volez ou marchez vers le sud à travers {zone:1439} jusqu'à {area:415}, en {zone:1440}. Remplissez l'{item:265772} dans le lac autour de la ville, puis reprenez le bateau pour Menethil.",
		["The blue waterskin"] = "L'outre bleue",
		["The brown waterskin"] = "L'outre marron",
		["The red waterskin"] = "L'outre rouge",
		["The {item:5177} that lets you place water totems, and {spell:5394} with it."] = "Le {item:5177}, qui permet de poser les totems d'eau, et {spell:5394} avec.",
		["the {item:7810}, for {npc:258043}"] = "la {item:7810}, pour {npc:258043}",
		["{area:71} pour out of {area:68} at the east end of Redridge (fly from {zone:1455} to {area:69}). Fill the {item:265747} at their foot, where the Murloc Nightcrawlers gather; pull the murlocs off the spot first. If the skin vanishes without counting, abandon the quest and take it again from {npc:258203} for a new one."] = "Les {area:71} s'écoulent du {area:68} à l'extrémité est des Carmines (volez de {zone:1455} à {area:69}). Remplissez l'{item:265747} à leur pied, là où se rassemblent les Marcheurs de l'ombre murlocs ; éloignez d'abord les murlocs de l'endroit. Si l'outre disparaît sans compter, abandonnez la quête et reprenez-la auprès de {npc:258203} pour en avoir une nouvelle.",
		["{npc:258043}'s burrow hut stands on the north-western shore of the loch, below {area:146}, north of {area:144}."] = "La hutte-terrier de {npc:258043} se dresse sur la rive nord-ouest du loch, sous le {area:146}, au nord de {area:144}.",
		["{npc:258043}: a new {quest:94616}"] = "{npc:258043} : un nouveau {quest:94616}",
		["{npc:258043}: your {item:6637}"] = "{npc:258043} : votre {item:6637}",
		["{npc:258043}: {spell:5394} and your {item:5177}"] = "{npc:258043} : {spell:5394} et votre {item:5177}",
		["{npc:258203}'s family lives in a cave beneath the southern falls of the {zone:1437}, east of {area:836}: not in a town. Through the Algaz tunnel north of {zone:1432}, then east off the road."] = "La famille de {npc:258203} vit dans une grotte sous les chutes du sud des {zone:1437}, à l'est de {area:836} : pas dans une ville. Passez le tunnel d'Algaz au nord du {zone:1432}, puis quittez la route vers l'est.",
		["{quest:94494} (Alliance)"] = "{quest:94494} (Alliance)",
} end)()
t.guides["forever/class/shaman/call-of-water-horde"] = (function() return {
		["At 20 {npc:5892} in the {object:172957} sends you to {npc:5901} in the {zone:1413}. (Swart in {area:362} gives the same letter: carry either.)"] = "Au niveau 20, {npc:5892}, dans la {object:172957}, vous envoie voir {npc:5901} dans les {zone:1413}. (Swart, à {area:362}, donne la même lettre : prenez l'une ou l'autre.)",
		["At 20 {npc:5906}, a shaman trainer on {area:1640} in {zone:1456}, sends you to {npc:5901} in the {zone:1413}. ({npc:3066} in {area:222} gives the same letter: carry either.)"] = "Au niveau 20, {npc:5906}, maître des chamans sur la {area:1640} aux {zone:1456}, vous envoie voir {npc:5901} dans les {zone:1413}. ({npc:3066}, au {area:222}, donne la même lettre : prenez l'une ou l'autre.)",
		["Back to {npc:5899}. She gives you the {item:7810} for {npc:5901}."] = "Retournez voir {npc:5899}. Elle vous donne la {item:7810} pour {npc:5901}.",
		["Back to {npc:5901} south of {area:392}. Keep the {item:5177} in your bags for good: every water totem needs it."] = "Retournez voir {npc:5901}, au sud de {area:392}. Gardez le {item:5177} dans vos sacs pour de bon : chaque totem d'eau en a besoin.",
		["Click the {object:113791} to place the bracers and the drops. A few seconds later the pure {npc:5895} rises on the stone in the middle of the pool: speak to it while the {spell:8202} lasts (drink again by the stone if it has worn off). It gives you the {item:7813} for {npc:5901}. Gone before you could speak to it? Back at {npc:5901} ask for {quest:63} (a fresh {quest:972} for {npc:7007}, who stands just west of the shrine): hand it to Tiev, stay close while he calls the spirit back, then speak to it."] = "Cliquez sur le {object:113791} pour y poser les brassards et les gouttes. Quelques secondes plus tard, la {npc:5895} pure s'élève sur la pierre au milieu du bassin : parlez-lui tant que dure la {spell:8202} (buvez de nouveau près de la pierre si elle s'est dissipée). Elle vous donne l'{item:7813} pour {npc:5901}. Elle a disparu avant que vous lui parliez ? Retournez voir {npc:5901} et demandez {quest:63} (un nouveau {quest:972} pour {npc:7007}, qui se tient juste à l'ouest du sanctuaire) : remettez-le à Tiev, restez près de lui pendant qu'il rappelle l'esprit, puis parlez à celui-ci.",
		["Fly to the {area:228}. The shrine lies in a hollow just south-west of it: go round the back of the crypt to the thick tree between the two hills, hop past it onto the rocks and drop west down the slope to the pool (each drop costs a little health). Drink the {item:6637} beside the tall standing stone by the pool: several water elementals appear, and only the corrupt one near the middle can be attacked (Tab picks it). The {npc:5894} is level 22 and casts {spell:8056} and {spell:122}; if someone just killed it, it is back in about three minutes. Its bracers always drop."] = "Volez jusqu'au {area:228}. Le sanctuaire se trouve dans un creux juste au sud-ouest : faites le tour de la crypte par l'arrière jusqu'au gros arbre entre les deux collines, sautez sur les rochers derrière lui et descendez la pente vers l'ouest jusqu'au bassin (chaque saut coûte un peu de vie). Buvez le {item:6637} à côté de la haute pierre levée près du bassin : plusieurs élémentaires d'eau apparaissent, et seul le corrompu, près du milieu, peut être attaqué (Tab le cible). La {npc:5894} est de niveau 22 et lance {spell:8056} et {spell:122} ; si quelqu'un vient de la tuer, elle revient en trois minutes environ. Ses brassards tombent toujours.",
		["Lost the {quest:972}?"] = "Vous avez perdu le {quest:972} ?",
		["Only if the {quest:972} is gone from your bags: {npc:5901} gives you another."] = "Seulement si le {quest:972} n'est plus dans vos sacs : {npc:5901} vous en donne un autre.",
		["The muddy pond below {npc:5899}'s hut. Step right into the puddle before you use the {item:7766} (too far away and it refuses). Filling it calls a hostile {npc:3456} (level 20): kill it, and watch for the quilboar hunter by the pond, who may start shooting afterwards."] = "La mare boueuse sous la hutte de {npc:5899}. Entrez bien dans la flaque avant d'utiliser l'{item:7766} (trop loin, il refuse). Le remplir appelle un {npc:3456} hostile (niveau 20) : tuez-le, et méfiez-vous du chasseur huran près de la mare, qui peut se mettre à tirer ensuite.",
		["The right fountain stands in a ring of standing stones on the island of the small green lake south of {area:415}, west of Lake Mystral (not the island in Lake Mystral itself). From the {zone:1413} take the road north through the {area:1703} and on west. Water elementals and walking treants guard the lake and root you in place; an elite {npc:12836} roams {zone:1440} and can pass close by. Use the {item:7767} beside the fountain."] = "La bonne fontaine se dresse dans un cercle de pierres levées, sur l'île du petit lac vert au sud d'{area:415}, à l'ouest du lac Mystral (pas l'île du lac Mystral lui-même). Depuis les {zone:1413}, prenez la route vers le nord par le {area:1703}, puis continuez vers l'ouest. Des élémentaires d'eau et des tréants errants gardent le lac et vous immobilisent ; un {npc:12836} élite parcourt {zone:1440} et peut passer tout près. Utilisez l'{item:7767} à côté de la fontaine.",
		["The {item:5177} that lets you place water totems, and {spell:5394} with it."] = "Le {item:5177}, qui vous permet de poser des totems d'eau, et {spell:5394} avec.",
		["The {npc:5895}"] = "La {npc:5895}",
		["The {object:107045}"] = "Le {object:107045}",
		["The {object:107045} stands in the middle of {area:272}, just outside the church. From the {zone:1413}: the zeppelin from {zone:1454} to {zone:1420}, then south past the {zone:1458} and through {zone:1421} (or fly once you have the {area:272} flight path). {area:287} is contested: Alliance players may attack. Stand beside the well and use the {item:7768}."] = "Le {object:107045} se dresse au milieu de {area:272}, juste devant l'église. Depuis les {zone:1413} : le zeppelin d'{zone:1454} vers {zone:1420}, puis au sud après {zone:1458} et à travers la {zone:1421} (ou volez une fois que vous avez le trajet aérien de {area:272}). {area:287} est une zone contestée : les joueurs de l'Alliance peuvent attaquer. Placez-vous à côté du puits et utilisez l'{item:7768}.",
		["The {object:107046}"] = "Le {object:107046}",
		["The {object:113791}"] = "Le {object:113791}",
		["the {item:7810}, for {npc:5901}"] = "la {item:7810}, pour {npc:5901}",
		["{item:6637}, beside the standing stone"] = "{item:6637}, à côté de la pierre levée",
		["{item:7766}, standing in the puddle"] = "{item:7766}, debout dans la flaque",
		["{item:7767}, beside the fountain"] = "{item:7767}, à côté de la fontaine",
		["{item:7768}, beside the well"] = "{item:7768}, à côté du puits",
		["{npc:5899} lives in the southern {zone:1413}, south of {area:378}: her hut sits on a hilltop of {area:1701} with a spinning windmill beside it, and the way up is the ridge by the lone tree. Quilboar camp all around the hill; Stormhides, thunderhawks and hyenas roam the plains on the way."] = "{npc:5899} vit dans le sud des {zone:1413}, au sud du {area:378} : sa hutte se dresse au sommet d'une colline de la {area:1701}, avec un moulin à vent qui tourne à côté, et l'on y monte par la crête près de l'arbre isolé. Des hurans campent tout autour de la colline ; des Peaux-de-tonnerre, des faucons-tonnerre et des hyènes errent dans les plaines en chemin.",
		["{npc:5901} hands you the {item:6637} and the {item:7811}: take everything she offers before you leave for Silverpine, or you will be back for more."] = "{npc:5901} vous remet le {item:6637} et les {item:7811} : prenez tout ce qu'elle propose avant de partir pour la forêt des Pins-Argentés, sinon vous devrez revenir en chercher.",
		["{npc:5901} is not in {area:392}: take the small coast road south from {area:392} past the pirate camp and over a low hill; her fishing hut, with a shark strung up outside, stands by the water before the pirate ship. If you reach the ship you went too far."] = "{npc:5901} n'est pas à {area:392} : prenez la petite route côtière au sud de {area:392}, passez le camp des pirates et franchissez une colline basse ; sa cabane de pêcheur, avec un requin pendu devant, se dresse au bord de l'eau avant le navire pirate. Si vous arrivez au navire, vous êtes allé trop loin.",
		["{npc:5901}: Narm's letter"] = "{npc:5901} : la lettre de Narm",
		["{npc:5901}: Swart's letter"] = "{npc:5901} : la lettre de Swart",
		["{npc:5901}: a new {quest:972}"] = "{npc:5901} : un nouveau {quest:972}",
		["{npc:5901}: your {item:6637}"] = "{npc:5901} : votre {item:6637}",
		["{npc:5901}: {npc:5892}'s letter"] = "{npc:5901} : la lettre de {npc:5892}",
		["{npc:5901}: {npc:5906}' letter"] = "{npc:5901} : la lettre de {npc:5906}",
		["{npc:5901}: {spell:5394} and your {item:5177}"] = "{npc:5901} : {spell:5394} et votre {item:5177}",
		["{quest:63} (Horde)"] = "{quest:63} (Horde)",
} end)()
t.guides["forever/class/shaman/darkreaver"] = (function() return {
		["200 Horde reputation"] = "200 de réputation Horde",
		["A five-player dungeon event: {area:2057} lies under {area:2298}, the island town in the south-east of the {zone:1422}. In the {object:179746}'s basement, first clear every mob in the room, then use the {item:18746} at its centre: four waves of spirits follow, each closing with an Aspect mini-boss (the first wave weak and slow, the rest elite). Fight in a corner so nothing else joins, and drink between waves: it is long. Then {npc:14516} (level 62 elite) appears: he Cleaves, casts {spell:686} and {spell:6958}, and Dominates a player's mind against the group. His head always drops."] = "Un événement de donjon à cinq joueurs : {area:2057} se trouve sous {area:2298}, la ville insulaire au sud-est des {zone:1422}. Au sous-sol du Grand ossuaire, nettoyez d'abord tous les monstres de la salle, puis utilisez le {item:18746} en son centre : quatre vagues d'esprits suivent, chacune terminée par un mini-boss Aspect (la première vague faible et lente, les autres élites). Combattez dans un coin pour que rien d'autre ne s'en mêle, et buvez entre les vagues : c'est long. Ensuite {npc:14516} (élite de niveau 62) apparaît : il porte des Enchaînements, lance {spell:686} et {spell:6958}, et domine l'esprit d'un joueur contre le groupe. Sa tête tombe toujours.",
		["A {area:2057} fight at 60 for Horde reputation; the {item:20134} may be gone in Forever."] = "Un combat à {area:2057} au niveau 60 pour de la réputation auprès de la Horde ; le {item:20134} a peut-être disparu dans Forever.",
		["At 58 {npc:13417}, the shaman trainer in the {object:172957}, asks for two rare diamonds; every Horde shaman goes to him. Skyborne: Forever's quest page lists this quest for Orcs, Tauren and Trolls only: ask before you buy the diamonds."] = "Au niveau 58, {npc:13417}, maître des chamans dans la {object:172957}, demande deux diamants rares ; tous les chamans de la Horde vont le voir. Éolides : la page de quête de Forever ne réserve cette quête qu'aux Orcs, Taurens et Trolls : renseignez-vous avant d'acheter les diamants.",
		["Both diamonds are rare: the auction house is the quick way. Miners find the {item:12800} in about one Thorium vein in a hundred (the Small Thorium Veins north of {area:2418} in the {zone:1428} respawn every five minutes). The {item:18335} drops from high-level elites at about one in a hundred, best from the rare elite Revanchion (about one in nine)."] = "Les deux diamants sont rares : l'hôtel des ventes est le plus rapide. Les mineurs trouvent le {item:12800} dans environ un filon de thorium sur cent (les Petits filons de thorium au nord du {area:2418}, dans les {zone:1428}, réapparaissent toutes les cinq minutes). Le {item:18335} tombe sur les élites de haut niveau environ une fois sur cent, surtout sur l'élite rare Revanchion (environ une fois sur neuf).",
		["Two diamonds"] = "Deux diamants",
		["he hands you the {item:18746}"] = "il vous remet {item:18746}",
		["{npc:13417}: 200 Horde reputation; the {item:20134} may be gone"] = "{npc:13417} : 200 de réputation auprès de la Horde ; le {item:20134} a peut-être disparu",
		["{quest:7668} needs level 60."] = "{quest:7668} demande le niveau 60.",
} end)()
t.guides["forever/class/shaman/spirit-totem"] = (function() return {
		["A five-player dungeon: needs a group of five, about level 50-55. Fly to {area:75} and ride east. The {area:1417} ({area:1477}) stands in the middle of the {area:74}: climb the stairs on the ruin's south side, dive into the flooded hall, swim down through it and follow the stairs and passages down to the portal. Two feathers of each colour, one from each of six elite troll mini-bosses (level 51-52) on the balconies around the temple's great round room, every kill, and each player on the quest loots their own: Gasher and {npc:5716} the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green. Mijan heals the others ({spell:139}, a {npc:3560}): kill him first; Hukku summons guardians and throws Shadow Bolt Volleys."] = "Un donjon à cinq joueurs : il faut un groupe de cinq, vers le niveau 50-55. Volez jusqu'à {area:75} et chevauchez vers l'est. Le {area:1417} ({area:1477}) se dresse au milieu de l'{area:74} : montez les marches du côté sud de la ruine, plongez dans la salle inondée, nagez vers le fond et suivez les escaliers et les couloirs jusqu'au portail. Deux plumes de chaque couleur, une sur chacun des six mini-boss trolls élites (niveau 51-52) sur les balcons autour de la grande salle ronde du temple, à chaque victime, et chaque joueur ayant la quête ramasse la sienne : Balafreur et {npc:5716} l'ambre, Hukku et Mijan la bleue, Zolo et Loro la verte. Mijan soigne les autres ({spell:139}, une {npc:3560}) : tuez-le en premier ; Hukku invoque des gardiens et lance des Salves d'Éclairs de l'ombre.",
		["At 50 {npc:13417}, the shaman trainer in the {object:172957}, asks for the four elements for {npc:6176}."] = "Au niveau 50, {npc:13417}, maître des chamans dans la {object:172957}, demande les quatre éléments pour {npc:6176}.",
		["At 50 {npc:3032}, a shaman trainer on {area:1640} in {zone:1456}, asks for the four elements for {npc:6176}. Skyborne: Forever's quest page lists {quest:8410} and {quest:8412} for Orcs, Tauren and Trolls only; if {npc:3032} has nothing for you, {npc:6176}'s own {quest:8411} is open to every Horde race, but {quest:8412} after it may still turn you away."] = "Au niveau 50, {npc:3032}, maître des chamans sur la {area:1640} aux {zone:1456}, demande les quatre éléments pour {npc:6176}. Éolides : la page de quête de Forever ne réserve {quest:8410} et {quest:8412} qu'aux Orcs, Taurens et Trolls ; si {npc:3032} n'a rien pour vous, la quête {quest:8411} de {npc:6176} lui-même est ouverte à toutes les races de la Horde, mais {quest:8412} qui la suit peut encore vous refuser.",
		["Eight of each. Fly or ride to the {area:813} and on to the west edge of the {zone:1422}, north-west of {area:3197}: the Venom Mist Lurkers (level 50-51, they poison) give the {item:20610} and the Diseased Black Bears (level 51-52, {spell:3427}) the {item:20611}, one kill in five each; the two Carrion Vultures there drop either. The bigger Diseased Grizzlies and Plague Lurkers further east almost never drop them. A few bears and lurkers also roam south-east of {area:159} in Tirisfal."] = "Huit de chaque. Volez ou chevauchez jusqu'au {area:813}, puis jusqu'à la lisière ouest des {zone:1422}, au nord-ouest du {area:3197} : les Rôdeuses venimeuses des brumes (niveau 50-51, elles empoisonnent) donnent l'{item:20610} et les Ours noirs malades (niveau 51-52, {spell:3427}) la {item:20611}, une victime sur cinq chacun ; les deux Vautours putrides du coin lâchent l'un ou l'autre. Les Grizzlys malades et les Rôdeuses pestilentielles, plus gros, plus à l'est, ne les lâchent presque jamais. Quelques ours et rôdeuses errent aussi au sud-est de {area:159}, dans les clairières de Tirisfal.",
		["Experience and gold"] = "Expérience et or",
		["Experience and gold at 50, ending in the {area:1417}; the Classic item choice may be gone in Forever."] = "De l'expérience et de l'or au niveau 50, avec une fin au {area:1417} ; le choix d'objet de Classic a peut-être disparu dans Forever.",
		["One each of {item:7069}, Fire, Earth and Water; all four trade, so the auction house is quickest. To farm them, {zone:1417} has the exiles near {area:320} (level 38-39, about one kill in eight to ten, respawn under seven minutes): Thundering Exiles south-east of it (air), Rumbling Exiles south-west (earth), Burning Exiles far to the north-west (fire), and the {npc:2794} far to the south-west (water, about one in seven). Water comes easier from the Patches of Elemental Water in {zone:1447} (two in five) or {npc:14269} by {area:69} in Redridge."] = "Un exemplaire de chaque : {item:7069}, Feu, Terre et Eau ; les quatre s'échangent, l'hôtel des ventes est donc le plus rapide. Pour les farmer, les {zone:1417} ont les exilés près du {area:320} (niveau 38-39, environ une victime sur huit à dix, réapparition en moins de sept minutes) : les Exilés foudroyants au sud-est (air), les Exilés grondants au sud-ouest (terre), les Exilés ardents loin au nord-ouest (feu), et le {npc:2794} loin au sud-ouest (eau, environ une fois sur sept). L'eau s'obtient plus facilement sur les Flaques d'eau élémentaire d'{zone:1447} (deux fois sur cinq) ou sur {npc:14269} près de {area:69}, dans les Carmines.",
		["Spider eye and bear claw"] = "Œil d'araignée et griffe d'ours",
		["The four elements"] = "Les quatre éléments",
		["The {area:1417}"] = "Le {area:1417}",
		["{item:20606}: Gasher, {npc:5716}"] = "{item:20606} : Balafreur, {npc:5716}",
		["{item:20607}: Hukku, Mijan"] = "{item:20607} : Hukku, Mijan",
		["{item:20608}: Zolo, Loro"] = "{item:20608} : Zolo, Loro",
		["{item:7067}: Rumbling Exiles"] = "{item:7067} : Exilés grondants",
		["{item:7068}: Burning Exiles"] = "{item:7068} : Exilés ardents",
		["{item:7069}: Thundering Exiles"] = "{item:7069} : Exilés foudroyants",
		["{item:7070}: the {npc:2794}, or {zone:1447}'s water patches"] = "{item:7070} : le {npc:2794}, ou les flaques d'eau d'{zone:1447}",
		["{npc:6176} camps in the ruins of the east of {zone:1416}: from {area:272} follow the river east of town north into the hills."] = "{npc:6176} campe dans les ruines à l'est des {zone:1416} : depuis {area:272}, suivez vers le nord, dans les collines, la rivière à l'est du village.",
		["{npc:6176}: the old item choice may be gone, count on the experience"] = "{npc:6176} : l'ancien choix d'objet a peut-être disparu, comptez sur l'expérience",
		["{quest:8412} and {quest:8413}"] = "{quest:8412} et {quest:8413}",
} end)()
t.guides["forever/class/warlock/dread-mage-hat"] = (function() return {
		["A cloth hat in your late 20s: Zardeth's errand for any Alliance player pays warlocks this extra."] = "Un chapeau en tissu vers la fin de la vingtaine : la course de Zardeth, ouverte à tout joueur de l'Alliance, rapporte ce bonus aux démonistes.",
		["At 25 {npc:1435}, in the cellar of the {object:2164} in the {object:2101} (beside the warlock trainers), wants two ingredients for a brew. Do it when your leveling takes you to {zone:1431} and the {zone:1437}."] = "Au niveau 25, {npc:1435}, dans la cave de l'{object:2164} du {object:2101} (à côté des maîtres des démonistes), veut deux ingrédients pour une infusion. Faites-la quand votre progression vous mène au {zone:1431} et dans les {zone:1437}.",
		["Back to Zardeth once more: he offers warlocks a reward, which his imp {npc:1733}, standing beside him, hands over."] = "Retournez voir Zardeth une dernière fois : il offre une récompense aux démonistes, que son diablotin {npc:1733}, à côté de lui, vous remet.",
		["Back to Zardeth. He brews the {item:2788} and gives it to you for {npc:1439} in the Hall of Petitioners, the first hall on the right inside {object:2117}."] = "Retournez voir Zardeth. Il brasse la {item:2788} et vous la donne pour {npc:1439}, dans la salle des Requérants, la première salle à droite dans le {object:2117}.",
		["The root grows at the water's edge in the pool below the small falls east of {area:836}, beside the {object:147516} cave below the {area:146}: a tall, spiky wooden root, not at the foot of the dam itself."] = "La racine pousse au bord de l'eau, dans le bassin sous les petites chutes à l'est de {area:836}, à côté de la grotte {object:147516} sous le {area:146} : une haute racine de bois hérissée, pas au pied du barrage lui-même.",
		["{area:1098} stands in the north-east of {zone:1431}, north of {area:42}. The {object:321} is a small white flower low in the grass of the fenced garden beside Stalvan's house: hard to see, so sweep the garden with your mouse. Fetid Corpses (level 29) wander the grounds and come quickly: at 25, send your voidwalker at the nearest one, grab the flower and leave. {npc:315} (32) is inside the house; leave him alone."] = "Le {area:1098} se dresse au nord-est du {zone:1431}, au nord de {area:42}. La {object:321} est une petite fleur blanche basse dans l'herbe du jardin clôturé à côté de la maison de Stalvan : difficile à voir, balayez donc le jardin avec la souris. Des Cadavres fétides (niveau 29) errent sur le domaine et arrivent vite : au niveau 25, envoyez votre marcheur du Vide sur le plus proche, prenez la fleur et partez. {npc:315} (32) est dans la maison ; laissez-le tranquille.",
} end)()
t.guides["forever/class/warlock/enchanted-gold-bloodrobe"] = (function() return {
		["A rare cloth robe for your 30s from {npc:6266}; its last parts wait for levels 35 and 37."] = "Une robe en tissu rare pour vos niveaux 30, confectionnée par {npc:6266} ; ses dernières pièces attendent les niveaux 35 et 37.",
		["At 31 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "Au niveau 31, {npc:3326}, dans la {object:172960}, vous envoie voir {npc:6266} à {area:392}. Achetez d'abord une {item:5770} et une {item:3577} (étapes suivantes) pour vous éviter un voyage.",
		["At 31 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}; the zeppelin from {zone:1420} flies to {zone:1411}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "Au niveau 31, {npc:4563}, dans le {object:36082}, vous envoie voir {npc:6266} à {area:392} ; le zeppelin de {zone:1420} vole vers {zone:1411}. Achetez d'abord une {item:5770} et une {item:3577} (étapes suivantes) pour vous éviter un voyage.",
		["At 31 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "Au niveau 31, {npc:461}, dans l'{object:2164} du {object:2101}, vous envoie voir {npc:6266} à {area:392}. Achetez d'abord une {item:5770} et une {item:3577} (étapes suivantes) pour vous éviter un voyage.",
		["At 31 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "Au niveau 31, {npc:5172}, à {zone:1455}, vous envoie voir {npc:6266} à {area:392}. Achetez d'abord une {item:5770} et une {item:3577} (étapes suivantes) pour vous éviter un voyage.",
		["Back to {npc:2670} in {area:35}: he offers {quest:4785} as a quest you hand straight back to him. He may show no quest marker; talk to him anyway."] = "Retournez voir {npc:2670} à {area:35} : il propose {quest:4785}, une quête que vous lui rendez aussitôt. Il n'affiche parfois aucun marqueur de quête ; parlez-lui quand même.",
		["Back to {npc:6266}"] = "Retour auprès de {npc:6266}",
		["Back to {npc:6266} with the thread, the coals and a {item:6265}. Then wait beside her while she works the robe (do not attack her: the quest log calls it a kill), and speak to her again."] = "Retournez voir {npc:6266} avec le fil, les charbons et un {item:6265}. Attendez ensuite à côté d'elle pendant qu'elle travaille la robe (ne l'attaquez pas : le journal de quêtes parle de la tuer), puis parlez-lui de nouveau.",
		["Hatefury satyrs"] = "Satyres Fielfurie",
		["Tailors sew the {item:5770} from a rare pattern; miners smelt Gold Bars from {item:2776}. Everyone else buys both at the Auction House. If you wear the robe, take it off: {npc:6266} keeps it."] = "Les tailleurs cousent la {item:5770} grâce à un patron rare ; les mineurs fondent des Barres d'or à partir de {item:2776}. Tous les autres achètent les deux à l'hôtel des ventes. Si vous portez la robe, retirez-la : {npc:6266} la garde.",
		["The Burning Exiles (level 38-39), fire elementals at the {area:334} in western {zone:1417}, drop the coal about one time in three. The guide waits for level 37 first: below it they hit too hard to solo. They resist fire: {spell:686} and Corruption. The Cresting Charms from the Cresting Exiles near {area:321} finish one off once you have hurt it. Make a {item:6265} with {spell:1120} on the way."] = "Les Exilés ardents (niveau 38-39), des élémentaires de feu au {area:334}, dans l'ouest des {zone:1417}, lâchent le charbon environ une fois sur trois. Le guide attend d'abord le niveau 37 : en dessous, ils frappent trop fort pour être battus en solo. Ils résistent au feu : {spell:686} et Corruption. Les Charmes armoriés des Exilés grimpeurs près de {area:321} en achèvent un une fois que vous l'avez blessé. Créez un {item:6265} avec {spell:1120} en chemin.",
		["The Hatefury satyrs (level 31-32) hold {area:603} in the far north-east of {zone:1443}, past {area:608}: two kills in five give a vial, so plan on about 25."] = "Les satyres Fielfurie (niveau 31-32) tiennent {area:603}, à l'extrême nord-est de {zone:1443}, après {area:608} : deux victimes sur cinq donnent une fiole, comptez donc environ 25.",
		["The Lesser Infernals (36-37) and Demon Portal Guardians (38) of {area:602}, in the south of {zone:1443}, drop the stone half the time. The guide waits for level 35 first: at 31 they are too strong to solo. They resist fire, so use {spell:686} and Corruption."] = "Les Infernaux mineurs (36-37) et les Gardiens du Portail démoniaque (38) du {area:602}, au sud de {zone:1443}, lâchent la pierre une fois sur deux. Le guide attend d'abord le niveau 35 : au niveau 31, ils sont trop forts pour être battus en solo. Ils résistent au feu, utilisez donc {spell:686} et Corruption.",
		["The boat from {area:392} sails to {area:35}. {npc:2670} runs {object:59851} on an upper level of the town. Give him the {item:3577}; he will spin the thread later."] = "Le bateau de {area:392} va à {area:35}. {npc:2670} tient la boutique de couture « Un tailleur pour les cités » à un étage supérieur de la ville. Donnez-lui la {item:3577} ; il filera le fil plus tard.",
		["Vials of Hatefury Blood"] = "Fioles de sang de Fielfurie",
		["Wait beside {npc:6266} while she finishes the robe"] = "Attendez à côté de {npc:6266} pendant qu'elle termine la robe",
		["You need no thread yet: {npc:6266} wants demon parts from {zone:1443} next."] = "Vous n'avez pas encore besoin du fil : {npc:6266} veut ensuite des morceaux de démons de {zone:1443}.",
		["{item:3577}: the Auction House"] = "{item:3577} : l'hôtel des ventes",
		["{item:5770} and a {item:3577}"] = "{item:5770} et une {item:3577}",
		["{item:5770}: the Auction House"] = "{item:5770} : l'hôtel des ventes",
		["{item:6265}: {spell:1120} on an Exile as it dies"] = "{item:6265} : {spell:1120} sur un Exilé au moment où il meurt",
		["{npc:2670}: {quest:4785}, handed straight back"] = "{npc:2670} : {quest:4785}, rendue aussitôt",
		["{npc:6266} again"] = "Encore {npc:6266}",
		["{npc:6266} stands by {npc:6251}'s tower on the hill above {area:392}, behind the engineers' hut. She takes the robe, then sends the gold bar to {npc:2670} in {area:35}."] = "{npc:6266} se tient près de la tour de {npc:6251}, sur la colline au-dessus de {area:392}, derrière la cabane des ingénieurs. Elle prend la robe, puis vous envoie porter la barre d'or à {npc:2670}, à {area:35}.",
} end)()
t.guides["forever/class/warlock/felhunter-alliance"] = (function() return {
		["At 30 {npc:6120}, in the {object:32383}, sends you to {npc:6251} in {area:392}."] = "Au niveau 30, {npc:6120}, dans la {object:32383}, vous envoie voir {npc:6251} à {area:392}.",
		["At 30 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6251} in {area:392}."] = "Au niveau 30, {npc:6122}, dans la cave de l'{object:2164}, dans le {object:2101}, vous envoie voir {npc:6251} à {area:392}.",
		["Back to {npc:6251} in {area:392}. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the {quest:1804} on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon {quest:1795} and take it again from {npc:6251}. Keep the tome: {npc:6251} takes it back."] = "Retournez voir {npc:6251} à {area:392}. Quand vous acceptez, il trace le cercle d'invocation et ses acolytes canalisent un cercle plus grand par-dessus : attendez dans la tour que les deux soient terminés. Utilisez ensuite le {quest:1804} sur le cercle. Le chasseur corrompu (niveau 30, pas élite) réduit au silence et dévore le mana, et il disparaît au bout de deux minutes : sortez votre marcheur du Vide, ouvrez aussitôt avec vos dégâts sur la durée et laissez le marcheur du Vide encaisser. Si vous mourez ou s'il gagne, abandonnez {quest:1795} et reprenez-la auprès de {npc:6251}. Gardez le tome : {npc:6251} le reprend.",
		["Back to {npc:6294}"] = "Retournez voir {npc:6294}",
		["Felhunter (Alliance)"] = "Chasseur corrompu (Alliance)",
		["Rods of Channeling"] = "Bâtonnets de canalisation",
		["Rods of Channeling, from the Dragonmaw casters"] = "Bâtonnets de canalisation, sur les lanceurs de sorts Dragonmaw",
		["The Dragonmaw hold {area:1036} in the hills east of the road from {area:150} to {area:836}. Only the casters drop the rods, four kills in five: the Bonewarders (level 27, with skeleton pets) and Shadowwarders (28). A steep path north of the central spirit healer leads up into the camp past most of the warriors."] = "Les Dragonmaw tiennent le {area:1036}, dans les collines à l'est de la route qui va de {area:150} à {area:836}. Seuls les lanceurs de sorts lâchent les bâtonnets, quatre fois sur cinq : les Gardos (niveau 27, avec des squelettes familiers) et les Gardombres (28). Un chemin escarpé au nord du gardien des âmes central monte dans le camp en évitant la plupart des guerriers.",
		["The centaur cave opens in the cliffs north of {area:484}, a Horde town: keep clear of its guards. Inside, keep right at each fork, cross the pool by the small waterfall, and open the small dark box against the wall beside a larger chest: the larger one is the wrong one. You can open it only while on the quest. The centaurs respawn behind you on the way out."] = "La grotte des centaures s'ouvre dans les falaises au nord du {area:484}, une ville de la Horde : tenez-vous loin de ses gardes. À l'intérieur, prenez à droite à chaque embranchement, traversez le bassin près de la petite cascade et ouvrez la petite boîte sombre contre le mur, à côté d'un coffre plus grand : le grand n'est pas le bon. Vous ne pouvez l'ouvrir que pendant la quête. Les centaures réapparaissent derrière vous à la sortie.",
		["The felhunter, the demon to bring against spellcasters, and a {item:22244} for your shards."] = "Le chasseur corrompu, le démon à opposer aux lanceurs de sorts, et une {item:22244} pour vos fragments.",
		["The tome is a small grey-blue book lying in the sand of a murloc camp on the shore south-west of {area:271}, near the water's edge. Six or seven murlocs guard it and more lurk underwater: they come in groups, so Fear one and keep your voidwalker on the rest. Walk down to the water to click it; from the hillside the crates block the cursor."] = "Le tome est un petit livre gris-bleu posé dans le sable d'un camp de murlocs sur le rivage au sud-ouest d'{area:271}, près du bord de l'eau. Six ou sept murlocs le gardent et d'autres se cachent sous l'eau : ils viennent en groupe, alors apeurez-en un et gardez votre marcheur du Vide sur les autres. Descendez jusqu'à l'eau pour cliquer dessus ; depuis la colline, les caisses bloquent le curseur.",
		["{area:392} is a neutral goblin port on the {zone:1413} coast: the boat from {area:35} docks there. {npc:6251} stands on the hill above the town, behind the engineers' hut, by his little tower; {npc:6266} and two acolytes are with him. He sends you to {npc:6294} in {zone:1455}."] = "{area:392} est un port gobelin neutre sur la côte des {zone:1413} : le bateau de {area:35} y accoste. {npc:6251} se tient sur la colline au-dessus de la ville, derrière la cabane des ingénieurs, près de sa petite tour ; {npc:6266} et deux acolytes sont avec lui. Il vous envoie voir {npc:6294} à {zone:1455}.",
		["{item:6931}, from the {quest:1802} on the sand"] = "{item:6931}, sur le {quest:1802} dans le sable",
		["{item:6997}, in the {object:92423}"] = "{item:6997}, dans le {object:92423}",
		["{npc:6294} is in the library of the {object:32356}. He wants two lost pieces of the {quest:1758}: one on the {area:287} coast, one in {zone:1441}."] = "{npc:6294} est dans la bibliothèque du {object:32356}. Il veut deux morceaux perdus du {quest:1758} : l'un sur la côte de {area:287}, l'autre dans {zone:1441}.",
		["{npc:6294} pieces the tome together and gives you the {item:7006}: keep it, {npc:6251} takes it with the rods."] = "{npc:6294} reconstitue le tome et vous donne le {item:7006} : gardez-le, {npc:6251} le prend avec les bâtonnets.",
		["{quest:1804}, on the circle"] = "{quest:1804}, sur le cercle",
} end)()
t.guides["forever/class/warlock/felhunter-horde"] = (function() return {
		["At 30 {npc:5675}, in the {object:36082}, sends you to {npc:6251} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}. Take only one {quest:2996}: if {npc:6251} offers nothing, drop the duplicate from your log."] = "Au niveau 30, {npc:5675}, dans le {object:36082}, vous envoie voir {npc:6251} à {area:392}. Le zeppelin de {zone:1420} vole vers {zone:1411}. Ne prenez qu'une seule quête {quest:2996} : si {npc:6251} ne propose rien, supprimez le doublon de votre journal.",
		["At 30 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:6251} in {area:392}."] = "Au niveau 30, {npc:5875}, dans la {object:172960} sous la {object:172982}, vous envoie voir {npc:6251} à {area:392}.",
		["Back to {npc:6251} in {area:392}. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the {quest:1804} on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon {quest:1795} and take it again from {npc:6251}. Keep the tome: {npc:6251} takes it back."] = "Retournez voir {npc:6251} à {area:392}. Quand vous acceptez, il trace le cercle d'invocation et ses acolytes canalisent un cercle plus grand par-dessus : attendez dans la tour que les deux soient terminés. Utilisez ensuite le {quest:1804} sur le cercle. Le chasseur corrompu (niveau 30, pas élite) réduit au silence et dévore le mana, et il disparaît au bout de deux minutes : sortez votre marcheur du Vide, ouvrez aussitôt avec vos dégâts sur la durée et laissez le marcheur du Vide encaisser. Si vous mourez ou s'il gagne, abandonnez {quest:1795} et reprenez-la auprès de {npc:6251}. Gardez le tome : {npc:6251} le reprend.",
		["Back to {npc:6293}"] = "Retournez voir {npc:6293}",
		["Felhunter (Horde)"] = "Chasseur corrompu (Horde)",
		["Rods of Channeling"] = "Bâtonnets de canalisation",
		["Rods of Channeling, from the Dragonmaw casters"] = "Bâtonnets de canalisation, sur les lanceurs de sorts Dragonmaw",
		["The Dragonmaw hold {area:1036} in the hills east of the road through the {zone:1437}, south of the {area:881} you cross from {zone:1417}. Only the casters drop the rods, four kills in five: the Bonewarders (level 27, with skeleton pets) and Shadowwarders (28). A steep path north of the central spirit healer leads up into the camp past most of the warriors."] = "Les Dragonmaw tiennent le {area:1036}, dans les collines à l'est de la route qui traverse les {zone:1437}, au sud du {area:881} que vous franchissez depuis les {zone:1417}. Seuls les lanceurs de sorts lâchent les bâtonnets, quatre fois sur cinq : les Gardos (niveau 27, avec des squelettes familiers) et les Gardombres (28). Un chemin escarpé au nord du gardien des âmes central monte dans le camp en évitant la plupart des guerriers.",
		["The centaur cave opens in the cliffs north of {area:484}. Inside, keep right at each fork, cross the pool by the small waterfall, and open the small dark box against the wall beside a larger chest: the larger one is the wrong one. You can open it only while on the quest. The centaurs respawn behind you on the way out."] = "La grotte des centaures s'ouvre dans les falaises au nord du {area:484}. À l'intérieur, prenez à droite à chaque embranchement, traversez le bassin près de la petite cascade et ouvrez la petite boîte sombre contre le mur, à côté d'un coffre plus grand : le grand n'est pas le bon. Vous ne pouvez l'ouvrir que pendant la quête. Les centaures réapparaissent derrière vous à la sortie.",
		["The felhunter, the demon to bring against spellcasters, and a {item:22244} for your shards."] = "Le chasseur corrompu, le démon à opposer aux lanceurs de sorts, et une {item:22244} pour vos fragments.",
		["The tome is a small grey-blue book lying in the sand of a murloc camp on the shore south-west of {area:271}, near the water's edge. Six or seven murlocs guard it and more lurk underwater: they come in groups, so Fear one and keep your voidwalker on the rest. Walk down to the water to click it; from the hillside the crates block the cursor."] = "Le tome est un petit livre gris-bleu posé dans le sable d'un camp de murlocs sur le rivage au sud-ouest d'{area:271}, près du bord de l'eau. Six ou sept murlocs le gardent et d'autres se cachent sous l'eau : ils viennent en groupe, alors apeurez-en un et gardez votre marcheur du Vide sur les autres. Descendez jusqu'à l'eau pour cliquer dessus ; depuis la colline, les caisses bloquent le curseur.",
		["{area:392}'s flight point is a short flight from {zone:1454}'s. {npc:6251} stands on the hill above the town, behind the engineers' hut, by his little tower; {npc:6266} and two acolytes are with him. He sends you to {npc:6293} in the {zone:1458}."] = "Le point de vol de {area:392} est à un court vol de celui d'{zone:1454}. {npc:6251} se tient sur la colline au-dessus de la ville, derrière la cabane des ingénieurs, près de sa petite tour ; {npc:6266} et deux acolytes sont avec lui. Il vous envoie voir {npc:6293} à {zone:1458}.",
		["{item:6931}, from the {quest:1803} on the sand"] = "{item:6931}, sur le {quest:1803} dans le sable",
		["{item:6997}, in the {object:92423}"] = "{item:6997}, dans le {object:92423}",
		["{npc:6293} is in the {object:36082} of the {zone:1458}. He wants two lost pieces of the {quest:1801}: one on the {area:287} coast, one in {zone:1441}."] = "{npc:6293} est dans le {object:36082} de {zone:1458}. Il veut deux morceaux perdus du {quest:1801} : l'un sur la côte de {area:287}, l'autre dans {zone:1441}.",
		["{npc:6293} pieces the tome together and gives you the {item:7006}: keep it, {npc:6251} takes it with the rods."] = "{npc:6293} reconstitue le tome et vous donne le {item:7006} : gardez-le, {npc:6251} le prend avec les bâtonnets.",
		["{quest:1804}, on the circle"] = "{quest:1804}, sur le cercle",
} end)()
t.guides["forever/class/warlock/imp-alliance"] = (function() return {
		["Feather Charms"] = "Charmes de plume",
		["Imp (Alliance)"] = "Diablotin (Alliance)",
		["The Defias tent stands in the vineyard east of the Abbey. The book is small: it lies on the ground just right of the tent's opening, beside a blue jug. Three Defias Thugs (level 3-4) guard the tent; pull them one at a time, or step inside the tent and click the book, where they cannot reach you. The book respawns three minutes after someone takes it."] = "La tente des Défias se dresse dans le vignoble à l'est de l'abbaye. Le livre est petit : il est posé au sol juste à droite de l'entrée de la tente, à côté d'une cruche bleue. Trois Nervis défias (niveau 3-4) gardent la tente ; attirez-les un par un, ou entrez dans la tente et cliquez sur le livre, là où ils ne peuvent pas vous atteindre. Le livre réapparaît trois minutes après avoir été pris.",
		["The Frostmane Novices (level 3-4) sit at the back of the troll cave south of {area:77}, near Grek'nir the Cold by the icy pool: take the left tunnel past the entrance. Four kills in five drop a charm, but only two or three novices spawn, so you may wait out their three-minute respawn. They throw frostbolts from range; the Troll Whelps at the cave mouth jump anyone who passes. With the charms, your hearthstone takes you straight back: a new character's is set to {area:132}."] = "Les Novices Frostmane (niveau 3-4) se tiennent au fond de la grotte des trolls au sud d'{area:77}, près de Grik'nir le Froid au bord du bassin gelé : prenez le tunnel de gauche après l'entrée. Quatre fois sur cinq, ils lâchent un charme, mais seuls deux ou trois novices apparaissent, vous devrez donc peut-être attendre leur réapparition de trois minutes. Ils lancent des éclairs de givre à distance ; les Jeunes trolls à l'entrée de la grotte sautent sur quiconque passe. Une fois les charmes en main, votre pierre de foyer vous ramène tout droit : celle d'un nouveau personnage est liée à la {area:132}.",
		["The {object:83763}"] = "Les {object:83763}",
		["Your first demon at level 1-4: the imp, from your start zone's warlock trainer."] = "Votre premier démon, au niveau 1-4 : le diablotin, auprès du maître des démonistes de votre zone de départ.",
		["Your first letter ({item:9576}, from {npc:197} after Kobold Camp Cleanup) points you to {npc:459}, the warlock trainer in the little graveyard beside {area:24}. She asks for a book the Defias stole."] = "Votre première lettre ({item:9576}, de {npc:197} après Nettoyer le camp des kobolds) vous mène à {npc:459}, la maîtresse des démonistes dans le petit cimetière à côté de l'{area:24}. Elle demande un livre volé par les Défias.",
		["Your first letter ({item:9577}, from {npc:658} after Dwarven Outfitters) points you to {npc:460}, the warlock trainer upstairs inside {area:77}. He asks for three Feather Charms."] = "Votre première lettre ({item:9577}, de {npc:658} après Tailleur chez les nains) vous mène à {npc:460}, le maître des démonistes à l'étage d'{area:77}. Il demande trois Charmes de plume.",
		["{item:6785}, from the {object:83763}"] = "{item:6785}, dans les {object:83763}",
		["{npc:459} (Humans)"] = "{npc:459} (Humains)",
		["{npc:459} teaches you {spell:688} at the hand-in: summon it right away, it costs nothing and fights beside you."] = "{npc:459} vous apprend {spell:688} quand vous rendez la quête : invoquez-le tout de suite, il ne coûte rien et combat à vos côtés.",
		["{npc:460} (Gnomes)"] = "{npc:460} (Gnomes)",
		["{npc:460} teaches you {spell:688} at the hand-in: summon it right away, it costs nothing and fights beside you."] = "{npc:460} vous apprend {spell:688} quand vous rendez la quête : invoquez-le tout de suite, il ne coûte rien et combat à vos côtés.",
} end)()
t.guides["forever/class/warlock/imp-horde"] = (function() return {
		["Imp (Horde)"] = "Diablotin (Horde)",
		["Rattlecage Skulls"] = "Crânes de Cliquethorax",
		["The Rattlecage Skeletons (level 2-3) stand around the old smithy buildings just north of {area:154}, often right against the walls. Four kills in five drop a skull, so plan on about five; twenty of them spawn there and each comes back after five minutes."] = "Les Squelettes Cliquethorax (niveau 2-3) se tiennent autour des vieux bâtiments de la forge, juste au nord de {area:154}, souvent collés aux murs. Quatre fois sur cinq, ils lâchent un crâne, comptez donc environ cinq victimes ; vingt d'entre eux apparaissent là et chacun revient au bout de cinq minutes.",
		["The {quest:1485} (level 3-4) swarm the {area:365}, the cave north of the Den, inside and around its mouth. Almost every kill drops a head (80%), so about eight kills does it; they throw small fireballs, so pull them one at a time. They respawn in just over three minutes. Other classes hunt the same imps for their own {quest:1485} quest."] = "Les {quest:1485} (niveau 3-4) grouillent dans le {area:365}, la grotte au nord de l'Antre, à l'intérieur et autour de l'entrée. Presque chaque victime lâche une tête (80 %), environ huit suffisent donc ; ils lancent de petites boules de feu, attirez-les donc un par un. Ils réapparaissent en un peu plus de trois minutes. Les autres classes chassent les mêmes diablotins pour leur propre quête {quest:1485}.",
		["Vile Familiar Heads"] = "Têtes de Vil quasit",
		["Your first demon at level 1-4: the imp, with a starter blade or staff for Orcs and Trolls."] = "Votre premier démon, au niveau 1-4 : le diablotin, avec une lame ou un bâton de départ pour les Orcs et les Trolls.",
		["Your first letter ({item:9578}, from {npc:1569} after The Mindless Ones) points you to Maximillion, the warlock trainer in {area:154}. {npc:5667} waits inside the building beside him and asks for three Rattlecage Skulls."] = "Votre première lettre ({item:9578}, de {npc:1569} après Les Déchus) vous mène à Maximillion, le maître des démonistes à {area:154}. {npc:5667} attend dans le bâtiment à côté de lui et demande trois Crânes de Cliquethorax.",
		["Your first letter ({item:9579} for Orcs, {item:282346} for Trolls, from Gornek after Cutting Teeth) points you to Nartok, the warlock trainer in the Den. {npc:5765} stands just outside the Den in the {area:363} and asks for six Vile Familiar Heads."] = "Votre première lettre ({item:9579} pour les Orcs, {item:282346} pour les Trolls, de Gornek après La dent tranchante) vous mène à Nartok, le maître des démonistes dans l'Antre. {npc:5765} se tient juste devant l'Antre, dans la {area:363}, et demande six Têtes de Vil quasit.",
		["{npc:5667} (Undead)"] = "{npc:5667} (Morts-vivants)",
		["{npc:5667} teaches you {spell:688} when you hand in the skulls: summon it right away, it costs nothing and fights beside you."] = "{npc:5667} vous apprend {spell:688} quand vous rendez les crânes : invoquez-le tout de suite, il ne coûte rien et combat à vos côtés.",
		["{npc:5765} (Orcs and Trolls)"] = "{npc:5765} (Orcs et Trolls)",
		["{npc:5765} teaches you {spell:688} when you hand in the heads: summon it right away, it costs nothing and fights beside you. Then speak with {npc:3145} a few steps away for a starter weapon."] = "{npc:5765} vous apprend {spell:688} quand vous rendez les têtes : invoquez-le tout de suite, il ne coûte rien et combat à vos côtés. Parlez ensuite à {npc:3145}, à quelques pas, pour une arme de départ.",
} end)()
t.guides["forever/class/warlock/impsys-request"] = (function() return {
		["A staff, off-hand or robe for your 50s; {npc:14470}'s own errand, not a step of the Dreadsteed chain."] = "Un bâton, une main gauche ou une robe pour vos niveaux 50 ; une mission propre à {npc:14470}, pas une étape de la chaîne du Destrier de l'effroi.",
		["Amber Voodoo Feathers: Gasher, {npc:5716}"] = "Plumes vaudou ambre : Balafreur, {npc:5716}",
		["At 50 {npc:3326} in the {object:172960} sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "Au niveau 50, {npc:3326}, dans la {object:172960}, vous envoie voir {npc:14470} au {zone:1448} avec un morceau de {item:14256}.",
		["At 50 {npc:4563} in the {object:36082} sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "Au niveau 50, {npc:4563}, dans le {object:36082}, vous envoie voir {npc:14470} au {zone:1448} avec un morceau de {item:14256}.",
		["At 50 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "Au niveau 50, {npc:461}, dans l'{object:2164} du {object:2101}, vous envoie voir {npc:14470} au {zone:1448} avec un morceau de {item:14256}.",
		["At 50 {npc:5172} in {zone:1455} sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "Au niveau 50, {npc:5172}, à {zone:1455}, vous envoie voir {npc:14470} au {zone:1448} avec un morceau de {item:14256}.",
		["Blue Voodoo Feathers: Hukku, Mijan"] = "Plumes vaudou bleues : Hukku, Mijan",
		["Choose the {item:20536} (staff), the {item:20534} (off-hand) or the {item:20530}."] = "Choisissez le {item:20536} (bâton), l'{item:20534} (main gauche) ou la {item:20530}.",
		["Green Voodoo Feathers: Zolo, Loro"] = "Plumes vaudou vertes : Zolo, Loro",
		["One {item:14256}: the Jadefire satyrs of {zone:1448} drop it about one kill in fourteen, and so do the Legashi satyrs and the Felguard Sentries you hunt for Niby's essences. Quicker: buy one at the Auction House. You need it for the trainer's {quest:8419} or for {npc:14470}'s own {quest:8420}, the same errand: whichever you hold."] = "Un {item:14256} : les satyres Feu-de-jade du {zone:1448} en lâchent environ une fois sur quatorze, tout comme les satyres Legashi et les Sentinelles gangregardes que vous chassez pour les essences de Niby. Plus rapide : achetez-en un à l'hôtel des ventes. Il vous le faut pour la quête {quest:8419} du maître ou pour la quête {quest:8420} de {npc:14470} lui-même, la même course : celle que vous avez.",
		["The Irontree treants (level 52) of {area:1767}, in northern {zone:1448} west of {area:1998}, drop {item:20613} one time in four; the big {npc:7149} (55) often drops three at once but hits hard and dazes. The Tainted Oozes (51) around {npc:14470} and along the Bloodvenom drop the essence one time in five."] = "Les tréants Bois-de-fer (niveau 52) du {area:1767}, dans le nord du {zone:1448} à l'ouest du {area:1998}, lâchent du {item:20613} une fois sur quatre ; le grand {npc:7149} (55) en lâche souvent trois d'un coup mais frappe fort et hébète. Les Limons corrompus (51) autour de {npc:14470} et le long de la Vénéneuse lâchent l'essence une fois sur cinq.",
		["The {area:1417}"] = "{area:1417}",
		["The {area:1417} ({area:1477}, level 50-56, a group of five) stands in the middle of the {area:74}: swim down into the temple and take the stairs to the entrance. The six troll guardians (level 51-52, elite) stand on the balconies around the central pit, each with adds; each drops his feather every time: Gasher and {npc:5716} the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green. Not soloable at 52."] = "Le {area:1417} ({area:1477}, niveau 50-56, un groupe de cinq) se dresse au milieu de l'{area:74} : nagez vers le fond jusqu'au temple et prenez les escaliers jusqu'à l'entrée. Les six gardiens trolls (niveau 51-52, élites) se tiennent sur les balcons autour de la fosse centrale, chacun avec des renforts ; chacun lâche sa plume à chaque fois : Balafreur et {npc:5716} l'ambre, Hukku et Mijan la bleue, Zolo et Loro la verte. Impossible en solo au niveau 52.",
		["{item:20613} and Bloodvenom"] = "{item:20613} et Vénéneuse",
		["{npc:14470} again"] = "De nouveau {npc:14470}",
		["{npc:14470} now wants six {item:20609} from the {area:1417}: a dungeon run."] = "{npc:14470} veut maintenant six {item:20609} du {area:1417} : une sortie en donjon.",
		["{npc:14470} waits beside {npc:14469} on a rise just north-east of {area:1997}: coming north over the {area:1765} bridge, they stand off the road to the east, past a few oozes. Hand him the trainer's {quest:8419} with the cloth. Next he wants ten {item:20613} and four {item:20614}."] = "{npc:14470} attend à côté de {npc:14469} sur une butte juste au nord-est du {area:1997} : en venant du sud par le pont des {area:1765}, ils se tiennent à l'écart de la route, à l'est, après quelques limons. Rendez-lui la quête {quest:8419} du maître avec le tissu. Il veut ensuite dix {item:20613} et quatre {item:20614}.",
		["{npc:14470} waits beside {npc:14469} on a rise just north-east of {area:1997}: coming north over the {area:1765} bridge, they stand off the road to the east, past a few oozes. Take his own {quest:8420} and hand him the cloth at once. Next he wants ten {item:20613} and four {item:20614}."] = "{npc:14470} attend à côté de {npc:14469} sur une butte juste au nord-est du {area:1997} : en venant du sud par le pont des {area:1765}, ils se tiennent à l'écart de la route, à l'est, après quelques limons. Prenez sa propre quête {quest:8420} et rendez-lui aussitôt le tissu. Il veut ensuite dix {item:20613} et quatre {item:20614}.",
} end)()
t.guides["forever/class/warlock/incubus-alliance"] = (function() return {
		["At 20 {npc:6120}, the warlock trainer in {zone:1455}'s {object:32383}, sends you to {npc:6122} in {zone:1453}. Take the {area:2257}."] = "Au niveau 20, {npc:6120}, le maître des démonistes de la {object:32383} de {zone:1455}, vous envoie voir {npc:6122} à {zone:1453}. Prenez le {area:2257}.",
		["At 20 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6244} in the {zone:1413}: a long trip for the Alliance. Take the boat from {area:150} to Theramore and head west through {zone:1445}, or the boat from {area:35} to {area:392}."] = "Au niveau 20, {npc:6122}, dans la cave de l'{object:2164} du {object:2101}, vous envoie voir {npc:6244} dans les {zone:1413} : un long voyage pour l'Alliance. Prenez le bateau de {area:150} à Theramore et allez vers l'ouest à travers le {zone:1445}, ou le bateau de {area:35} à {area:392}.",
		["At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards."] = "Au niveau 20 : la succube et l'incube de Forever, son jumeau masculin, chacun avec une bourse d'âmes pour vos fragments.",
		["Back to {npc:6122} with the {quest:1738}. He hands you the {item:6913}: take the stairs behind him down to the crypt; part way along the lowest corridor a side stair on the left leads to the room with the purple circle. Stand on it and use the core. Summon your voidwalker first and keep the succubus (level 20, not elite) on the circle, or the guards may kill her and the kill does not count. If she wins, use the core again; keep it, {npc:6122} takes it back."] = "Retournez voir {npc:6122} avec le {quest:1738}. Il vous remet le {item:6913} : prenez l'escalier derrière lui pour descendre à la crypte ; à mi-chemin du couloir le plus bas, un escalier latéral à gauche mène à la salle au cercle violet. Placez-vous dessus et utilisez le cœur. Invoquez d'abord votre marcheur du Vide et gardez la succube (niveau 20, pas élite) sur le cercle, sinon les gardes risquent de la tuer et la victime ne compte pas. Si elle gagne, utilisez de nouveau le cœur ; gardez-le, {npc:6122} le reprend.",
		["Give Gakin the figurine, then use the {item:190309} at the middle of the same circle and defeat the incubus it calls (level 20, not elite; it can charm you) with your voidwalker tanking. Keep the figurine: {npc:6122} takes it back."] = "Donnez la figurine à Gakin, puis utilisez la {item:190309} au milieu du même cercle et vainquez l'incube qu'elle appelle (niveau 20, pas élite ; il peut vous charmer), votre marcheur du Vide encaissant les coups. Gardez la figurine : {npc:6122} la reprend.",
		["Ordil'Aran lies in north-west {zone:1440}, north of {area:415} along the road toward {zone:1439}. About twenty Dark Strand cultists hold the ruins around the great tree: keep to the outer wall, and click the {quest:1738} from as far away as it lets you. It is turned in to {npc:6122}, not to Takar."] = "Ordil'Aran se trouve au nord-ouest d'{zone:1440}, au nord d'{area:415}, le long de la route vers {zone:1439}. Une vingtaine de sectateurs du Sombre Brin tiennent les ruines autour du grand arbre : longez le mur extérieur et cliquez sur le {quest:1738} d'aussi loin que possible. Il se rend à {npc:6122}, pas à Takar.",
		["Succubus and Incubus (Alliance)"] = "Succube et incube (Alliance)",
		["The house stands alone in the trees of north-western {zone:1440}, north-west of Ordil'Aran and well north of {area:413}: do it on the same trip as the {quest:1738}. Take the {item:190307} from the table outside, light it at a campfire (a {object:29784} of your own, or Talen's fire on {area:414}), and go straight back: the {item:190308} burns out after five minutes, so a fire of your own beside the house is quickest. Without it the figure in the house stops you. The figurine is upstairs."] = "La maison se dresse, isolée, dans les arbres du nord-ouest d'{zone:1440}, au nord-ouest d'Ordil'Aran et bien au nord du {area:413} : faites-la lors du même voyage que le {quest:1738}. Prenez la {item:190307} sur la table dehors, allumez-la à un feu de camp (un {object:29784} à vous, ou le feu de Talen sur la {area:414}), et revenez tout droit : la {item:190308} s'éteint au bout de cinq minutes, un feu à vous à côté de la maison est donc le plus rapide. Sans elle, la silhouette dans la maison vous arrête. La figurine est à l'étage.",
		["The {item:190309}"] = "La {item:190309}",
		["the incubus"] = "l'incube",
		["the succubus"] = "la succube",
		["{item:190307}, on the table outside"] = "{item:190307}, sur la table dehors",
		["{item:190309}, upstairs"] = "{item:190309}, à l'étage",
		["{item:6913}, on the circle in the crypt"] = "{item:6913}, sur le cercle de la crypte",
		["{npc:185335}, at the circle in the crypt"] = "{npc:185335}, au cercle de la crypte",
		["{npc:6244} camps at a tent with a campfire just north-east of {area:378}, by a fork in the road: Horde ground, so come in from the east and keep clear of the Taurajo guards. {npc:6247} beside him starts the {item:6898}. Takar offers both branches: take both."] = "{npc:6244} campe sous une tente avec un feu de camp juste au nord-est du {area:378}, près d'une fourche de la route : c'est un territoire de la Horde, arrivez donc par l'est et tenez-vous loin des gardes de Taurajo. {npc:6247}, à côté de lui, lance la quête de l'{item:6898}. Takar propose les deux branches : prenez les deux.",
		["{quest:1717} (Gnomes)"] = "{quest:1717} (Gnomes)",
		["{quest:1739}: succubus"] = "{quest:1739} : succube",
		["{quest:65603}: incubus"] = "{quest:65603} : incube",
} end)()
t.guides["forever/class/warlock/incubus-horde"] = (function() return {
		["At 20 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:5909} a few steps away. Two trainers start these demons, {npc:5875} here and {npc:5675} in the {zone:1458}, and you can take only one; this guide follows whichever {quest:1472} you took. {npc:5909} offers both of {zone:1454}'s branches: take both."] = "Au niveau 20, {npc:5875}, dans la {object:172960} sous la {object:172982}, vous envoie voir {npc:5909}, à quelques pas. Deux maîtres lancent ces démons, {npc:5875} ici et {npc:5675} à {zone:1458}, et vous ne pouvez en prendre qu'un ; ce guide suit la quête {quest:1472} que vous avez prise. {npc:5909} propose les deux branches d'{zone:1454} : prenez les deux.",
		["At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards."] = "Au niveau 20 : la succube et l'incube de Forever, son jumeau masculin, chacun avec une bourse d'âmes pour vos fragments.",
		["Back to {npc:5675} with the lovers' hearts, then place the {item:190181} on the same circle and defeat the incubus they call (level 20, not elite; it can charm you). Keep the hearts: {npc:5675} takes them back."] = "Retournez voir {npc:5675} avec les cœurs des amants, puis posez les {item:190181} sur le même cercle et vainquez l'incube qu'ils appellent (niveau 20, pas élite ; il peut vous charmer). Gardez les cœurs : {npc:5675} les reprend.",
		["Back to {npc:5875} with the pendant. He hands you {item:6626}: take it across the {object:172960} to {npc:3216}'s tent, stand on the purple circle and use it. Summon your voidwalker first and let it tank: the succubus (level 20, not elite) charms and lashes; keep your damage over time on her. If she wins, use the pendant again. Keep the pendant: {npc:5875} takes it back."] = "Retournez voir {npc:5875} avec le pendentif. Il vous remet le {item:6626} : traversez la {object:172960} jusqu'à la tente de {npc:3216}, placez-vous sur le cercle violet et utilisez-le. Invoquez d'abord votre marcheur du Vide et laissez-le encaisser : la succube (niveau 20, pas élite) charme et fouette ; maintenez vos dégâts sur la durée sur elle. Si elle gagne, utilisez de nouveau le pendentif. Gardez le pendentif : {npc:5875} le reprend.",
		["Back to {npc:5875} with the scarf, then use the {item:190232} on the same circle in Neeru's tent and defeat the incubus it calls (level 20, not elite) with your voidwalker tanking. Keep the scarf: {npc:5875} takes it back."] = "Retournez voir {npc:5875} avec l'écharpe, puis utilisez l'{item:190232} sur le même cercle de la tente de Neeru et vainquez l'incube qu'elle appelle (niveau 20, pas élite), votre marcheur du Vide encaissant les coups. Gardez l'écharpe : {npc:5875} la reprend.",
		["Silverpine hearts"] = "Cœurs de la forêt des Pins-Argentés",
		["Succubus and Incubus (Horde)"] = "Succube et incube (Horde)",
		["the incubus"] = "l'incube",
		["the succubus"] = "la succube",
		["{area:422} lies in southern {zone:1440}, south-west of {area:431}. The Shadethicket Stone Movers and Bark Rippers (level 25-27) around the lake drop the {item:190232} about one time in twenty, and the lone {npc:3931} (30) can drop it too: plan on a good number of kills, so the guide waits for level 24 first (Forever made this quest level 27); with the succubus already bound you can leave it for your 20s leveling in {zone:1440}. They respawn in five minutes."] = "Le {area:422} se trouve dans le sud d'{zone:1440}, au sud-ouest du {area:431}. Les Bouge-pierres et les Arracheurs Sombretaillis (niveau 25-27) autour du lac lâchent l'{item:190232} environ une fois sur vingt, et l'{npc:3931} solitaire (30) peut aussi le lâcher : prévoyez bon nombre de victimes, le guide attend donc d'abord le niveau 24 (Forever a passé cette quête au niveau 27) ; une fois la succube liée, vous pouvez la garder pour votre progression de la vingtaine en {zone:1440}. Ils réapparaissent en cinq minutes.",
		["{item:6286}, on the circle below {npc:5675}"] = "{item:6286}, sur le cercle sous {npc:5675}",
		["{item:6626}, on the circle in Neeru's tent"] = "{item:6626}, sur le cercle de la tente de Neeru",
		["{npc:185333} (level 22) works as a tailor for the {area:279} wizards at {area:233}, in eastern Silverpine: the wizards around her are hostile. {npc:5682} (level 20, not elite) patrols near the {area:230} in the far south. Both are Alliance-friendly humans: attacking them can flag you for PvP. Each drops her or his heart."] = "{npc:185333} (niveau 22) travaille comme couturière pour les sorciers de {area:279} à {area:233}, dans l'est de la forêt des Pins-Argentés : les sorciers autour d'elle sont hostiles. {npc:5682} (niveau 20, pas élite) patrouille près du {area:230}, à l'extrême sud. Ce sont tous deux des humains amicaux envers l'Alliance : les attaquer peut vous marquer JcJ. Chacun lâche son cœur.",
		["{npc:185334} (level 22) works in {area:392}, on the {zone:1413} coast, at one of two spots in town: take the zeppelin to {zone:1411} and head south, or fly from {zone:1454}. He is an Alliance-friendly human: attacking him can flag you for PvP."] = "{npc:185334} (niveau 22) travaille à {area:392}, sur la côte des {zone:1413}, à l'un des deux endroits possibles en ville : prenez le zeppelin pour {zone:1411} et allez vers le sud, ou volez depuis {zone:1454}. C'est un humain amical envers l'Alliance : l'attaquer peut vous marquer JcJ.",
		["{npc:185335}, at the circle below {npc:5675}"] = "{npc:185335}, au cercle sous {npc:5675}",
		["{npc:185335}, at the circle in Neeru's tent"] = "{npc:185335}, au cercle de la tente de Neeru",
		["{npc:3363} keeps {object:173018} on the main street east of the {object:172960}. He asks you to look for his mate Krilge in {zone:1440}."] = "{npc:3363} tient {object:173018} dans la grande rue, à l'est de la {object:172960}. Il vous demande de chercher sa compagne Krilge en {zone:1440}.",
		["{npc:5683} (level 22, not elite; Comar in older records) wanders the north of the {zone:1437} just past the {area:881}, to the right as you come off the bridge. From the {zone:1458} head through {area:287} and {zone:1417}, where the mobs are 30 and up. Attacking her flags you for PvP."] = "{npc:5683} (niveau 22, pas élite ; Comar dans les anciennes archives) erre dans le nord des {zone:1437}, juste après le {area:881}, à droite en descendant du pont. Depuis {zone:1458}, passez par {area:287} et les {zone:1417}, où les monstres sont de niveau 30 et plus. L'attaquer vous marque JcJ.",
		["{object:1661}'s version, for warlocks who took {npc:5675}'s {quest:1472} instead of {npc:5875}'s. At 20 {npc:5675}, in the {object:36082}, sends you to {npc:5693} close by. {npc:5693} shows you an image of each quarry and offers both branches: take both."] = "La version de {object:1661}, pour les démonistes qui ont pris la quête {quest:1472} de {npc:5675} plutôt que celle de {npc:5875}. Au niveau 20, {npc:5675}, dans le {object:36082}, vous envoie voir {npc:5693}, tout près. {npc:5693} vous montre une image de chaque proie et propose les deux branches : prenez les deux.",
		["{quest:1474}: succubus ({zone:1458})"] = "{quest:1474} : succube ({zone:1458})",
		["{quest:1513}: succubus ({zone:1454})"] = "{quest:1513} : succube ({zone:1454})",
		["{quest:65597}: incubus ({zone:1458})"] = "{quest:65597} : incube ({zone:1458})",
		["{quest:65604}: incubus ({zone:1454})"] = "{quest:65604} : incube ({zone:1454})",
} end)()
t.guides["forever/class/warlock/orb-of-orahil"] = (function() return {
		["An off-hand orb or a staff for your late 30s, down the felhound's or the infernal's path, your pick."] = "Un orbe de main gauche ou un bâton vers la fin de la trentaine de niveaux, par la voie du gangrechien ou celle de l'infernal, au choix.",
		["At 35 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}."] = "Au niveau 35, {npc:3326}, dans la {object:172960}, vous envoie voir {npc:6266} à {area:392}.",
		["At 35 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}."] = "Au niveau 35, {npc:4563}, dans le {object:36082}, vous envoie voir {npc:6266} à {area:392}. Le zeppelin de {zone:1420} vole jusqu'à {zone:1411}.",
		["At 35 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}."] = "Au niveau 35, {npc:461}, dans l'{object:2164}, dans le {object:2101}, vous envoie voir {npc:6266} à {area:392}.",
		["At 35 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}."] = "Au niveau 35, {npc:5172}, à {zone:1455}, vous envoie voir {npc:6266} à {area:392}.",
		["Back to {npc:6266} in the tower above {area:392} with the cleansed orb. On the felhound path, accept her last quest and wait beside her while she completes the {item:15108} (do not attack her: the quest log calls it a kill), then speak to her again and pick the off-hand orb or the staff."] = "Retournez voir {npc:6266} dans la tour au-dessus de {area:392} avec l'orbe purifiée. Sur la voie du chien corrompu, acceptez sa dernière quête et attendez à côté d'elle pendant qu'elle termine l'{item:15108} (ne l'attaquez pas : le journal de quêtes parle de la tuer), puis parlez-lui de nouveau et choisissez l'orbe de main gauche ou le bâton.",
		["Back to {npc:6266} in the tower above {area:392} with the spirit and the gem first: her orb follows from it."] = "Retournez d'abord voir {npc:6266} dans la tour au-dessus de {area:392} avec l'esprit et la gemme : son orbe en découle.",
		["Choose an acolyte"] = "Choisissez un acolyte",
		["On the infernal path, accept her last quest and wait beside {npc:6266} while she completes the {item:15107}, then speak to her again and pick the off-hand orb or the staff."] = "Sur la voie de l'infernal, acceptez sa dernière quête et attendez à côté de {npc:6266} pendant qu'elle termine l'{item:15107}, puis parlez-lui de nouveau et choisissez l'orbe de main gauche ou le bâton.",
		["Orb of Orahil"] = "Orbe d'Orahil",
		["Pick one acolyte: you can take only one of their quests. {npc:6254}'s felhound path ends with the Orb or {item:15106}, the shadow versions; {npc:6252}'s infernal path with the Orb or {item:15105}, much the same items on the fire side. Most warlocks lean on shadow, but compare the four in their tooltips first. The guide follows the one you take. Keep the ruby or the emerald: it is handed back."] = "Choisissez un acolyte : vous ne pouvez prendre qu'une seule de leurs quêtes. La voie du chien corrompu de {npc:6254} se termine par l'orbe ou le {item:15106}, les versions d'ombre ; la voie de l'infernal de {npc:6252} par l'orbe ou le {item:15105}, à peu près les mêmes objets côté feu. La plupart des démonistes misent sur l'ombre, mais comparez d'abord les quatre dans leurs infobulles. Le guide suit celle que vous prenez. Gardez le rubis ou l'émeraude : on vous le reprend.",
		["The demon's spirit"] = "L'esprit du démon",
		["The {item:15107}"] = "L'{item:15107}",
		["The {item:15108}"] = "L'{item:15108}",
		["Wait beside {npc:6266} while she makes the orb"] = "Attendez à côté de {npc:6266} pendant qu'elle fabrique l'orbe",
		["{area:602} fills south-central {zone:1443}, east of {area:2408}. The Burning Blade Summoners (level 38-39, warlocks with imps) carry the {item:7291} every time. For the spirit, bring your demon to low health with your damage over time, then channel the ruby or the emerald on it and keep channelling while it dies, as with {spell:1120}: the gem does no damage of its own. The ruby works on the coven's felhounds: the two Mana Eaters (37-38) in the north, and the Mage Hunters (38) and Ley Hunters (39) further south. The emerald works on the Lesser Infernals (36-37, sixteen of them, fire-resistant)."] = "Le {area:602} occupe le centre-sud de {zone:1443}, à l'est du {area:2408}. Les Invocateurs de la Lame ardente (niveau 38-39, des démonistes avec des diablotins) portent l'{item:7291} à chaque fois. Pour l'esprit, amenez le démon à peu de vie avec vos dégâts sur la durée, puis canalisez le rubis ou l'émeraude sur lui et continuez pendant qu'il meurt, comme avec {spell:1120} : la gemme ne fait aucun dégât par elle-même. Le rubis fonctionne sur les chiens corrompus du convent : les deux Mange-mana (37-38) au nord, et les Chasseurs de mages (38) et Chasseurs Ley (39) plus au sud. L'émeraude fonctionne sur les Infernaux mineurs (36-37, ils sont seize, résistants au feu).",
		["{item:12648}, from a {npc:4678}, {npc:4681} or {npc:4685}"] = "{item:12648}, sur un {npc:4678}, un {npc:4681} ou un {npc:4685}",
		["{item:12649}, from a {npc:4676}"] = "{item:12649}, sur un {npc:4676}",
		["{item:7291}, from the Burning Blade Summoners"] = "{item:7291}, sur les Invocateurs de la Lame ardente",
		["{npc:6252}: he gives you the {item:12646}"] = "{npc:6252} : il vous remet l'{item:12646}",
		["{npc:6254}: she gives you the {item:12647}"] = "{npc:6254} : elle vous remet le {item:12647}",
		["{npc:6266} and her two acolytes stand in {npc:6251}'s tower on the hill above {area:392}."] = "{npc:6266} et ses deux acolytes se tiennent dans la tour de {npc:6251}, sur la colline au-dessus de {area:392}.",
		["{npc:6546} lives at her farm in the middle of {zone:1445}, south of the road from the {zone:1413} and south-west of Theramore; a spirit healer stands beside it. Deadmire, a level 45 crocolisk, patrols the creeks just north-east. Hand in the orb now; Cleansing waits for level 38. Before you accept it, clear the spiders and crocolisks around her paddock. Accepting starts a 3-minute timer: she walks to the paddock and lets the {npc:6549} out. It is elite (level 40): grouping up is encouraged; a warlock of about 40 can solo it with Fear or {spell:710} and damage over time, a level 38 one brings a friend. The timer keeps running after the kill, so hand in at once. If time runs out, abandon the quest and take it from {npc:6546} again."] = "{npc:6546} vit dans sa ferme au milieu du {zone:1445}, au sud de la route venant des {zone:1413} et au sud-ouest de Theramore ; un gardien des âmes se tient à côté. Mortebourbe, un crocilisque de niveau 45, patrouille les ruisseaux juste au nord-est. Rendez l'orbe maintenant ; la purification attend le niveau 38. Avant de l'accepter, nettoyez les araignées et les crocilisques autour de son enclos. Accepter lance un compte à rebours de 3 minutes : elle marche jusqu'à l'enclos et libère le {npc:6549}. Il est élite (niveau 40) : mieux vaut former un groupe ; un démoniste d'environ 40 peut le battre seul avec Peur ou {spell:710} et des dégâts sur la durée, un démoniste de niveau 38 vient avec un ami. Le compte à rebours continue après la victoire, rendez donc la quête aussitôt. Si le temps s'écoule, abandonnez la quête et reprenez-la auprès de {npc:6546}.",
} end)()
t.guides["forever/class/warlock/orb-of-soranruk"] = (function() return {
		["A rare off-hand orb or staff for your 20s, for fragments from two dungeons."] = "Une orbe de main gauche ou un bâton rare pour votre vingtaine, contre des fragments de deux donjons.",
		["Back to {npc:6247}"] = "Retour auprès de {npc:6247}",
		["Choose the off-hand {item:6898} or the two-handed {item:15109}."] = "Choisissez l'{item:6898} de main gauche ou le {item:15109} à deux mains.",
		["Soran'ruk Fragments, from the Twilight Acolytes inside"] = "Fragments de Soran'ruk, sur les Acolytes du crépuscule à l'intérieur",
		["{area:236} (level 22-30, a group of five) stands on the hill south of the {area:228}. Free the prisoner in the cells right of the entrance and he opens the way into the courtyard. The Shadowfang Darksouls (level 20-21, elite) are not in the courtyard: they walk the halls past it, up the ramp that curves left and in the building after. About twelve stand in a run and one in five drops the Large Fragment, so clear every Darksoul and run it again if it does not drop."] = "Le {area:236} (niveau 22-30, un groupe de cinq) se dresse sur la colline au sud du {area:228}. Libérez le prisonnier dans les cellules à droite de l'entrée et il vous ouvre le chemin de la cour. Les Ténébreux d'Ombrecroc (niveau 20-21, élites) ne sont pas dans la cour : ils parcourent les salles au-delà, en haut de la rampe qui tourne à gauche et dans le bâtiment suivant. Une douzaine se tiennent là par expédition et un sur cinq lâche le grand fragment : éliminez donc tous les Ténébreux et recommencez s'il ne tombe pas.",
		["{area:2797} (level 24-32, a group of five) opens in the ruins on the north-west coast of {zone:1440}, under the water at {area:414}. The Twilight Acolytes (level 24-25, elite, healers) stand in the last halls, around {npc:4832} and the altar before {npc:4829}; each one drops a fragment, but only three spawn in a run and they do not come back for two hours, so one run covers one warlock: kill them first, before they heal the rest."] = "{area:2797} (niveau 24-32, un groupe de cinq) s'ouvre dans les ruines de la côte nord-ouest d'{zone:1440}, sous l'eau à la {area:414}. Les Acolytes du crépuscule (niveau 24-25, élites, soigneurs) se tiennent dans les dernières salles, autour de {npc:4832} et de l'autel devant {npc:4829} ; chacun lâche un fragment, mais seuls trois apparaissent par expédition et ils ne reviennent pas avant deux heures, une expédition ne suffit donc qu'à un seul démoniste : tuez-les en premier, avant qu'ils ne soignent les autres.",
		["{item:6915}, from the Shadowfang Darksouls inside"] = "{item:6915}, sur les Ténébreux d'Ombrecroc à l'intérieur",
} end)()
t.guides["forever/class/warlock/shard-of-the-green-flame"] = (function() return {
		["A rare off-hand for your 50s from {npc:14469} and {npc:14470} in {zone:1448}, the camp that also offers An Imp's Request."] = "Un objet de main gauche rare pour les niveaux 50, de {npc:14469} et {npc:14470} à {zone:1448}, le camp qui propose aussi « La demande d'un diablotin ».",
		["At 50 {npc:14469} and his imp {npc:14470} wait on a rise in central {zone:1448} just north-east of {area:1997}: coming north over the {area:1765} bridge, they stand off the road to the east, past a few oozes. {npc:14469} sends you to {npc:14470}, beside him, who wants three Flawless Fel Essences from three places."] = "Au niveau 50, {npc:14469} et son diablotin {npc:14470} attendent sur une butte au centre du {zone:1448}, juste au nord-est du {area:1997} : en venant du sud par le pont des {area:1765}, ils se tiennent à l'écart de la route, à l'est, après quelques limons. {npc:14469} vous envoie voir {npc:14470}, à côté de lui, qui veut trois Gangressences parfaites venues de trois endroits.",
		["Back to {npc:14469}"] = "Retournez voir {npc:14469}",
		["Back to {npc:14470}. He hands you the {item:18626}: keep it, it wakes the infernal {npc:14467}."] = "Retournez voir {npc:14470}. Il vous remet le {item:18626} : gardez-le, il réveille l'infernal {npc:14467}.",
		["The Felguard Sentries (level 54) walk around the {area:72} in the south of the {zone:1419}, each with a felhunter. Leave the level 57 Servants of Razelikh alone: they cannot be killed without their own quest."] = "Les Sentinelles gangregardes (niveau 54) font le tour de la {area:72}, au sud des {zone:1419}, chacune avec un chasseur corrompu. Laissez tranquilles les Serviteurs de Razelikh de niveau 57 : on ne peut pas les tuer sans leur propre quête.",
		["The Legashi satyrs (level 51-53) hold the Legash Encampment on {zone:1447}'s northern coast. Every kind drops the essence three times in four; the satyrs burn mana and the Hellcallers rain fire, so pull them singly."] = "Les satyres Legashi (niveau 51-53) tiennent le campement Legashi sur la côte nord d'{zone:1447}. Chaque type lâche l'essence trois fois sur quatre ; les satyres brûlent le mana et les Appelle-l'enfer font pleuvoir le feu, attirez-les donc un par un.",
		["{area:1763} lies just south of {area:1997}, west of the road. The guide waits for level 53 first: its Legionnaires are 55. Of its two caves, {area:1770} is the northern one, further up the hill; the other has no Legionnaires. {area:1770}'s tunnels run north under the hills, and the Jaedenar Legionnaires (level 55) stand in its deeper halls, from the first ramps on toward {npc:9516}'s chamber; they Uppercut anyone in melee. Three kills in four give the essence, but only about eleven spawn: clear your way in and wait out a five-minute respawn if you must. The cultists of {area:1763} and {area:1770} are all hostile."] = "{area:1763} se trouve juste au sud du {area:1997}, à l'ouest de la route. Le guide attend d'abord le niveau 53 : ses Légionnaires sont de niveau 55. De ses deux grottes, {area:1770} est celle du nord, plus haut sur la colline ; l'autre n'a pas de Légionnaires. Les tunnels de {area:1770} filent vers le nord sous les collines, et les Légionnaires de Jaedenar (niveau 55) se tiennent dans ses salles profondes, des premières rampes jusqu'à la chambre de {npc:9516} ; ils frappent d'un uppercut quiconque est au corps à corps. Trois victimes sur quatre donnent l'essence, mais seule une onzaine apparaît : frayez-vous un chemin et attendez cinq minutes leur réapparition s'il le faut. Les sectateurs de {area:1763} et de {area:1770} sont tous hostiles.",
		["{item:18626}, at {object:179677}"] = "{item:18626}, aux {object:179677}",
		["{npc:14467}' remains lie in {area:1766}, the burnt crater north of {npc:14469}: follow the road north from his camp; the remains lie a little east of it. Use the {item:18626} beside them and wait for him to rise. {npc:14467} is elite (level 55): grouping up is encouraged; a warlock of 55 or more can solo him with Fear and damage over time, or with Enslave Demon, but fire spells do nothing to him and he knocks you back. If you die he heals to full; he rises again three minutes after he dies. An elite infernal patrols the pool south of the remains: pull {npc:14467} away from it. He always drops his core. Lost the {item:18626}? Abandon the quest and take it again from {npc:14470}."] = "Les restes de {npc:14467} gisent dans le {area:1766}, le cratère brûlé au nord de {npc:14469} : suivez la route vers le nord depuis son camp ; les restes sont un peu à l'est. Utilisez le {item:18626} à côté d'eux et attendez qu'il se relève. {npc:14467} est élite (niveau 55) : mieux vaut former un groupe ; un démoniste de niveau 55 ou plus peut le battre seul avec Peur et des dégâts sur la durée, ou avec Asservir démon, mais les sorts de feu ne lui font rien et il vous repousse. Si vous mourez, il récupère toute sa vie ; il se relève trois minutes après sa mort. Un infernal élite patrouille autour du bassin au sud des restes : éloignez {npc:14467} de lui. Il lâche toujours son noyau. Vous avez perdu le {item:18626} ? Abandonnez la quête et reprenez-la auprès de {npc:14470}.",
} end)()
t.guides["forever/class/warlock/tome-of-sacrifice"] = (function() return {
		["A rare off-hand at 60, {npc:14463}'s payment for capturing a {npc:12396} in the {zone:1419}."] = "Une main gauche rare au niveau 60, le paiement de {npc:14463} pour la capture d'un {npc:12396} dans {zone:1419}.",
		["At 60 {npc:14463} waits in the {area:73}, the demon-filled hollow in the west of the {zone:1419}. The Scar is full of hard-hitting elites: Soulstone yourself first, then keep to the right-hand wall going in, or ride through mounted. {npc:14463} gives you two errands at once."] = "Au niveau 60, {npc:14463} attend dans la {area:73}, le creux rempli de démons à l'ouest des {zone:1419}. La Balafre est pleine d'élites qui frappent fort : posez d'abord une Pierre d'âme sur vous-même, puis longez le mur de droite en entrant, ou traversez sur votre monture. {npc:14463} vous confie deux courses à la fois.",
		["Back to {npc:14463}"] = "Retour auprès de {npc:14463}",
		["Hand both in to {npc:14463} and take the {item:18601}. Find a {npc:12396} (level 61, elite) standing alone in the {area:73}, open from about 30 yards with your voidwalker on him, and channel the prison on him for about 20 seconds: he attacks you to break free, and his {spell:45} can interrupt the channel, so sacrifice the voidwalker for its shield if you must. Grouping up is encouraged: a second player to tank makes it easy. When the channel finishes he becomes the {item:18605}: click it. If the channel breaks, kill him or run, and try another."] = "Rendez les deux à {npc:14463} et prenez la {item:18601}. Trouvez un {npc:12396} (niveau 61, élite) seul dans la {area:73}, engagez à une trentaine de mètres avec votre marcheur du Vide sur lui, et canalisez la prison sur lui pendant une vingtaine de secondes : il vous attaque pour se libérer, et son {spell:45} peut interrompre la canalisation, sacrifiez donc le marcheur du Vide pour son bouclier s'il le faut. Mieux vaut former un groupe : un second joueur pour encaisser rend la chose facile. Quand la canalisation se termine, il devient le {item:18605} : cliquez dessus. Si la canalisation est interrompue, tuez-le ou fuyez, et essayez sur un autre.",
		["The Hederine demons (level 57-60, elite) hold {area:2256} in the far south of {zone:1452}: grouping up is encouraged. Two Slayers guard the gorge past the bridge; the western tunnel leads to more Initiates, the easiest of them (watch for their {spell:7645}). A warlock can solo them one at a time with Fear or {spell:710} and damage over time, but slowly. Any of them can drop the Tears, four kills in five."] = "Les démons Hederine (niveau 57-60, élites) tiennent la {area:2256}, à l'extrême sud du {zone:1452} : mieux vaut former un groupe. Deux Tueurs gardent la gorge après le pont ; le tunnel ouest mène à d'autres Initiés, les plus faciles d'entre eux (méfiez-vous de leur {spell:7645}). Un démoniste peut les battre seul un par un avec Peur ou {spell:710} et des dégâts sur la durée, mais lentement. N'importe lequel peut lâcher les larmes, quatre fois sur cinq.",
		["The Wildspawn satyrs (level 55-57, elite) fill the Warpwood Quarter, {area:2577}'s eastern wing: bring a group of five. Four in five drop a blood, but they do not come back for two hours and one full clear may come up short of fifteen; reset and run it again. The back door at {area:2518} needs the {item:18249}, which drops inside this wing; until someone has it, go in by {area:2577}'s main gate in central {zone:1444}."] = "Les satyres Wildspawn (niveau 55-57, élites) remplissent le Warpwood Quarter, l'aile est de {area:2577} : venez avec un groupe de cinq. Quatre sur cinq lâchent un sang, mais ils ne reviennent pas avant deux heures et un nettoyage complet peut ne pas suffire pour quinze ; réinitialisez et recommencez. La porte de derrière, au {area:2518}, exige la {item:18249}, qui tombe dans cette aile ; tant que personne ne l'a, entrez par la porte principale de {area:2577}, au centre de {zone:1444}.",
		["{item:18601}, on a {npc:12396}"] = "{item:18601}, sur un {npc:12396}",
		["{item:18603}, from the Wildspawn inside"] = "{item:18603}, sur les Wildspawn à l'intérieur",
		["{item:18605}, click it"] = "{item:18605}, cliquez dessus",
} end)()
t.guides["forever/class/warlock/voidwalker-alliance"] = (function() return {
		["At 10 {npc:6120}, the warlock trainer in {zone:1455}'s {object:32383}, sends you to {npc:6122} in {zone:1453}. Take the {area:2257} from {object:171524}. If {npc:6120} does not offer it, go to {npc:6122} anyway: he still gives you the next quest."] = "Au niveau 10, {npc:6120}, le maître des démonistes de la {object:32383} de {zone:1455}, vous envoie voir {npc:6122} à {zone:1453}. Prenez le {area:2257} depuis {object:171524}. Si {npc:6120} ne la propose pas, allez quand même voir {npc:6122} : il vous donne malgré tout la quête suivante.",
		["At 10 {npc:6121}, in the cellar of the Lion's Pride Inn in {area:87} (the stairs down are in the back room past the butcher's table), sends you to {npc:6122} in {zone:1453}."] = "Au niveau 10, {npc:6121}, dans la cave de l'auberge de la Fierté du lion à {area:87} (l'escalier qui descend est dans l'arrière-salle, après l'étal du boucher), vous envoie voir {npc:6122} à {zone:1453}.",
		["Back to {npc:6122}. He hands you the {item:6928}. The circle is hard to find: take the stairs behind {npc:6122} down; part way along the lowest corridor a side stair on the left leads into a room with a glowing purple circle in the middle. Stand on it and use the choker. The voidwalker (level 10, not elite) gets dangerous below 30% health: {spell:14868}, Corruption and {spell:348} with your imp on it, Fear when it gets close. If it beats you, use the choker again. Keep the choker: {npc:6122} takes it back."] = "Retournez voir {npc:6122}. Il vous remet le {item:6928}. Le cercle est difficile à trouver : prenez l'escalier derrière {npc:6122} pour descendre ; à mi-chemin du couloir le plus bas, un escalier latéral à gauche mène à une salle avec un cercle violet lumineux au milieu. Placez-vous dessus et utilisez le collier. Le marcheur du Vide (niveau 10, pas élite) devient dangereux sous 30 % de vie : {spell:14868}, Corruption et {spell:348} avec votre diablotin sur lui, Peur quand il s'approche. S'il vous bat, utilisez de nouveau le collier. Gardez le collier : {npc:6122} le reprend.",
		["Voidwalker (Alliance)"] = "Marcheur du Vide (Alliance)",
		["Your tank demon at 10: the voidwalker, after a dark sorceress's choker and a fight in {npc:6122}'s crypt."] = "Votre démon-tank au niveau 10 : le marcheur du Vide, après le collier d'une sorcière noire et un combat dans la crypte de {npc:6122}.",
		["{item:6928}, on the circle in the crypt"] = "{item:6928}, sur le cercle de la crypte",
		["{npc:6121}, Lion's Pride Inn cellar"] = "{npc:6121}, cave de l'auberge de la Fierté du lion",
		["{npc:881} (level 9) is inside the farmhouse at the {area:62}, south-east Elwynn near the Redridge road. {npc:473} (level 10) and a warrior stand with her and join the fight; Morgan gouges and goes for your imp, so keep him Feared. Put your damage over time on {npc:881} first, Fear the others, and loot her choker before you finish them: it stays yours even if you die after. She throws fireballs from range and is back three minutes after she dies. Have the quest before you kill her, or the choker does not drop."] = "{npc:881} (niveau 9) est dans la ferme du {area:62}, au sud-est de la forêt d'Elwynn, près de la route des Carmines. {npc:473} (niveau 10) et un guerrier se tiennent avec elle et se joignent au combat ; Morgan utilise Suriner et s'en prend à votre diablotin, gardez-le donc sous Peur. Mettez d'abord vos dégâts sur la durée sur {npc:881}, apeurez les autres, et ramassez son collier avant de les achever : il reste à vous même si vous mourez ensuite. Elle lance des boules de feu à distance et revient trois minutes après sa mort. Ayez la quête avant de la tuer, sinon le collier ne tombe pas.",
		["{quest:1685} (Humans)"] = "{quest:1685} (Humains)",
		["{quest:1715} (Gnomes)"] = "{quest:1715} (Gnomes)",
		["{quest:1715} is the tavern in the {object:2101}; {npc:6122} is in its cellar, down the stairs inside."] = "{quest:1715} est la taverne du {object:2101} ; {npc:6122} est dans sa cave, en bas de l'escalier intérieur.",
} end)()
t.guides["forever/class/warlock/voidwalker-horde"] = (function() return {
		["At 10 {npc:3294} sends you to {npc:5875}. He stands outside at the back of {area:362}'s barracks, the big building on the east side of town (not the inn), a few steps from {npc:3172}, the warlock trainer. {npc:5875} stands with the senior warlocks in the {object:172960}, the cavern under {zone:1454}'s {object:172982}. An Orc or Troll leveling in {zone:1420} can take the {zone:1458} version from {npc:5724} in {area:159} instead (the {zone:1458} steps below): you can do only one of the two."] = "Au niveau 10, {npc:3294} vous envoie voir {npc:5875}. Il se tient dehors, à l'arrière de la caserne de {area:362}, le grand bâtiment du côté est de la ville (pas l'auberge), à quelques pas de {npc:3172}, le maître des démonistes. {npc:5875} se tient avec les démonistes chevronnés dans la {object:172960}, la caverne sous la {object:172982} d'{zone:1454}. Un Orc ou un Troll qui progresse dans les {zone:1420} peut prendre à la place la version de {zone:1458} auprès de {npc:5724} à {area:159} (les étapes de {zone:1458} plus bas) : vous ne pouvez faire que l'une des deux.",
		["At 10 {npc:5724}, upstairs in the {area:2119} in {area:159}, sends you to {npc:5675}: the version for the Undead, and for Orcs and Trolls who level in {zone:1420} instead of taking {npc:5875}'s. {npc:5675} stands in the {zone:1458}'s {object:36082}, by the Temple of the Damned."] = "Au niveau 10, {npc:5724}, à l'étage de la {area:2119} à {area:159}, vous envoie voir {npc:5675} : la version pour les Morts-vivants, et pour les Orcs et Trolls qui progressent dans les {zone:1420} au lieu de prendre celle de {npc:5875}. {npc:5675} se tient dans le {object:36082} de {zone:1458}, près du temple des Damnés.",
		["Back to {npc:5675}. He hands you the {item:6284}: go down the stairs from him to the summoning circle and use them while standing on it. Fight the voidwalker (level 10, not elite) on the circle: if it wanders off, the city guards may kill it and the kill does not count. {spell:14868}, Corruption and {spell:348} with your imp tanking bring it down; it hits harder below 30%. If you lose, use the runes again. Keep the runes: {npc:5675} takes them back."] = "Retournez voir {npc:5675}. Il vous remet les {item:6284} : descendez l'escalier depuis lui jusqu'au cercle d'invocation et utilisez-les en vous tenant dessus. Combattez le marcheur du Vide (niveau 10, pas élite) sur le cercle : s'il s'éloigne, les gardes de la ville risquent de le tuer et la victime ne compte pas. {spell:14868}, Corruption et {spell:348}, avec votre diablotin pour encaisser, en viennent à bout ; il frappe plus fort sous 30 %. Si vous perdez, utilisez de nouveau les runes. Gardez les runes : {npc:5675} les reprend.",
		["Back to {npc:5875}. He hands you the {item:7464}: take them across the {object:172960} to {npc:3216}'s tent, stand on the purple circle on its floor and use them. The voidwalker (level 10, not elite) hits hard at 30% health and leaves after three minutes, so start at once: {spell:14868}, Corruption and {spell:348}, send your imp in, and Fear it when you need a breather. If it beats you or leaves, the glyphs are not used up: use them again on the circle. Keep the glyphs: {npc:5875} takes them back."] = "Retournez voir {npc:5875}. Il vous remet les {item:7464} : traversez la {object:172960} jusqu'à la tente de {npc:3216}, placez-vous sur le cercle violet au sol et utilisez-les. Le marcheur du Vide (niveau 10, pas élite) frappe fort à 30 % de vie et s'en va au bout de trois minutes, commencez donc aussitôt : {spell:14868}, Corruption et {spell:348}, envoyez votre diablotin, et apeurez-le quand vous avez besoin de souffler. S'il vous bat ou s'en va, les glyphes ne sont pas consommés : utilisez-les de nouveau sur le cercle. Gardez les glyphes : {npc:5875} les reprend.",
		["The Scarlet tower stands in the fields west of the {zone:1458}'s ruins (not the tower near {area:154}). The grimoire is in the small chest on the ground floor, under the stairs; ignore the chest upstairs. {npc:1662} (level 9) and a {npc:1537} guard it: kill them, or Fear the zealot while you deal with Perrine. Scarlet Missionaries and Zealots (level 7-9) walk the fields around the tower. The chest is back three seconds after anyone opens it."] = "La tour écarlate se dresse dans les champs à l'ouest des ruines de {zone:1458} (pas la tour près de {area:154}). Le grimoire est dans le petit coffre au rez-de-chaussée, sous l'escalier ; ignorez le coffre de l'étage. {npc:1662} (niveau 9) et un {npc:1537} le gardent : tuez-les, ou apeurez le zélote pendant que vous vous occupez de Perrine. Des Missionnaires et des Zélotes écarlates (niveau 7-9) parcourent les champs autour de la tour. Le coffre revient trois secondes après avoir été ouvert.",
		["Voidwalker (Horde)"] = "Marcheur du Vide (Horde)",
		["Your tank demon at 10: the voidwalker, after a stolen book and a fight at a summoning circle."] = "Votre démon-tank au niveau 10 : le marcheur du Vide, après un livre volé et un combat dans un cercle d'invocation.",
		["{area:817} is the cave in the cliffs just east of {zone:1454}'s gate. Inside, take the right-hand ramp up and follow it to the top: the {object:58595} sits on that upper ledge, which cannot be reached from the lower floor. The cave is packed with Burning Blade Apprentices and Fanatics (level 9-11, many with voidwalkers) that respawn quickly, and {npc:3204}, a level 14 Burning Blade warlock, stands near the stash. Old notes call him elite; Forever's data lists him as normal. At 10 it is hard alone: pull one pack at a time and Fear the extra, wait for 11, or go with a friend. The stash always holds the tablet."] = "Le {area:817} est la grotte dans les falaises juste à l'est de la porte d'{zone:1454}. À l'intérieur, prenez la rampe de droite et suivez-la jusqu'en haut : la {object:58595} se trouve sur cette corniche supérieure, inaccessible depuis le niveau inférieur. La grotte est bondée d'Apprentis de la Lame ardente et de Fanatiques (niveau 9-11, beaucoup avec des marcheurs du Vide) qui réapparaissent vite, et {npc:3204}, un démoniste de la Lame ardente de niveau 14, se tient près de la cachette. D'anciennes notes le disent élite ; les données de Forever le donnent normal. Au niveau 10, c'est dur en solo : attirez un groupe à la fois et apeurez le surplus, attendez le niveau 11, ou venez avec un ami. La cachette contient toujours la tablette.",
		["{item:6284}, on the circle below {npc:5675}"] = "{item:6284}, sur le cercle sous {npc:5675}",
		["{item:6285}, in {object:37098}"] = "{item:6285}, dans le {object:37098}",
		["{item:6535}, in the {object:58595}"] = "{item:6535}, dans la {object:58595}",
		["{item:7464}, on the circle in Neeru's tent"] = "{item:7464}, sur le cercle de la tente de Neeru",
		["{npc:5724}, upstairs in the {area:159} inn"] = "{npc:5724}, à l'étage de l'auberge de {area:159}",
		["{quest:1506} (Orcs and Trolls)"] = "{quest:1506} (Orcs et Trolls)",
} end)()
t.guides["forever/class/warrior/brutal-armor"] = (function() return {
		["At 20, {npc:3041}, the warrior trainer of {zone:1456}, sends you to {npc:6394} in {area:378}."] = "Au niveau 20, {npc:3041}, maître des guerriers de {zone:1456}, vous envoie voir {npc:6394} à {area:378}.",
		["At 20, {npc:3354} in the {object:172958} sends you to {npc:6394} in {area:378}."] = "Au niveau 20, {npc:3354}, dans la {object:172958}, vous envoie voir {npc:6394} à {area:378}.",
		["At 20, {npc:4595}, a warrior trainer of the {zone:1458}, sends you to {npc:6394} in {area:378}."] = "Au niveau 20, {npc:4595}, maître des guerriers de {zone:1458}, vous envoie voir {npc:6394} à {area:378}.",
		["Back to {npc:5878} on {area:1699}. {quest:1848} is the first piece; he then sends you to three crafters, one per piece: take all three."] = "Retournez voir {npc:5878} sur la {area:1699}. {quest:1848} est la première pièce ; il vous envoie ensuite voir trois artisans, un par pièce : prenez les trois.",
		["Fly to {area:378}. {npc:6394} stands in the hut with the leatherworking and tailoring trainers."] = "Volez jusqu'au {area:378}. {npc:6394} se tient dans la hutte des maîtres du travail du cuir et de la couture.",
		["Hillsbrad Miners"] = "Mineurs d'Hillsbrad ({npc:2269})",
		["Iron Bars"] = "Barres de fer",
		["Iron Bars: {npc:8673}"] = "Barres de fer : {npc:8673}",
		["Roogug in {area:1717}"] = "Roogug dans {area:1717}",
		["Roogug is an elite quilboar (level 28) inside {area:1717}, the dungeon at the south end of the {zone:1413}; a five-player dungeon: needs a group of five, his guards come with him. The guide waits for level 26 first. Inside take the left path at the first fork, cross the vine bridge over the pig pens, go past the room with the big cauldron: he waits in the room on the right. He casts {spell:403} and calls Earth Rumblers. The vial always drops."] = "Roogug est un huran élite (niveau 28) dans le {area:1717}, le donjon au sud des {zone:1413} ; un donjon à cinq joueurs : il faut un groupe de cinq, ses gardes viennent avec lui. Le guide attend d'abord le niveau 26. À l'intérieur, prenez à gauche au premier embranchement, traversez le pont de lianes au-dessus des enclos à cochons, dépassez la salle au grand chaudron : il attend dans la salle de droite. Il lance {spell:403} et appelle des Grondeurs de terre. La fiole tombe toujours.",
		["Take the zeppelin from {zone:1454} to {zone:1420}; {npc:6411} works in the {zone:1458}'s {object:36078}. She wants 8 Sturdy Dragonmaw Shinbones."] = "Prenez le zeppelin d'{zone:1454} vers {zone:1420} ; {npc:6411} travaille dans le {object:36078} de {zone:1458}. Elle veut 8 Solides tibias de Dragonmaw.",
		["The Dragonmaw orcs (level 26-30) camp in the middle of the {zone:1437}; from {area:321} in Arathi head south over the {area:881} ({area:150} is Alliance). With {quest:1846} from {npc:6411} in your log, every Raider, Swamprunner, Centurion, Shadowwarder and Bonewarder drops a {item:7131} (without the quest they drop none): right-click it to test it, and about one in four comes out sturdy, the rest break, so expect 30 or more kills for 8. You can test while moving or fighting. The orcs run for help at 15%; Raiders net you, Centurions shield-bash, Shadowwarders cast {spell:686}, Bonewarders raise skeletons."] = "Les orcs Dragonmaw (niveau 26-30) campent au milieu des {zone:1437} ; depuis {area:321}, en Arathi, allez au sud par le {area:881} ({area:150} est à l'Alliance). Avec {quest:1846} de {npc:6411} dans votre journal, chaque Pillard, Coureur des marais, Centurion, Gardombre et Gardos lâche un {item:7131} (sans la quête, ils n'en lâchent aucun) : faites un clic droit dessus pour le tester ; environ un sur quatre se révèle solide, les autres se brisent, comptez donc 30 victimes ou plus pour 8. Vous pouvez tester en vous déplaçant ou en combattant. Les orcs fuient chercher de l'aide à 15 % ; les Pillards lancent des filets, les Centurions donnent des coups de bouclier, les Gardombres lancent {spell:686}, les Gardos relèvent des squelettes.",
		["The satyrs of {area:430}, north-east of {area:431} ({area:429}, level 28-30), and the Felmusk satyrs north-west of the post (25-27) drop a hoof four kills in five. A {area:429} satyr at 15% health may cast {spell:6925} and heal to full: finish it fast or stun it. Hellcallers throw Fireballs from 40 yards; Felmusk satyrs reek in melee and run for help at 15%."] = "Les satyres de {area:430}, au nord-est du {area:431} ({area:429}, niveau 28-30), et les satyres Gangremusc au nord-ouest du poste (25-27) lâchent un sabot quatre fois sur cinq. Un satyre {area:429} à 15 % de vie peut lancer {spell:6925} et récupérer toute sa vie : achevez-le vite ou étourdissez-le. Les Appelle-l'enfer lancent des Boules de feu à 40 mètres ; les satyres Gangremusc empestent au corps à corps et fuient chercher de l'aide à 15 %.",
		["The {npc:6167} (level 28, not elite, larger than the young ones around her) roams the south edge of the {area:465} in south-west Stonetalon, near the road to {zone:1443}. She is the only one: she returns 5 minutes after dying and drops the {item:6840} four kills in five. She spits {spell:3396} from 30 yards."] = "La {npc:6167} (niveau 28, pas élite, plus grande que les jeunes autour d'elle) parcourt la lisière sud du {area:465}, au sud-ouest des Serres-Rocheuses, près de la route de {zone:1443}. Elle est la seule : elle revient 5 minutes après sa mort et lâche la {item:6840} quatre fois sur cinq. Elle crache {spell:3396} à 30 mètres.",
		["You have 30 minutes, and each {item:7119} rots 15 minutes after you loot it, so take the quest only when ready (logging out does not stop the clock). The Silithid Mounds dot the {area:390} south of {area:378}; every silithid drops an antenna. Creepers (level 20-21) and Grubs are the easiest: Swarmers (21-22) call small swarms and Creepers lay eggs that hatch adds. The eastern part of the field has plenty of Creepers. {item:7120}, a shield, is the reward."] = "Vous avez 30 minutes, et chaque {item:7119} pourrit 15 minutes après avoir été ramassée : ne prenez donc la quête que lorsque vous êtes prêt (se déconnecter n'arrête pas le chrono). Les Antres des silithides parsèment le {area:390} au sud du {area:378} ; chaque silithide lâche une antenne. Les Rampants (niveau 20-21) et les Larves sont les plus faciles : les Grouillants (21-22) appellent de petits essaims et les Rampants pondent des œufs d'où sortent des renforts. La partie est du champ compte beaucoup de Rampants. Le {item:7120}, un bouclier, est la récompense.",
		["You need 10 Iron Bars. Miners smelt them from {item:2772} (one ore a bar, {spell:3307} at {skill:186} 125); everyone else buys them at the auction house in {zone:1454}."] = "Il vous faut 10 Barres de fer. Les mineurs les fondent à partir de {item:2772} (un minerai par barre, {spell:3307} à 125 en {skill:186}) ; tous les autres les achètent à l'hôtel des ventes d'{zone:1454}.",
		["You need 10 {item:7127}. The guide waits for level 25 first. The Hillsbrad Miners (level 26-27) work the mine in the hills west of {area:271} and drop the azurite four kills in five; they fight in {spell:71}, sunder your armor and run for help at 30% health. Fly to {area:272} and head south-west."] = "Il vous faut 10 {item:7127}. Le guide attend d'abord le niveau 25. Les Mineurs d'Hillsbrad (niveau 26-27) travaillent dans la mine des collines à l'ouest d'{area:271} et lâchent l'azurite quatre fois sur cinq ; ils combattent en {spell:71}, fracassent votre armure et fuient chercher de l'aide à 30 % de vie. Volez jusqu'à {area:272} et allez vers le sud-ouest.",
		["You need 15 Smoky Iron Ingots. The {area:2160} lies at the east end of {area:461}, east of {area:460}; every Windshear kobold (level 19-23) drops an ingot four kills in five. Stonecutters, Geomancers and Overlords run for help when low; Geomancers cast {spell:116}."] = "Il vous faut 15 Lingots de fer cendré. La {area:2160} se trouve à l'extrémité est de la {area:461}, à l'est de la {area:460} ; chaque kobold Cisaille-vent (niveau 19-23) lâche un lingot quatre fois sur cinq. Les Tailleurs de pierre, les Géomanciens et les Seigneurs fuient chercher de l'aide quand leur vie est basse ; les Géomanciens lancent {spell:116}.",
		["from the Dragonmaw orcs: right-click to test it"] = "sur les orcs Dragonmaw : clic droit pour le tester",
		["{item:6840}, from the {npc:6167}"] = "{item:6840}, sur la {npc:6167}",
		["{item:6841}, from Roogug"] = "{item:6841}, sur Roogug",
		["{item:7119}, from the silithid"] = "{item:7119}, sur les silithides",
		["{item:7126}, from the Windshear kobolds"] = "{item:7126}, sur les kobolds Cisaille-vent",
		["{item:7127}, from the Hillsbrad Miners"] = "{item:7127}, sur les Mineurs d'Hillsbrad",
		["{npc:6408} is in {area:367} on the {zone:1411} coast. He wants 7 Uncloven Satyr Hooves."] = "{npc:6408} est au {area:367}, sur la côte de {zone:1411}. Il veut 7 sabots de satyre intacts.",
		["{npc:6410} works on {zone:1456}'s lowest level, close to the blacksmith."] = "{npc:6410} travaille au niveau le plus bas des {zone:1456}, près du forgeron.",
} end)()
t.guides["forever/class/warrior/fire-hardened-armor"] = (function() return {
		["At 20, {npc:5113}, the warrior trainer of {zone:1455}, sends you to {quest:1698} in Redridge."] = "Au niveau 20, {npc:5113}, le maître des guerriers de {zone:1455}, vous envoie voir {quest:1698} dans les Carmines.",
		["At 20, {npc:5479}, beside {npc:5480} in the warrior trainers' building of {object:2100}, sends you to {quest:1698} in Redridge."] = "Au niveau 20, {npc:5479}, à côté de {npc:5480} dans le bâtiment des maîtres des guerriers de la {object:2100}, vous envoie voir {quest:1698} dans les Carmines.",
		["At 20, {npc:7315}, the warrior trainer of {zone:1457}, sends you to {quest:1698} in Redridge."] = "Au niveau 20, {npc:7315}, le maître des guerriers de {zone:1457}, vous envoie voir {quest:1698} dans les Carmines.",
		["Back to {npc:5413} in the {object:28027} for the hauberk. He then sends you to the smith of your race; the other two smiths' pieces are open to you as well: talk to them directly."] = "Retournez voir {npc:5413} dans le {object:28027} pour le haubert. Il vous envoie ensuite voir le forgeron de votre race ; les pièces des deux autres forgerons vous sont aussi ouvertes : parlez-leur directement.",
		["Charred and Galvanized Horns"] = "Cornes carbonisées et Cornes galvanisées",
		["Enter the {area:98} and come back"] = "Entrez dans les {area:98} et revenez",
		["Fire Hardened Armor"] = "Armure en acier trempé",
		["Ride the {area:2257} from {zone:1453} to {zone:1455}. {quest:1704}, a gnome smith, works in {object:171524} near the engineering trainers. He wants 20 {item:6848}."] = "Prenez le {area:2257} de {zone:1453} à {zone:1455}. {quest:1704}, un forgeron gnome, travaille à {object:171524}, près des maîtres de l'ingénierie. Il veut 20 {item:6848}.",
		["Roogug in {area:1717}"] = "Roogug dans le {area:1717}",
		["Roogug is an elite quilboar (level 28) inside {area:1717}, the dungeon at the south end of the {zone:1413}; a five-player dungeon: needs a group of five, and his guards come with him. Inside take the left path at the first fork, cross the root bridge, go past the big empty cauldron: he is in a dead end on the right, with about ten elites on the way. He casts {spell:403} and calls Earth Rumblers. The vial always drops."] = "Roogug est un huran élite (niveau 28) dans le {area:1717}, le donjon au sud des {zone:1413} ; un donjon à cinq joueurs : il faut un groupe de cinq, et ses gardes viennent avec lui. À l'intérieur, prenez à gauche au premier embranchement, traversez le pont de racines, dépassez le grand chaudron vide : il est dans un cul-de-sac à droite, avec une dizaine d'élites en chemin. Il lance {spell:403} et appelle des Grondeurs de terre. La fiole tombe toujours.",
		["Scorched Spider Fangs"] = "Crocs d'araignée brûlés",
		["The Nightbane worgen of {zone:1431} (Dark Runners, Vile Fangs, Shadow Weavers, Worgen and Tainted Ones, level 26-31) south and west of {area:42} drop the {quest:1705} four kills in five. The Tainted Ones poison and howl; Vile Fangs cause {spell:3427}."] = "Les worgens Plaie-de-nuit du {zone:1431} (Messagers, Crocs noirs, Tisseurs d'ombre, Worgens et Contaminés, niveau 26-31) au sud et à l'ouest de {area:42} lâchent le {quest:1705} quatre fois sur cinq. Les Contaminés empoisonnent et hurlent ; les Crocs noirs infligent {spell:3427}.",
		["The chimaeras live south-west of {area:460} in the {area:465}; the guide waits for level 26 first. You need 12 Charred Horns from the Fledgling (level 25-27) and Young Chimaeras (23-25), four kills in five, and the {item:6840} from the {npc:6167} (28, the big one), also four in five. Only three Fledglings, two Young and one Matriarch live there, each back in 5 minutes, so expect to wait. Fledglings and the Matriarch spit {spell:3396}, the Young cast {spell:403}. Alliance: fly to {area:467} and head south."] = "Les chimères vivent au sud-ouest de la {area:460}, dans le {area:465} ; le guide attend d'abord le niveau 26. Il vous faut 12 Cornes carbonisées, sur les Petites chimères (niveau 25-27) et les Jeunes chimères (23-25), quatre fois sur cinq, et la {item:6840} sur la {npc:6167} (28, la grande), quatre fois sur cinq aussi. Seules trois Petites chimères, deux Jeunes et une Matriarche vivent là, chacune de retour en 5 minutes : attendez-vous à patienter. Les Petites chimères et la Matriarche crachent {spell:3396}, les Jeunes lancent {spell:403}. Alliance : volez jusqu'au {area:467} et allez vers le sud.",
		["The shells lie on the ground under the wyvern nests at {area:482} in western {zone:1441}, deeper into the gorge. Only nine exist and each returns 3 minutes after you pick it, so you will wait; some shell-like things there cannot be looted. Highperch Wyverns (level 28-31) guard them and sometimes come several at once."] = "Les carapaces gisent au sol sous les nids de wyvernes de {area:482}, dans l'ouest de {zone:1441}, plus loin dans la gorge. Il n'en existe que neuf et chacune revient 3 minutes après avoir été ramassée, vous devrez donc attendre ; certaines choses qui ressemblent à des carapaces ne peuvent pas être ramassées. Des Wyvernes de Haut-perchoir (niveau 28-31) les gardent et arrivent parfois à plusieurs.",
		["You have one hour, and {npc:6166}'s {spell:8553} leaves you drunk for 8-10 minutes. Run north-west into the {area:98}, keeping close to the cliff wall to miss most gnoll packs, and go in as far as the first fork; then come back to {npc:6166} (from the ridge you can jump down into {area:69}). Dying and releasing your spirit fails the quest: abandon it and {npc:6166} gives it again."] = "Vous avez une heure, et l'{spell:8553} de {npc:6166} vous laisse ivre pendant 8 à 10 minutes. Courez au nord-ouest jusqu'aux {area:98}, en longeant la falaise pour éviter la plupart des groupes de gnolls, et entrez jusqu'au premier embranchement ; revenez ensuite voir {npc:6166} (depuis la crête, vous pouvez sauter jusqu'à {area:69}). Mourir et libérer votre esprit fait échouer la quête : abandonnez-la et {npc:6166} vous la redonne.",
		["You need 50 fangs. The Leech Stalkers and Cave Stalkers (level 21-22) crawl in the middle of the {zone:1437}, north of {area:836}; every one drops a fang. They poison; back in 5 minutes."] = "Il vous faut 50 crocs. Les Traqueuses sanguines et les Traqueuses des grottes (niveau 21-22) rampent au milieu des {zone:1437}, au nord de {area:836} ; chacune lâche un croc. Elles empoisonnent ; de retour en 5 minutes.",
		["{item:6839}, from the young chimaeras"] = "{item:6839}, sur les jeunes chimères",
		["{item:6840}, from the {npc:6167}"] = "{item:6840}, sur la {npc:6167}",
		["{item:6841}, from Roogug"] = "{item:6841}, sur Roogug",
		["{item:6845}, from {npc:6170}"] = "{item:6845}, sur {npc:6170}",
		["{item:6848}, from {quest:1708}"] = "{item:6848}, sur le {quest:1708}",
		["{npc:1416} keeps the weapon shop in the north-west of the {object:28027}, a short walk from {npc:5413}. He wants 20 {quest:1705} and the {item:6845}."] = "{npc:1416} tient la boutique d'armes au nord-ouest du {object:28027}, à deux pas de {npc:5413}. Il veut 20 {quest:1705} et la {item:6845}.",
		["{npc:5413} works in the Dwarven District of Stormwind. He takes the {item:6843} (lost it? abandon the quest and {npc:6166} gives a new one) and gives you {item:6970}, a shield; {quest:1701} is a level 28 quest, with {item:6842} listing what it needs."] = "{npc:5413} travaille dans le quartier des Nains de Hurlevent. Il prend le {item:6843} (perdu ? abandonnez la quête et {npc:6166} vous en donne un nouveau) et vous donne la {item:6970}, un bouclier ; {quest:1701} est une quête de niveau 28, et les {item:6842} indiquent ce qu'il lui faut.",
		["{npc:6170} (level 32, not elite) carries the {item:6845}, four kills in five; the guide waits for level 30 first. He walks between the inside and the mouth of the {area:2161} mine south-east of {area:42}, so wait at the entrance and pull him outside. He poisons and howls."] = "{npc:6170} (niveau 32, pas élite) porte la {item:6845}, quatre fois sur cinq ; le guide attend d'abord le niveau 30. Il fait des allers-retours entre l'intérieur et l'entrée de la mine du {area:2161}, au sud-est de {area:42} ; attendez donc à l'entrée et attirez-le dehors. Il empoisonne et hurle.",
		["{quest:1698} sits in the inn at {area:69}. His test is timed: before you take it, clear the Redridge gnolls on the path to the {area:98} in the hills north-west of {area:69}, including the two on the rock by the cave mouth (climb it from its right side)."] = "{quest:1698} est à l'auberge de {area:69}. Son épreuve est chronométrée : avant de la prendre, éliminez les gnolls des Carmines sur le chemin des {area:98}, dans les collines au nord-ouest de {area:69}, y compris les deux sur le rocher près de l'entrée de la grotte (escaladez-le par la droite).",
		["{quest:1703} works on the south side of the {area:1660} in {zone:1457}. He wants 20 {quest:1710}."] = "{quest:1703} travaille du côté sud de la {area:1660}, à {zone:1457}. Il veut 20 {quest:1710}.",
		["{quest:1705}, from the Nightbane worgen"] = "{quest:1705}, sur les worgens Plaie-de-nuit",
} end)()
t.guides["forever/class/warrior/haggards-weapons"] = (function() return {
		["At 10, {npc:1229}, the warrior trainer in {area:131}, sends you to {quest:1679} in {zone:1455}. Any Alliance warrior may take one of the three roads, never two: in {zone:1453} at 10 anyway? {npc:5480}'s {quest:1638} is the quickest stance (one fight in a tavern), with a Haggard's weapon after it."] = "Au niveau 10, {npc:1229}, le maître des guerriers de {area:131}, vous envoie voir {quest:1679} à {zone:1455}. Tout guerrier de l'Alliance peut prendre l'une des trois voies, jamais deux : vous êtes de toute façon à {zone:1453} au niveau 10 ? La quête {quest:1638} de {npc:5480} est la posture la plus rapide (un seul combat dans une taverne), suivie d'une arme de Haggard.",
		["At 10, {npc:252377} stands with the trainers by {area:16638}'s west gate. A cultist, {npc:257196}, holds her family's shield at the {area:16629}."] = "Au niveau 10, {npc:252377} se tient avec les maîtres près de la porte ouest de {area:16638}. Un sectateur, {npc:257196}, détient le bouclier de sa famille au {area:16629}.",
		["At 10, {npc:3598}, the warrior trainer in {area:186}, or {npc:2151}, who patrols the road west of {area:186}, sends you to {quest:1684} on the {area:1660} in {zone:1457}. Any Alliance warrior may take one of the three roads, never two: in {zone:1453} at 10 anyway? {npc:5480}'s {quest:1638} teaches the same stance after one fight in a tavern."] = "Au niveau 10, {npc:3598}, la maîtresse des guerriers de {area:186}, ou {npc:2151}, qui patrouille sur la route à l'ouest de {area:186}, vous envoie voir {quest:1684} sur la {area:1660}, à {zone:1457}. Tout guerrier de l'Alliance peut prendre l'une des trois voies, jamais deux : vous êtes de toute façon à {zone:1453} au niveau 10 ? La quête {quest:1638} de {npc:5480} enseigne la même posture après un seul combat dans une taverne.",
		["At 10, {npc:913}, the warrior trainer by the inn in {area:87}, sends you to {npc:6089} in {zone:1453}; {npc:5480}, the warrior trainer in {zone:1453}'s {object:2100}, offers it too."] = "Au niveau 10, {npc:913}, la maîtresse des guerriers près de l'auberge de {area:87}, vous envoie voir {npc:6089} à {zone:1453} ; {npc:5480}, la maîtresse des guerriers de la {object:2100} de {zone:1453}, la propose aussi.",
		["Back on the {area:1660}: {npc:4088} hands you the {item:6812}; {npc:6142} works on the far, south side of the same terrace, easy to miss."] = "De retour sur la {area:1660} : {npc:4088} vous remet le {item:6812} ; {npc:6142} travaille de l'autre côté, au sud de la même terrasse, facile à manquer.",
		["Back to {npc:252377} in {area:16638}. She teaches {spell:71} and gives you the {item:275290}, a shield to use it with. {npc:6090}'s road below still gives a weapon, once you reach {zone:1453}."] = "Retournez voir {npc:252377} à {area:16638}. Elle enseigne {spell:71} et vous donne le {item:275290}, un bouclier à utiliser avec. La voie de {npc:6090}, plus bas, donne encore une arme, une fois à {zone:1453}.",
		["Back to {npc:294}"] = "Retour auprès de {npc:294}",
		["Back to {npc:6114} for {spell:71}, then to {quest:1680} at the {object:32372} in the middle of {zone:1455}."] = "Retournez voir {npc:6114} pour {spell:71}, puis {quest:1680} à la {object:32372}, au centre de {zone:1455}.",
		["Elunite under {area:442}"] = "Élunite sous {area:442}",
		["Head north-west from {area:16638} to the {area:16629}. {npc:257196} stands west of the shrine's approach, among the cult's Guardians, Spiritcallers and Blademasters: pull them one at a time before you take him. He drops the {item:263993}."] = "Allez au nord-ouest de {area:16638} jusqu'au {area:16629}. {npc:257196} se tient à l'ouest de l'accès au sanctuaire, parmi les Gardiens, les Mande-esprits et les Maîtres-lames du culte : attirez-les un par un avant de vous attaquer à lui. Il lâche le {item:263993}.",
		["Take the boat from {area:702} to {area:442}. The wreck lies underwater just south of {area:442}'s southern pier, where the Menethil boat docks. Open Crates of Elunite on the sea floor around the wreck, by a huge sunken turtle, toward the beach and under the pier until you have eight; every crate holds ore and comes back in 3-5 minutes. The grey {npc:6133} (level 11) drifts around the middle of the wreck and always drops the medallion: target it when you see it, so you can find it after surfacing for air. Watch your breath; Threshers can join in."] = "Prenez le bateau du {area:702} à {area:442}. L'épave gît sous l'eau juste au sud de la jetée sud d'{area:442}, là où accoste le bateau de Menethil. Ouvrez les caisses d'élunite au fond de la mer autour de l'épave, près d'une énorme tortue engloutie, vers la plage et sous la jetée, jusqu'à en avoir huit ; chaque caisse contient du minerai et revient en 3 à 5 minutes. L'{npc:6133} grise (niveau 11) dérive autour du milieu de l'épave et lâche toujours le médaillon : ciblez-la quand vous la voyez, pour la retrouver après être remonté respirer. Surveillez votre souffle ; des Batteurs peuvent s'en mêler.",
		["from {npc:6093}"] = "sur {npc:6093}",
		["{item:263993}, from {npc:257196}"] = "{item:263993}, sur {npc:257196}",
		["{item:6782}, from {object:85563}"] = "{item:6782}, dans le {object:85563}",
		["{item:6800}, from {object:85562}"] = "{item:6800}, dans le {object:85562}",
		["{item:6808}, from Crates of Elunite"] = "{item:6808}, dans les caisses d'élunite",
		["{item:6809}, from the {npc:6133}"] = "{item:6809}, sur l'{npc:6133}",
		["{npc:252377} in {area:16638}"] = "{npc:252377} à {area:16638}",
		["{npc:294}'s manor stands at the south-east edge of the {area:88} in eastern Elwynn, at the end of a short road that does not join the main one."] = "Le manoir de {npc:294} se dresse à la lisière sud-est du {area:88}, dans l'est de la forêt d'Elwynn, au bout d'une courte route qui ne rejoint pas la route principale.",
		["{npc:6089} and {npc:6090} are in the Pig and Whistle tavern in {object:2100}; {npc:6090} is the drunk at the far end of the bar. {npc:6090} (level 10) hits harder than his level, so start at full health; he gives up at low health instead of dying. If he wins, he disappears for about three minutes: keep the quest and talk to him again when he is back. A Dwarf, Gnome or Night Elf who took {quest:1638} from {npc:5480} instead of their home road is led through {zone:1453} from here."] = "{npc:6089} et {npc:6090} sont dans la taverne du Pig and Whistle, dans la {object:2100} ; {npc:6090} est l'ivrogne au fond du comptoir. {npc:6090} (niveau 10) frappe plus fort que son niveau, commencez donc avec toute votre vie ; il abandonne quand sa vie est basse au lieu de mourir. S'il gagne, il disparaît pendant trois minutes environ : gardez la quête et reparlez-lui quand il revient. Un Nain, un Gnome ou un Elfe de la nuit qui a pris {quest:1638} auprès de {npc:5480} au lieu de la voie de chez lui est guidé à travers {zone:1453} à partir d'ici.",
		["{npc:6093} (level 11) camps in the far south-east of Elwynn. A guard stands beside him and Defias and wolves are spread around the camp (now and then a rarer guard too): clear them one at a time, then kill Jack. He always drops {item:6783}; open {object:85563} in the crates by him for {item:6782}. Jack returns 3 minutes after dying, the box 1 minute after opening."] = "{npc:6093} (niveau 11) campe à l'extrême sud-est de la forêt d'Elwynn. Un garde se tient à côté de lui et des Défias et des loups sont répartis autour du camp (parfois aussi un garde plus rare) : éliminez-les un par un, puis tuez Jack. Il lâche toujours la {item:6783} ; ouvrez le {object:85563} dans les caisses près de lui pour l'{item:6782}. Jack revient 3 minutes après sa mort, le coffre 1 minute après avoir été ouvert.",
		["{quest:1678} (level 11, a lone troll) waits at his hut on a hill south of {area:135}, near the mountains at the top of a short ramp, with no other trolls around; the hut at the front of {area:135} is the wrong one. He fights in {spell:71} and sunders your armor; {spell:6343} slows him. His head always drops; he returns about 8 minutes after dying."] = "{quest:1678} (niveau 11, un troll solitaire) attend dans sa hutte sur une colline au sud du {area:135}, près des montagnes en haut d'une courte rampe, sans autres trolls autour ; la hutte à l'avant du {area:135} n'est pas la bonne. Il combat en {spell:71} et fracasse votre armure ; {spell:6343} le ralentit. Sa tête tombe toujours ; il revient environ 8 minutes après sa mort.",
		["{quest:1679} in {zone:1455}"] = "{quest:1679} à {zone:1455}",
		["{quest:1679} stands in the {object:32390} in the {object:32359}."] = "{quest:1679} se tient dans la salle d'armes de la {object:32359}.",
		["{quest:1681} lies in eastern {zone:1426}, below {area:212} on its south side. Dark Iron Spies (level 8-10) stand along the way, far enough apart to pull one at a time. {object:85562} is in the basement of the southernmost house; {npc:6124} (level 11) stands by it and charges on sight. The box always holds the ore and refills 15 minutes after opening."] = "{quest:1681} se trouve dans l'est de {zone:1426}, en contrebas du {area:212}, sur sa rive sud. Des Espions Sombrefer (niveau 8-10) se tiennent le long du chemin, assez espacés pour être attirés un par un. Le {object:85562} est dans la cave de la maison la plus au sud ; le {npc:6124} (niveau 11) se tient à côté et charge à vue. Le coffre contient toujours le minerai et se remplit 15 minutes après avoir été ouvert.",
		["{quest:1683} (level 10, a satyr) stands at a hidden moonwell up a hillside west of {area:186}. The trail is hard to spot: it starts behind a Gnarlpine camp and climbs in switchbacks lined with lamp posts. The furbolgs below can come in groups. His horn always drops; he returns 5 minutes after dying."] = "{quest:1683} (niveau 10, un satyre) se tient près d'un puits de lune caché, en haut d'un flanc de colline à l'ouest de {area:186}. Le sentier est difficile à repérer : il part derrière un camp Pin-tordu et monte en lacets bordés de lampadaires. Les furbolgs en contrebas peuvent arriver en groupe. Sa corne tombe toujours ; il revient 5 minutes après sa mort.",
		["{quest:1684} in {zone:1457}"] = "{quest:1684} à {zone:1457}",
		["{quest:1684} stands on the {area:1660}."] = "{quest:1684} se tient sur la {area:1660}.",
		["{spell:71} and a Weapon (Alliance)"] = "{spell:71} et une arme (Alliance)",
		["{spell:71} at 10 and a one-hand weapon of your choice from {zone:1453}, {zone:1455} or {zone:1457}."] = "{spell:71} au niveau 10 et une arme à une main de votre choix, à {zone:1453}, {zone:1455} ou {zone:1457}.",
} end)()
t.guides["forever/class/warrior/heirloom-weapon"] = (function() return {
		["At 10, {npc:2131}, the warrior trainer inside the inn of {area:159}, sends you to {npc:1496} by the graveyard on {area:159}'s west edge. This road and {npc:5810}'s exclude each other: drop {quest:1505} or {quest:1498} from your log if you hold one."] = "Au niveau 10, {npc:2131}, le maître des guerriers dans l'auberge de {area:159}, vous envoie voir {npc:1496}, près du cimetière à la lisière ouest de {area:159}. Cette voie et celle de {npc:5810} s'excluent : supprimez {quest:1505} ou {quest:1498} de votre journal si vous en avez une.",
		["At 10, {npc:252377} stands with the trainers by {area:16638}'s west gate. A cultist, {npc:257196}, holds her family's shield at the {area:16629}."] = "Au niveau 10, {npc:252377} se tient avec les maîtres près de la porte ouest de {area:16638}. Un sectateur, {npc:257196}, détient le bouclier de sa famille au {area:16629}.",
		["At 10, {npc:3063}, the warrior trainer of {area:222}, sends you to {npc:5810} in the {zone:1413}. {npc:3041} in {zone:1456} offers it too."] = "Au niveau 10, {npc:3063}, le maître des guerriers du {area:222}, vous envoie voir {npc:5810} dans les {zone:1413}. {npc:3041}, aux {zone:1456}, la propose aussi.",
		["At 10, {npc:3169}, the warrior trainer in the barracks of {area:362}, sends you to {npc:5810} in the {zone:1413}. Sorek in {zone:1454}'s {object:172958} offers it too. Any Horde warrior may take one of the two roads, never both: heading to {zone:1420} at 10 anyway? {npc:2131} in {area:159}'s inn offers the other: one fight by {area:159}'s graveyard for the same stance, then the Agamand crypt for an heirloom weapon."] = "Au niveau 10, {npc:3169}, le maître des guerriers de la caserne de {area:362}, vous envoie voir {npc:5810} dans les {zone:1413}. Sorek, dans la {object:172958} d'{zone:1454}, la propose aussi. Tout guerrier de la Horde peut prendre l'une des deux voies, jamais les deux : vous allez de toute façon dans les {zone:1420} au niveau 10 ? {npc:2131}, à l'auberge de {area:159}, propose l'autre : un combat près du cimetière de {area:159} pour la même posture, puis la crypte des Agamand pour une arme de famille.",
		["Back to {npc:1500}"] = "Retournez voir {npc:1500}",
		["Back to {npc:252377} in {area:16638}. She teaches {spell:71} and gives you the {item:275290}, a shield to use it with. {npc:5810}'s road below still gives a weapon later, once you reach Kalimdor."] = "Retournez voir {npc:252377} à {area:16638}. Elle enseigne {spell:71} et vous donne le {item:275290}, un bouclier à utiliser avec. La voie de {npc:5810}, plus bas, donne encore une arme plus tard, une fois en Kalimdor.",
		["Back to {npc:5810} under his tree west of {area:379}."] = "Retournez voir {npc:5810} sous son arbre, à l'ouest du {area:379}.",
		["Dillinger stands by the graveyard on {area:159}'s west edge. An Orc, Troll, Tauren or Skyborne who took {quest:1818} from {npc:2131} instead of {npc:5810}'s road is led through {area:159} from here."] = "Dillinger se tient près du cimetière, à la lisière ouest de {area:159}. Un Orc, un Troll, un Tauren ou un Éolide qui a pris {quest:1818} auprès de {npc:2131} au lieu de la voie de {npc:5810} est guidé à travers {area:159} à partir d'ici.",
		["Head north-west from {area:16638} to the {area:16629}. {npc:257196} stands west of the shrine's approach, among the cult's Guardians, Spiritcallers and Blademasters: pull them one at a time before you take him. He drops the {item:263993}."] = "Allez au nord-ouest de {area:16638} jusqu'au {area:16629}. {npc:257196} se tient à l'ouest de l'accès au sanctuaire, parmi les Gardiens, les Mande-esprits et les Maîtres-lames du culte : attirez-les un par un avant de vous attaquer à lui. Il lâche le {item:263993}.",
		["Singed Scales in {area:369}"] = "Écailles roussies à la {area:369}",
		["The four Agamand Weapon Racks are inside the {area:158} at the north end of {area:157}, north of {area:159}, one rack per room: one in the lowest room, two in the pair of rooms up the stairs, one in the room above those. The axe rack stands in a dark corner. The crypt's undead come in packs of three or more and return quickly; the ones in the top room are not linked. The axe, dagger and mace racks take 15 minutes to refill after someone loots them."] = "Les quatre Râteliers d'armes Agamand sont dans la {area:158}, au nord des {area:157}, au nord de {area:159}, un râtelier par salle : un dans la salle la plus basse, deux dans les deux salles en haut de l'escalier, un dans la salle au-dessus. Le râtelier à hache se trouve dans un coin sombre. Les morts-vivants de la crypte viennent par groupes de trois ou plus et reviennent vite ; ceux de la salle du haut ne sont pas liés. Les râteliers à hache, à dague et à masse mettent 15 minutes à se remplir après avoir été fouillés.",
		["The {area:158}"] = "La {area:158}",
		["You need five Singed Scales. Thunder Lizards (level 9-10) and Lightning Hides (10-11) live down in the {area:369} crevasse in north-west {zone:1411}, south of {zone:1454}: from the {zone:1413} bridge turn left and follow the river north into it. Both drop a scale about four kills in five; both cast {spell:5401}."] = "Il vous faut cinq Écailles roussies. Les Lézards-tonnerre (niveau 9-10) et les Foudroyants (10-11) vivent au fond de la crevasse de la {area:369}, au nord-ouest de {zone:1411}, au sud d'{zone:1454} : depuis le pont des {zone:1413}, tournez à gauche et suivez la rivière vers le nord pour y entrer. Les deux lâchent une écaille environ quatre fois sur cinq ; les deux lancent {spell:5401}.",
		["{item:263993}, from {npc:257196}"] = "{item:263993}, sur {npc:257196}",
		["{item:6486}, from the lizards"] = "{item:6486}, sur les lézards",
		["{item:6534}, from the {object:58369}"] = "{item:6534}, dans le {object:58369}",
		["{npc:1500} is in the {area:2119}, the inn on {area:159}'s east side."] = "{npc:1500} est dans la {area:2119}, l'auberge du côté est de {area:159}.",
		["{npc:252377} in {area:16638}"] = "{npc:252377} à {area:16638}",
		["{npc:5810} at {area:379}"] = "{npc:5810} au {area:379}",
		["{npc:6390} sleeps in the mausoleum in the graveyard just north of Dillinger. To wake him, click the flat skull plaque on the ground, left of the path to the mausoleum door; the seal lifts and {npc:6390} (level 11, not elite) walks out. Start at full health."] = "{npc:6390} dort dans le mausolée du cimetière, juste au nord de Dillinger. Pour le réveiller, cliquez sur la plaque plate en forme de crâne au sol, à gauche du chemin menant à la porte du mausolée ; le sceau se lève et {npc:6390} (niveau 11, pas élite) sort. Commencez avec toute votre vie.",
		["{spell:71} and a Weapon (Horde)"] = "{spell:71} et une arme (Horde)",
		["{spell:71} at 10 and a one-hand weapon of your choice: {npc:5810}'s road, {area:159}'s crypt, or the Skybreaker shield."] = "{spell:71} au niveau 10 et une arme à une main de votre choix : la voie de {npc:5810}, la crypte de {area:159}, ou le bouclier Brise-ciel.",
} end)()
t.guides["forever/class/warrior/quelserrar"] = (function() return {
		["A tank sword at 60: a {area:2577} book, then {npc:10184}'s breath tempers the blade (the sword is not in Forever's items yet)."] = "Une épée de tank au niveau 60 : un livre de {area:2577}, puis le souffle d'{npc:10184} trempe la lame (l'épée n'est pas encore dans les objets de Forever).",
		["Back to {npc:14368} in the Athenaeum of Dire Maul West: through the West door with the {item:18249} again, and a group to reach the library."] = "Retournez voir {npc:14368} dans l'Athenaeum de Haches-Tripes Ouest : de nouveau par la porte Ouest avec la {item:18249}, et avec un groupe pour atteindre la bibliothèque.",
		["Kill {npc:10184}, then target her corpse and use the {item:18488} on it before the 20 minutes run out. It becomes the {item:18492}, with no time limit."] = "Tuez {npc:10184}, puis ciblez sa dépouille et utilisez la {item:18488} dessus avant la fin des 20 minutes. Elle devient la {item:18492}, sans limite de temps.",
		["Shen'dralar reputation"] = "Réputation auprès des Shen'dralar",
		["The book is a rare random drop from the bosses of all three {area:2577} wings (Alzzin, Hydrospawn and the rest of the East, Tendris, Illyanna, Kalendris, {npc:11496} and the West, {npc:11501} and the North's guards) and very rarely from the tribute chest; it can be traded, so the auction house may have one. {area:2577} is a five-player dungeon in the ruins of central {zone:1444}: needs a group of five. Right-click the book to start the quest; it stays in your bags."] = "Le livre est un butin aléatoire rare sur les boss des trois ailes de {area:2577} (Alzzin, Hydrogénos et le reste de l'Est, Tendris, Illyanna, Kalendris, {npc:11496} et l'Ouest, {npc:11501} et les gardes du Nord) et très rarement dans le coffre du tribut ; il peut être échangé, l'hôtel des ventes peut donc en avoir un. {area:2577} est un donjon à cinq joueurs dans les ruines du centre de {zone:1444} : il faut un groupe de cinq. Faites un clic droit sur le livre pour lancer la quête ; il reste dans vos sacs.",
		["click the heated blade on the ground"] = "cliquez sur la lame chauffée au sol",
		["from {item:18401}"] = "sur le {item:18401}",
		["{item:18488}, on her corpse"] = "{item:18488}, sur sa dépouille",
		["{item:18489}: plant it in her breath"] = "{item:18489} : plantez-la dans son souffle",
		["{npc:10184} is the 40-player raid boss of {area:2159}, a cave in the {area:511} of southern {zone:1445}; she returns once a week. Tell the raid first. Late in the fight (around 10-15% health, when she has landed again) use the {item:18489} to plant it in the path of her fire breath, usually by the main tank's feet. When her breath has heated it, click the {object:179562} to take the {item:18488}: from then you have 20 minutes. Her breath can kill you while you plant or pick up the blade; if you die and nobody brings you back before she dies, wait for next week. Planted in the wrong place? Abandon the quest, take it again from Lydros for a new blade."] = "{npc:10184} est le boss de raid à 40 joueurs du {area:2159}, une grotte dans la {area:511} au sud du {zone:1445} ; elle revient une fois par semaine. Prévenez d'abord le raid. Tard dans le combat (vers 10-15 % de vie, une fois qu'elle s'est reposée au sol), utilisez la {item:18489} pour la planter sur le trajet de son souffle de feu, en général aux pieds du tank principal. Quand son souffle l'a chauffée, cliquez sur la {object:179562} pour prendre la {item:18488} : vous avez alors 20 minutes. Son souffle peut vous tuer pendant que vous plantez ou ramassez la lame ; si vous mourez et que personne ne vous ressuscite avant sa mort, attendez la semaine suivante. Plantée au mauvais endroit ? Abandonnez la quête et reprenez-la auprès de Lydros pour une nouvelle lame.",
		["{npc:10184}'s breath"] = "Le souffle d'{npc:10184}",
		["{npc:10184}'s corpse"] = "La dépouille d'{npc:10184}",
		["{npc:14368} stands in the Athenaeum, the library at the far end of Dire Maul West, past the Court of the Highborne and the Prison of Immol'thar. The West door needs the {item:18249}, which Pusillin drops in Dire Maul East (he runs; chase him), or a rogue to pick it. Clearing to the library needs your group of five. He takes the book, hands you {item:18513} to give straight back, then the {item:18489}. Keep that blade: lose it, and you must abandon the quest and take it again."] = "{npc:14368} se tient dans l'Athenaeum, la bibliothèque tout au fond de Haches-Tripes Ouest, après la Cour des Bien-nés et la prison d'Immol'thar. La porte Ouest exige la {item:18249}, que Pusillin lâche à Haches-Tripes Est (il s'enfuit ; poursuivez-le), ou un voleur pour la crocheter. Nettoyer jusqu'à la bibliothèque demande votre groupe de cinq. Il prend le livre, vous remet {item:18513} à lui rendre aussitôt, puis la {item:18489}. Gardez cette lame : si vous la perdez, vous devez abandonner la quête et la reprendre.",
		["{npc:14368}, in the Athenaeum"] = "{npc:14368}, dans l'Athenaeum",
		["{npc:14368}: hand back the Dull and Flat Elven Blade"] = "{npc:14368} : rendez la lame elfique terne et plate",
} end)()
t.guides["forever/class/warrior/voodoo-feathers"] = (function() return {
		["At 50, {npc:3041}, the warrior trainer of {zone:1456}, sends you to the {npc:7572} in the {zone:1435}."] = "Au niveau 50, {npc:3041}, le maître des guerriers de {zone:1456}, vous envoie voir le {npc:7572} dans le {zone:1435}.",
		["At 50, {npc:3354} in the {object:172958} sends you to the {npc:7572} in the {zone:1435}."] = "Au niveau 50, {npc:3354}, dans la {object:172958}, vous envoie voir le {npc:7572} dans le {zone:1435}.",
		["At 50, {npc:4593}, a warrior trainer of the {zone:1458}, sends you to the {npc:7572} in the {zone:1435}."] = "Au niveau 50, {npc:4593}, un maître des guerriers de {zone:1458}, vous envoie voir le {npc:7572} dans le {zone:1435}.",
		["At 50, {npc:5113}, the warrior trainer of {zone:1455}, sends you to the {npc:7572} in the {zone:1435}."] = "Au niveau 50, {npc:5113}, le maître des guerriers de {zone:1455}, vous envoie voir le {npc:7572} dans le {zone:1435}.",
		["At 50, {npc:5479}, beside {npc:5480} in the warrior trainers' building of {object:2100}, sends you to the {npc:7572} in the {zone:1435}."] = "Au niveau 50, {npc:5479}, à côté de {npc:5480} dans le bâtiment des maîtres des guerriers de la {object:2100}, vous envoie voir le {npc:7572} dans le {zone:1435}.",
		["At 50, {npc:7315}, the warrior trainer of {zone:1457}, sends you to the {npc:7572} in the {zone:1435}."] = "Au niveau 50, {npc:7315}, le maître des guerriers de {zone:1457}, vous envoie voir le {npc:7572} dans le {zone:1435}.",
		["Back to the {npc:10996}"] = "Retour auprès du {npc:10996}",
		["Experience"] = "Expérience",
		["Experience at 50, ending in the {area:1417}; Classic's item choice may be gone on Forever."] = "De l'expérience au niveau 50, avec une fin au {area:1417} ; le choix d'objet de Classic a peut-être disparu dans Forever.",
		["Helboars"] = "Sangliers infernaux",
		["In Classic the {npc:10996} let you choose the {item:20130}, the {item:20521} or the {item:20517} here. Forever's change notes say the choice is gone, though its quest page still lists three unnamed rewards: look at the reward window before you hand in."] = "Dans Classic, le {npc:10996} vous laissait choisir ici le {item:20130}, la {item:20521} ou les {item:20517}. Les notes de mise à jour de Forever disent que le choix a disparu, mais sa page de quête liste encore trois récompenses sans nom : regardez la fenêtre de récompense avant de rendre la quête.",
		["Seven Helboars (level 52-53, not elite) roam the north-west of the {zone:1419}, south-west of {area:1438}; some stand near the ogres on the mountainside by the road. They charge from 25 yards and cast {spell:8349}. They share spawn points with the Felbeasts and scorpids: if no boars are around, kill those and boars may appear instead. Back in 5 minutes."] = "Sept Sangliers infernaux (niveau 52-53, pas élites) parcourent le nord-ouest des {zone:1419}, au sud-ouest du {area:1438} ; certains se tiennent près des ogres, sur le flanc de la montagne au bord de la route. Ils chargent à 25 mètres et lancent {spell:8349}. Ils partagent leurs points d'apparition avec les gangrebêtes et les scorpides : s'il n'y a aucun sanglier, tuez ceux-là et des sangliers peuvent apparaître à leur place. De retour en 5 minutes.",
		["Shadowsworn camps"] = "Camps des liges d'ombre",
		["The Shadowsworn camp around the mouth of the {area:1440} cave, south of {area:1438} on the way to the {area:72}. You need 20 Adepts (level 52-53, they leech blood and heal hurt allies: kill them first), 10 Cultists (51-52, they throw from range, so close in) and 20 Thugs (52-53, Thrash and {spell:1766}). Thugs can run short before the others: kill every Shadowsworn you pass."] = "Les Jurés-de-l'ombre campent autour de l'entrée de la grotte du {area:1440}, au sud du {area:1438} sur le chemin de la {area:72}. Il vous faut 20 Adeptes (niveau 52-53, ils drainent le sang et soignent leurs alliés blessés : tuez-les en premier), 10 Sectateurs (51-52, ils frappent à distance, rapprochez-vous donc) et 20 Voyous (52-53, Rossée et {spell:1766}). Les Voyous peuvent manquer avant les autres : tuez chaque Juré-de-l'ombre que vous croisez.",
		["The {area:1417}"] = "Le {area:1417}",
		["The {npc:7572}"] = "Le {npc:7572}",
		["The {npc:7572}, a ghost, stands in the south-west of the {zone:1435}, at the pass into the {zone:1419}, a short ride south-west of {area:75}. Horde: fly to {area:75}. Alliance: fly to {area:1438} in the {zone:1419} and ride north through the pass. High-level beasts roam the way."] = "Le {npc:7572}, un fantôme, se tient au sud-ouest du {zone:1435}, au col qui mène aux {zone:1419}, à courte distance au sud-ouest de {area:75}. Horde : volez jusqu'à {area:75}. Alliance : volez jusqu'au {area:1438}, dans les {zone:1419}, et chevauchez vers le nord par le col. Des bêtes de haut niveau rôdent en chemin.",
		["You need two feathers of each colour from the six Atal'ai troll guardians (level 51-52, elite) on the {area:1417}'s balcony, who hold the barrier in front of {npc:5710}: Gasher and {npc:5716} drop the amber, Hukku and Mijan the blue, Zolo and Loro the green, every kill; each player on the quest loots their own set. The {area:1417} is a five-player dungeon: needs a group of five. It lies in the {area:74} in eastern {zone:1435}: climb the temple's outer steps, dive into the flooded hall and follow the stairs down to the entrance. Inside, reach the balcony by the stairs or the path on the right, not the spiral stairs. Hukku calls guardians and casts {spell:9081} and {spell:8282}; Mijan heals the others ({spell:139}, a {npc:3560}, {spell:331} below half health): kill her or her ward fast; {npc:5716} cleaves."] = "Il vous faut deux plumes de chaque couleur, sur les six gardiens trolls Atal'ai (niveau 51-52, élites) du balcon du {area:1417}, qui tiennent la barrière devant {npc:5710} : Balafreur et {npc:5716} lâchent l'ambre, Hukku et Mijan la bleue, Zolo et Loro la verte, à chaque victime ; chaque joueur ayant la quête ramasse son propre lot. Le {area:1417} est un donjon à cinq joueurs : il faut un groupe de cinq. Il se trouve dans l'{area:74}, dans l'est du {zone:1435} : montez les marches extérieures du temple, plongez dans la salle inondée et suivez les escaliers jusqu'à l'entrée. À l'intérieur, rejoignez le balcon par les escaliers ou le chemin de droite, pas par l'escalier en colimaçon. Hukku appelle des gardiens et lance {spell:9081} et {spell:8282} ; Mijan soigne les autres ({spell:139}, une {npc:3560}, {spell:331} sous la moitié de sa vie) : tuez-la vite, ou sa garde ; {npc:5716} porte des enchaînements.",
		["{item:20606}, from Gasher and {npc:5716}"] = "{item:20606}, sur Balafreur et {npc:5716}",
		["{item:20607}, from Hukku and Mijan"] = "{item:20607}, sur Hukku et Mijan",
		["{item:20608}, from Zolo and Loro"] = "{item:20608}, sur Zolo et Loro",
} end)()
t.guides["forever/class/warrior/whirlwind-weapon"] = (function() return {
		["At 30, {npc:3041}, the warrior trainer of {zone:1456}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Au niveau 30, {npc:3041}, le maître des guerriers des {zone:1456}, vous envoie voir {npc:6236} sur l'{area:720}, dans les {zone:1413}.",
		["At 30, {npc:3354} in the {object:172958} sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Au niveau 30, {npc:3354}, dans la {object:172958}, vous envoie voir {npc:6236} sur l'{area:720}, dans les {zone:1413}.",
		["At 30, {npc:4595}, a warrior trainer of the {zone:1458}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Au niveau 30, {npc:4595}, un maître des guerriers de {zone:1458}, vous envoie voir {npc:6236} sur l'{area:720}, dans les {zone:1413}.",
		["At 30, {npc:5113}, the warrior trainer of {zone:1455}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Au niveau 30, {npc:5113}, le maître des guerriers de {zone:1455}, vous envoie voir {npc:6236} sur l'{area:720}, dans les {zone:1413}.",
		["At 30, {npc:5479}, beside {npc:5480} in the warrior trainers' building of {object:2100}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Au niveau 30, {npc:5479}, à côté de {npc:5480} dans le bâtiment des maîtres des guerriers de la {object:2100}, vous envoie voir {npc:6236} sur l'{area:720}, dans les {zone:1413}.",
		["Back to {npc:6176}. Accepting {quest:1713} starts his ritual, and {quest:1712} appears just north of his camp. {quest:1712} is elite (level 40): grouping up is encouraged; it needs a group of two or three around level 40. It deals nature damage (a {item:6052} soaks it), whirls, and {spell:10101} throws you far while it heals itself as you run back: fight with your back to a slope or rock. The {item:6894} always drops. If the fight fails {npc:6176} stops answering: abandon {quest:1713} and take it again for a new summon; the earlier items are not needed again."] = "Retournez voir {npc:6176}. Accepter {quest:1713} lance son rituel, et {quest:1712} apparaît juste au nord de son camp. {quest:1712} est élite (niveau 40) : mieux vaut former un groupe ; il faut un groupe de deux ou trois vers le niveau 40. Il inflige des dégâts de nature (une {item:6052} les absorbe), tourbillonne, et {spell:10101} vous projette loin pendant qu'il se soigne le temps que vous reveniez : combattez dos à une pente ou à un rocher. Le {item:6894} tombe toujours. Si le combat échoue, {npc:6176} ne répond plus : abandonnez {quest:1713} et reprenez-la pour une nouvelle invocation ; les objets précédents ne sont pas redemandés.",
		["Bloodscalp Tusks"] = "Défenses de Bloodscalp",
		["Click {object:89931} with the 24 charms in your bags and {quest:1712} in your log. Its window asks for the charms straight away, with nothing to accept: Continue, then Complete, and it hands you the {quest:1714}."] = "Cliquez sur {object:89931} avec les 24 charmes dans vos sacs et {quest:1712} dans votre journal de quêtes. Sa fenêtre demande les charmes tout de suite, sans rien à accepter : « Continuer », puis « Terminer », et il vous remet {quest:1714}.",
		["Fly to {area:392} and go south along the {area:391}. {area:720} lies offshore to the south-east: wade across on the shallow sand bar; off it the water is deep and fatigue sets in. {npc:6236} stands by the arena."] = "Volez jusqu'à {area:392} et allez au sud le long de la {area:391}. L'{area:720} se trouve au large, au sud-est : traversez à gué par le banc de sable peu profond ; à côté, l'eau est profonde et la fatigue s'installe. {npc:6236} se tient près de l'arène.",
		["The cauldron wants 8 of each charm, 24 in all, and each exile drops its charm about one kill in three, so plan on some 70 kills. All are level 38-39, not elite: the guide waits for level 37 first, and a friend helps. Burning Exiles (fire) by the {area:334} in the north-west, north-west of {area:320}; Thundering Exiles (air) by the {area:336} south-east of {area:320}, casting {spell:403} from 40 yards; Cresting Exiles (water) by the {area:333}, north-west of {area:321}, with {spell:122}. About a dozen of each, back in under 7 minutes. The charms trade and sell on the auction house; using one banishes another kind of exile for a while (Burning on Thundering, Thundering on Cresting, Cresting on Burning)."] = "Le chaudron veut 8 charmes de chaque sorte, 24 en tout, et chaque exilé lâche son charme environ une fois sur trois : comptez quelque 70 victimes. Tous sont de niveau 38-39, pas élites : le guide attend d'abord le niveau 37, et un ami aide. Les Exilés ardents (feu) près du {area:334}, au nord-ouest, au nord-ouest du {area:320} ; les Exilés foudroyants (air) près du {area:336}, au sud-est du {area:320}, qui lancent {spell:403} à 40 mètres ; les Exilés grimpeurs (eau) près du {area:333}, au nord-ouest de {area:321}, avec {spell:122}. Une douzaine de chaque, de retour en moins de 7 minutes. Les charmes s'échangent et se vendent à l'hôtel des ventes ; en utiliser un bannit un autre type d'exilé pour un temps (Ardent sur Foudroyant, Foudroyant sur Grimpeur, Grimpeur sur Ardent).",
		["The exiles of Arathi"] = "Les exilés d'Arathi",
		["You have 10 minutes. Eat and drink to full, then step onto the grate in the middle of the crowd: {npc:6248} announces the challengers (level 26-27), who come one at a time, 15-20 seconds apart, and only while you stand near the grate. After each kill, step off the grate to eat or bandage; step back on when ready for the next. Six of them, then {npc:6238} (level 33, not elite) walks out; he stays neutral until you attack him, so bandage or eat first. Do not use {spell:1160}: it sends the challengers running and more of them pile in at once. If nothing starts, step off and on the grate again, or abandon the quest and take it again."] = "Vous avez 10 minutes. Mangez et buvez jusqu'à être plein, puis montez sur la grille au milieu de la foule : {npc:6248} annonce les adversaires (niveau 26-27), qui arrivent un par un, à 15-20 secondes d'intervalle, et seulement tant que vous êtes près de la grille. Après chaque victoire, descendez de la grille pour manger ou vous bander ; remontez quand vous êtes prêt pour le suivant. Il y en a six, puis {npc:6238} (niveau 33, pas élite) entre ; il reste neutre tant que vous ne l'attaquez pas, bandez-vous ou mangez donc d'abord. N'utilisez pas {spell:1160} : cela fait fuir les adversaires et ils reviennent ensuite à plusieurs. Si rien ne commence, descendez de la grille et remontez-y, ou abandonnez la quête et reprenez-la.",
		["You need 30 tusks. Every Bloodscalp troll (level 33-37) of north-west Stranglethorn drops one about one kill in three, so plan on some 80 kills: the camps and ruins north and north-west of {area:117} and around the {area:123} on the coast. They enrage below 30% health and the Warriors disarm; back in 5 minutes."] = "Il vous faut 30 défenses. Chaque troll Bloodscalp (niveau 33-37) du nord-ouest de Strangleronce en lâche une environ une fois sur trois : comptez quelque 80 victimes. Les camps et les ruines au nord et au nord-ouest du {area:117}, et autour des {area:123} sur la côte. Ils enragent sous 30 % de vie et les Guerriers désarment ; de retour en 5 minutes.",
		["You need 8 {item:3357}. Herbalists pick it by rivers and lakes in the {zone:1437}, {zone:1417} and {zone:1434}; otherwise the auction house. Herb vendors keep only one at a time and restock every two hours: {npc:1302} and {npc:1313} in {zone:1453}, {npc:844} on the road in eastern Elwynn, Jeeda at {area:460} in Stonetalon, Montarr in {zone:1441}. Kurzen Medicine Men in northern Stranglethorn drop one about one kill in twelve."] = "Il vous faut 8 {item:3357}. Les herboristes la cueillent au bord des rivières et des lacs des {zone:1437}, des {zone:1417} et de {zone:1434} ; sinon, l'hôtel des ventes. Les marchands d'herbes n'en ont qu'une à la fois et se réapprovisionnent toutes les deux heures : {npc:1302} et {npc:1313} à {zone:1453}, {npc:844} sur la route dans l'est de la forêt d'Elwynn, Jeeda à la {area:460} dans les Serres-Rocheuses, Montarr dans {zone:1441}. Les Guérisseurs Kurzen du nord de Strangleronce en lâchent une environ une fois sur douze.",
		["{item:4479}, from Burning Exiles"] = "{item:4479}, sur les Exilés ardents",
		["{item:4480}, from Thundering Exiles"] = "{item:4480}, sur les Exilés foudroyants",
		["{item:4481}, from Cresting Exiles"] = "{item:4481}, sur les Exilés grimpeurs",
		["{item:6894}, from {quest:1712}"] = "{item:6894}, sur {quest:1712}",
		["{npc:6176} camps by ruins on the east bank of the river that runs past {area:272}, a short walk north-east of the town, just over the border in {zone:1416}; his cauldron stands beside him. Horde: fly to {area:272}. Alliance: fly to {area:271} and go north along the river; {area:272}'s guards are level 42 elites, so keep away from the town. Accepting {quest:1712} gives you {item:6929}, the list of what he needs: 8 {item:3357}, 30 Bloodscalp Tusks and the {item:6851} from his cauldron. The cauldron's {item:6851} is not a quest you take: it never shows in your quest log. Come back with its charms and hand them in at the cauldron."] = "{npc:6176} campe près de ruines sur la rive est de la rivière qui passe à {area:272}, à courte distance au nord-est du village, juste après la frontière des {zone:1416} ; son chaudron se trouve à côté de lui. Horde : volez jusqu'à {area:272}. Alliance : volez jusqu'à {area:271} et remontez la rivière vers le nord ; les gardes de {area:272} sont des élites de niveau 42, tenez-vous donc loin du village. Accepter {quest:1712} vous donne le {item:6929}, la liste de ce qu'il lui faut : 8 {item:3357}, 30 Défenses de Bloodscalp et l'{item:6851} de son chaudron. L'{item:6851} du chaudron n'est pas une quête à prendre : elle n'apparaît jamais dans votre journal de quêtes. Revenez avec ses charmes et rendez-les au chaudron.",
		["{npc:6176}: {item:6975}, Sword or Warhammer"] = "{npc:6176} : {item:6975}, épée ou marteau de guerre",
		["{quest:1714}, from the cauldron by {npc:6176}"] = "{quest:1714}, dans le chaudron près de {npc:6176}",
		["{spell:2458} at 30 and a {spell:1680} axe, sword or warhammer at 40."] = "{spell:2458} au niveau 30 et une hache, une épée ou un marteau de guerre {spell:1680} au niveau 40.",
} end)()
t.guides["forever/collectibles/mounts/alliance/black-war-mounts"] = (function() return {
		["Black War Mounts"] = "Montures de guerre noires",
		["PvP rank 11"] = "Rang JcJ 11",
		["{item:18243}, {spell:10907}, 100g"] = "{item:18243}, {spell:10907}, 100 po",
		["{item:18244}, {spell:826}, 100g"] = "{item:18244}, {spell:826}, 100 po",
		["{npc:12783} sells the mounts in {zone:1453}'s {object:2100} by the {area:2918}, beside the other honor quartermasters. The Forever client lists each at 100g. Each one also needs its kind's riding: Humans ride the steed, Night Elves the tiger, Gnomes the battlestrider, Dwarves the ram. A Skyborne, or anyone choosing another race's mount, first needs that riding from its trainer (Exalted with the race's city)."] = "{npc:12783} vend les montures dans la {object:2100} de {zone:1453}, près du {area:2918}, à côté des autres intendants d'honneur. Le client Forever les affiche chacune à 100 po. Chacune demande aussi la monte de son espèce : les Humains montent le destrier, les Elfes de la nuit le tigre, les Gnomes le trotteur de bataille, les Nains le bélier. Un Éolide, ou quiconque choisit la monture d'une autre race, doit d'abord apprendre cette monte auprès de son maître (Exalté auprès de la ville de cette race).",
		["{npc:14332}, {spell:824}, 100g"] = "{npc:14332}, {spell:824}, 100 po",
		["{spell:1299382} come from battlegrounds, PvP quests and the season's weekly tasks, with a weekly cap; Commander (rank 11) unlocks the Black War mounts. The Player vs. Player tab of your character pane shows your rank and what you may buy. {skill:762} one at full speed needs Journeyman {skill:762} (level 60). Polestar cannot read your rank, so this step waits for level 60 and Journeyman {skill:762}."] = "Les {spell:1299382} viennent des champs de bataille, des quêtes JcJ et des tâches hebdomadaires de la saison, avec un plafond hebdomadaire ; Commandant (rang 11) débloque les montures de guerre noires. L'onglet Joueur contre Joueur de votre fiche de personnage montre votre rang et ce que vous pouvez acheter. Pour monter à pleine vitesse, la {skill:762} ne suffit pas : il faut la {skill:762} (compagnon) (niveau 60). Polestar ne peut pas lire votre rang, cette étape attend donc le niveau 60 et la {skill:762} (compagnon).",
		["{spell:22723}, {spell:828}, 100g"] = "{spell:22723}, {spell:828}, 100 po",
} end)()
t.guides["forever/collectibles/mounts/alliance/horse"] = (function() return {
		["Any Alliance race can buy these horses, but riding one also takes {spell:824}, which only Humans get with {skill:762}. {npc:4732} teaches it to other races once they are Exalted with {faction:72} (the Stormwind Reputation guide shows the way). Until then, don't buy a horse for this character."] = "Toute race de l'Alliance peut acheter ces chevaux, mais en monter un demande aussi {spell:824}, que seuls les Humains reçoivent avec la {skill:762}. {npc:4732} l'enseigne aux autres races une fois Exaltées auprès de {faction:72} (le guide de réputation de Hurlevent montre le chemin). D'ici là, n'achetez pas de cheval pour ce personnage.",
		["Horse"] = "Cheval",
		["Learn to ride"] = "Apprendre à monter",
		["Pick a colour"] = "Choisir une couleur",
		["The {npc:5404} is not at {npc:384}: {npc:1460} sells it, at the stables of {area:150} in the {zone:1437} (20g in the Forever client). Skip this unless you want that colour."] = "L'{npc:5404} n'est pas chez {npc:384} : c'est {npc:1460} qui le vend, aux écuries de {area:150}, dans les {zone:1437} (20 po dans le client Forever). Passez cette étape si vous ne tenez pas à cette couleur.",
		["{item:2411}, 20g, {npc:1460}"] = "{item:2411}, 20 po, {npc:1460}",
		["{item:2414}, 20g"] = "{item:2414}, 20 po",
		["{item:5655}, 20g"] = "{item:5655}, 20 po",
		["{item:5656}, 20g"] = "{item:5656}, 20 po",
		["{npc:384} sells the other colours (20g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:384} vend les autres couleurs (20 po chacune dans le client Forever). Achetez celles que vous voulez, ou aucune si la monture reçue vous plaît.",
		["{npc:4732} and {npc:384}'s horse pen are at {area:88} in eastern {zone:1429}. At 40 {npc:4732} teaches {skill:762} to Humans for 100g (10% less at Honored with {faction:72}), and it comes with a horse. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{npc:4732} et l'enclos à chevaux de {npc:384} sont au {area:88}, dans l'est de la {zone:1429}. Au niveau 40, {npc:4732} enseigne la {skill:762} aux Humains pour 100 po (10 % de moins à Honoré auprès de {faction:72}), avec un cheval. Les autres races apprennent la {skill:762}, avec leur propre première monture, auprès du maître de monte de leur race.",
		["{npc:4732}, riding trainer"] = "{npc:4732}, maître de monte",
		["{npc:5404} in {area:150}"] = "{npc:5404} à {area:150}",
		["{spell:824} for other races"] = "{spell:824} pour les autres races",
} end)()
t.guides["forever/collectibles/mounts/alliance/mechanostrider"] = (function() return {
		["Any Alliance race can buy these mechanostriders, but riding one also takes {spell:10907}, which only Gnomes get with {skill:762}. {npc:7954} teaches it to other races once they are Exalted with {faction:54} (the Gnomeregan Exiles Reputation guide shows the way). Until then, don't buy a mechanostrider for this character."] = "Toute race de l'Alliance peut acheter ces mécanotrotteurs, mais en monter un demande aussi {spell:10907}, que seuls les Gnomes reçoivent avec la {skill:762}. {npc:7954} l'enseigne aux autres races une fois Exaltées auprès des {faction:54} (le guide de réputation des Exilés de Gnomeregan montre le chemin). D'ici là, n'achetez pas de mécanotrotteur pour ce personnage.",
		["In Classic only Dwarves and Gnomes could ride mechanostriders; in Forever every Alliance race can learn {spell:10907}."] = "Dans Classic, seuls les Nains et les Gnomes pouvaient monter les mécanotrotteurs ; dans Forever, toute race de l'Alliance peut apprendre {spell:10907}.",
		["Learn to ride"] = "Apprenez la monte",
		["Mechanostrider"] = "Mécanotrotteur",
		["Pick a colour"] = "Choisissez une couleur",
		["{area:189} is just east of {area:131}; {npc:7954} stands beside {npc:7955}'s mechanostriders. At 40 {npc:7954} teaches {skill:762} to Gnomes for 100g (10% less at Honored with {faction:54}), and it comes with a mechanostrider. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "Le {area:189} est juste à l'est de {area:131} ; {npc:7954} se tient à côté des mécanotrotteurs de {npc:7955}. Au niveau 40, {npc:7954} enseigne la {skill:762} aux Gnomes pour 100 po (10 % de moins à Honoré auprès des {faction:54}), avec un mécanotrotteur. Les autres races apprennent la {skill:762}, avec leur propre première monture, auprès du maître de monte de leur race.",
		["{item:13321}, 20g"] = "{item:13321}, 20 po",
		["{item:13322}, 20g"] = "{item:13322}, 20 po",
		["{item:8563}, 20g"] = "{item:8563}, 20 po",
		["{item:8595}, 20g"] = "{item:8595}, 20 po",
		["{npc:7954}, riding trainer"] = "{npc:7954}, maître de monte",
		["{npc:7955} sells the other colours (20g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:7955} vend les autres couleurs (20 po chacune dans le client Forever). Achetez celles que vous voulez, ou aucune si la monture reçue vous plaît.",
		["{spell:10907} for other races"] = "{spell:10907} pour les autres races",
} end)()
t.guides["forever/collectibles/mounts/alliance/pack-kodo"] = (function() return {
		["6,000 Merchant's Favor"] = "6,000 Faveur du marchand",
		["The camp is at {area:1002} in western {zone:1433}, where the roads from {zone:1429}, {zone:1431} and {area:69} meet. {npc:256736} sells the {npc:10636} only once you are Exalted with the {faction:2586}, and it costs 6,000 Merchant's Favor. Crates pay only Favor (about 15 a crate return); the reputation comes from Craftsman's Writs and the one-time {item:280179}, so follow the Supply Factions Reputation guide and keep 6,000 Favor aside."] = "Le camp se trouve aux {area:1002}, dans l'ouest des {zone:1433}, là où se rejoignent les routes de la {zone:1429}, du {zone:1431} et de {area:69}. {npc:256736} ne vend le {npc:10636} qu'une fois que vous êtes Exalté auprès de l'{faction:2586}, et il coûte 6 000 Faveurs du marchand. Les caisses ne rapportent que de la Faveur (environ 15 par caisse rendue) ; la réputation vient des Commissions d'artisan et de l'{item:280179}, unique, suivez donc le guide de réputation des factions de ravitaillement et mettez 6 000 Faveurs de côté.",
		["The reins need level 60 and Journeyman Riding to ride (Forever client); you can buy them earlier."] = "Les rênes demandent le niveau 60 et la monte Compagnon pour être utilisées (client Forever) ; vous pouvez les acheter avant.",
		["{faction:2586} camp"] = "Camp de l'{faction:2586}",
} end)()
t.guides["forever/collectibles/mounts/alliance/paladin-charger"] = (function() return {
		["An {item:12800} comes from Thorium veins and obsidian, about one vein in a hundred; a {item:18335} drops rarely from elites of level 59 and up (Revanchion and {npc:14695} about one kill in nine and one in a hundred). The Auction House is the usual source of both."] = "Un {item:12800} provient des filons de thorium et de l'obsidienne, environ un filon sur cent ; un {item:18335} tombe rarement sur les élites de niveau 59 et plus (Revanchion et {npc:14695}, environ une victime sur neuf et une sur cent). L'hôtel des ventes est la source habituelle des deux.",
		["Arcanite Bars x6: an alchemist, or the Trade District Auction House"] = "Barres d'arcanite x6 : un alchimiste, ou l'hôtel des ventes du quartier commerçant",
		["At 60 {npc:5149} in the {object:32362} sends you to {quest:7638} in {zone:1453}'s Cathedral of Light."] = "Au niveau 60, {npc:5149}, dans {object:32362}, vous envoie voir {quest:7638} à la cathédrale de la Lumière de {zone:1453}.",
		["Back to Lord Grayson"] = "Retour auprès du seigneur Grayson",
		["Bring the materials and 150 gold, taken at the hand-in. {npc:1416} walks to his forge and hands you the {item:18753}."] = "Apportez les matériaux et 150 pièces d'or, prélevées quand vous rendez la quête. {npc:1416} va jusqu'à sa forge et vous remet le {item:18753}.",
		["Dire Maul West's door"] = "La porte de Haches-Tripes Ouest",
		["Enriched Manna Biscuits"] = "Biscuits enrichis en manne",
		["Enriched Manna Biscuits: {npc:10857}, {area:3197}"] = "Biscuits enrichis en manne : {npc:10857}, {area:3197}",
		["Lord Grayson blesses the censer into the {item:18752} for {area:2627}."] = "Le seigneur Grayson bénit l'encensoir, qui devient l'{item:18752}, pour {area:2627}.",
		["Lord Grayson hands you {item:18804}: open it for the {item:18746} and the {item:18792}. Keep both."] = "Le seigneur Grayson vous remet la {item:18804} : ouvrez-la pour le {item:18746} et le {item:18792}. Gardez les deux.",
		["Lord Grayson keeps the barding for now: you get it back with the next quest."] = "Le seigneur Grayson garde le caparaçon pour l'instant : vous le récupérez avec la quête suivante.",
		["Lord Grayson takes the censer back."] = "Le seigneur Grayson reprend l'encensoir.",
		["Paladin Charger"] = "Destrier de paladin",
		["Stratholme Supply Crates, inside"] = "Caisses de fournitures de Stratholme, à l'intérieur",
		["Terrordale Spirits x25"] = "Esprits de Val-Terreur x25",
		["The {spell:23214} chain is long: {area:2279}, Dire Maul West and {area:2057} with a group, 350 gold in donations, and materials worth several hundred more (6 Arcanite Bars, 40 {item:14047}, 10 {item:8836}, two diamonds). Start saving early. Lord Grayson stands in the Cathedral of Light, {npc:6171} nearby."] = "La chaîne de {spell:23214} est longue : {area:2279}, Haches-Tripes Ouest et {area:2057} en groupe, 350 pièces d'or en dons, et des matériaux valant plusieurs centaines de plus (6 Barres d'arcanite, 40 {item:14047}, 10 {item:8836}, deux diamants). Commencez à économiser tôt. Le seigneur Grayson se tient dans la cathédrale de la Lumière, {npc:6171} tout près.",
		["Two diamonds"] = "Deux diamants",
		["Your epic mount at 60, summoned at will: the faster step up from the Warhorse."] = "Votre monture épique au niveau 60, invoquée à volonté : l'étape plus rapide après le Cheval de guerre.",
		["{area:2057} lies under {area:2298}, the island town in the south-east of the {zone:1422}; the door needs the {item:13704} (The Key to {area:2057}). Clear the {object:179746}, Rattlegore's room in the basement, then use the {item:18746} at its centre. Four waves of spirits come, each ending with an Aspect: players judge them with {spell:1105}, Justice, Righteousness and then Light, which stuns them. {npc:14516} (level 62 elite) comes after the last; he mind-controls players. Loot the {item:18749}, use it inside the Ossuary to redeem it, and give it and the {item:18792} to {npc:14568}. If the group wipes, the gates lock and the scryer is gone: abandon the quest and take it again from Lord Grayson for a new satchel. A group of five at 60. Again Into the {object:179746}, after the mount, lets you fight him again."] = "{area:2057} se trouve sous {area:2298}, la ville insulaire au sud-est des {zone:1422} ; la porte exige la {item:13704} (La clé de {area:2057}). Nettoyez le Grand ossuaire, la salle de Cliquettripes au sous-sol, puis utilisez le {item:18746} en son centre. Quatre vagues d'esprits arrivent, chacune terminée par un Aspect : les joueurs les jugent avec {spell:1105}, Justice, Piété puis Lumière, ce qui les étourdit. {npc:14516} (élite de niveau 62) vient après la dernière ; il contrôle l'esprit des joueurs. Ramassez l'{item:18749}, utilisez-la dans l'ossuaire pour la racheter, et donnez-la avec le {item:18792} au {npc:14568}. Si le groupe est anéanti, les grilles se ferment et le cristal disparaît : abandonnez la quête et reprenez-la auprès du seigneur Grayson pour une nouvelle sacoche. Un groupe de cinq au niveau 60. « De nouveau dans le Grand ossuaire », après la monture, permet de l'affronter de nouveau.",
		["{area:2279} is a dungeon for a group of five at 58-60, at the north end of the {zone:1423}. Stratholme Supply Crates along the streets of both halves hold the Holy Water, one to three each; they come back after three minutes. Some crates let out a swarm of plagued rats or maggots: be ready. The main gate (the Scarlet half) needs no key."] = "{area:2279} est un donjon pour un groupe de cinq au niveau 58-60, au nord des {zone:1423}. Les Caisses de fournitures de Stratholme, le long des rues des deux moitiés, contiennent l'eau bénite, une à trois chacune ; elles reviennent au bout de trois minutes. Certaines caisses libèrent un essaim de rats ou d'asticots pestiférés : soyez prêt. La porte principale (la moitié écarlate) ne demande pas de clé.",
		["{area:2577} lies in central {zone:1444}. From the gate at the foot of the ruins, walk up through the outer courtyards to the West wing's door at their north end; it needs a {item:18249} (from Pusillin in Dire Maul East) or a rogue's lockpicking. {npc:11489} (level 60 elite) stands at the far end of the West wing's first courtyard. Once attacked he calls every {npc:11459} still alive in the courtyard: kill them first. His death frees the {quest:7643}: talk to it to give it the horse feed and the {item:18753}, and it blesses the barding. A group of five at 60."] = "{area:2577} se trouve au centre de {zone:1444}. Depuis la porte au pied des ruines, montez à travers les cours extérieures jusqu'à la porte de l'aile Ouest, à leur extrémité nord ; elle exige une {item:18249} (de Pusillin, à Haches-Tripes Est) ou le crochetage d'un voleur. {npc:11489} (élite de niveau 60) se tient au fond de la première cour de l'aile Ouest. Une fois attaqué, il appelle chaque {npc:11459} encore en vie dans la cour : tuez-les d'abord. Sa mort libère l'{quest:7643} : parlez-lui pour lui donner la nourriture pour cheval et le {item:18753}, et il bénit le caparaçon. Un groupe de cinq au niveau 60.",
		["{area:2627} lies in the far north-west of the {zone:1423}, west of the {area:2279} gates. Stand inside a green glowing patch on the ground (a {object:179747}; some are inside the ruined houses) and use the {item:18752}: up to three Terrordale Spirits (level 59-60) rise and attack. Their {spell:7713} lowers all your stats by 30%: fight them one at a time and use {spell:2878}. The patches come back quickly; several paladins can work side by side."] = "{area:2627} se trouve à l'extrême nord-ouest des {zone:1423}, à l'ouest des portes de {area:2279}. Placez-vous dans une tache verte lumineuse au sol (un esprit hanteur de Val-Terreur ; certaines sont dans les maisons en ruine) et utilisez l'{item:18752} : jusqu'à trois Esprits de Val-Terreur (niveau 59-60) s'élèvent et attaquent. Leur {spell:7713} réduit toutes vos caractéristiques de 30 % : combattez-les un par un et utilisez {spell:2878}. Les taches reviennent vite ; plusieurs paladins peuvent travailler côte à côte.",
		["{item:14047} drops from humanoids of level 50 and up ({area:2255}'s Bruisers, the Scarlet Crusade in the Plaguelands, the {area:2577} ogres). {item:8836} is a Plaguelands herb ({skill:182} 220), common around {area:3197}. An {item:12360} is an alchemist's transmute from a {item:12359} and an {item:12363}, once every two days per alchemist: ask a guild alchemist early, or buy the bars. The Auction House sells all three."] = "Le {item:14047} tombe sur les humanoïdes de niveau 50 et plus (les Cogneurs d'{area:2255}, la Croisade écarlate dans les Maleterres, les ogres de {area:2577}). Les {item:8836} sont une herbe des Maleterres ({skill:182} 220), courante autour du {area:3197}. Une {item:12360} est une transmutation d'alchimiste à partir d'une {item:12359} et d'un {item:12363}, une fois tous les deux jours par alchimiste : demandez tôt à un alchimiste de votre guilde, ou achetez les barres. L'hôtel des ventes vend les trois.",
		["{item:14047} x40"] = "{item:14047} x40",
		["{item:18749}, inside the {object:179746}"] = "{item:18749}, dans le Grand ossuaire",
		["{item:18752}, inside a green patch"] = "{item:18752}, dans une tache verte",
		["{item:18792}, from the satchel"] = "{item:18792}, dans la sacoche",
		["{item:8836} x10"] = "{item:8836} x10",
		["{npc:11406}, the priest trainer, walks about the {object:32386} in {zone:1455}'s {object:32362}. He gives you his censer for a donation of 150 gold, taken at the hand-in. Keep the censer."] = "{npc:11406}, le maître des prêtres, déambule dans la salle des Mystères de la {object:32362} de {zone:1455}. Il vous donne son encensoir contre un don de 150 pièces d'or, prélevé quand vous rendez la quête. Gardez l'encensoir.",
		["{npc:11406}: 150 gold"] = "{npc:11406} : 150 pièces d'or",
		["{npc:11489}, inside the West wing"] = "{npc:11489}, dans l'aile Ouest",
		["{npc:1416} works in {zone:1453}'s {object:28027}. He forges the {item:18753} from your materials and 150 gold."] = "{npc:1416} travaille dans le {object:28027} de {zone:1453}. Il forge le {item:18753} avec vos matériaux et 150 pièces d'or.",
		["{npc:1416}'s materials"] = "Matériaux de {npc:1416}",
		["{npc:1416}: 150 gold"] = "{npc:1416} : 150 pièces d'or",
		["{npc:2357} breeds horses in {area:271}'s stable. She makes the {quest:7645} from the 20 biscuits and 50 gold, taken at the hand-in."] = "{npc:2357} élève des chevaux dans l'écurie d'{area:271}. Elle prépare le {quest:7645} avec les 20 biscuits et 50 pièces d'or, prélevées quand vous rendez la quête.",
		["{npc:6171}, Cathedral of Light"] = "{npc:6171}, cathédrale de la Lumière",
		["{npc:928}: the {item:18753}"] = "{npc:928} : {item:18753}",
		["{object:2160} quartermasters sell Enriched Manna Biscuits, five for 60 silver, once the {object:92525} is Friendly with you: {npc:10857} at {area:3197} or {npc:11536} at {area:2268}. Scourgestones and the Plaguelands quests raise the standing."] = "Les intendants de l'{object:2160} vendent les Biscuits enrichis en manne, cinq pour 60 pièces d'argent, une fois que l'{object:92525} vous est Amicale : {npc:10857} au {area:3197} ou {npc:11536} à la {area:2268}. Les pierres du Fléau et les quêtes des Maleterres font monter la réputation.",
} end)()
t.guides["forever/collectibles/mounts/alliance/paladin-warhorse"] = (function() return {
		["At 40 {npc:6179}, upstairs in the {object:32386}, sends you to {npc:6171} in {zone:1453} ({npc:5149} downstairs gives the same errand; take one). Take the {area:2257} to {zone:1453}."] = "Au niveau 40, {npc:6179}, à l'étage de la salle des Mystères, vous envoie voir {npc:6171} à {zone:1453} ({npc:5149}, en bas, donne la même course ; prenez-en une). Prenez le {area:2257} jusqu'à {zone:1453}.",
		["Paladin Warhorse"] = "Cheval de guerre de paladin",
		["Your first mount at 40, summoned at will: a paladin buys no horse."] = "Votre première monture au niveau 40, invoquée à volonté : un paladin n'achète pas de cheval.",
		["{npc:6171} stands in the Cathedral of Light. At 40 he offers {quest:1661}: accept it and hand it straight back to learn {spell:13819}. Paladins do not buy a horse."] = "{npc:6171} se tient dans la cathédrale de la Lumière. Au niveau 40, il propose {quest:1661} : acceptez-la et rendez-la aussitôt pour apprendre {spell:13819}. Les paladins n'achètent pas de cheval.",
} end)()
t.guides["forever/collectibles/mounts/alliance/ram"] = (function() return {
		["Any Alliance race can buy these rams, but riding one also takes {spell:826}, which only Dwarves get with {skill:762}. {npc:4772} teaches it to other races once they are Exalted with {faction:47} (the Ironforge Reputation guide shows the way). Until then, don't buy a ram for this character."] = "Toute race de l'Alliance peut acheter ces béliers, mais en monter un demande aussi {spell:826}, que seuls les Nains reçoivent avec la {skill:762}. {npc:4772} l'enseigne aux autres races une fois Exaltées auprès de {faction:47} (le guide de réputation de Forgefer montre le chemin). D'ici là, n'achetez pas de bélier pour ce personnage.",
		["Learn to ride"] = "Apprenez à monter",
		["Pick a colour"] = "Choisissez une couleur",
		["Ram"] = "Bélier",
		["{area:803} is east of {area:131} on the road to {zone:1432}; {npc:4772} stands beside {npc:1261}'s rams. At 40 {npc:4772} teaches {skill:762} to Dwarves for 100g (10% less at Honored with {faction:47}), and it comes with a ram. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "Le {area:803} est à l'est de {area:131}, sur la route du {zone:1432} ; {npc:4772} se tient à côté des béliers de {npc:1261}. Au niveau 40, {npc:4772} enseigne la {skill:762} aux Nains pour 100 po (10 % de moins à Honoré auprès de {faction:47}), avec un bélier. Les autres races apprennent la {skill:762}, avec leur propre première monture, auprès du maître de monte de leur race.",
		["{item:5864}, 20g"] = "{item:5864}, 20 po",
		["{item:5872}, 20g"] = "{item:5872}, 20 po",
		["{item:5873}, 20g"] = "{item:5873}, 20 po",
		["{npc:1261} sells the other colours (20g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:1261} vend les autres couleurs (20 po chacune dans le client Forever). Achetez celles que vous voulez, ou aucune si la monture reçue vous plaît.",
		["{npc:4772}, riding trainer"] = "{npc:4772}, maître d'équitation",
		["{spell:826} for other races"] = "{spell:826} pour les autres races",
} end)()
t.guides["forever/collectibles/mounts/alliance/saber"] = (function() return {
		["Any Alliance race can buy these sabers, but riding one also takes {spell:828}, which only Night Elves get with {skill:762}. {npc:4753} teaches it to other races once they are Exalted with {faction:69} (the Darnassus Reputation guide shows the way). Until then, don't buy a saber for this character."] = "Toute race de l'Alliance peut acheter ces sabres, mais en monter un demande aussi {spell:828}, que seuls les Elfes de la nuit reçoivent avec la {skill:762}. {npc:4753} l'enseigne aux autres races une fois Exaltées auprès de {faction:69} (le guide de réputation de Darnassus montre le chemin). D'ici là, n'achetez pas de sabre pour ce personnage.",
		["Learn to ride"] = "Apprendre à monter",
		["Pick a colour"] = "Choisir une couleur",
		["Saber"] = "Sabre",
		["new in Forever, 20g; beta players found it here"] = "nouveau dans Forever, 20 po ; les joueurs de la bêta l'ont trouvé ici",
		["{item:8629}, 20g"] = "{item:8629}, 20 po",
		["{item:8631}, 20g"] = "{item:8631}, 20 po",
		["{item:8632}, 20g"] = "{item:8632}, 20 po",
		["{npc:4730} sells the other colours (20g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:4730} vend les autres couleurs (20 po chacune dans le client Forever). Achetez celles que vous voulez, ou aucune si la monture reçue vous plaît.",
		["{npc:4753} and {npc:4730}'s sabers are in the {area:1658}'s riding grounds in {faction:69}. At 40 {npc:4753} teaches {skill:762} to Night Elves for 100g (10% less at Honored with {faction:69}), and it comes with a saber. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{npc:4753} et les sabres-de-givre de {npc:4730} sont sur le terrain de monte de l'{area:1658}, à {faction:69}. Au niveau 40, {npc:4753} enseigne la {skill:762} aux Elfes de la nuit pour 100 po (10 % de moins à Honoré auprès de {faction:69}), avec un sabre. Les autres races apprennent la {skill:762}, avec leur propre première monture, auprès du maître de monte de leur race.",
		["{npc:4753}, riding trainer"] = "{npc:4753}, maître de monte",
		["{spell:828} for other races"] = "{spell:828} pour les autres races",
} end)()
t.guides["forever/collectibles/mounts/alliance/stormpike-battle-charger"] = (function() return {
		["The Forever client lists it at 200g and level 60. It runs at full speed, so riding it needs Journeyman {skill:762}; any Alliance race can ride it."] = "Le client Forever l'affiche à 200 po et au niveau 60. Elle va à pleine vitesse, la monter demande donc la {skill:762} (compagnon) ; toute race de l'Alliance peut la monter.",
		["{area:2839} (level 51+) raises {faction:730}: win, capture towers and graveyards, and hand in the battleground's turn-ins; the Alterac Valley Reputation guide shows the fastest way. {npc:13217} waits outside the battleground on the {zone:1416} border above {area:287}; {npc:13216} inside {area:2839} sells the same mount."] = "La {area:2839} (niveau 51+) fait monter la {faction:730} : gagnez, prenez des tours et des cimetières, et rendez les objets du champ de bataille ; le guide de réputation de la vallée d'Alterac montre le chemin le plus rapide. {npc:13217} attend hors du champ de bataille, à la frontière des {zone:1416}, au-dessus d'{area:287} ; {npc:13216}, dans la {area:2839}, vend la même monture.",
		["{npc:13217}, 200g"] = "{npc:13217}, 200 po",
} end)()
t.guides["forever/collectibles/mounts/alliance/swift-horse"] = (function() return {
		["Any Alliance race can buy these horses, but riding one also takes {spell:824}, which only Humans get with {skill:762}. {npc:4732} teaches it to other races once they are Exalted with {faction:72} (the Stormwind Reputation guide shows the way). Until then, don't buy a horse for this character."] = "Toute race de l'Alliance peut acheter ces chevaux, mais en monter un demande aussi {spell:824}, que seuls les Humains reçoivent avec la {skill:762}. {npc:4732} l'enseigne aux autres races une fois Exaltées auprès de {faction:72} (le guide de réputation de Hurlevent montre le chemin). D'ici là, n'achetez pas de cheval pour ce personnage.",
		["Journeyman {skill:762}"] = "{skill:762} (compagnon)",
		["Pick a colour"] = "Choisir une couleur",
		["Swift Horse"] = "Cheval rapide",
		["{item:18776}, 200g"] = "{item:18776}, 200 po",
		["{item:18777}, 200g"] = "{item:18777}, 200 po",
		["{item:18778}, 200g"] = "{item:18778}, 200 po",
		["{npc:384} sells the other colours (200g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:384} vend les autres couleurs (200 po chacune dans le client Forever). Achetez celles que vous voulez, ou aucune si la monture reçue vous plaît.",
		["{npc:4732} and {npc:384}'s horse pen are at {area:88} in eastern {zone:1429}. At 60 {npc:4732} teaches Journeyman {skill:762} to Humans for 1,000g (10% less at Honored with {faction:72}); Blizzard says it comes with a mount. Other races train it at their own race's riding trainer. Each swift horse costs 200g here."] = "{npc:4732} et l'enclos à chevaux de {npc:384} sont au {area:88}, dans l'est de la {zone:1429}. Au niveau 60, {npc:4732} enseigne la {skill:762} (compagnon) aux Humains pour 1 000 po (10 % de moins à Honoré auprès de {faction:72}) ; d'après Blizzard, elle s'accompagne d'une monture. Les autres races l'apprennent auprès du maître de monte de leur race. Chaque cheval rapide coûte ici 200 po.",
		["{npc:4732}, riding trainer"] = "{npc:4732}, maître de monte",
		["{spell:824} for other races"] = "{spell:824} pour les autres races",
} end)()
t.guides["forever/collectibles/mounts/alliance/swift-mechanostrider"] = (function() return {
		["Any Alliance race can buy these mechanostriders, but riding one also takes {spell:10907}, which only Gnomes get with {skill:762}. {npc:7954} teaches it to other races once they are Exalted with {faction:54} (the Gnomeregan Exiles Reputation guide shows the way). Until then, don't buy a mechanostrider for this character."] = "Toute race de l'Alliance peut acheter ces mécanotrotteurs, mais en monter un demande aussi {spell:10907}, que seuls les Gnomes reçoivent avec la {skill:762}. {npc:7954} l'enseigne aux autres races une fois Exaltées auprès des {faction:54} (le guide de réputation des Exilés de Gnomeregan montre le chemin). D'ici là, n'achetez pas de mécanotrotteur pour ce personnage.",
