		["{zone:1445} is east of the southern {zone:1413}; {area:496} in the north-west is the Horde town."] = "{zone:1445} se trouve à l'est du sud des {zone:1413} ; {area:496}, au nord-ouest, est la ville de la Horde.",
		["{zone:1445}: level 61+ area"] = "{zone:1445} : zone de niveau 61+",
		["{zone:2652}, the ruins between {zone:1443} and {zone:1412}, is entered from southern {zone:1443} through the {area:2657}."] = "On entre dans {zone:2652}, les ruines entre {zone:1443} et {zone:1412}, depuis le sud de {zone:1443} par {area:2657}.",
} end)()
t.guides["forever/exploration/kalimdor-45-60"] = (function() return {
		["1 area to discover here, level 15."] = "1 zone à découvrir ici, niveau 15.",
		["12 areas to discover here, levels 47-54."] = "12 zones à découvrir ici, niveaux 47-54.",
		["13 areas to discover here, levels 55-60."] = "13 zones à découvrir ici, niveaux 55-60.",
		["19 areas to discover here, levels 42-55."] = "19 zones à découvrir ici, niveaux 42-55.",
		["7 areas to discover here, level 55."] = "7 zones à découvrir ici, niveau 55.",
		["7 areas to discover here, levels 48-55."] = "7 zones à découvrir ici, niveaux 48-55.",
		["9 areas to discover here. Its creatures are level 54-60."] = "9 zones à découvrir ici. Ses créatures sont de niveau 54-60.",
		["Alliance town: Horde characters only need to touch its edge (guards)"] = "Ville de l'Alliance : les personnages de la Horde n'ont qu'à en toucher le bord (gardes)",
		["Exploration: {zone:1414} 45-60"] = "Exploration : {zone:1414} 45-60",
		["Exploring the entire world map on one character is a Forever Legacy Challenge (1 account-wide Legacy Point)."] = "Explorer toute la carte du monde avec un seul personnage est un défi d'héritage de Forever (1 point d'héritage pour tout le compte).",
		["Flight path here: {area:1237} (Kroum)."] = "Trajet aérien ici : {area:1237} (Kroum).",
		["Flight path here: {area:1997} (Brakkar)."] = "Trajet aérien ici : {area:1997} (Brakkar).",
		["Flight path here: {area:1998} (Mishellena)."] = "Trajet aérien ici : {area:1998} (Mishellena).",
		["Flight path here: {area:2255} (Maethrya)."] = "Trajet aérien ici : {area:2255} (Maethrya).",
		["Flight path here: {area:2255} (Yugrek)."] = "Trajet aérien ici : {area:2255} (Yugrek).",
		["Flight path here: {area:3137} (Jarrodenus)."] = "Trajet aérien ici : {area:3137} (Jarrodenus).",
		["Flight path here: {area:3425} ({npc:15177})."] = "Trajet aérien ici : {area:3425} ({npc:15177}).",
		["Flight path here: {area:3425} ({npc:15178})."] = "Trajet aérien ici : {area:3425} ({npc:15178}).",
		["Flight path here: {area:541} (Gryfe)."] = "Trajet aérien ici : {area:541} (Gryfe).",
		["Flight path here: {area:976} ({npc:7823})."] = "Trajet aérien ici : {area:976} ({npc:7823}).",
		["Flight path here: {area:976} ({npc:7824})."] = "Trajet aérien ici : {area:976} ({npc:7824}).",
		["Flight path here: {zone:1450} (Faustron)."] = "Trajet aérien ici : {zone:1450} (Faustron).",
		["Flight path here: {zone:1450} (Sindrayl)."] = "Trajet aérien ici : {zone:1450} (Sindrayl).",
		["Fly to {area:1237} if you have it, otherwise to {area:431}, and walk east out of {zone:1440} into {zone:1447}."] = "Prenez un vol pour {area:1237} si vous l'avez, sinon pour {area:431}, et marchez vers l'est pour quitter {zone:1440} et entrer en {zone:1447}.",
		["Fly to {area:3137} if you have it, otherwise to {area:415}, and walk east out of {zone:1440} into {zone:1447}."] = "Prenez un vol pour {area:3137} si vous l'avez, sinon pour {area:415}, et marchez vers l'est pour quitter {zone:1440} et entrer en {zone:1447}.",
		["From western {zone:1446} take the path down into {zone:1449}. {area:541} in the north is a neutral camp."] = "Depuis l'ouest de {zone:1446}, prenez le chemin qui descend dans {zone:1449}. {area:541}, au nord, est un camp neutre.",
		["Horde town: Alliance characters only need to touch its edge (guards)"] = "Ville de la Horde : les personnages de l'Alliance n'ont qu'à en toucher le bord (gardes)",
		["Starts in {zone:1446}, south of {zone:1445}. The last area of this guide completes the {zone:1414} map. 20 areas to discover here, levels 40-50."] = "Commence en {zone:1446}, au sud de {zone:1445}. La dernière zone de ce guide complète la carte de {zone:1414}. 20 zones à découvrir ici, niveaux 40-50.",
		["Take the {area:1769} tunnel in northern {zone:1448} through to {zone:1450} (druids: {spell:18960}). {area:2361} is neutral."] = "Prenez le tunnel de {area:1769}, au nord de {zone:1448}, pour rejoindre {zone:1450} (druides : {spell:18960}). {area:2361} est neutre.",
		["The other exit of the {area:1769} tunnel leads into {zone:1452}. {area:2255} is a neutral goblin town with flight masters for both factions."] = "L'autre sortie du tunnel de {area:1769} mène à {zone:1452}. {area:2255} est une ville gobeline neutre avec des maîtres de vol pour les deux factions.",
		["any one of these names counts"] = "n'importe lequel de ces noms compte",
		["{zone:1446} is south of {zone:1445} and {zone:1441}. {area:976} is a neutral goblin town."] = "{zone:1446} se trouve au sud de {zone:1445} et de {zone:1441}. {area:976} est une ville gobeline neutre.",
		["{zone:1448} is north of {zone:1440}."] = "{zone:1448} se trouve au nord de {zone:1440}.",
		["{zone:1451} is west of {zone:1449}, through the pass in its north-west. {area:3425} is neutral."] = "{zone:1451} est à l'ouest du {zone:1449}, par le col au nord-ouest. {area:3425} est neutre.",
		["{zone:2482} is reached from {zone:1452} through {area:2256} in the south. It is Forever's endgame leveling zone."] = "On rejoint {zone:2482} depuis {zone:1452} par {area:2256}, au sud. C'est la zone de progression de fin de jeu de Forever.",
} end)()
t.guides["forever/exploration/zephras-isle"] = (function() return {
		["Exploration: {zone:2521}"] = "Exploration : {zone:2521}",
		["Skyborne start here. Everyone else takes a skyboat, about every five minutes; either faction may take either one."] = "Les Éolides commencent ici. Les autres prennent un aéronef, environ toutes les cinq minutes ; les deux factions peuvent prendre l'un ou l'autre.",
		["The skyboat leaves the cliffs south of {area:17045}, north of {zone:1456} (another flies from {area:279})."] = "L'aéronef part des falaises au sud de {area:17045}, au nord de {zone:1456} (un autre part de {area:279}).",
		["The skyboat leaves the north side of {area:279} in the {zone:1416} (another flies from north of {zone:1456})."] = "L'aéronef part du côté nord de {area:279}, dans {zone:1416} (un autre part du nord de {zone:1456}).",
		["any one of these names counts"] = "n'importe lequel de ces noms compte",
		["{zone:2521} is the Skyborne starting island, a world of its own in {area:17221}; anyone may visit. 20 areas to discover here, levels 3-12."] = "{zone:2521} est l'île de départ des Éolides, un monde à part dans {area:17221} ; tout le monde peut la visiter. 20 zones à découvrir ici, niveaux 3-12.",
} end)()
t.guides["forever/horde/02-the-barrens"] = (function() return {
		["Assist {npc:261366}: stay by him when {npc:261367} and the {area:21} marines come up the ridge"] = "Aidez {npc:261366} : restez près de lui quand {npc:261367} et les soldats de marine de {area:21} montent la crête",
		["At the {object:147538}: summons {quest:882}"] = "À l'arbre mort : invoque {quest:882}",
		["Back east over the bridge and up the trail to {npc:5900}'s shrine, as at 10. {npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "Retournez vers l'est par le pont et montez le sentier jusqu'au sanctuaire de {npc:5900}, comme à l'étape 10. {npc:5900} fabrique {item:6636} avec le goudron et la bourse. Utilisez-le près du brasero à côté de lui pour révéler {npc:5893}, tuez-la pour obtenir {item:6655}, puis placez la braise dans le brasero.",
		["Back to the Razormane camp. Geomancers and Defenders hold its eastern half; {npc:3438} walks among them.\nCareful: Razormane Flesheaters and Berserkers (18-19) are elites in the camp's north-east, near {npc:3438}: pull {npc:3438} and the quilboar away from them one at a time."] = "Retour au camp Tranchecrin. Les Géomanciennes et les Défenseurs tiennent sa moitié est ; {npc:3438} se promène parmi eux.\nAttention : les Dévoreuses et les Berserkers tranchecrin (18-19) sont des élites au nord-est du camp, près de {npc:3438} : attirez {npc:3438} et les hurans un par un loin d'eux.",
		["Bristleback camps"] = "Camps Dos-hirsute",
		["Burning Blade Cultists hold {area:1898} in northern {zone:1411}; they drop the {item:6652}. The {item:5026} comes from the Razormane on your next visit to their camp."] = "Les Sectateurs de la Lame ardente tiennent {area:1898}, dans le nord de {zone:1411} ; ils laissent tomber la {item:6652}. Le {item:5026} vient des Tranchecrin lors de votre prochaine visite à leur camp.",
		["Cast {spell:18960}"] = "Lancez {spell:18960}",
		["Dogran is chained up in the quilboar camp west of the road."] = "Dogran est enchaîné dans le camp huran à l'ouest de la route.",
		["Down the {area:458} to {area:378} again."] = "Redescendez la {area:458} jusqu'au {area:378}.",
		["Fill the {item:7766} at the quilboar watering hole"] = "Remplissez l'{item:7766} au point d'eau des huttiers",
		["Fly from the Crossroads to {area:1638}. {quest:853} waits in the {area:2197}, the cave under {area:1640}: hand in the spores there first, while their time runs. Then {npc:3033} trains you on {area:1639}."] = "Volez de la Croisée à {area:1638}. {quest:853} attend dans {area:2197}, la grotte sous la {area:1640} : rendez-y d'abord les spores, tant que leur temps court. Ensuite, {npc:3033} vous entraîne sur la {area:1639}.",
		["Fly to {area:1637}"] = "Prendre un vol pour {area:1637}",
		["Fly to {area:1638} to train: {npc:3033} is on {area:1639}."] = "Volez jusqu'aux {area:1638} pour vous entraîner : {npc:3033} est sur la {area:1639}.",
		["Follow the road east to the outpost above the {area:814}."] = "Suivez la route vers l'est jusqu'à l'avant-poste au-dessus de {area:814}.",
		["Follow the road south-east to {area:392} on the coast."] = "Suivez la route vers le sud-est jusqu'à {area:392}, sur la côte.",
		["Follow the {area:458} south to {area:378}."] = "Suivez la {area:458} vers le sud jusqu'au {area:378}.",
		["Grimtotem camp"] = "Le camp Totem sinistre",
		["He gives you the {item:15826}"] = "Il vous donne le {item:15826}",
		["He offers {quest:1838} next (1838, level 30): it needs {area:1717} and sends you all over Kalimdor and the Eastern Kingdoms. The Warrior class guide {quest:1838} covers it."] = "Il propose ensuite {quest:1838} (1838, niveau 30) : elle demande {area:1717} et vous envoie partout en Kalimdor et dans les Royaumes de l'Est. Le guide de classe Guerrier {quest:1838} la couvre.",
		["In from the north gate: {npc:3464} first, {npc:3338} by the inn, then up to {npc:3449} and {npc:3429} on the tower platform, where the flight master stands."] = "Entrez par la porte nord : d'abord {npc:3464}, {npc:3338} près de l'auberge, puis montez voir {npc:3449} et {npc:3429} sur la plateforme de la tour, où se tient le maître de vol.",
		["In the camp, Water Seekers and Thornweavers hold the western half, Hunters the middle; the supply crates sit at its eastern end.\nPlainstriders here count toward the beaks.\nCareful: Razormane Flesheaters and Berserkers (18-19) are elites; they stand in the camp's north-east, beside the supply crates: pull the quilboar away from them one at a time."] = "Dans le camp, les Sourciers et les Tisseuses d'épines tiennent la moitié ouest, les Chasseurs le milieu ; les caisses de ravitaillement sont à son extrémité est.\nLes Trotteurs des plaines d'ici comptent pour les becs.\nAttention : les Dévoreuses et les Berserkers tranchecrin (18-19) sont des élites ; ils se tiennent au nord-est du camp, à côté des caisses de ravitaillement : attirez les hurans un par un loin d'eux.",
		["Inside"] = "À l'intérieur",
		["Keep it: {npc:12696} in {zone:1440}, next guide"] = "Gardez-la : {npc:12696} en {zone:1440}, guide suivant",
		["North to the {area:383}. {npc:3682} camps below the hills; {npc:261366}, the hermit on the ridge behind him, has work for you only once {npc:3682} sends you up."] = "Au nord vers les {area:383}. {npc:3682} campe au pied des collines ; {npc:261366}, l'ermite sur la crête derrière lui, n'a du travail pour vous qu'une fois que {npc:3682} vous y envoie.",
		["North up the {area:458} to the Crossroads: {npc:3448} at the south gate, {npc:3432} by the inn, {npc:3428} west of the north gate."] = "Remontez la {area:458} vers le nord jusqu'à la Croisée : {npc:3448} à la porte sud, {npc:3432} près de l'auberge, {npc:3428} à l'ouest de la porte nord.",
		["North up the {area:458} to the Crossroads: {npc:3448} at the south gate, {npc:3432} by the inn, {npc:3428} west of the north gate. Keep the {item:5075}: {npc:3430} takes it on the next stop in {area:378}."] = "Remontez la {area:458} vers le nord jusqu'à la Croisée : {npc:3448} à la porte sud, {npc:3432} près de l'auberge, {npc:3428} à l'ouest de la porte nord. Gardez l'{item:5075} : {npc:3430} la prendra lors du prochain passage au {area:378}.",
		["On the top floor"] = "Au dernier étage",
		["On the way back down the {area:1076}, {npc:11856} is held in {npc:11858}'s hut at the bend in the road. Once you take her quest she walks straight off south-east to {area:2538}, the burned village, without waiting: stay close, or the quest fails.\nCareful: Three Grimtotems ambush her at the burned village and go for her, not you: pull them off her and kill their caster quickly."] = "En redescendant {area:1076}, {npc:11856} est retenue dans la hutte de {npc:11858}, au tournant de la route. Une fois sa quête acceptée, elle part directement vers le sud-est jusqu'à {area:2538}, le village incendié, sans vous attendre : restez près d'elle, sinon la quête échoue.\nAttention : trois Totem sinistre lui tendent une embuscade au village incendié et s'en prennent à elle, pas à vous : détournez-les d'elle et tuez vite leur lanceur de sorts.",
		["Over the {area:814} bridge below {area:379} and south along the {zone:1411} bank to where a narrow trail climbs the mountain: {npc:5900} keeps the shrine at the top. Mind the edges on the way up, and come back down the same trail."] = "Traversez le pont de {area:814} sous {area:379} puis longez la rive de {zone:1411} vers le sud jusqu'à un sentier étroit qui monte dans la montagne : {npc:5900} garde le sanctuaire au sommet. Attention aux bords en montant, et redescendez par le même sentier.",
		["Raptor nests"] = "Nids de raptors",
		["Razormane camp"] = "Camp Tranchecrin",
		["Savannah Patriarchs roam the plains east of the hills, and the Sprung Traps lie among them. {quest:876} leads the Witchwing harpies in the hills to the west.\nCareful: The route in passes stealthed Harpy Ambushers and an elite harpy that patrols."] = "Les Patriarches des savanes parcourent les plaines à l'est des collines, et les Pièges déclenchés se trouvent au milieu d'eux. {quest:876} dirige les harpies Ensorçaile dans les collines à l'ouest.\nAttention : le chemin d'accès passe près de harpies embusquées camouflées et d'une harpie élite qui patrouille.",
		["South-west from {area:392} across the plains to the {area:1697}: the three nests sit together south-west of the oasis, and Sunscale Scytheclaws guard them. Each nest needs a {item:5165}: kill Sunscale raptors (most drop one) until you have three, then use a feather at each nest."] = "Au sud-ouest de {area:392}, traversez les plaines jusqu'à {area:1697} : les trois nids se trouvent ensemble au sud-ouest de l'oasis, et des Faucheurs solécaille les gardent. Chaque nid demande une {item:5165} : tuez des raptors solécaille (la plupart en laissent tomber une) jusqu'à en avoir trois, puis utilisez une plume à chaque nid.",
		["Tauren: the {npc:11957} waits on the southern hill above the bridge. Skyborne: the {npc:272054} stands south of the twin bridges. Then the dens east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue."] = "Taurens : le {npc:11957} attend sur la colline sud au-dessus du pont. Éolides : l'{npc:272054} se tient au sud des ponts jumeaux. Ensuite, les tanières à l'est du lac : quittez votre forme, cliquez sur la statue à l'entrée pour cinq minutes de camouflage, évitez les esprits à l'intérieur et prenez une relique de chaque ; la {item:280680} se trouve au pied de la statue de chat blanc.",
		["The Venture Co. Overseers and Enforcers at the mine in the north-east corner of the zone drop the {item:5097}."] = "Les Surveillants de la KapitalRisk et Massacreurs de la KapitalRisk de la mine au nord-est de la zone laissent l'{item:5097}.",
		["The road climbs north as the {area:1076}. {quest:1483} has a hut where the road forks east to {area:461}."] = "La route grimpe vers le nord : c'est {area:1076}. {quest:1483} a une cabane là où la route bifurque vers l'est en direction de {area:461}.",
		["The {object:172960} is the canyon under the {object:172982}."] = "{object:172960} est le canyon sous {object:172982}.",
		["The {object:177792} lies at the north edge of the {area:382}, by the Venture Co. tower. It holds the {item:15883} for {quest:30}."] = "{object:177792} se trouve au bord nord de {area:382}, près de la tour de la KapitalRisk. Il contient le {item:15883} pour {quest:30}.",
		["The {object:4141} stands at the Venture Co. research site west of the {area:382}. Close the three valves around the drill, use the console again, then take the {item:5089} from {npc:3471} beside it.\nCareful: Several guards stand within aggro range of the valves, respawn in under about 3 minutes, and run at low health to bring back help; nearby mobs also join if you use a valve while they are close."] = "La {object:4141} se trouve sur le site de recherche de la KapitalRisk, à l'ouest de {area:382}. Fermez les trois vannes autour de la foreuse, utilisez à nouveau la console, puis prenez la {item:5089} sur l'{npc:3471}, juste à côté.\nAttention : plusieurs gardes se tiennent à portée d'aggro des vannes, réapparaissent en moins de 3 minutes environ et fuient à faible vie pour ramener de l'aide ; les monstres proches se joignent aussi au combat si vous utilisez une vanne près d'eux.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:209797} (level 20 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:209797} (élite de niveau 20) demande un groupe de 2. Passez-le si vous êtes seul : la route vous fait regagner cette expérience en tuant des monstres.",
		["Thunder Lizards and Lightning Hides graze just across the bridge below {area:379}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Les Lézards-tonnerre et les Foudroyants paissent juste de l'autre côté du pont, sous {area:379}.\nAttention : Halikor, un élite de niveau 12, rôde sur {area:369} parmi les lézards : repérez-le avant d'attirer quoi que ce soit.",
		["Thunder lizards across the river"] = "Lézards-tonnerre de l'autre côté de la rivière",
		["Thunderhawk Cloudscrapers circle over the same plains south of the camp."] = "Les Faucons-tonnerre des nuages tournoient au-dessus des mêmes plaines au sud du camp.",
		["Thunderheads graze on the plains just south of {area:378}. {quest:884}, a blue thunder lizard, roams among them: his Tailspike starts a quest."] = "Les Têtes-tonnerre paissent dans les plaines juste au sud du {area:378}. {quest:884}, un lézard-tonnerre bleu, erre parmi eux : sa pointe caudale lance une quête.",
		["Twitching Antennae"] = "Antennes frémissantes",
		["Twitching Antennae from the silithid"] = "Antennes mobiles sur les silithides",
		["Underwater"] = "Sous l'eau",
		["Upstairs"] = "À l'étage",
		["West from the burned village to {area:2539}: {npc:12816} stands just outside it, before the village."] = "À l'ouest du village incendié, jusqu'à {area:2539} : {npc:12816} se tient juste à l'extérieur, avant le village.",
		["While you are in the camp: {npc:3429}'s Water Seekers and Thornweavers in its western half, the Hunters in the middle, the supply crates at its eastern end.\nCareful: Razormane Flesheaters and Berserkers (18-19) are elites; they stand in the camp's north-east, beside the supply crates: pull the quilboar away from them one at a time."] = "Tant que vous êtes dans le camp : les Sourciers et les Tisseuses d'épines de {npc:3429} dans sa moitié ouest, les Chasseurs au milieu, les caisses de ravitaillement à son extrémité est.\nAttention : les Dévoreuses et les Berserkers tranchecrin (18-19) sont des élites ; ils se tiennent au nord-est du camp, à côté des caisses de ravitaillement : attirez les hurans un par un loin d'eux.",
		["Wizzlecrank drives his shredder out of the camp: stay with him and kill whatever attacks him. {npc:3442} takes it in {area:392}.\nCareful: The route leads west and climbs a ramp. Once you reach the top, two Venture Company mobs ambush you."] = "Wizzlecrank sort du camp avec son déchiqueteur : restez avec lui et tuez tout ce qui l'attaque. {npc:3442} le récupère à {area:392}.\nAttention : la route mène vers l'ouest et monte une rampe. Une fois en haut, deux monstres de la KapitalRisk vous tendent une embuscade.",
		["{area:1697}: kill these as you meet them"] = "{area:1697} : tuez-les au passage",
		["{area:1898} cultists"] = "Sectateurs de {area:1898}",
		["{area:385}: kill these as you meet them"] = "{area:385} : tuez-les au passage",
		["{area:392} flight master"] = "Maître de vol de {area:392}",
		["{item:10338}, from any zhevra; Zhevra Chargers graze around the tree"] = "{item:10338}, sur n'importe quel zhévra ; des Étalons zhévra paissent autour de l'arbre",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}, dans un {object:177785} au fond du lac",
		["{item:2449} from {npc:3490}; herbalists pick it on the plains"] = "{item:2449} auprès de {npc:3490} ; les herboristes en cueillent dans les plaines",
		["{npc:11798} in {area:2361} flies druids there"] = "{npc:11798} à {area:2361} y emmène les druides",
		["{npc:11799}, at the {area:2362}"] = "{npc:11799}, à {area:2362}",
		["{npc:11802}: the welcome from {npc:3033}"] = "{npc:11802} : l'accueil de {npc:3033}",
		["{npc:11856}, inside {npc:11858}'s hut"] = "{npc:11856}, dans la hutte de {npc:11858}",
		["{npc:11857}: keep it, {npc:11864} at {area:460} in the {zone:1413} & Stonetalon guide"] = "{npc:11857} : gardez-la, {npc:11864} à {area:460}, dans le guide {zone:1413} et Serres-Rocheuses",
		["{npc:16227}, beside {npc:3442}"] = "{npc:16227}, à côté de {npc:3442}",
		["{npc:246344} teaches Paladins in {area:1638}. You have no flight path there yet: fly to {area:378}, head west through {zone:1412} and up a lift, and take the flight path from {npc:2995} on the central rise."] = "{npc:246344} forme les Paladins aux {area:1638}. Vous n'avez pas encore ce trajet aérien : volez jusqu'au {area:378}, allez vers l'ouest à travers {zone:1412} et montez par un ascenseur, puis prenez le trajet auprès de {npc:2995} sur la mesa centrale.",
		["{npc:262119} and his marines hold the wrecked caravan south of {npc:261366}. The marines are linked: pulling one calls the rest. Pull from the edge and run; they leash short, so you can thin the camp one at a time before tackling the Corporal."] = "Le {npc:262119} et ses soldats de marine tiennent la caravane détruite au sud de {npc:261366}. Les soldats sont liés : en attirer un fait venir les autres. Attirez-les depuis le bord et courez ; ils abandonnent vite la poursuite, vous pouvez donc éclaircir le camp un par un avant d'affronter le caporal.",
		["{npc:3338} by the inn first, then the innkeeper, Helbrim by the north gate, {npc:3429} and {npc:3449} on the tower platform, {npc:3432} by the inn, and {npc:3448} at the south gate last. His seed test waits for the {npc:3395} pass at the {area:388}: go straight on north-west to the {area:383}. After the spores Helbrim offers {quest:853}, a delivery to {zone:1456} within 45 minutes: this route doesn't go there, so leave it (Druids take it on the next Crossroads stop, right before their flight to {zone:1456})."] = "{npc:3338} près de l'auberge d'abord, puis l'aubergiste, Helbrim près de la porte nord, {npc:3429} et {npc:3449} sur la plateforme de la tour, {npc:3432} près de l'auberge, et {npc:3448} à la porte sud en dernier. Son test des graines attend le passage pour {npc:3395} à {area:388} : continuez tout droit vers le nord-ouest jusqu'à {area:383}. Après les spores, Helbrim propose {quest:853}, une livraison à {zone:1456} en moins de 45 minutes : cet itinéraire n'y va pas, laissez-la donc (les druides la prennent à l'arrêt suivant à la Croisée, juste avant leur vol pour {zone:1456}).",
		["{npc:3390}: 45 minutes, for Zamah on the {zone:1456} step next"] = "{npc:3390} : 45 minutes, pour Zamah à l'étape suivante, à {zone:1456}",
		["{npc:3391}, upstairs"] = "{npc:3391}, à l'étage",
		["{npc:3395} walks among the Kolkar at the {area:388} south-east of the Crossroads. Test {npc:3448}'s seeds at the bubbling fissure on the oasis' east bank while you are there."] = "{npc:3395} se promène parmi les Kolkar à {area:388}, au sud-est de la Croisée. Testez les graines de {npc:3448} à la fissure bouillonnante sur la rive est de l'oasis pendant que vous y êtes.",
		["{npc:3396} leads the Kolkar on the west shore of {area:387}, south of {npc:3389}. He walks that shore, from about 46,36 in the north to 46,42 in the south: if he isn't at the arrow, follow the shore until you meet him. Hand his head to {npc:3389} on your last Crossroads stop. Oasis Snapjaws crawl in the oasis' water there: their shells are for {npc:3448}."] = "{npc:3396} mène les Kolkar sur la rive ouest de {area:387}, au sud de {npc:3389}. Il parcourt cette rive, d'environ 46,36 au nord à 46,42 au sud : s'il n'est pas à la flèche, suivez la rive jusqu'à le trouver. Rendez sa tête à {npc:3389} lors de votre dernier arrêt à la Croisée. Des Gueules d'acier des oasis rampent là dans l'eau de l'oasis : leurs carapaces sont pour {npc:3448}.",
		["{npc:3429}, at the top of the tower"] = "{npc:3429}, en haut de la tour",
		["{npc:3430}, in the cage"] = "{npc:3430}, dans la cage",
		["{npc:3432} offers {quest:95774} once {quest:4921} is handed in"] = "{npc:3432} propose {quest:95774} une fois {quest:4921} rendue",
		["{npc:3442}: the console is in the {area:382}, later"] = "{npc:3442} : la console est dans {area:382}, plus tard",
		["{npc:3448}: the Oasis Snapjaws at {area:387}, with {npc:3396} after the {zone:1454} trip"] = "{npc:3448} : les Gueules d'acier des oasis à {area:387}, avec {npc:3396} après le voyage à {zone:1454}",
		["{npc:3448}: the bubbling fissure at the {area:388}, on the {npc:3395} pass"] = "{npc:3448} : la fissure bouillonnante à {area:388}, lors du passage pour {npc:3395}",
		["{npc:3449}: the harpies come later, in the {area:383}"] = "{npc:3449} : les harpies viendront plus tard, dans {area:383}",
		["{npc:3465} is chained inside the hold. Talk to him to start the escort and stay close: Theramore soldiers attack on the way out. He walks you back to {area:392}."] = "{npc:3465} est enchaîné dans le fort. Parlez-lui pour lancer l'escorte et restez près de lui : des soldats de Theramore attaquent à la sortie. Il vous ramène à {area:392}.",
		["{npc:4197} lives in {area:2539}, the troll village just inside Stonetalon at the end of the road west from {npc:3389}."] = "{npc:4197} vit à {area:2539}, le village troll juste à l'entrée des Serres-Rocheuses, au bout de la route qui part vers l'ouest depuis {npc:3389}.",
		["{npc:4201}, inside"] = "{npc:4201}, à l'intérieur",
		["{npc:4201}: for {npc:3442}, beside {area:392}'s flight master at the end of the {zone:1413} & Stonetalon guide"] = "{npc:4201} : pour {npc:3442}, à côté du maître de vol de {area:392}, à la fin du guide {zone:1413} et Serres-Rocheuses",
		["{npc:4276}, below ground"] = "{npc:4276}, sous terre",
		["{npc:5878} camps beside the road east toward {area:392}."] = "{npc:5878} campe au bord de la route à l'est, vers {area:392}.",
		["{npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "{npc:5900} fabrique le {item:6636} avec le goudron et la bourse. Utilisez-le près du brasero à côté de lui pour révéler la {npc:5893}, tuez-la pour obtenir la {item:6655}, puis placez la braise dans le brasero.",
		["{npc:5901} waits on the hill south of {area:392}, on your way north."] = "{npc:5901} attend sur la colline au sud de {area:392}, sur votre route vers le nord.",
		["{npc:5907} stands on the ridge north of the Razormane camp."] = "{npc:5907} se tient sur la crête au nord du camp Tranchecrin.",
		["{npc:5907}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:5907} : {npc:2523}, votre {item:5176} et le {item:263412}",
		["{npc:5909}, a few steps away"] = "{npc:5909}, à quelques pas",
		["{npc:6018} stands in the {object:172961} on the city's west side."] = "{npc:6018} se tient dans {object:172961}, à l'ouest de la ville.",
		["{npc:6018} stands in the {object:172961}, on the city's west side."] = "{npc:6018} se tient dans la {object:172961}, à l'ouest de la ville.",
		["{npc:6018}: {npc:4606} in the {zone:1458}, two guides on"] = "{npc:6018} : {npc:4606} à {zone:1458}, dans deux guides",
		["{npc:6394}, inside"] = "{npc:6394}, à l'intérieur",
		["{object:3972} poster"] = "Affiche {object:3972}",
		["{quest:1483}, inside"] = "{quest:1483}, à l'intérieur",
		["{quest:1492}, on the dock"] = "{quest:1492}, sur le quai",
		["{quest:6127}: {area:384}, next guide"] = "{quest:6127} : {area:384}, guide suivant",
		["{quest:853}, in the {area:2197}"] = "{quest:853}, dans {area:2197}",
		["{quest:865}, if still open: Sunscale Scytheclaws prowl among the lions"] = "{quest:865}, si elle est encore en cours : des Faucheurs solécaille rôdent parmi les lions",
		["{zone:1413}: kill these as you meet them"] = "{zone:1413} : tuez-les au passage",
		["{zone:1454} class quests"] = "Quêtes de classe à {zone:1454}",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
		["{zone:1456} flight master"] = "Maître de vol des {zone:1456}",
} end)()
t.guides["forever/horde/03-silverpine-forest"] = (function() return {
		["Class trainer"] = "Maître de classe",
		["Follow the road north-east to the Yoricks' house at {area:238}."] = "Suivez la route vers le nord-est jusqu'à la maison des Yorick, à {area:238}.",
		["Follow the road south. The {object:1627} sits beside it, north of Pyrewood."] = "Suivez la route vers le sud. {object:1627} se trouve au bord, au nord de Bois-du-Bûcher.",
		["Inside"] = "À l'intérieur",
		["Mottled Worgs"] = "Worgs chamarrés",
		["Mottled Worgs prowl the hills around the house."] = "Les Worgs chamarrés rôdent sur les collines autour de la maison.",
		["North again to the Yoricks' house."] = "Retournez au nord jusqu'à la maison des Yorick.",
		["North of the {area:228}. {npc:1983} haunts the {area:240}: kill it, then walk across the field."] = "Au nord de {area:228}. {npc:1983} hante le {area:240} : tuez-le, puis traversez le champ.",
		["Speak with {npc:10181}, in the {object:36126}: {quest:93739}"] = "Parlez à {npc:10181}, dans {object:36126} : {quest:93739}",
		["Speak with {npc:10540}, in Grommash Hold"] = "Parlez à {npc:10540}, dans le fort Grommash",
		["Speak with {npc:3230}, in Grommash Hold"] = "Parlez à {npc:3230}, dans le fort Grommash",
		["Take the road north toward {zone:1420}: the Yoricks' house at {area:238} is on the way. {quest:425} lurks a short walk west of it."] = "Prenez la route du nord vers {zone:1420} : la maison des Yorick, à {area:238}, est sur le chemin. {quest:425} rôde à courte distance à l'ouest.",
		["Talk to {npc:10181}"] = "Parlez à {npc:10181}",
		["Talk to {npc:10540}"] = "Parlez à {npc:10540}",
		["Talk to {npc:3230}"] = "Parlez à {npc:3230}",
		["The cattails and speargrass grow along the water in the {object:172958}, east of the Drag."] = "Les massettes et les herbes-lances poussent au bord de l'eau dans {object:172958}, à l'est de la Herse.",
		["The {object:172960} is the canyon under the {object:172982}; {quest:829} stands at its far end."] = "{object:172960} est le canyon sous {object:172982} ; {quest:829} se tient tout au fond.",
		["Vile Fin murlocs"] = "Murlocs Aileron noir",
		["Walk in through the main gate. {npc:268701} stands in the {object:172982}."] = "Entrez par la grande porte. {npc:268701} se tient dans la {object:172982}.",
		["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Pendant que vous y êtes : apprenez le maniement des bâtons auprès de {npc:2704} ({object:172958}, 10 pièces d'argent) ; l'arme de mêlée d'un Chasseur vaut surtout par ses caractéristiques, et les armes à deux mains en portent le plus.",
		["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Pendant que vous y êtes : apprenez le maniement des bâtons auprès de {npc:2704} ({object:172958}, 10 pièces d'argent) ; un bâton apporte plus de caractéristiques de sorts qu'une arme à une main pendant la progression.",
		["While you're here: learn {spell:197} from {npc:11868} ({object:172958}, 10 silver); two-handers level a Paladin fastest."] = "Pendant que vous y êtes : apprenez {spell:197} auprès de {npc:11868} ({object:172958}, 10 pièces d'argent) ; les armes à deux mains font progresser un Paladin le plus vite.",
		["While you're here: learn {spell:197} from {npc:11868} ({object:172958}, 10 silver); two-handers level a Warrior fastest."] = "Pendant que vous y êtes : apprenez {spell:197} auprès de {npc:11868} ({object:172958}, 10 pièces d'argent) ; les armes à deux mains font progresser un Guerrier le plus vite.",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["Zeppelin to {zone:1458}"] = "Zeppelin pour {zone:1458}",
		["{area:159} is a short walk north up the road from the zeppelin towers; {npc:1499} is in the town hall."] = "{area:159} est à quelques pas au nord en remontant la route depuis les tours du zeppelin ; {npc:1499} est dans l'hôtel de ville.",
		["{area:228} is the Forsaken crypt-town in the middle of the forest. Everyone you need stands around the crypt entrance; {npc:2226}, the bat handler, is just east of it."] = "{area:228} est la ville-crypte des Réprouvés, au milieu de la forêt. Tous ceux dont vous avez besoin se tiennent autour de l'entrée de la crypte ; {npc:2226}, le maître des chauves-souris, est juste à l'est.",
		["{npc:11044}, in the Apothecarium"] = "{npc:11044}, dans l'Apothicarium",
		["{npc:11046}, the alchemy trainer, stands next door to {npc:3348}."] = "{npc:11046}, le maître des alchimistes, se tient juste à côté de {npc:3348}.",
		["{npc:11046}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:11046} : Camping 101, au feu de camp de Brakk en {zone:1411}",
		["{npc:11066}, the enchanting trainer, works in the Drag."] = "{npc:11066}, le maître des enchanteurs, travaille dans la Herse.",
		["{npc:11066}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:11066} : Camping 101, au feu de camp de Brakk en {zone:1411}",
		["{npc:1518}, inside"] = "{npc:1518}, à l'intérieur",
		["{npc:1937}: for Quinn, on the road north at the end"] = "{npc:1937} : pour Quinn, sur la route du nord à la fin",
		["{npc:1951}, inside"] = "{npc:1951}, à l'intérieur",
		["{npc:1952}, below ground"] = "{npc:1952}, sous terre",
		["{npc:1978} waits north-east of the house. Escort him back to {npc:1950}; worgs attack on the way."] = "{npc:1978} attend au nord-est de la maison. Escortez-le jusqu'à {npc:1950} ; des worgs attaquent en chemin.",
		["{npc:1978}, inside"] = "{npc:1978}, à l'intérieur",
		["{npc:2226}: {npc:4556} in the {zone:1458}, at the end of this guide; no need to buy the flight"] = "{npc:2226} : {npc:4556} à {zone:1458}, à la fin de ce guide ; inutile de payer le vol",
		["{npc:246152} trains Paladins in {area:159}, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine."] = "{npc:246152} entraîne les paladins à {area:159}, à courte distance au nord par la route depuis les tours des zeppelins. Redescendez la même route pour la forêt des Pins argentés.",
		["{npc:2855}, the tailoring trainer, is in the {object:172958}."] = "{npc:2855}, le maître des tailleurs, se trouve dans {object:172958}.",
		["{npc:2855}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:2855} : Camping 101, au feu de camp de Brakk en {zone:1411}",
		["{npc:3348} and {npc:3347} run the alchemy shop in the Drag; {npc:11046} is next door."] = "{npc:3348} et {npc:3347} tiennent la boutique d'alchimie de la Herse ; {npc:11046} est juste à côté.",
		["{npc:3365}, the leatherworking trainer, works in the {object:172958}."] = "{npc:3365}, le maître des travailleurs du cuir, travaille dans {object:172958}.",
		["{npc:3365}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:3365} : Camping 101, au feu de camp de Brakk en {zone:1411}",
		["{npc:3404}, the herbalism trainer, keeps her shop in the Drag."] = "{npc:3404}, la maîtresse des herboristes, tient sa boutique dans la Herse.",
		["{npc:3404}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:3404} : Camping 101, au feu de camp de Brakk en {zone:1411}",
		["{npc:4551}, the bat handler"] = "{npc:4551}, le maître des chauves-souris",
		["{npc:4551}: keep {item:16210}, Podrig takes it on the next stop at the {area:228}, at 22"] = "{npc:4551} : gardez {item:16210}, Podrig le prendra à la prochaine étape, à {area:228}, au niveau 22",
		["{npc:4556}, the weapon merchant beside the bat handler"] = "{npc:4556}, le marchand d'armes à côté du maître des chauves-souris",
		["{npc:4586}, the engineering trainer, works in the {zone:1458}."] = "{npc:4586}, le maître des ingénieurs, travaille à {zone:1458}.",
		["{npc:4586}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4586} : Camping 101, au feu de camp de {npc:265812} à Tirisfal",
		["{npc:4598}, the mining trainer, works in the {zone:1458}."] = "{npc:4598}, le maître des mineurs, travaille à {zone:1458}.",
		["{npc:4598}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4598} : Camping 101, au feu de camp de {npc:265812} à Tirisfal",
		["{npc:4605}, the blacksmithing trainer, works in the {zone:1458}."] = "{npc:4605}, le maître des forgerons, travaille à {zone:1458}.",
		["{npc:4605}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4605} : Camping 101, au feu de camp de {npc:265812} à Tirisfal",
		["{npc:4949}, inside Grommash Hold"] = "{npc:4949}, dans le fort Grommash",
		["{npc:4949}: {quest:93739}, a tour of the Horde's leaders"] = "{npc:4949} : {quest:93739}, une tournée des chefs de la Horde",
		["{npc:7088}, the skinning trainer, stands in the {object:172958}."] = "{npc:7088}, le maître des dépeceurs, se tient dans {object:172958}.",
		["{npc:7088}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:7088} : Camping 101, au feu de camp de Brakk en {zone:1411}",
		["{quest:264} is handed in at {object:24776}, a grave a few steps south of the crypt entrance, not to a person."] = "{quest:264} se rend à {object:24776}, une tombe à quelques pas au sud de l'entrée de la crypte, et non à un personnage.",
} end)()
t.guides["forever/horde/04-the-barrens"] = (function() return {
		["Bael'dun fortress"] = "Forteresse de Bael'dun",
		["East along the road from {area:2539} to {npc:4049}'s camp, on the way to {area:378}."] = "Vers l'est par la route depuis {area:2539} jusqu'au camp de {npc:4049}, sur le chemin du {area:378}.",
		["Fly to the Crossroads from the wind rider master: {npc:2995} on {zone:1456}'s central rise."] = "Volez jusqu'à la Croisée depuis le maître des coursiers du vent : {npc:2995}, sur le plateau central des {zone:1456}.",
		["Fly to {area:1638}"] = "Voler jusqu'aux {area:1638}",
		["Fly to {area:1638} first: two of its elders give quests worked on this guide's and the next guide's walks."] = "Volez d'abord jusqu'aux {area:1638} : deux de ses anciens donnent des quêtes réalisées pendant les trajets de ce guide et du suivant.",
		["Fly to {area:378}"] = "Voler jusqu'au {area:378}",
		["Fly to {area:392}"] = "Voler jusqu'à {area:392}",
		["Follow the road north toward {area:467}. Antlered Coursers graze along the way; the Sap Beasts, Twilight Runners and Fey Dragons roam the woods below the Peak, and the Cenarion druids hold the grove there."] = "Suivez la route vers le nord en direction du {area:467}. Des Coursiers à ramure ({npc:4018}) paissent en chemin ; Bêtes de sève ({npc:4020}), Coureurs crépusculaires ({npc:4067}) et Dragons-faë ({npc:4016}) parcourent les bois sous le pic, et les druides cénariens tiennent le bosquet là-bas.",
		["Follow the road west past Regthar's bunkers and {npc:4049}'s camp into Stonetalon: {npc:3995} waits below ground in {area:2539}, at the foot of the {area:1076}."] = "Suivez la route vers l'ouest après les bunkers de Regthar et le camp de {npc:4049} jusqu'aux Serres-Rocheuses : {npc:3995} attend sous terre à {area:2539}, au pied de {area:1076}.",
		["Follow the road west past Regthar's bunkers: {npc:4049} camps beside it at the edge of Stonetalon."] = "Suivez la route vers l'ouest après les bunkers de Regthar : {npc:4049} campe à côté, à l'orée des Serres-Rocheuses.",
		["From {area:2539} follow the road east to {npc:4049}'s camp, then south-east across the plains to {area:378}."] = "Depuis {area:2539}, suivez la route vers l'est jusqu'au camp de {npc:4049}, puis allez au sud-est à travers les plaines jusqu'au {area:378}.",
		["From {area:378} follow the road west through the gate into {zone:1412}, then north past {area:222} to {zone:1456}; a lift at the foot of the bluffs takes you up."] = "Depuis le {area:378}, suivez la route vers l'ouest et passez la porte vers {zone:1412}, puis allez au nord après {area:222} jusqu'aux {zone:1456} ; un ascenseur au pied des pitons vous fait monter.",
		["Gaea Dirt Mounds"] = "Monticules de poussière de Gaea ({object:177929})",
		["Gaea Seeds"] = "Graines de Gaea ({item:16205})",
		["Head back down the {area:1076} to {area:2539}."] = "Redescendez {area:1076} jusqu'à {area:2539}.",
		["South of Gann, the Bael'dun dwarves dig at {area:359}. Excavators and Foremen work the pit; {npc:3392} (26) carries the journal: pull him alone.\nCareful: Excavators (level 21-22) and Foremen (level 22-23) run off for help once they fall to 15% health, so more dwarves can join the fight."] = "Au sud de Gann, les nains de Bael'dun creusent à {area:359}. Des Excavateurs et des Contremaîtres travaillent dans la fosse ; le {npc:3392} (26) porte le journal : attirez-le seul.\nAttention : les Excavateurs (niveau 21-22) et les Contremaîtres (niveau 22-23) fuient chercher de l'aide une fois à 15 % de vie, d'autres nains peuvent donc rejoindre le combat.",
		["South-west of Bael Modan, {npc:12576} waits at the top of the {area:1718}."] = "Au sud-ouest de Bael Modan, {npc:12576} attend en haut de {area:1718}.",
		["South-west of Sun Rock lies the burned {area:465}. Plant the Gaea Seeds in the dirt mounds on the valley floor; the fire elementals drop {item:16312}. Bloodfury Harpies and Ambushers nest on the north side, Slayers and Roguefeathers to the south."] = "Au sud-ouest de Roche-Soleil s'étend le {area:465}. Plantez les Graines de Gaea dans les monticules de terre au fond de la vallée ; les élémentaires de feu lâchent {item:16312}. Harpies et Embusquées Rougefurie nichent au nord, Tueuses et Volplumes au sud.",
		["The Bael'dun Soldiers, Riflemen and Officers guard the fortress on the east side of the dig; all three items drop from them.\nCareful: Riflemen (level 24-25) Shoot from 5-30 yd, so nearby ones can join a fight from range."] = "Les Soldats, les Fusiliers et les Officiers de Bael'dun gardent la forteresse du côté est des fouilles ; les trois objets viennent d'eux.\nAttention : les Fusiliers (niveau 24-25) utilisent Tir de 5 à 30 m, ceux qui sont proches peuvent donc rejoindre un combat à distance.",
		["The Gaea Seeds lie in the grass around the southern shore of {area:464}, north of Sun Rock.\nCareful: Pridewings around the lake can aggro as a linked group."] = "Les Graines de Gaea se trouvent dans l'herbe autour de la rive sud du {area:464}, au nord du Roc-Soleil.\nAttention : les Fièrailes autour du lac peuvent attaquer en groupe lié.",
		["The dwarves' flying machine sits on its platform inside the dig site. Use the {item:5021} that {npc:3341} gave you on it."] = "La machine volante des nains repose sur sa plateforme dans le site de fouilles. Utilisez dessus le {item:5021} que {npc:3341} vous a donné.",
		["The flying machine"] = "La machine volante",
		["The road west past {npc:4049}'s camp"] = "La route de l'ouest après le camp de {npc:4049}",
		["The {area:1718}"] = "{area:1718}",
		["The {object:667362} grows on the bottom of {area:464}, off the same southern shore: dive to the plants and the Dried Mirkweed Piles; both give pods. Watch your breath."] = "Le {object:667362} pousse au fond du {area:464}, au large de la même rive sud : plongez jusqu'aux plantes et aux Tas d'obscurcie séchée ; les deux donnent des cosses. Surveillez votre souffle.",
		["To {zone:1456}"] = "Vers les {zone:1456}",
		["Up the {area:1076} past {npc:4201} and west to {area:460}; coming from {npc:4073}, back west past Ziz's hut."] = "Montez {area:1076} après {npc:4201}, puis allez vers l'ouest jusqu'à {area:460} ; si vous venez de {npc:4073}, revenez vers l'ouest en passant la hutte de Ziz.",
		["Up the {area:1076} to {npc:4201}' hut, then east along the road toward {area:461}: {npc:4074} patrols the road just east of the fork, {npc:4073} the slopes further north-east below the crag. Both are lone shredder robots; they roam, so follow the road until you meet them."] = "Montez {area:1076} jusqu'à la hutte de {npc:4201}, puis allez vers l'est par la route en direction de {area:461} : {npc:4074} patrouille sur la route juste à l'est de l'embranchement, {npc:4073} sur les pentes plus au nord-est, sous l'escarpement. Ce sont deux robots déchiqueteurs solitaires ; ils se déplacent, suivez donc la route jusqu'à les croiser.",
		["{area:378} flight master"] = "Maître de vol du {area:378}",
		["{area:465}: kill these as you meet them"] = "{area:465} : tuez-les au passage",
		["{item:277936}, from any Bloodfury harpy"] = "{item:277936}, sur n'importe quelle harpie Rougefurie",
		["{npc:10079}, at the top of the lift"] = "{npc:10079}, en haut de l'élévateur",
		["{npc:11860}: Glittering Sunstones from the Bloodfury harpies"] = "{npc:11860} : Héliolites lumineuses ({item:277936}) sur les harpies Rougefurie",
		["{npc:11861}, beside {npc:11862}"] = "{npc:11861}, à côté de {npc:11862}",
		["{npc:11862}, up on the ledge"] = "{npc:11862}, en haut sur la corniche",
		["{npc:11864} stands by the bonfire inside Sun Rock: Makaba's news that Kaya is alive is for her."] = "{npc:11864} se tient près du feu de camp à l'intérieur de Roche-Soleil : la nouvelle de Makaba selon laquelle Kaya est vivante lui est destinée.",
		["{npc:14242}, up in the tree just east of {npc:3341}"] = "{npc:14242}, dans l'arbre juste à l'est de {npc:3341}",
		["{npc:2995}, the wind rider master, stands on the central rise: take his flight path if you don't have it. {npc:3024} and {npc:4721} stand a short walk east of him."] = "{npc:2995}, le maître des coursiers du vent, se tient sur le plateau central : prenez son trajet aérien si vous ne l'avez pas. {npc:3024} et {npc:4721} se tiennent à quelques pas à l'est de lui.",
		["{npc:3024}: the {object:667362} grows in {area:464}, by Sun Rock"] = "{npc:3024} : le {object:667362} pousse dans le {area:464}, près de Roche-Soleil",
		["{npc:3341} walks around {area:1701}: look inside the circle on the map"] = "{npc:3341} se promène autour de {area:1701} : cherchez dans le cercle sur la carte",
		["{npc:3375} walks around {area:359}: look inside the circle on the map"] = "{npc:3375} se promène autour de {area:359} : cherchez dans le cercle sur la carte",
		["{npc:3429}, at the top of the tower"] = "{npc:3429}, en haut de la tour",
		["{npc:3430}, in the cage"] = "{npc:3430}, dans la cage",
		["{npc:3433}, at the north edge of the camp"] = "{npc:3433}, au bord nord du camp",
		["{npc:3442} stands beside the flight master you land at."] = "{npc:3442} se tient à côté du maître de vol où vous atterrissez.",
		["{npc:3442}: {quest:1094}, from {npc:4201}"] = "{npc:3442} : {quest:1094}, de la part de {npc:4201}",
		["{npc:3995}, below ground"] = "{npc:3995}, sous terre",
		["{npc:4049}: {npc:4074} and {npc:4073} roam east of {npc:4201}, on the way up"] = "{npc:4049} : {npc:4074} et {npc:4073} errent à l'est de {npc:4201}, sur le chemin de la montée",
		["{npc:4128} walks around {area:1156}: look inside the circle on the map"] = "{npc:4128} se promène autour de {area:1156} : cherchez dans le cercle sur la carte",
		["{npc:4198}'s next quest, Ordanus, is on the Alliance side of {zone:1440}. Skip it."] = "La quête suivante de {npc:4198}, Ordanus, se trouve du côté Alliance d'{zone:1440}. Passez-la.",
		["{npc:4198}, outside the gate"] = "{npc:4198}, devant la porte",
		["{npc:4721}: the phial comes from {zone:1440}, next guide"] = "{npc:4721} : la fiole vient d'{zone:1440}, guide suivant",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole, south of {area:378}, on the way to {area:359}."] = "La hutte de {npc:5899} se dresse sur la crête au-dessus du point d'eau des hurans, au sud de {area:378}, sur la route de {area:359}.",
		["{npc:5899}: the blue waterskin is filled in {zone:1440}, next guide"] = "{npc:5899} : l'outre bleue se remplit dans {zone:1440}, au guide suivant",
		["{npc:5899}: the red waterskin from {area:272}"] = "{npc:5899} : l'outre rouge de {area:272}",
		["{quest:873}, a big threshadon, swims in the shallows off the {area:391}, east of {npc:3388}."] = "{quest:873}, un grand battrodon, nage dans les hauts-fonds au large de {area:391}, à l'est de {npc:3388}.",
		["{zone:1442}: kill these as you meet them"] = "{zone:1442} : tuez-les au passage",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
		["{zone:1456} first: two of its elders give quests worked on this guide's and the next guide's walks. Fly to {area:378}; from there it is a walk west into {zone:1412} and north to the bluffs."] = "D'abord les {zone:1456} : deux de ses anciens donnent des quêtes réalisées pendant les trajets de ce guide et du suivant. Volez jusqu'au {area:378} ; de là, marchez vers l'ouest jusqu'en {zone:1412}, puis vers le nord jusqu'aux pitons.",
		["{zone:1456}'s central rise"] = "Le plateau central des {zone:1456}",
} end)()
t.guides["forever/horde/05-stonetalon-mountains"] = (function() return {
		["Back on the road south. Where it turns east into {area:287}, {npc:2214} waits at {area:285}."] = "De nouveau sur la route vers le sud. Là où elle tourne vers l'est dans {area:287}, {npc:2214} attend à {area:285}.",
		["Below ground"] = "Sous terre",
		["Down the road through Silverpine to the {area:228}: from the zeppelin towers, south through Tirisfal; from the {object:177790}, south-east from the coast to the road. {npc:2121} and {npc:1937} stand by the crypt entrance."] = "Descendez la route à travers la forêt des Pins argentés jusqu'au {area:228} : depuis les tours des zeppelins, vers le sud à travers Tirisfal ; depuis le {object:177790}, vers le sud-est depuis la côte jusqu'à la route. {npc:2121} et {npc:1937} se tiennent près de l'entrée de la crypte.",
		["Druid trainer"] = "Maître des druides",
		["East of Zoram'gar, the Thistlefur furbolgs fill the village and the hills around their hold.\nCareful: A Shaman at 15% health or lower runs off to find help, which can pull extra furbolgs."] = "À l'est de Zoram'gar, les furbolgs Crins-de-chardon remplissent le village et les collines autour de leur repaire.\nAttention : un Chaman à 15 % de vie ou moins fuit chercher de l'aide, ce qui peut attirer des furbolgs en plus.",
		["Every Wrathtail naga along the strand north of the outpost drops heads."] = "Chaque naga Irequeue de la grève au nord de l'avant-poste lâche des têtes.",
		["Fly to {area:1637}"] = "Prendre un vol pour {area:1637}",
		["From Seereth's camp head north-east across the {zone:1413} to the road north of the Crossroads; Rogues coming from Fizzule's tower head west to it. {npc:8582} stands on the watch tower of the {area:1703} where the road enters {zone:1440}."] = "Depuis le camp de Seereth, allez vers le nord-est à travers {zone:1413} jusqu'à la route au nord de la Croisée ; les voleurs qui viennent de la tour de Fizzule y vont vers l'ouest. {npc:8582} se tient sur la tour de guet du {area:1703}, là où la route entre en {zone:1440}.",
		["Inside the hold, Troll Chests lie along the tunnels. {npc:12818} is held deep inside: free him and protect him all the way out, then he runs home to {area:428}.\nCareful: Two scripted ambushes occur, each made up of three Thistlefurs (a Shaman, a Pathfinder and an Avenger, Ursa or Den Watcher): the first when you come back to the tunnel's fork inside the cave, the second just beyond the gate where {npc:3987} roams."] = "Dans le repaire, des Coffres de troll se trouvent le long des tunnels. {npc:12818} est retenu tout au fond : libérez-le et protégez-le jusqu'à la sortie, puis il rentre chez lui à {area:428}.\nAttention : deux embuscades scénarisées ont lieu, chacune composée de trois Crins-de-chardon (un Chaman, un Éclaireur et un Vengeur, une Ursa ou un Protecteur) : la première quand vous revenez à l'embranchement du tunnel dans la grotte, la seconde juste après la porte où rôde {npc:3987}.",
		["Naga brazier"] = "Brasero naga",
		["Naga heads"] = "Têtes de nagas",
		["On the way west, {npc:267214} is stuck in a ravine south of the main road, south-east of {area:415}. Shadowhorn Stags and Ashenvale Bears roam the woods all around it."] = "En allant vers l'ouest, {npc:267214} est coincé dans un ravin au sud de la route principale, au sud-est d'{area:415}. Des Cerfs à corne noire et des Ours d'Ashenvale parcourent les bois tout autour.",
		["Out of the inn to the {area:431} flight master and fly to {area:1637}."] = "Sortez de l'auberge, allez au maître de vol du {area:431} et volez jusqu'à {area:1637}.",
		["Steer {npc:267214}'s {npc:271181} out of the ravine to the main road within four minutes; if the channel breaks, ask {npc:267214} again."] = "Guidez {npc:271181} de {npc:267214} hors du ravin jusqu'à la route principale en moins de quatre minutes ; si la canalisation se rompt, redemandez à {npc:267214}.",
		["Thistlefur Hold"] = "Antre des Crins-de-Chardon",
		["Zeppelin to {zone:1458}"] = "Zeppelin pour {zone:1458}",
		["{area:431} is just north up the road. Coming in from the south, the flight master and {npc:12696}'s hunt board at {area:428} come first, then the vendors. {npc:12867} at the lumber camp offers Ashenvale Outrunners: leave it for the next {zone:1440} visit, at 26."] = "Le {area:431} est juste au nord, en remontant la route. En arrivant du sud, le maître de vol et le tableau de chasse de {npc:12696} à {area:428} viennent d'abord, puis les marchands. {npc:12867}, au camp de bûcherons, propose « Les estafettes d'Ashenvale » : gardez-la pour la prochaine visite en {zone:1440}, au niveau 26.",
		["{item:15882}, from the {object:177790}"] = "{item:15882}, dans le {object:177790}",
		["{item:271343}, from a {npc:1973}"] = "{item:271343}, sur un {npc:1973}",
		["{item:271350}, from the Tortured Souls among the ruins; below ground"] = "{item:271350}, sur les Âmes torturées parmi les ruines ; sous terre",
		["{npc:12818}, below ground"] = "{npc:12818}, sous terre",
		["{npc:2214}: Darthalia in {area:272}"] = "{npc:2214} : Darthalia à {area:272}",
		["{npc:2391} in {area:272} teaches Poisons: keep it"] = "{npc:2391}, à {area:272}, enseigne les Poisons : gardez la quête",
		["{npc:246152} trains Paladins in {area:159}, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine."] = "{npc:246152} entraîne les paladins à {area:159}, à courte distance au nord par la route depuis les tours des zeppelins. Redescendez la même route pour la forêt des Pins argentés.",
		["{npc:271181}, on the road"] = "{npc:271181}, sur la route",
		["{npc:3034} in {zone:1412}; {zone:1454} has no druid trainer"] = "{npc:3034} en {zone:1412} ; {zone:1454} n'a pas de maître des druides",
		["{npc:5875} stands in the {object:172960}. Use {item:6626} on the summoning circle there and defeat the succubus to bind her."] = "{npc:5875} se tient dans {object:172960}. Utilisez le {item:6626} sur le cercle d'invocation qui s'y trouve et vainquez la succube pour la lier.",
		["{npc:6389} stands just west of the crypt entrance: hand him {item:16210} from the {zone:1458}."] = "{npc:6389} se tient juste à l'ouest de l'entrée de la crypte : remettez-lui {item:16210} venant de {zone:1458}.",
} end)()
t.guides["forever/horde/06-hillsbrad-foothills"] = (function() return {
		["After returning Mission: Possible But Not Probable to Shenthul, bring {quest:2479} to {npc:2391} in {area:272}. Stay beside him until the brewing objective completes, then hand in the follow-up to learn Poisons. Finish it even if the Zanzil poison has already been removed; removing the debuff alone does not teach the skill."] = "Après avoir rendu Mission : possible mais pas probable à Shenthul, apportez {quest:2479} à {npc:2391}, à {area:272}. Restez à côté de lui jusqu'à ce que l'objectif de préparation soit rempli, puis rendez la quête suivante pour apprendre les Poisons. Terminez-la même si le poison de Zanzil a déjà été retiré ; retirer l'affaiblissement ne suffit pas à apprendre la compétence.",
		["Back to {area:272}"] = "Retour à {area:272}",
		["Bears, creepers and lions"] = "Ours, rampemousses et lions",
		["Careful: When one lion is attacked, nearby lions come to its aid, and the Vicious Black Bears sharing those fields can also join the fight."] = "Attention : quand un lion est attaqué, les lions proches viennent l'aider, et les Ours noirs vicieux qui partagent ces champs peuvent aussi rejoindre le combat.",
		["Drull and {npc:2238} are chained inside {area:275}'s courtyard buildings. Their locks need keys: {npc:2427} carries the {item:3467} and {npc:2428} the {item:3499}, both in the keep. Kill them, then open both locks.\nFrom {area:272} go south-east into the hills on the way to {area:275}. Rogues and Watchmen hold the camps along the way."] = "Drull et {npc:2238} sont enchaînés dans les bâtiments de la cour de {area:275}. Leurs cadenas nécessitent des clés : {npc:2427} porte la {item:3467} et {npc:2428} la {item:3499}, tous deux dans le donjon. Tuez-les, puis ouvrez les deux cadenas.\nDepuis {area:272}, allez vers le sud-est dans les collines en direction de {area:275}. Des Voleurs et des Guetteurs tiennent les camps en chemin.",
		["Drull's ball and chain"] = "Boulet et chaîne de Drull",
		["Fill the {item:7768} at the {object:107045} beside the inn"] = "Remplissez l'{item:7768} au {object:107045} à côté de l'auberge",
		["Inside"] = "À l'intérieur",
		["Just south of Masoj, the {item:3502} grow on the hillsides above the river."] = "Juste au sud de Masoj, les {item:3502} poussent sur les collines au-dessus de la rivière.",
		["Keep it: the {area:287} coast, later on the route"] = "Gardez-la : la côte de {area:287}, plus loin sur l'itinéraire",
		["Masoj hides on the hillside above {area:290}, south-west of Durnholde, on the way down to the blossoms."] = "Masoj se cache sur le flanc de colline au-dessus de {area:290}, au sud-ouest de Fort-de-Durn, en descendant vers les fleurs.",
		["Masoj wants an Apothecary Vial placed on three peaks. The southern one is the hilltop above {area:290}, south-east of the blossoms: use a vial at the top."] = "Masoj veut qu'une Fiole d'apothicaire soit placée sur trois sommets. Celui du sud est la colline au-dessus de {area:290}, au sud-est des fleurs : utilisez une fiole au sommet.",
		["Poison chain unfinished? Resume your current stage in the Class guide Poisons (Horde); completed quests do not need restarting. Arrange a group for Gallywix, finish the Hinott follow-up, then return to this leveling guide."] = "Suite des poisons inachevée ? Reprenez votre étape actuelle dans le guide de classe Poisons (Horde) ; les quêtes terminées n'ont pas besoin d'être recommencées. Formez un groupe pour Gallywix, terminez la suite d'Hinott, puis revenez à ce guide de progression.",
		["The Peasants work the fields south of the farmhouses. Every {area:287} human drops skulls; the Peasants drop them most often.\nCareful: A fleeing peasant that reaches the town hall can bring back many adds, including {area:287} footmen; snares, roots or similar effects keep them from escaping."] = "Les Paysans travaillent dans les champs au sud des fermes. Tous les humains de {area:287} lâchent des crânes ; les Paysans le plus souvent.\nAttention : un paysan qui fuit et atteint l'hôtel de ville peut ramener de nombreux renforts, dont des fantassins de {area:287} ; les effets de ralentissement, d'immobilisation ou similaires l'empêchent de s'échapper.",
		["The farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere. {npc:2451} tends the field south of the farms."] = "Les fermes à l'est du village de {area:287}. {npc:232} travaille le champ près de la ferme du nord, {npc:2403} celui plus au sud-est ; Ouvriers agricoles et Fermiers d'Hillsbrad sont partout. {npc:2451} s'occupe du champ au sud des fermes.",
		["The smithy"] = "La forge",
		["The smithy stands in the middle of {area:287} town. {npc:2404} and his apprentices work at the forge; the {object:1736} is stacked beside it. {npc:2449} walks the street north of it."] = "La forge se trouve au centre du village de {area:287}. {npc:2404} et ses apprentis y travaillent ; la {object:1736} est empilée à côté. {npc:2449} arpente la rue au nord.",
		["The {object:556670} poster by the inn"] = "L'affiche {object:556670} près de l'auberge",
		["Train with {npc:3033}. Before you fly on, {npc:3024} and {npc:4721}, a short walk east of the wind rider master, give two quests worked on the next guides' walks; then fly on to the Crossroads, where the next guide starts."] = "Entraînez-vous auprès de {npc:3033}. Avant de repartir, {npc:3024} et {npc:4721}, à quelques pas à l'est du maître des coursiers du vent, donnent deux quêtes qui se font en chemin dans les guides suivants ; puis prenez un vol pour la Croisée, où commence le guide suivant.",
		["West of Tarren Mill, Gray Bears, Forest Moss Creepers and Starving Mountain Lions roam the hills on the way down to the farms. The creepers drop {item:3477} rarely; you need only one."] = "À l'ouest de Moulin-de-Tarren, des Ours gris, des Rampemousses forestières et des Lions des montagnes affamés parcourent les collines en descendant vers les fermes. Les rampemousses lâchent rarement l'{item:3477} ; il vous en faut un seul.",
		["While you're here: learn Polearms from {npc:11870} ({object:36070}, 1 gold); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Pendant que vous y êtes : apprenez le maniement des armes d'hast auprès de {npc:11870} ({object:36070}, 1 pièce d'or) ; l'arme de mêlée d'un Chasseur vaut surtout par ses caractéristiques, et les armes à deux mains en portent le plus.",
		["While you're here: learn Polearms from {npc:11870} ({object:36070}, 1 gold); two-handers level a Warrior fastest."] = "Pendant que vous y êtes : apprenez le maniement des armes d'hast auprès de {npc:11870} ({object:36070}, 1 pièce d'or) ; les armes à deux mains font progresser un Guerrier le plus vite.",
		["While you're here: learn Swords from {npc:11870} ({object:36070}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "Pendant que vous y êtes : apprenez le maniement des épées auprès de {npc:11870} ({object:36070}, 10 pièces d'argent) ; une épée en main droite fait progresser un Voleur régulièrement.",
		["While you're here: learn {spell:202} from {npc:11870} ({object:36070}, 10 silver); two-handers level a Paladin fastest."] = "Pendant que vous y êtes : apprenez {spell:202} auprès de {npc:11870} ({object:36070}, 10 pièces d'argent) ; les armes à deux mains font progresser un Paladin le plus vite.",
		["While you're here: learn {spell:202} from {npc:11870} ({object:36070}, 10 silver); two-handers level a Warrior fastest."] = "Pendant que vous y êtes : apprenez {spell:202} auprès de {npc:11870} ({object:36070}, 10 pièces d'argent) ; les armes à deux mains font progresser un Guerrier le plus vite.",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["{area:272} flight master"] = "Maître de vol de {area:272}",
		["{area:272} is your base for this guide: the hearth brings you back here twice. Everyone stands around the town square."] = "{area:272} est votre base pour ce guide : la pierre de foyer vous y ramène deux fois. Tout le monde se tient autour de la place du village.",
		["{area:275}: kill these as you meet them"] = "{area:275} : tuez-les au passage",
		["{area:286}: kill these as you meet them"] = "{area:286} : tuez-les au passage",
		["{item:15885}: use a half at the {area:2362}"] = "{item:15885} : utilisez une moitié au {area:2362}",
		["{item:3692}: the Peasants in the fields"] = "{item:3692} : les Paysans d'Hillsbrad dans les champs",
		["{npc:11798} in {area:2361} flies druids there"] = "{npc:11798} à {area:2361} y emmène les druides",
		["{npc:2055}, in the Apothecarium"] = "{npc:2055}, dans l'Apothicarium",
		["{npc:2055}, in the {zone:1458}"] = "{npc:2055}, à {zone:1458}",
		["{npc:2215}: orders for {npc:270438}, on the way to Durnholde"] = "{npc:2215} : ordres pour {npc:270438}, sur la route de Fort-de-Durn",
		["{npc:2216}, inside"] = "{npc:2216}, à l'intérieur",
		["{npc:2229}, inside"] = "{npc:2229}, à l'intérieur",
		["{npc:2230}, next to Lydon; inside"] = "{npc:2230}, à côté de Lydon ; à l'intérieur",
		["{npc:2238}'s ball and chain"] = "Boulet et chaîne de {npc:2238}",
		["{npc:2261} walks around here: look inside the circle on the map"] = "{npc:2261} se promène par ici : cherchez dans le cercle sur la carte",
		["{npc:2274} is {npc:232}'s dog, at the northern farmhouse in {area:286}."] = "{npc:2274} est le chien de {npc:232}, à la ferme du nord dans {area:286}.",
		["{npc:2391}: Poisons"] = "{npc:2391} : Poisons",
		["{npc:2451} walks around {area:286}: look inside the circle on the map"] = "{npc:2451} se promène autour de {area:286} : cherchez dans le cercle sur la carte",
		["{npc:3024}: {quest:97538}, the Mirkweed in {area:464} by Sun Rock"] = "{npc:3024} : {quest:97538}, les herbes à {area:464}, près du Roc-du-Soleil",
		["{npc:4606} stands in the {object:36070}."] = "{npc:4606} se tient dans le {object:36070}.",
		["{npc:4721}: {quest:1195}, the phial from {zone:1440}'s Laughing Sisters"] = "{npc:4721} : {quest:1195}, la fiole des Sœurs rieuses de {zone:1440}",
} end)()
t.guides["forever/horde/07-ashenvale"] = (function() return {
		["A short walk north of the Galak camps, the cave of {area:1557} leads down to its deepest chamber, where the {object:20807} burns. Use the {item:5868} on it, then loot the {item:5869} at once: the flame only stays out briefly, and if it relights the phial is gone. Then east to {npc:2986}'s mesa.\nCareful: Two Galak Flame Guards (30) stand by the brazier and a centaur guard walks the cave: pull them away one at a time before you douse the flame."] = "À courte distance au nord des camps galak, la grotte de {area:1557} descend jusqu'à sa salle la plus profonde, où brûle {object:20807}. Utilisez {item:5868} dessus, puis ramassez aussitôt {item:5869} : la flamme ne reste éteinte que brièvement, et si elle se rallume la fiole est perdue. Ensuite, partez à l'est vers la mesa de {npc:2986}.\nAttention : deux Gardes de la flamme galak (30) se tiennent près du brasero et un garde centaure arpente la grotte : attirez-les un par un à l'écart avant d'éteindre la flamme.",
		["Back south to the camp, then up into {zone:1456} for the flight to {area:378}."] = "Retournez au camp au sud, puis montez à {zone:1456} pour le vol vers {area:378}.",
		["Back to {npc:12867} at the lumber camp, on the road north to Splintertree."] = "Retour auprès de {npc:12867} au camp de bûcherons, sur la route du nord vers le Poste de Bois-brisé.",
		["Class trainer"] = "Maître de classe",
		["Climb the path to the top of {area:2097}. {npc:10646} is held captive beside {npc:10896} (29): clear the guards and {npc:10896} first, then free her and protect her on the walk down; Grimtotem ambushers come at you on the way."] = "Montez le chemin jusqu'au sommet de {area:2097}. {npc:10646} est retenue captive près de {npc:10896} (29) : éliminez d'abord les gardes et {npc:10896}, puis libérez-la et protégez-la pendant la descente ; des embusqués du Totem sinistre vous attaquent en route.",
		["Felmusk satyrs"] = "Satyres Gangremusc",
		["Fly to {area:1638}"] = "Prendre un vol pour {area:1638}",
		["Fly to {area:1638} from Zoram'gar. If you don't know its flight path, fly to {area:378} and walk north through {zone:1412} instead."] = "Prenez le vol de Zoram'gar pour {area:1638}. Si vous ne connaissez pas ce trajet aérien, volez plutôt jusqu'à {area:378} et marchez vers le nord à travers {zone:1412}.",
		["Fly to {area:2897}"] = "Prendre un vol pour {area:2897}",
		["Fly to {area:378}"] = "Prendre un vol pour {area:378}",
		["Follow the main road east past {area:415} (Alliance: keep to the road). {npc:12678}, a big grizzly, roams the {area:418} south of the road, west of {area:421}. His paw starts the next hunt quest."] = "Suivez la route principale vers l'est après {area:415} (Alliance : restez sur la route). {npc:12678}, un grand grizzly, rôde dans {area:418}, au sud de la route, à l'ouest de {area:421}. Sa patte lance la quête de chasse suivante.",
		["From the {area:2360} head north-east to the Warsong lumber camp on the road: {npc:12867} stands there."] = "Depuis {area:2360}, allez au nord-est jusqu'au camp de bûcherons chanteguerre, sur la route : {npc:12867} s'y tient.",
		["Galak centaurs"] = "Centaures galak",
		["Gazebo"] = "Belvédère",
		["Gloomrise Toxin Samples, from the Gnawed Corpses"] = "Échantillons de toxine de la cime du Chagrin ({item:273001}), sur les Cadavres rongés ({npc:264096})",
		["Keep east on the road. {npc:12858} waits south-west of the Warsong lumber camp. He and his grunts storm the {area:2360}: let them take aggro and stay with {npc:12858} until {npc:12860} is dead."] = "Continuez vers l'est sur la route. {npc:12858} attend au sud-ouest du Camp de bûcherons chanteguerre. Lui et ses grunts prennent d'assaut {area:2360} : laissez-les attirer l'aggro et restez avec {npc:12858} jusqu'à la mort de {npc:12860}.",
		["Kill the {npc:10720} that comes for {npc:10638}"] = "Tuez {npc:10720} qui s'en prend à {npc:10638}",
		["Laughing Sisters"] = "Les Sœurs rieuses",
		["Level 29.49"] = "Niveau 29.49",
		["North of the camp, spiders overrun the burial ground at {area:17044}. Use {npc:264074}'s {item:273015} on the Gnawed Corpses; the Spinners drop the {item:273181}. {npc:264082} sits at the north end: her {item:273658} starts {quest:96294}."] = "Au nord du camp, des araignées envahissent le cimetière de {area:17044}. Utilisez {item:273015} de {npc:264074} sur les Gnawed Corpses ; les Spinners laissent {item:273181}. {npc:264082} se tient au nord : son objet {item:273658} lance {quest:96294}.",
		["North-west of Splintertree, the Felmusk satyrs camp in the woods. Every satyr can drop horns."] = "Au nord-ouest de Bois-brisé, les Satyres Gangremusc campent dans les bois. Chaque satyre peut laisser des cornes.",
		["On the way back north-east to Splintertree: {npc:12676} prowls the woods south-east of the Warsong lumber camp."] = "Sur le chemin du retour vers Bois-brisé, au nord-est : {npc:12676} rôde dans les bois au sud-est du Camp de bûcherons chanteguerre.",
		["Only if the {npc:10617} dropped his plot for you: {npc:10638} stands at {area:2237}."] = "Seulement si {npc:10617} vous a laissé son plan : {npc:10638} se tient à {area:2237}.",
		["Ride the lift down, then follow the road east through the canyons to {area:484}, a Tauren village on top of the mesas. Its lift is on the north side."] = "Descendez par l'ascenseur, puis suivez la route vers l'est à travers les canyons jusqu'à {area:484}, un village tauren au sommet des mesas. Son ascenseur est du côté nord.",
		["Sapphires of Aku'Mai"] = "Saphirs d'Aku'Mai",
		["South from Raynewood, the moonwell sits in a hollow west of the river, hard to see from the road; {area:421} is west of it. Use the {item:5867} at the moonwell to fill it."] = "Au sud de Raynewood, le puits de lune se trouve dans un creux à l'ouest de la rivière, difficile à voir depuis la route ; {area:421} est à l'ouest. Utilisez {item:5867} au puits de lune pour la remplir.",
		["Speak with {npc:3057}, in {area:1638}: {quest:93739}"] = "Parlez à {npc:3057}, à {area:1638} : {quest:93739}",
		["Take the lift down. The egg lies in a nest on the canyon floor in one of three spots: south-east of the mesas (52.3,55.2), east (56.4,50.4) or south-west (37.6,56.1)."] = "Descendez par l'ascenseur. L'œuf repose dans un nid au fond du canyon, à l'un de trois endroits : au sud-est des mesas (52.3,55.2), à l'est (56.4,50.4) ou au sud-ouest (37.6,56.1).",
		["Talk to {npc:3057}"] = "Parlez à {npc:3057}",
		["The Earthen Ring"] = "Le Cercle terrestre",
		["The Foulweald furbolgs hold the woods east of {area:421}, south of the road. Place {item:16972} on the {object:178206} and guard it: the furbolgs come to tear it down. {npc:12918} comes last; his totem drops in the basket."] = "Les furbolgs Vile-sylve tiennent les bois à l'est de {area:421}, au sud de la route. Placez {item:16972} sur {object:178206} et gardez-le : les furbolgs viennent l'abattre. {npc:12918} arrive en dernier ; son totem tombe dans la corbeille.",
		["The Galak camps fill the canyon north of Freewind; Scouts, Wranglers and Windchasers share every camp. A lone {npc:10617} walks a long path between the camps: if you meet him, kill him, his note starts a quest for {area:2237}. Don't wait for him."] = "Les camps galak remplissent le canyon au nord du Poste de Librevent ; Eclaireurs, Querelleurs et Chasse-vent galak partagent chaque camp. Un {npc:10617} solitaire parcourt un long chemin entre les camps : si vous le croisez, tuez-le, sa note lance une quête pour {area:2237}. Ne l'attendez pas.",
		["The Laughing Sisters, dryads, wander {area:426} around {npc:12677}'s woods; one of them drops {npc:4721}'s {item:5867}, which can take several kills."] = "Les Sœurs rieuses, des dryades, errent dans {area:426} autour des bois de {npc:12677} ; l'une d'elles laisse {item:5867} de {npc:4721}, ce qui peut demander plusieurs victimes.",
		["The Sapphires are blue crystals on the walls of the tunnels leading to the {area:2797} portal, underground and outside the instance: swim down from the pit, under the wall, into the cave. The satyrs and naga in the tunnels are elite: grouping up is advised. The crystals respawn quickly, so there is no need to go deep."] = "Les Saphirs d'Aku'Mai sont des cristaux bleus sur les parois des tunnels menant au portail de {area:2797}, sous terre et hors de l'instance : plongez depuis la fosse, passez sous le mur et entrez dans la grotte. Les satyres et nagas des tunnels sont élites : il est conseillé de grouper. Les cristaux réapparaissent vite, inutile d'aller loin.",
		["The Wanted poster beside {npc:10537}"] = "L'avis de recherche près de {npc:10537}",
		["The night elf {quest:6503} (23-24) stalk the woods south and south-east of the lumber camp; they stealth, so watch for them."] = "{quest:6503} (23-24), des elfes de la nuit, rôdent dans les bois au sud et au sud-est du camp de bûcherons ; elles sont camouflées, restez attentif.",
		["The way to the Sapphires is through the sunken ruins at the north end of the strand: go down the stairs into the pit."] = "On rejoint les saphirs par les ruines englouties au nord de la plage : descendez l'escalier dans la fosse.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:10992} is a level 30 elite: most classes solo it at level 32, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. La {npc:10992} est une élite de niveau 30 : la plupart des classes la tuent seules au niveau 32, mais vous aurez peut-être besoin d'aide. Passez-la si vous êtes seul : la route vous fait regagner cette expérience en tuant des monstres.",
		["Underwater"] = "Sous l'eau",
		["Warsong lumber camp"] = "Camp de bûcherons chanteguerre",
		["West of Freewind, the Grimtotem camps below {area:2097}. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps."] = "À l'ouest du Poste de Librevent, les camps du Totem sinistre sous {area:2097}. Les notes secrètes sont dans les Coffres à documents des camps sud-est, sud-ouest et nord-ouest.",
		["West of Mystral Lake, {npc:12678}, a big grizzly, roams the {area:418}: his paw now drops for you."] = "À l'ouest du lac Mystral, {npc:12678}, un grand grizzly, rôde dans {area:418} : sa patte tombe désormais pour vous.",
		["West of Whitereach the wyverns nest on the {area:482} cliffs; the eggs lie in the nests. {npc:10427} waits on the east side of the nesting grounds: free him and keep him alive on the walk back to {area:2237}.\nCareful: Wyverns at level 28-29 fly overhead and can be pulled without warning. A group of three wyverns can ambush you once you pass the first pillar at the bottom."] = "À l'ouest de Whitereach, les wyvernes nichent sur les falaises de {area:482} ; les œufs sont dans les nids. {npc:10427} attend du côté est des aires de nidification : libérez-le et gardez-le en vie sur le chemin du retour vers {area:2237}.\nAttention : des wyvernes de niveau 28-29 volent au-dessus de vous et peuvent être attirées sans prévenir. Un groupe de trois wyvernes peut vous tendre une embuscade une fois le premier pilier passé, en bas.",
		["While you're here: learn {spell:199} from {npc:11869} (10 silver); two-handers level a Warrior fastest."] = "Pendant que vous y êtes : apprenez {spell:199} auprès de {npc:11869} (10 pièces d'argent) ; les armes à deux mains font progresser un Guerrier le plus vite.",
		["for {npc:5901}, south of {area:392}: next guide"] = "pour {npc:5901}, au sud de {area:392} : guide suivant",
		["grind on {npc:4101}"] = "tuez en boucle : {npc:4101}",
		["{area:17044}: kill these as you meet them"] = "{area:17044} : tuez-les au passage",
		["{area:2797} ruins"] = "Ruines de {area:2797}",
		["{area:2897} flight master"] = "Maître de vol de {area:2897}",
		["{area:392} flight master"] = "Maître de vol de {area:392}",
		["{area:418} fountain"] = "Fontaine de {area:418}",
		["{area:483}: kill these as you meet them"] = "{area:483} : tuez-les au passage",
		["{item:273181}, from Gloomrise Spinners"] = "{item:273181}, sur les Tisseuses de la cime du Chagrin ({npc:264081})",
		["{item:5867}, at the {object:20806}"] = "{item:5867}, à {object:20806}",
		["{item:5867}, from a {npc:4054}"] = "{item:5867}, sur une {npc:4054}",
		["{item:5868}, at the {object:20807}"] = "{item:5868}, à {object:20807}",
		["{item:5869}, from the {object:20807}"] = "{item:5869}, sur {object:20807}",
		["{npc:10377}, by the wind rider master"] = "{npc:10377}, près du maître des coursiers du vent",
		["{npc:10428}'s next quest, Sacred Fire, ends in {zone:1456}, off this route. Skip it."] = "La quête suivante de {npc:10428}, Feu sacré, se termine à {zone:1456}, hors de cet itinéraire. Passez-la.",
		["{npc:10617}'s {quest:4881}, if you meet him"] = "{quest:4881} de {npc:10617}, si vous le croisez",
		["{npc:10645}, inside"] = "{npc:10645}, à l'intérieur",
		["{npc:12676}, a big nightsaber, prowls the same woods further east, on the way north to Splintertree. Her claw starts the next hunt quest."] = "{npc:12676}, un grand sabre-de-nuit, rôde dans les mêmes bois plus à l'est, sur le chemin du nord vers le Poste de Bois-brisé. Sa griffe lance la quête de chasse suivante.",
		["{npc:12677}, a shadow panther, stalks the woods around {area:426}, west of the Felmusk camp. Her head starts the next hunt quest."] = "{npc:12677}, une panthère des ombres, rôde dans les bois autour de {area:426}, à l'ouest du camp Gangremusc. Sa tête lance la quête de chasse suivante.",
		["{npc:12696} keeps the hunt board at {area:428}, by the flight master: take {quest:6383} and hand it straight back. {npc:12678}, {npc:12676} and {npc:12677} drop their trophies only after it."] = "{npc:12696} tient le tableau des chasses à {area:428}, près du maître de vol : prenez {quest:6383} et rendez-la aussitôt. {npc:12678}, {npc:12676} et {npc:12677} ne laissent leurs trophées qu'après cela.",
		["{npc:12718}: only if you carry the manual pages"] = "{npc:12718} : seulement si vous portez les pages du manuel",
		["{npc:12736} offers a {area:2797} quest next; leave it unless you have a group."] = "{npc:12736} Sancrea propose ensuite une quête à {area:2797} ; laissez-la sauf si vous avez un groupe.",
		["{npc:210995}, a Forever addition, stands on the west shore of {area:421} with three quick Dragonslayer quests."] = "{npc:210995}, un ajout de Forever, se tient sur la rive ouest de {area:421} avec trois quêtes rapides de tueur de dragon.",
		["{npc:2986} stands on a mesa top east of the Galak camps. For the {quest:1149}, walk off the end of the planks beside him: you land safely."] = "{npc:2986} se tient au sommet d'une mesa à l'est des camps galak. Pour {quest:1149}, avancez jusqu'au bout des planches à côté de lui et sautez : vous atterrissez sans dommage.",
		["{npc:2986}, below ground"] = "{npc:2986}, sous terre",
		["{npc:3024} stands beside {npc:4721}, east of {npc:2995}."] = "{npc:3024} se tient à côté de {npc:4721}, à l'est de {npc:2995}.",
		["{npc:4721} stands a short walk east of {npc:2995}."] = "{npc:4721} se tient à quelques pas à l'est de {npc:2995}.",
		["{npc:4721}: {npc:4722} at {area:484}, later in this guide"] = "{npc:4721} : {npc:4722} à {area:484}, plus loin dans ce guide",
		["{npc:4722} stands in {area:484}: {npc:4721}'s filled phial is for him."] = "{npc:4722} se tient à {area:484} : la fiole remplie de {npc:4721} est pour lui.",
		["{npc:4722}: the {object:20807} in {area:1557}, among the Galak camps"] = "{npc:4722} : {object:20807} dans {area:1557}, parmi les camps galak",
		["{npc:4877}, inside"] = "{npc:4877}, à l'intérieur",
		["{object:176344}, north-west camp"] = "{object:176344}, camp nord-ouest",
		["{object:176344}, south-east camp"] = "{object:176344}, camp sud-est",
		["{object:176344}, south-west camp"] = "{object:176344}, camp sud-ouest",
		["{object:3646}; below ground"] = "{object:3646} ; sous terre",
		["{zone:1456} flight master"] = "Maître de vol des {zone:1456}",
		["{zone:1456}'s central rise"] = "Le plateau central des {zone:1456}",
} end)()
t.guides["forever/horde/30-40/01-hillsbrad-foothills"] = (function() return {
		["Back to the fields: the Peasants work south of the farmhouses. Careful: A fleeing peasant that reaches the town hall can bring back adds; snares or roots keep them from escaping."] = "Retour aux champs : les Paysans travaillent au sud des fermes. Attention : un paysan qui s'enfuit et atteint l'hôtel de ville peut ramener des renforts ; les ralentissements ou les immobilisations les empêchent de s'échapper.",
		["Back to {area:272}"] = "Retour à {area:272}",
		["Back to {area:272}."] = "Retour à {area:272}.",
		["Below ground"] = "Sous terre",
		["Boulderfist camp"] = "Camp Rochepoing",
		["Daggerspine naga"] = "Nagas Daguéchine",
		["Daggerspine shore"] = "Rivage des Daguéchine",
		["Drull's ball and chain"] = "Boulet et chaîne de Drull",
		["Fly to {area:1497}"] = "Prendre un vol pour {area:1497}",
		["Fly to {area:1637}"] = "Prendre un vol pour {area:1637}",
		["Fly to {area:272}"] = "Prendre un vol pour {area:272}",
		["For characters of 29 to 33, but most quests here are level 32-34, a few up to 36: on purpose, for their experience. The Syndicate, {area:279}'s guards and the Boulderfist ogres are 31-35, so pull them one at a time."] = "Pour les personnages de niveau 29 à 33, mais la plupart des quêtes ici sont de niveau 32-34, quelques-unes jusqu'à 36 : c'est voulu, pour leur expérience. Le Syndicat, les gardes de {area:279} et les ogres Rochepoing sont de niveau 31-35 : attirez-les un par un.",
		["From {area:271} head north past {area:272} and follow the road on into the Alterac foothills. {quest:535} waits by the Syndicate camp. He offers his errand only while you carry {npc:2229}'s Infiltration: hand him the stout at once, and his reward is the Syndicate Missive Krusk wants. A missive from the Syndicate here does the same: with one in your bags the guide passes {quest:535}."] = "Depuis {area:271}, remontez vers le nord après {area:272} et suivez la route jusque dans les contreforts d'Alterac. {quest:535} attend près du camp du Syndicat. Il ne propose sa course que tant que vous avez « Infiltration » de {npc:2229} : donnez-lui tout de suite la bière, et sa récompense est la Missive du Syndicat que veut Krusk. Une missive du Syndicat obtenue ici fait la même chose : avec une missive dans vos sacs, le guide passe {quest:535}.",
		["Head back north to {area:272}."] = "Retournez vers le nord jusqu'à {area:272}.",
		["Head back south down the road to {area:272}."] = "Redescendez la route vers le sud jusqu'à {area:272}.",
		["Hillsbrad Peasants"] = "Paysans d'Hillsbrad",
		["Inside"] = "À l'intérieur",
		["Inside {area:288}"] = "Dans {area:288}",
		["Only if {quest:535}'s missive didn't come your way: the Syndicate Footpads and Thieves (32-34) around the camps west of the road carry missives too; about one in three drops one. Careful: at 31-32 they are still above you and stand close together, with Wizards (34-35) among them: pull one at a time from the camp's edge."] = "Seulement si la missive de {quest:535} ne vous est pas parvenue : les Détrousseurs et Larrons du Syndicat (32-34) autour des camps à l'ouest de la route portent aussi des missives ; environ un sur trois en laisse tomber une. Attention : au niveau 31-32, ils sont encore au-dessus de vous et se tiennent serrés, avec des Sorciers (34-35) parmi eux : attirez-les un par un depuis le bord du camp.",
		["Place the {object:1729} on the {object:1728} beside the inn; upstairs"] = "Placez le {object:1729} sur la {object:1728} à côté de l'auberge ; à l'étage",
		["Shindigger keg"] = "Tonneau de Shindigger",
		["South-east of Tarren Mill. Drull and {npc:2238} are chained in the keep's courtyard buildings: {npc:2427} carries the {item:3467} and {npc:2428} the {item:3499}, both in the keep. Kill them, then open both locks."] = "Au sud-est de Moulin-de-Tarren. Drull et {npc:2238} sont enchaînés dans les bâtiments de la cour du donjon : {npc:2427} porte la {item:3467} et {npc:2428} la {item:3499}, tous deux dans le donjon. Tuez-les, puis ouvrez les deux serrures.",
		["South-west, the Cave and Ferocious Yetis (30-32) fill the {area:277} in the hills west of {area:272}; about one in sixteen carries the rod. Stay in these caverns: the Mountain and Giant Yetis (32-34) of the cave further north carry it too, but at 29-30 they hit hard and come in pairs."] = "Au sud-ouest, les Yétis des grottes et les Yétis féroces (30-32) remplissent {area:277}, dans les collines à l'ouest de {area:272} ; environ un sur seize porte le bâtonnet. Restez dans ces cavernes : les Yétis des montagnes et les Yétis géants (32-34) de la grotte plus au nord le portent aussi, mais au niveau 29-30 ils frappent fort et viennent par deux.",
		["Syndicate missives"] = "Missives du Syndicat",
		["The smithy"] = "La forge",
		["The third flame burns in the smaller cave up in the hills north of the caverns.\nCareful: Giant and Mountain Yetis (32-34) stand around the flame, often in pairs, and Frostmaw, a rare yeti (37), roams nearby. At 30-31 they are over your level: pull the yetis one at a time from the cave mouth before you use the Rod, and watch for Frostmaw before you go in."] = "La troisième flamme brûle dans la plus petite grotte, en haut des collines au nord des cavernes.\nAttention : des Yétis géants et des Yétis des montagnes (32-34) entourent la flamme, souvent par deux, et Gueule-glacée, un yéti rare (37), rôde tout près. Au niveau 30-31, ils sont au-dessus de votre niveau : attirez les yétis un par un depuis l'entrée de la grotte avant d'utiliser le Bâtonnet, et guettez Gueule-glacée avant d'entrer.",
		["The {area:279} crater's eastern rim"] = "Le bord est du cratère de {area:279}",
		["Torn Fin beach"] = "Plage des Aileron déchiré",
		["Torn Fin murlocs"] = "Murlocs Aileron déchiré",
		["Town hall"] = "Hôtel de ville",
		["Train"] = "Entraînement",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "Entraînez-vous pendant que vous êtes à {zone:1458} : les maîtres se trouvent dans {object:36070}, {object:36073} et {object:36082} (paladins : {npc:260093}).",
		["Train your new spells."] = "Apprenez vos nouveaux sorts.",
		["West across the foothills to {area:287} town: the smithy stands in the middle of it. {npc:2404} and his apprentices work at the forge; the {object:1736} is stacked beside it."] = "À l'ouest à travers les contreforts jusqu'au village d'{area:287} : la forge se trouve en son centre. {npc:2404} et ses apprentis travaillent à la forge ; la {object:1736} est empilée à côté.",
		["West past the hills to the farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere."] = "À l'ouest après les collines, jusqu'aux fermes à l'est du village d'{area:287}. {npc:232} travaille le champ près de la ferme du nord, {npc:2403} celui plus au sud-est ; il y a des Ouvriers agricoles et des Fermiers partout.",
		["You missed Darthalia's first errands, from the 22-25 {area:287} guide: they come first now. They are a few levels below you and quick, and they open the rest of the {quest:527} in this guide."] = "Vous avez manqué les premières courses de Darthalia, du guide {area:287} 22-25 : elles passent d'abord maintenant. Elles sont quelques niveaux en dessous du vôtre et rapides, et elles ouvrent la suite de {quest:527} dans ce guide.",
		["Zeppelin to {zone:1458}"] = "Zeppelin pour {zone:1458}",
		["{area:228} flight master"] = "Maître de vol du {area:228}",
		["{area:321} flight master"] = "Maître de vol de {area:321}",
		["{area:392} flight master"] = "Maître de vol de {area:392}",
		["{area:484} flight master"] = "Maître de vol de {area:484}",
		["{item:3388}: auction house or an alchemist, for {quest:515}."] = "{item:3388} : hôtel des ventes ou un alchimiste, pour {quest:515}.",
		["{item:3703}, for {npc:2333}"] = "{item:3703}, pour {npc:2333}",
		["{npc:2216}, inside"] = "{npc:2216}, à l'intérieur",
		["{npc:2229} wants his two scouts freed from {area:275} before he trusts you with Infiltration."] = "{npc:2229} veut que ses deux éclaireurs soient libérés de {area:275} avant de vous confier « Infiltration ».",
		["{npc:2229}, inside"] = "{npc:2229}, à l'intérieur",
		["{npc:2238}'s ball and chain"] = "Boulet et chaîne de {npc:2238}",
		["{npc:2410}, inside"] = "{npc:2410}, à l'intérieur",
		["{npc:2437}, inside"] = "{npc:2437}, à l'intérieur",
		["{npc:260093} trains Paladins in the {zone:1458}."] = "{npc:260093} forme les Paladins à {zone:1458}.",
		["{npc:2792}, by the gate"] = "{npc:2792}, près de la porte",
		["{npc:4949}, Grommash Hold, if you carry it"] = "{npc:4949}, Grommash Hold, si vous l'avez",
		["{object:1761}, inside"] = "{object:1761}, à l'intérieur",
		["{zone:1456} flight master"] = "Maître de vol des {zone:1456}",
		["{zone:1458} flight master"] = "Maître de vol de {zone:1458}",
		["{zone:1458} trainers"] = "Maîtres de {zone:1458}",
} end)()
t.guides["forever/horde/30-40/02-thousand-needles"] = (function() return {
		["Back south to {npc:11863}'s tower."] = "Retournez au sud jusqu'à la tour de {npc:11863}.",
		["Clam beds"] = "Bancs de praires",
		["Fly to {area:460}"] = "Prenez un vol pour {area:460}",
		["Fly to {area:484}"] = "Prendre un vol pour {area:484}",
		["Head north along the coast, then inland to the ruined tower of {area:2405}: {npc:11863} waits inside. The coast's clams and naga come after {area:599}, on one walk north to {area:2406}."] = "Remontez la côte vers le nord, puis enfoncez-vous dans les terres jusqu'à la tour en ruine d'{area:2405} : {npc:11863} attend à l'intérieur. Les praires et les nagas de la côte viendront après {area:599}, en une seule marche vers le nord jusqu'à {area:2406}.",
		["Keep north to {area:598}. The Slitherblade Myrmidons, Naga and Sorceresses hold the beach; pull them one at a time. Any Slitherblade can drop {item:15881}."] = "Continuez vers le nord jusqu'à {area:598}. Les Myrmidons, Nagas et Ensorceleuses Lame-sinueuse tiennent la plage ; attirez-les un par un. N'importe quel Lame-sinueuse peut laisser tomber la {item:15881}.",
		["On the top floor"] = "Au dernier étage",
		["Swim out to {area:2406} off the far northern tip and use the {item:15766} on the {object:177673}: {npc:12369} (38) rises; kill him for the {quest:6027}. He is well above you: rest to full first. {object:177786} stands on the shore beside the statue: open it with both keys."] = "Nagez jusqu'à {area:2406}, au large de la pointe nord, et utilisez la {item:15766} sur la {object:177673} : {npc:12369} (38) surgit ; tuez-le pour obtenir le {quest:6027}. Il est bien plus fort que vous : reposez-vous d'abord. {object:177786} se trouve sur le rivage à côté de la statue : ouvrez-le avec les deux clés.",
		["The zeppelin lands at the tower outside {zone:1454}'s main gate. {npc:5639} walks the Drag: if he isn't at the arrow, look along its streets to the south-west. {npc:5640} stands in the {object:172961} on the west side of the city."] = "Le zeppelin se pose à la tour devant la porte principale d'{zone:1454}. {npc:5639} parcourt la Herse : s'il n'est pas à la flèche, cherchez-le dans ses rues au sud-ouest. {npc:5640} se tient dans {object:172961}, à l'ouest de la ville.",
		["Underwater"] = "Sous l'eau",
		["West to the shore. Giant Softshell Clams lie in the shallows and the Enraged Reef Crawlers walk the beach: each clam you open on the sea floor, and some crawlers, give a {item:15874}. Open each one in your bags for its meat.\nThe Drysnap Crawlers and Pincers on the same beach carry {item:15878}, about one in seven."] = "Vers l'ouest jusqu'au rivage. Les Praires géantes reposent dans les hauts-fonds et les Clampants des récifs enragés parcourent la plage : chaque praire que vous ouvrez au fond de l'eau, ainsi que certains clampants, donne une {item:15874}. Ouvrez-la dans vos sacs pour récupérer sa chair.\nLes Clampants claque-sec et les Pinceurs de la même plage portent la {item:15878}, environ un sur sept.",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["{area:392} flight master"] = "Maître de vol de {area:392}",
		["{area:484} flight master"] = "Maître de vol de {area:484}",
		["{item:15766}, on the {object:177673}"] = "{item:15766}, sur la {object:177673}",
		["{item:15878}, from the Drysnap crabs"] = "{item:15878}, sur les crabes Sèchepince",
		["{item:15881}, from the Slitherblade naga"] = "{item:15881}, sur les nagas Lame-sinueuse",
		["{npc:5641}'s next errand sends you after a demon lord with an elite guard: skip it."] = "La mission suivante de {npc:5641} vous envoie contre un seigneur démon escorté d'élites : passez-la.",
		["{npc:5892} stands in the {object:172957}."] = "{npc:5892} se tient dans {object:172957}.",
		["{npc:5901}: {npc:3527} and your {item:5177}"] = "{npc:5901} : {npc:3527} et votre {item:5177}",
		["{npc:5905} also starts Elemental Aid ({area:1717}), the 33-40 chain to The Tempest's Weapons: forever/class/shaman/call-of-air-horde."] = "{npc:5905} lance aussi Elemental Aid ({area:1717}), la suite 33-40 menant à The Tempest's Weapons : forever/class/shaman/call-of-air-horde.",
		["{npc:5905}: your {item:5178}"] = "{npc:5905} : votre {item:5178}",
		["{object:177787} lies on the ground just south-west of {npc:11863}'s tower, on the way down to the shore: read it. Its two keys drop only while you have the quest."] = "{object:177787} gît sur le sol juste au sud-ouest de la tour de {npc:11863}, sur le chemin qui descend vers le rivage : lisez-le. Ses deux clés ne tombent que si vous avez la quête.",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
		["{zone:1456} flight master"] = "Maître de vol des {zone:1456}",
} end)()
t.guides["forever/horde/30-40/03-stranglethorn-vale"] = (function() return {
		["Back north to the camp."] = "Retournez au camp, au nord.",
		["Back to {area:1637}"] = "Retour à {area:1637}",
		["Back to {object:3202}."] = "Retour à {object:3202}.",
		["Boat to {area:35}"] = "Bateau pour {area:35}",
		["Dizzywig's parts go back to Kravel in the {area:439}, off the route: leave them."] = "Les pièces de Dizzywig retournent à Kravel dans {area:439}, hors de l'itinéraire : laissez-les.",
		["Fly to {area:1637}"] = "Prendre un vol pour {area:1637}",
		["Fly to {area:35}"] = "Prendre un vol pour {area:35}",
		["Fly to {area:392}"] = "Prendre un vol pour {area:392}",
		["Fly to {object:3202}"] = "Prendre un vol pour {object:3202}",
		["Follow the road north out of {object:3202}; Nesingwary's hunting camp sits on the hill north-east of the river. {npc:773} wants it investigated: walk among its tents. From here on, keep every page of {quest:338} you loot: {npc:716} takes them on your next Stranglethorn visit."] = "Suivez la route vers le nord depuis {object:3202} ; le camp de chasse de Nesingwary se trouve sur la colline au nord-est de la rivière. {npc:773} veut qu'on enquête dessus : marchez parmi ses tentes. Dès maintenant, gardez chaque page de {quest:338} ramassée : {npc:716} les prendra lors de votre prochain passage à Strangleronce.",
		["Green Hills pages"] = "Pages des Vertes collines",
		["Leave {area:35} through the tunnel and follow the road north to {object:3202}, the orc camp on the west side of the vale. Stay on the road: the jungle beside it is above your level."] = "Quittez {area:35} par le tunnel et suivez la route vers le nord jusqu'à {object:3202}, le camp orc à l'ouest de la vallée. Restez sur la route : la jungle alentour est au-dessus de votre niveau.",
		["Level 36"] = "Niveau 36",
		["Mosh'Ogg camp"] = "Camp Mosh'Ogg",
		["Nesingwary's camp"] = "Camp de Nesingwary",
		["North-west of Grom'gol the {area:104} lies under the water off the coast. The {item:4094} rests on the sea floor by the sunken ruins; watch your breath and the murlocs."] = "Au nord-ouest de Grom'gol, {area:104} s'étend sous l'eau au large de la côte. L'{item:4094} repose au fond de la mer près des ruines englouties ; surveillez votre souffle et les murlocs.",
		["River Crocolisks lie along the river below the camp. Young Stranglethorn Tigers prowl west of the camp, Young Panthers east of it. Head west past the camp. Stranglethorn Raptors (33-34) hunt the clearings, and the Bloodscalp trolls hold the ruins on the coast: every Bloodscalp can drop a tusk. A {item:4614} is a very rare drop from them: if one drops, read it. Careful: The troll camps have many patrolling mobs, so other trolls often join a fight."] = "Des Crocilisques des rivières se trouvent le long de la rivière sous le camp. Les Jeunes tigres de Strangleronce rôdent à l'ouest du camp, les Jeunes panthères à l'est. Allez vers l'ouest après le camp. Les Raptors de Strangleronce (33-34) chassent dans les clairières, et les trolls Bloodscalp tiennent les ruines sur la côte : chaque Bloodscalp peut lâcher une défense. Le {item:4614} est un butin très rare sur eux : si vous en obtenez un, lisez-le. Attention : les camps trolls ont de nombreuses patrouilles, d'autres trolls rejoignent donc souvent le combat.",
		["The Bloodscalp Headhunters (36-37) in the village on the coast carry the shrunken heads.\nThe Bloodscalp trolls hold the ruins up the coast north of the reef and the village beyond; every one can drop a {item:3915}. Keep looting pages of {quest:338}."] = "Les Chasseurs de tête Bloodscalp (36-37) du village sur la côte portent les têtes réduites.\nLes trolls Bloodscalp tiennent les ruines plus haut sur la côte, au nord du récif, et le village au-delà ; chacun peut lâcher un {item:3915}. Continuez à ramasser des pages de {quest:338}.",
		["The Shadowmaw Panthers come much later, by {object:3202}"] = "Les Panthères Ombregueule viendront bien plus tard, près de {object:3202}",
		["Underwater"] = "Sous l'eau",
		["West past the camp, Crystal Spine Basilisks (34-35) sit on the rocks; every Bloodscalp in the village beyond can drop an ear.\n{npc:729}, a level 37 tiger, prowls the hilltop south-west of the camp.\nCareful: The raptor nest has young raptors that join the fight when you attack the adults."] = "À l'ouest après le camp, des Basilics de cristal (34-35) se tiennent sur les rochers ; chaque Bloodscalp du village plus loin peut lâcher une oreille.\n{npc:729}, un tigre de niveau 37, rôde au sommet de la colline au sud-ouest du camp.\nAttention : le nid de raptors abrite de jeunes raptors qui rejoignent le combat quand vous attaquez les adultes.",
		["from {npc:4723}"] = "sur {npc:4723}",
		["grind on {npc:1142}"] = "tuez en boucle : {npc:1142}",
		["{area:100}: kill these as you meet them"] = "{area:100} : tuez-les au passage",
		["{area:102}: kill these as you meet them"] = "{area:102} : tuez-les au passage",
		["{area:2408} flight master"] = "Maître de vol de {area:2408}",
		["{area:301}: kill these as you meet them"] = "{area:301} : tuez-les au passage",
		["{area:35} first: the goblins' boat sails there from {area:392}, and every {area:35} quest is for the north of the vale, which you then walk up into."] = "{area:35} d'abord : le bateau des gobelins s'y rend depuis {area:392}, et toutes les quêtes de {area:35} concernent le nord de la vallée, que vous remonterez ensuite à pied.",
		["{area:35} flight master"] = "Maître de vol de {area:35}",
		["{item:5852}, in {object:20691}"] = "{item:5852}, dans {object:20691}",
		["{npc:2464} stands in the middle of {object:3202}, {npc:2497} near the zeppelin tower, {npc:2465} beside the flight master."] = "{npc:2464} se tient au centre de {object:3202}, {npc:2497} près de la tour du zeppelin, {npc:2465} à côté du maître de vol.",
		["{npc:2495}'s shop is in the building east of the inn; {npc:2498} is on the inn's bottom floor, {npc:2496}, {npc:737} and {npc:773} upstairs beside the flight master."] = "La boutique de {npc:2495} est dans le bâtiment à l'est de l'auberge ; {npc:2498} est au rez-de-chaussée de l'auberge, {npc:2496}, {npc:737} et {npc:773} à l'étage, à côté du maître de vol.",
		["{npc:2495}, inside"] = "{npc:2495}, à l'intérieur",
		["{npc:2496}, upstairs"] = "{npc:2496}, à l'étage",
		["{npc:2496}: Cozzle's footlocker is at {area:37}, later in this guide"] = "{npc:2496} : le coffre de Cozzle se trouve à {area:37}, plus loin dans ce guide",
		["{npc:2496}: for Pozzik at the {area:2240}, on the way to {zone:1446} around level 43"] = "{npc:2496} : pour Pozzik à {area:2240}, en route vers {zone:1446} vers le niveau 43",
		["{npc:2497}: for Arathi, later on the route"] = "{npc:2497} : pour les Hautes-terres Arathies, plus loin sur l'itinéraire",
		["{npc:2498}, inside"] = "{npc:2498}, à l'intérieur",
		["{npc:3391} waits upstairs in the house by the flight master; {quest:1111} stands on the docks, beside the boat."] = "{npc:3391} attend à l'étage de la maison près du maître de vol ; {quest:1111} se tient sur les quais, à côté du bateau.",
		["{npc:3391}, upstairs"] = "{npc:3391}, à l'étage",
		["{npc:3391}: for {npc:4631} in {area:35}, where the boat goes"] = "{npc:3391} : pour {npc:4631} à {area:35}, là où va le bateau",
		["{npc:4631} stands on the pier where the boat docks. {npc:2495}'s shop is in the building east of the inn; {npc:2498} is on the inn's bottom floor, {npc:2496}, {npc:737} and {npc:773} upstairs, {npc:2858} the flight master on the upper deck."] = "{npc:4631} se tient sur la jetée où accoste le bateau. La boutique de {npc:2495} est dans le bâtiment à l'est de l'auberge ; {npc:2498} est au rez-de-chaussée de l'auberge, {npc:2496}, {npc:737} et {npc:773} à l'étage, {npc:2858}, le maître de vol, sur le ponton supérieur.",
		["{npc:4631}, on the pier"] = "{npc:4631}, sur la jetée",
		["{npc:4723} (38) is inside the Venture Co. house on {area:37}'s west shore, among the geologists: his key opens {object:20691} in the same house, which holds the blueprints for {npc:2496}."] = "{npc:4723} (38) est dans la maison de la KapitalRisk sur la rive ouest de {area:37}, parmi les géologues : sa clé ouvre {object:20691} dans la même maison, qui contient les plans pour {npc:2496}.",
		["{npc:737}, upstairs"] = "{npc:737}, à l'étage",
		["{npc:773}, upstairs"] = "{npc:773}, à l'étage",
		["{object:3202} flight master"] = "Maître de vol de Grom'gol",
		["{quest:1111}, on the docks"] = "{quest:1111}, sur les quais",
		["{zone:1434}: kill these as you meet them"] = "{zone:1434} : tuez-les au passage",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
		["{zone:1456} flight master"] = "Maître de vol des {zone:1456}",
} end)()
t.guides["forever/horde/30-40/04-dustwallow-marsh"] = (function() return {
		["Back to {area:1637}"] = "Retour à {area:1637}",
		["Fly to {area:1637}"] = "Prendre un vol pour {area:1637}",
		["Fly to {area:2408}"] = "Prendre un vol pour {area:2408}",
		["Fly to {area:378}"] = "Volez jusqu'au {area:378}",
		["Fly to {area:392}"] = "Prendre un vol pour {area:392}",
		["Head east back to the {area:497}."] = "Retournez vers l'est jusqu'à {area:497}.",
		["Head east from {area:378} along the road into the marsh. The burned-out {area:403} stands beside it just past the border; the shield, the badge and the hoofprints are in and beside the ruin."] = "Allez vers l'est depuis le {area:378} par la route qui entre dans le marais. Les ruines incendiées de {area:403} se dressent au bord, juste après la frontière ; le bouclier, l'insigne et les empreintes de sabots sont dans la ruine et à côté.",
		["Head north to {area:502}. Stinky stands at the foot of the hill; escort him while he gathers Bogbean Leaves just south of it."] = "Allez vers le nord jusqu'à {area:502}. Stinky se tient au pied de la colline ; escortez-le pendant qu'il ramasse des feuilles de fève des marais juste au sud.",
		["Head south along the coast from {area:392} to {area:720}. {npc:6236} stands by the arena: step on the grate to start the fight; the challengers come one at a time, then {npc:6238} (33)."] = "Descendez la côte vers le sud depuis {area:392} jusqu'à {area:720}. {npc:6236} se tient près de l'arène : marchez sur la grille pour lancer le combat ; les adversaires arrivent un par un, puis {npc:6238} (33).",
		["Head west back across the marsh. The Darkfang Venomspitters on the ridges north of Brackenwall drop the venom sacs. Theramore Infiltrators (35-36) sneak through the same woods: they are stealthed, so look closely.\nThe Darkmist spiders swarm the cavern mouth north-west of Brackenwall; every kind drops eyes.\nCareful: Darkfang Lurkers (level 36-37) use Sneak to stealth while out of combat and cast Poison once fighting.\nCareful: Stealthed spiders in the same area will attack you on sight.\nCareful: Darkmist Lurkers move about stealthed and use poison once in combat. The spiders stand close together, so adds are common; pulling single targets from the outer edge cuts down on them."] = "Retraversez le marais vers l'ouest. Les Crache-venin Sombrecroc, sur les crêtes au nord de Fougeraie, lâchent les poches de venin. Les Infiltrateurs de Theramore (35-36) se faufilent dans les mêmes bois : ils sont camouflés, regardez bien.\nLes araignées de Sombrebrume grouillent à l'entrée de la caverne au nord-ouest de Fougeraie ; toutes lâchent des yeux.\nAttention : les Rôdeuses Sombrecroc (niveau 36-37) se camouflent hors combat et lancent Poison une fois en combat.\nAttention : des araignées camouflées dans la même zone vous attaquent à vue.\nAttention : les Rôdeuses de Sombrebrume se déplacent camouflées et utilisent du poison en combat. Les araignées sont serrées les unes contre les autres, les monstres en plus sont donc fréquents ; attirer des cibles isolées depuis le bord extérieur les limite.",
		["Jarl lives in the {area:497} south-east of {area:502}."] = "Jarl vit au {area:497}, au sud-est de la {area:502}.",
		["Mirefin murlocs"] = "Murlocs Aileron boueux",
		["Shadowprey"] = "Proie-de-l'Ombre",
		["South-east from the manor to {area:513}: the {object:20925} lies on the sea floor off the docks on the isle's east side. Swim in and out and keep off the piers and the town: Theramore's guards are level 53-57."] = "Au sud-est du manoir jusqu'à {area:513} : {object:20925} gît au fond de la mer au large des quais, sur la côte est de l'île. Entrez et sortez à la nage et tenez-vous à l'écart des jetées et de la ville : les gardes de Theramore sont de niveau 53-57.",
		["Stinky Ignatz"] = "Ignatz \"Puant\"",
		["Swamp Eye Jarl"] = "Jarl \"Oeil-des-marais\"",
		["Take the road north at the fork to the ogre village of Brackenwall."] = "À l'embranchement, prenez la route du nord jusqu'au village ogre de Mur-de-Fougères.",
		["The Mirefin murlocs crowd the coast east and north-east of {area:502}; every kind drops heads."] = "Les murlocs Aileron boueux peuplent la côte à l'est et au nord-est de la {area:502} ; tous laissent tomber des têtes.",
		["The {area:2657}"] = "{area:2657}",
		["Underwater"] = "Sous l'eau",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["only if you carry a {item:3853} ({skill:164} or the Auction House)"] = "seulement si vous avez une {item:3853} ({skill:164} ou Hôtel des ventes)",
		["{area:2408} flight master"] = "Maître de vol de {area:2408}",
		["{area:392} flight master"] = "Maître de vol de {area:392}",
		["{area:496} flight master"] = "Maître de vol de {area:496}",
		["{area:496}: kill these as you meet them"] = "{area:496} : tuez-les au passage",
		["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}, pour « Œil-des-marais » Jarl",
		["{npc:3446} stands below Gazlowe's house by the flight master, towards the docks."] = "{npc:3446} se tient sous la maison de Gazlowe, près du maître de vol, en direction des quais.",
		["{npc:4503}, at the south edge of the village where the road comes in"] = "{npc:4503}, à l'entrée sud du village, là où arrive la route",
		["{npc:4983} waits in the {area:2302} east of the village. Follow him to Reethe and keep him alive through the fight that breaks out."] = "{npc:4983} attend dans {area:2302}, à l'est du village. Suivez-le jusqu'à Reethe et gardez-le en vie pendant le combat qui éclate.",
		["{npc:6019} waits at the goblin camp on the west side of the {area:596}."] = "{npc:6019} attend au camp gobelin, du côté ouest du {area:596}.",
		["{object:20985}, beside the manor"] = "{object:20985}, à côté du manoir",
		["{object:20985}, now that {npc:4791} has read the report"] = "{object:20985}, maintenant que {npc:4791} a lu le rapport",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
		["{zone:1456} flight master"] = "Maître de vol des {zone:1456}",
} end)()
t.guides["forever/horde/30-40/05-arathi-highlands"] = (function() return {
		["Back to {area:321}"] = "Retour à {area:321}",
		["Below ground"] = "Sous terre",
		["Each {object:180105} is a ring of standing stones; the key sits on the stone at its heart. The eastern circle is on the hills north-west of {area:321}.\nCareful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East."] = "Chaque {object:180105} est un anneau de pierres levées ; la clé repose sur la pierre en son centre. Le cercle de l'est se trouve sur les collines au nord-ouest de {area:321}.\nAttention : chaque pierre centrale est gardée par environ trois élémentaires proches du niveau 39, qui attaquent ensemble si vous cliquez sur la pierre sans les avoir éliminés : des Exilés ardents à l'ouest, des Exilés foudroyants au cercle extérieur, des Exilés grimpeurs à l'est.",
		["Fleshstalker raptors"] = "Raptors charognards",
		["Fly to {area:272}"] = "Prendre un vol pour {area:272}",
		["Head back east to {area:272}."] = "Retournez vers l'est jusqu'à {area:272}.",
		["Highland Fleshstalkers (36-37) hunt the southern highlands, a pack north of {area:316} and another on the plain to its west. Pull them one at a time."] = "Des Charognards des hautes-terres ({npc:2561}) (36-37) chassent dans le sud des hautes-terres, une meute au nord de {area:316} et une autre dans la plaine à son ouest. Attirez-les un par un.",
		["Inside"] = "À l'intérieur",
		["North-east of Hammerfall the Drywhisker kobolds mine the gorge; the Kobolds at the mouth and the Diggers and Surveyors deeper in all drop the Motes of Myzrael.\nCareful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them."] = "Au nord-est de Trépas-d'Orgrim, les kobolds Drywhisker exploitent la gorge ; les Kobolds à l'entrée, et les Fouilleurs et les Géomètres plus loin, lâchent tous des Particules de Myzrael.\nAttention : chaque type de kobold fuit chercher de l'aide quand sa vie est basse (les Kobolds à 30 %, les Géomètres et les Fouilleurs à 15 %), ce qui peut en attirer d'autres.",
		["The inner circle lies south of the western circle, east of Stromgarde."] = "Le cercle intérieur se trouve au sud du cercle ouest, à l'est de Stromgarde.",
		["The {object:138492}"] = "{object:138492}",
		["The {object:1763} poster by the inn"] = "L'affiche {object:1763} près de l'auberge",
		["The {object:2690}"] = "{object:2690}",
		["The {object:2691}"] = "{object:2691}",
		["The {object:2701} lie at the far end of the gorge."] = "{object:2701} se trouvent tout au fond de la gorge.",
		["The {object:2702}"] = "{object:2702}",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "Entraînez-vous pendant que vous êtes à {zone:1458} : les maîtres se trouvent dans {object:36070}, {object:36073} et {object:36082} (paladins : {npc:260093}).",
		["Underwater"] = "Sous l'eau",
		["West of the cove the Daggerspine Raiders and Sorceresses (38-40) hold the shore: pull them one at a time. The two wrecks lie in the shallows off it, the charts and logs inside them; the gems lie on the sea floor around the wrecks."] = "À l'ouest de la crique, les Ecumeurs ({npc:2595}) et Sorcières Daguéchine (38-40) tiennent le rivage : attirez-les un par un. Les deux épaves gisent dans les hauts-fonds au large, les cartes et journaux à l'intérieur ; les gemmes reposent au fond de la mer autour des épaves.",
		["Zeppelin to {zone:1458}"] = "Zeppelin pour {zone:1458}",
		["{area:17707}: kill these as you meet them"] = "{area:17707} : tuez-les au passage",
		["{area:328}: kill these as you meet them"] = "{area:328} : tuez-les au passage",
		["{npc:2229}, inside"] = "{npc:2229}, à l'intérieur",
		["{npc:2410}, inside"] = "{npc:2410}, à l'intérieur",
		["{npc:2437}, inside"] = "{npc:2437}, à l'intérieur",
		["{npc:2792}, by the gate"] = "{npc:2792}, près de la porte",
		["{quest:503}, on the top floor"] = "{quest:503}, au dernier étage",
		["{zone:1458} flight master"] = "Maître de vol de {zone:1458}",
		["{zone:1458} trainers"] = "Maîtres de {zone:1458}",
} end)()
t.guides["forever/horde/30-40/06-badlands"] = (function() return {
		["Below ground"] = "Sous terre",
		["Head back south down the road, past the {area:1877}."] = "Redescendez la route vers le sud, en passant {area:1877}.",
		["Into the {zone:1418}"] = "Vers {zone:1418}",
		["Keep north on the road; the chest lies in the {area:1517} dig site, at the foot of the ruins north-west of the road."] = "Continuez vers le nord sur la route ; le coffre se trouve sur le site de fouilles d'{area:1517}, au pied des ruines au nord-ouest de la route.",
		["Lesser Rock Elementals"] = "Elémentaires de roche inférieurs ({npc:2735})",
		["Rock Elementals"] = "Elémentaires de roche",
		["Stonevault troggs"] = "Troggs Stonevault",
		["for Helgrum in {area:75}, around level 42"] = "pour Helgrum l'Agile à {area:75}, vers le niveau 42",
		["{npc:6868}, inside"] = "{npc:6868}, à l'intérieur",
		["{quest:1106}: Fizzle's letter from the {area:439}"] = "{quest:1106} : la lettre de Fizzle, de {area:439}",
		["{zone:1418}: kill these as you meet them"] = "{zone:1418} : tuez-les au passage",
} end)()
t.guides["forever/horde/40-50/01-stranglethorn-vale"] = (function() return {
		["\"Sea Wolf\" MacKinley, on the top floor"] = "« Loup de mer » MacKinley, au dernier étage",
		["Below ground"] = "Sous terre",
		["Draenethyst crystals"] = "Cristaux de draenéthyste",
		["Fly to {area:35}"] = "Prendre un vol pour {area:35}",
		["Fly to {object:3202}"] = "Vol pour {object:3202}",
		["Follow the coast south. The naga explorers wade along the shore and carry the reed bundles; the {object:759} bubbles in the hills just east of them."] = "Suivez la côte vers le sud. Les explorateurs nagas pataugent le long du rivage et portent les bottes de roseaux ; {object:759} bouillonne dans les collines juste à l'est.",
		["Further north, the goblins of the Venture Co. dig at the mine east of the road; miners, foremen, surveyors and tinkerers all drop the crystals.\nCareful: Stealthed Shadowmaw Panthers and Stranglethorn Tigresses roam the area around the camp."] = "Plus au nord, les gobelins de la KapitalRisk creusent dans la mine à l'est de la route ; mineurs, contremaîtres, géomètres et bricoleurs lâchent tous les cristaux.\nAttention : des Panthères Ombregueule camouflées et des Tigresses de Strangleronce parcourent les environs du camp.",
		["Hand Unbagwa the fangs and stay by him: he calls three waves of gorillas, then {npc:1514}. Fight them one at a time."] = "Donnez les crocs à Unbagwa et restez près de lui : il appelle trois vagues de gorilles, puis {npc:1514}. Combattez-les un par un.",
		["Head north to the Skullsplitter ruins east of the Venture Co. mine; pull the headhunters and berserkers one at a time. {npc:1059} guards the south-western ruins, and one pile of trophy skulls stands on the ruins' north side. Every Skullsplitter can drop a tusk or a necklace: the necklaces are the slow part, so keep killing in the warriors' camp north of the ruins until you have them all."] = "Allez vers le nord jusqu'aux ruines Skullsplitter, à l'est de la mine de la KapitalRisk ; attirez les chasseurs de têtes et les berserkers un par un. {npc:1059} garde les ruines du sud-ouest, et un tas de crânes trophées se trouve du côté nord des ruines. Chaque Skullsplitter peut lâcher une défense ou un collier : les colliers sont la partie lente, alors continuez à tuer dans le camp des guerriers au nord des ruines jusqu'à les avoir tous.",
		["Head north up the road to the hunters' camp."] = "Remontez la route vers le nord jusqu'au camp des chasseurs.",
		["Head north up the road; the hunters camp on the hill above the river."] = "Remontez la route vers le nord ; les chasseurs campent sur la colline au-dessus de la rivière.",
		["Head south to {area:35}. Shaky Phillipe waits on the docks."] = "Allez vers le sud jusqu'à {area:35}. Shaky Phillipe attend sur les quais.",
		["Head west to {object:3202}."] = "Allez vers l'ouest jusqu'à Grom'gol.",
		["Inside"] = "À l'intérieur",
		["Inside {area:1742}"] = "Dans {area:1742}",
		["Into the {zone:1435}"] = "Vers {zone:1435}",
		["Ironjaw Basilisks"] = "Basilics gueule de fer",
		["Jungle Stalkers"] = "Traqueurs de la jungle",
		["Jungle stalkers"] = "Traqueurs de la jungle",
		["Leave town by the tunnel; the note lies in the pirates' cove just north of {area:35}."] = "Quittez la ville par le tunnel ; la note se trouve dans la crique des pirates juste au nord de {area:35}.",
		["Level 42.68"] = "Niveau 42.68",
		["Level 42.74"] = "Niveau 42.74",
		["Mistvale gorillas"] = "Gorilles de Valbrume",
		["Nesingwary's camp"] = "Camp de Nesingwary",
		["Noboru wanders the clearing south-west of the {area:76}; his cudgel starts a quest."] = "Noboru erre dans la clairière au sud-ouest de {area:76} ; son gourdin lance une quête.",
		["North-east of Mistvale, Zanzil's followers camp in the jungle; every one of them can carry the mixture."] = "Au nord-est de Valbrume, les disciples de Zanzil campent dans la jungle ; chacun d'eux peut porter le mélange.",
		["Pirate ghosts"] = "Pirates fantômes",
		["Ride north-east to the {area:76}. The crystals stand along the way up to {npc:5391}'s cage."] = "Chevauchez vers le nord-est jusqu'à {area:76}. Les cristaux se dressent le long du chemin qui monte vers la cage de {npc:5391}.",
		["Sawtooth crocolisks"] = "Crocilisques Dents-de-scie",
		["Skullsplitter warriors"] = "Guerriers Skullsplitter",
		["South of Booty Bay the Bloodsail swashbucklers camp on the {area:43}; the charts and the orders lie in their tents. Any Bloodsail can carry snuff and {npc:2493}'s eye, so keep killing until you have both."] = "Au sud de Baie-du-Butin, les bretteurs de la Voile sanglante campent sur {area:43} ; les cartes et les ordres se trouvent dans leurs tentes. Tout pirate de la Voile sanglante peut porter le tabac et l'œil de {npc:2493} : continuez jusqu'à avoir les deux.",
		["The Bloodsail ships"] = "Les navires de la Voile sanglante",
		["The Jungle Stalkers (40-41) hunt the coast south of {object:3202}. They are well above you: pull one at a time and rest between fights."] = "Les Traqueurs de la jungle (40-41) chassent sur la côte au sud de Grom'gol. Ils sont bien au-dessus de vous : attirez-les un par un et reposez-vous entre les combats.",
		["The crocolisks wallow in the pools around {npc:5391}'s camp and south towards {area:75}; about one in four drops a flank."] = "Les crocilisques se vautrent dans les mares autour du camp de {npc:5391} et vers le sud jusqu'à {area:75} ; environ un sur quatre laisse tomber un flanc.",
		["The gorillas roam the valley around Unbagwa. The elders drop the giblets; any of them can drop a fang."] = "Les gorilles parcourent la vallée autour d'Unbagwa. Les anciens laissent tomber les abats ; tous peuvent laisser tomber un croc.",
		["The stalker raptors hunt the jungle south of {object:3202}, out towards the west coast."] = "Les raptors traqueurs chassent dans la jungle au sud de {object:3202}, vers la côte ouest.",
		["The three ghostly pirates haunt the jungle north of {area:35}, near Zanzil's camps: {npc:2535} and {npc:2536} stand together, {npc:2537} further east."] = "Les trois pirates fantômes hantent la jungle au nord de {area:35}, près des camps de Zanzil : {npc:2535} et {npc:2536} se tiennent ensemble, {npc:2537} plus à l'est.",
		["The {area:43}"] = "{area:43}",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:728} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:728} est un élite de niveau 40 : la plupart des classes le tuent seules au niveau 42, mais vous aurez peut-être besoin d'aide. Passez-le si vous êtes seul : la route vous fait regagner cette expérience en tuant des monstres.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:730} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:730} est un élite de niveau 43 : la plupart des classes le tuent seules au niveau 45, mais vous aurez peut-être besoin d'aide. Passez-le si vous êtes seul : la route vous fait regagner cette expérience en tuant des monstres.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:731} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nCareful: Tigers and stealthed shadowmaw panthers roam close to him. Clear them before you pull him. When he is pulled, {npc:731} calls for help from creatures within 20 yd."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. Le {npc:731} est un élite de niveau 43 : la plupart des classes le tuent seules au niveau 45, mais vous aurez peut-être besoin d'aide. Passez-le si vous êtes seul : la route vous fait regagner cette expérience en tuant des monstres.\nAttention : des tigres et des panthères Ombregueule camouflées rôdent près de lui. Éliminez-les avant de l'attirer. Une fois attiré, le {npc:731} appelle à l'aide les créatures à moins de 20 m.",
		["Venture Co. mine"] = "Mine de la KapitalRisk",
		["West of the expedition, the Bloodscalp chiefs {npc:1061} and {npc:1062} stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them. Stay on the Bloodscalps here until level 41: {quest:586}, at the cauldron next, sends you to Skullsplitters of 41-43. Or, with a group, run the {area:1517} dungeon instead.\nOn the coast between Zul'Kunda and {object:3202} an {npc:2635} (level 38 elite) shares the spawns of the ordinary crocolisks: kill it if it is up and take its skin for {npc:2495}."] = "À l'ouest de l'expédition, les chefs Bloodscalp {npc:1061} et {npc:1062} se tiennent ensemble dans les ruines de Zul'Kunda. Éliminez d'abord leurs gardes, puis attirez-les. Restez sur les Bloodscalp ici jusqu'au niveau 41 : {quest:586}, au chaudron juste après, vous envoie contre des Skullsplitter de niveau 41-43. Ou bien, en groupe, faites plutôt le donjon d'{area:1517}.\nSur la côte entre Zul'Kunda et {object:3202}, un {npc:2635} (élite de niveau 38) partage les points d'apparition des crocilisques ordinaires : tuez-le s'il est là et prenez sa peau pour {npc:2495}.",
		["Zanzil's camps"] = "Les camps de Zanzil",
		["Zul'Kunda"] = "Ruines de Zul'Kunda",
		["Zul'Mamwe"] = "Ruines de Zul'Mamwe",
		["for a later stop in the {zone:1435}"] = "pour une étape ultérieure dans {zone:1435}",
		["grind on {npc:667}"] = "tuez en boucle : {npc:667}",
		["the Drowned City's entrance, underwater"] = "l'entrée de la Cité engloutie, sous l'eau",
		["the {object:2076}"] = "le {object:2076}",
		["the {object:2076}, beside {npc:2497}"] = "le {object:2076}, à côté de {npc:2497}",
		["{area:127}: kill these as you meet them"] = "{area:127} : tuez-les au passage",
		["{area:1577}: kill these as you meet them"] = "{area:1577} : tuez-les au passage",
		["{area:340} flight master"] = "Maître de vol de {area:340}",
		["{npc:1442}, upstairs"] = "{npc:1442}, à l'étage",
		["{npc:1443}, on the top floor"] = "{npc:1443}, au dernier étage",
		["{npc:2488}, on the top floor"] = "{npc:2488}, au dernier étage",
		["{npc:2495}, inside: the {item:4105}"] = "{npc:2495}, à l'intérieur : la {item:4105}",
		["{npc:2495}: the Snapjaw skins gathered earlier; inside"] = "{npc:2495} : les peaux de Gueule d'acier ramassées plus tôt ; à l'intérieur",
		["{npc:2495}: the {npc:2635} suns on the coast between Zul'Kunda and {object:3202}, later on this loop"] = "{npc:2495} : le {npc:2635} se dore au soleil sur la côte entre Zul'Kunda et {object:3202}, plus tard dans cette boucle",
		["{npc:2496}, on the balcony beside MacKinley"] = "{npc:2496}, sur le balcon à côté de MacKinley",
		["{npc:2498}, inside"] = "{npc:2498}, à l'intérieur",
		["{npc:2519}: the cavern entrance under the {area:104}, west of the camp"] = "{npc:2519} : l'entrée de la caverne sous {area:104}, à l'ouest du camp",
		["{npc:4631}, on the docks: Gazlowe's letter, if you carry it"] = "{npc:4631}, sur les quais : la lettre de Gazlowe, si vous l'avez",
		["{npc:5391} is held in the {area:76} in the swamp's north-east. Free him and follow him out, fighting off the swamp creatures that chase him."] = "{npc:5391} est retenu à {area:76}, dans le nord-est du marais. Libérez-le et suivez-le dehors en repoussant les créatures du marais qui le poursuivent.",
		["{npc:5591}, inside"] = "{npc:5591}, à l'intérieur",
		["{npc:669} walks around here: look inside the circle on the map"] = "{npc:669} se promène par ici : cherchez dans le cercle sur la carte",
		["{npc:6807}, upstairs"] = "{npc:6807}, à l'étage",
		["{npc:6930}, upstairs"] = "{npc:6930}, à l'étage",
		["{npc:737}, upstairs"] = "{npc:737}, à l'étage",
		["{object:3202} flight master"] = "Maître de vol de Grom'gol",
		["{quest:95770}: west of {object:3202}, swim out over the {area:104} and dive to the cavern entrance in the reef; the quest completes as you find it. Leave the cavern for now: the jungle stalkers are south along the coast."] = "{quest:95770} : à l'ouest de {object:3202}, nagez au-dessus de {area:104} et plongez jusqu'à l'entrée de la caverne dans le récif ; la quête s'accomplit dès que vous la trouvez. Laissez la caverne pour l'instant : les traqueurs de la jungle sont au sud, le long de la côte.",
} end)()
t.guides["forever/horde/40-50/02-feralas"] = (function() return {
		["Fly to {area:1637}"] = "Prendre un vol pour {area:1637}",
		["Fly to {area:1638}"] = "Prendre un vol pour {area:1638}",
		["Fly to {area:484}"] = "Prendre un vol pour {area:484}",
		["Fly to {object:3202}"] = "Prendre un vol pour {object:3202}",
		["Fly to {zone:1454}. From the flight master: the {object:172960}, then the Drag, then the {object:172958}."] = "Volez jusqu'à {zone:1454}. Depuis le maître de vol : {object:172960}, puis la Herse, puis {object:172958}.",
		["Grimtotem camp"] = "Camp du Totem sinistre",
		["Kodos: {npc:3685}, beside {npc:3690} in {area:222}."] = "Kodos : {npc:3685}, à côté de {npc:3690} à {area:222}.",
		["North of the gnolls the ogres hold a hilltop outpost; pull the ogre-magi to you. The cobalt is in the dirt mounds around the outpost, and the scroll lies on the ground inside it."] = "Au nord des gnolls, les ogres tiennent un avant-poste sur une colline ; attirez les Ogres-mages Gordunni vers vous. Le Cobalt Gordunni est dans les tas de terre autour de l'avant-poste, et le Parchemin Gordunni est par terre à l'intérieur.",
		["Raptors: Zjolnir, beside {npc:7953} in {area:367}."] = "Raptors : Zjolnir, à côté de {npc:7953} à {area:367}.",
		["Ride north-east to the goblin harbour on the coast."] = "Allez au nord-est jusqu'au port gobelin sur la côte.",
		["Riding and Galestriders: {npc:265756}, at the {area:17684} in {area:16638} on Zephras Isle."] = "Monte et Trotteurs des trombes : {npc:265756}, aux {area:17684} à {area:16638}, sur l'île de Zéphras.",
		["Riding at 40"] = "Monte au niveau 40",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. {npc:4752} teaches Orcs in the {object:172958}, by {npc:3362}'s kennel. Skyborne learn it from {npc:265756} at the {area:17684} in {area:16638} on Zephras Isle, with a Galestrider: the skyboat to the isle leaves the cliffs south of {area:17045}, north of {zone:1456}, about every five minutes. Your race's other mounts are 20 gold each: Collectibles, Mounts · Level 40 has a guide for each."] = "La monte demande le niveau 40 et coûte 100 pièces d'or ; l'apprendre vous donne une monture. {npc:4752} l'enseigne aux Orcs dans la {object:172958}, près du chenil de {npc:3362}. Les Éolides l'apprennent auprès de {npc:265756} aux {area:17684} à {area:16638}, sur l'île de Zéphras, avec un Trotteur des trombes : l'aéronef pour l'île part des falaises au sud de {area:17045}, au nord des {zone:1456}, toutes les cinq minutes environ. Les autres montures de votre race coûtent 20 pièces d'or chacune : Objets de collection, Montures · Niveau 40 a un guide pour chacune.",
		["South along the coast, the Southsea pirates hold the cove. {npc:7883} and the stolen cargo are on the docks at its far end. Any pirate can drop a hat, the kidnappers most often.\nCareful: Two or three pirates stand with {npc:7883}, and many more pirates from the town join the fight once it starts."] = "Au sud le long de la côte, les pirates des Mers du Sud tiennent la crique. {npc:7883} et la cargaison volée sont sur les quais, tout au bout. N'importe quel pirate peut lâcher un chapeau, les kidnappeurs le plus souvent.\nAttention : deux ou trois pirates se tiennent avec {npc:7883}, et beaucoup d'autres pirates de la ville rejoignent le combat une fois qu'il a commencé.",
		["The Grimtotem tauren camp beside the sprite darters' grove; raiders, naturalists and shamans all carry horns."] = "Les taurens du Totem sinistre campent à côté du bosquet des Fées fléchetteuses ; Ecumeurs, Naturalistes et Chamans portent tous des Cornes de Totem sinistre.",
		["The Woodpaw gnolls camp in the hills just north-west of Mojache; any of them can drop a mane.\nCareful: Every Woodpaw gnoll except the Alpha runs off for help at 15% health, which can pull more gnolls into the fight."] = "Les gnolls Patte-de-bois campent dans les collines juste au nord-ouest de Mojache ; n'importe lequel peut lâcher une crinière.\nAttention : tous les gnolls Patte-de-bois sauf l'Alpha fuient chercher de l'aide à 15 % de vie, ce qui peut attirer d'autres gnolls dans le combat.",
		["The Zukk'ash hive burrows into the hills south-east of the camp; {quest:7731} waits in its deepest chamber."] = "La ruche des Zukk'ash s'enfonce dans les collines au sud-est du camp ; {quest:7731} attend dans sa chambre la plus profonde.",
		["The bandits and thieves camp in the dunes east of {area:976}. Every Wastewander can carry a water pouch: keep ten, five for each of Luglunket's bounties.\nCareful: Wastewander Rogues (level 43-44) move stealthed, so they can approach unseen."] = "Les bandits et les voleurs campent dans les dunes à l'est de {area:976}. Chaque Bat-le-désert peut porter une outre d'eau : gardez-en dix, cinq pour chacune des primes de Luglunket.\nAttention : les Voleurs Bat-le-désert (niveau 43-44) se déplacent camouflés et peuvent donc approcher sans être vus.",
		["The battle map lies in the Woodpaw camp south of Mojache."] = "Le Plan de bataille des Griffebois se trouve dans le camp Griffebois au sud de Mojache.",
		["The shadow mages, rogues and assassins camp south-east of {area:976}.\nSouth-east of Gadgetzan the Wastewander bandits camp in the dunes; {npc:7847} stands in the eastern camp.\nCareful: Wastewander Rogues keep Sneak up while out of combat, so hidden rogues can join a fight you start at a camp.\nCareful: Two stealthed Wastewander Rogues travel with him wherever he goes. At his spawn camp, two shadowmages and their minions are close enough to join a fight with him. Out by the towers you can fight him without them."] = "Les mages des ombres, les voleurs et les assassins campent au sud-est de {area:976}.\nAu sud-est de Gadgetzan, les bandits Bat-le-désert campent dans les dunes ; {npc:7847} se tient dans le camp est.\nAttention : les Voleurs Bat-le-désert restent camouflés hors combat, des voleurs cachés peuvent donc rejoindre un combat que vous lancez dans un camp.\nAttention : deux Voleurs Bat-le-désert camouflés l'accompagnent partout. À son camp d'apparition, deux mages des ombres et leurs serviteurs sont assez proches pour se joindre au combat. Près des tours, vous pouvez l'affronter sans eux.",
		["The sprite darters flit over the grove just west of Mojache; nearly every one drops a wing. The Woodpaw alphas lead the camps south-west of it: kill them within the hour.\nCareful: Most Alphas sit in small tent camps with 2-4 other gnolls that join the fight, and other gnolls patrol between the camps."] = "Les fées fléchetteuses voltigent au-dessus du bosquet juste à l'ouest de Mojache ; presque toutes lâchent une aile. Les alphas Patte-de-bois dirigent les camps au sud-ouest : tuez-les dans l'heure.\nAttention : la plupart des Alphas se tiennent dans de petits camps de tentes avec 2 à 4 autres gnolls qui se joignent au combat, et d'autres gnolls patrouillent entre les camps.",
		["To {area:976}"] = "Vers {area:976}",
		["Upstairs"] = "À l'étage",
		["Wolves: {npc:3362}, beside {npc:4752}."] = "Loups : {npc:3362}, à côté de {npc:4752}.",
		["Woodpaw battle map"] = "Plan de bataille des Griffebois",
		["Woodpaw north camp"] = "Camp Griffebois du nord",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["for the {zone:1425}, around level 48"] = "pour {zone:1425}, vers le niveau 48",
		["for {area:35}, around level 50"] = "pour {area:35}, vers le niveau 50",
		["for {zone:1454}, around level 45"] = "pour {zone:1454}, vers le niveau 45",
		["water pouches in your bags"] = "Outres de Bat-le-désert dans vos sacs",
		["{area:1099} flight master"] = "Maître de vol de {area:1099}",
		["{area:1336}: kill these as you meet them"] = "{area:1336} : tuez-les au passage",
		["{area:1937}: kill these as you meet them"] = "{area:1937} : tuez-les au passage",
		["{area:2522}: kill these as you meet them"] = "{area:2522} : tuez-les au passage",
		["{area:392} flight master"] = "Maître de vol de {area:392}",
		["{area:392} for the Felsteed"] = "{area:392} pour le Palefroi corrompu",
		["{area:75} flight master"] = "Maître de vol de {area:75}",
		["{area:976} flight master"] = "Maître de vol de {area:976}",
		["{area:976} is the walled goblin town just past the {zone:1446} border."] = "{area:976} est la ville gobeline fortifiée juste après la frontière de {zone:1446}.",
		["{area:985}: kill these as you meet them"] = "{area:985} : tuez-les au passage",
		["{npc:3690}, riding trainer"] = "{npc:3690}, maître de monte",
		["{npc:4630}: the {item:5852} from {npc:2496}, if you carry them"] = "{npc:4630} : les {item:5852} de {npc:2496}, si vous les avez sur vous",
		["{npc:4706}, beside {npc:4630}"] = "{npc:4706}, à côté de {npc:4630}",
		["{npc:4752}, riding trainer"] = "{npc:4752}, maître de monte",
		["{npc:5234} walks around {area:2522}: look inside the circle on the map"] = "{npc:5234} se promène autour de {area:2522} : cherchez dans le cercle sur la carte",
		["{npc:6986}, the Drag"] = "{npc:6986}, la Herse",
		["{npc:7010}, the Drag"] = "{npc:7010}, la Herse",
		["{npc:7777} walks around {area:1099}: look inside the circle on the map"] = "{npc:7777} se promène autour de {area:1099} : cherchez dans le cercle sur la carte",
		["{npc:7854}, inside"] = "{npc:7854}, à l'intérieur",
		["{npc:7881}, inside"] = "{npc:7881}, à l'intérieur",
		["{npc:7882}, inside"] = "{npc:7882}, à l'intérieur",
		["{npc:7953}, riding trainer"] = "{npc:7953}, maître de monte",
		["{npc:8115}: for {zone:1454}, around level 45"] = "{npc:8115} : pour {zone:1454}, vers le niveau 45",
		["{quest:2863}: one hour from now"] = "{quest:2863} : dans une heure",
		["{zone:1444}: kill these as you meet them"] = "{zone:1444} : tuez-les au passage",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
		["{zone:1456} flight master"] = "Maître de vol des {zone:1456}",
} end)()
t.guides["forever/horde/40-50/03-feralas"] = (function() return {
		["Back east past {area:75}: the Atal'ai artifacts lie in the water and on the banks of the {quest:1424}."] = "Retournez à l'est après {area:75} : les Artefacts atal'ai se trouvent dans l'eau et sur les rives du Bassin des larmes (quête {quest:1424}).",
		["Below ground"] = "Sous terre",
		["Dragon caves"] = "Grottes des dragons",
		["Fly to {area:1099}"] = "Prendre un vol pour {area:1099}",
		["Fly to {area:496}"] = "Prendre un vol pour {area:496}",
		["Fly to {area:75}"] = "Prendre un vol pour {area:75}",
		["Frayfeather hippogryphs"] = "Hippogryphes Aigreplume",
		["Inside {area:498}"] = "Dans {area:498}",
		["Level 45.37"] = "Niveau 45.37",
		["Murlocs of the Misty Reed"] = "Les murlocs de Misty Reed",
		["Northspring harpies"] = "Harpies Northspring",
		["Onyxia's eggs"] = "Oeufs d'Onyxia",
		["Rage Scar yetis"] = "Yétis Griffe féroce",
		["Ride back north to Brackenwall."] = "Retournez au nord jusqu'à Mur-de-Fougères.",
		["Ride north-west to the {area:1108}; {npc:14637} waits on the dock."] = "Allez au nord-ouest jusqu'à {area:1108} ; {npc:14637} Fandazzle attend sur le quai.",
		["Ride west along the road; the scroll lies at the water's edge in the swamp's far west."] = "Suivez la route vers l'ouest ; le parchemin se trouve au bord de l'eau, à l'extrême ouest du marais.",
		["Riding at 40"] = "Monte au niveau 40",
		["Rogue Vale screechers"] = "Hurleurs des vallées insoumis",
		["Sawtooth crocolisks"] = "Crocilisques Dents-de-scie",
		["Sea elementals and sea sprays wash along the shore around the dock. Zap the giants with {item:18904} first: shrunken, they lose their elite strength. Shore striders wade in the water; the land walkers and cliff giants roam the hills further north."] = "Des Elémentaires marins et des Embruns longent le rivage autour du quai. Zappez d'abord les géants avec {item:18904} : rétrécis, ils perdent leur force d'élite. Les Marcheurs des rivages pataugent dans l'eau ; les Marcheurs des terres et les Géants des falaises parcourent les collines plus au nord.",
		["Skeletal horses: {npc:4731}, beside {npc:4773} in {area:159}."] = "Chevaux squelettes : {npc:4731}, à côté de {npc:4773} à {area:159}.",
		["South of the vale the Frayfeather hippogryphs roost on the slopes; nearly every one drops sinew and metallic fragments."] = "Au sud du val, les Hippogryphes Aigreplume nichent sur les pentes ; presque tous laissent tomber des Tendons résistants et des Fragments métalliques.",
		["Sprite darters and forest walkers"] = "Fées fléchetteuses et Marcheurs des bois",
		["The Eggs of Onyxia lie in the dragon caves in the {area:511}'s south-east, guarded by the scalebanes; smash five."] = "Les Oeufs d'Onyxia reposent dans les grottes des dragons au sud-est de {area:511}, gardés par les Plaiedécailles Crins-de-feu ; écrasez-en cinq.",
		["The Marsh Murlocs live on the strand south of the post; the Inkspewers are along the shore east of it and the Flesheaters further west, around the huts on the western shore."] = "Les Murlocs des marais vivent sur la grève au sud du poste ; les Crache-encre sont le long du rivage à l'est et les Mange-chair plus à l'ouest, autour des huttes de la rive ouest.",
		["The Northspring harpies nest on the ridges in the far north-west. They are 48-50, a few levels above you: the Windcallers heal, so kill them first and pull one at a time."] = "Les harpies Northspring nichent sur les crêtes tout au nord-ouest. Elles sont de niveau 48-50, quelques niveaux au-dessus de vous : les Implorateurs du vent soignent, tuez-les en premier et attirez-les un par un.",
		["The sprite darters flit over the grove just west of the camp and carry the {item:9589}; the Wandering Forest Walkers, a little further west, carry the Splintered Logs."] = "Les Fées fléchetteuses voltigent au-dessus du bosquet juste à l'ouest du camp et portent les {item:9589} ; les Marcheurs des bois errants, un peu plus à l'ouest, portent les Bûches fendues.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:1173} needs a group of 3. Skip it if you are alone: the route has you grind the XP back.\n{npc:4500} is elite: grouping up is advised. Beat him down until he gives up, then report to {npc:4501}."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {quest:1173} demande un groupe de 3. Passez-la si vous êtes seul : la route vous fait regagner cette expérience en tuant des monstres.\nLe {npc:4500} est élite : il est conseillé de se grouper. Frappez-le jusqu'à ce qu'il abandonne, puis faites votre rapport à {npc:4501}.",
		["To {area:1099}"] = "Vers {area:1099}",
		["Underwater"] = "Sous l'eau",
		["Zeppelin to {object:3202}"] = "Zeppelin pour {object:3202}",
		["Zeppelin to {zone:1458}"] = "Zeppelin pour {zone:1458}",
		["for the {npc:5598} in the {zone:1425}, around level 48"] = "pour l'{npc:5598} dans {zone:1425}, vers le niveau 48",
		["for the {object:2555} in {zone:1445}, later in this guide"] = "pour le {object:2555} à {zone:1445}, plus loin dans ce guide",
		["for the {zone:1425} owlbeasts, around level 48"] = "pour les chouettards de {zone:1425}, vers le niveau 48",
		["grind on {npc:4329}"] = "tuez en boucle : {npc:4329}",
		["the {object:2555}"] = "le {object:2555}",
		["{area:1099} flight master"] = "Maître de vol de {area:1099}",
		["{area:1108}: kill these as you meet them"] = "{area:1108} : tuez-les au passage",
		["{area:2403}: kill these as you meet them"] = "{area:2403} : tuez-les au passage",
		["{area:496} flight master"] = "Maître de vol de {area:496}",
		["{area:510}: kill these as you meet them"] = "{area:510} : tuez-les au passage",
		["{npc:1443}, on the top floor"] = "{npc:1443}, au dernier étage",
		["{npc:2934}, on the way back to Zinge"] = "{npc:2934}, sur le chemin du retour vers Zinge",
		["{npc:4329} walks around {area:510}: look inside the circle on the map"] = "{npc:4329} se promène autour de {area:510} : cherchez dans le cercle sur la carte",
		["{npc:4500}'s challenge, back in Brackenwall, needs a group of three. Alone, grind the Firemane scouts here on the {area:511}'s northern edge to level 45.37 before you ride back north, so you don't come back down for it. Or, with a group, run the {area:978} dungeon or the {area:1517} dungeon instead."] = "Le défi de {npc:4500}, de retour à Mur-de-Fougères, demande un groupe de trois. Seul, tuez en boucle les Eclaireurs Crins-de-feu ici, sur la lisière nord de {area:511}, jusqu'au niveau 45.37 avant de repartir vers le nord, pour ne pas avoir à redescendre. Ou, en groupe, faites plutôt le donjon {area:978} ou le donjon {area:1517}.",
		["{npc:4501}, below ground"] = "{npc:4501}, sous terre",
		["{npc:4773}, riding trainer"] = "{npc:4773}, maître de monte",
		["{npc:5591}, inside"] = "{npc:5591}, à l'intérieur",
		["{npc:7825}, the {object:36126}"] = "{npc:7825}, dans le {object:36126}",
		["{npc:7854}, inside"] = "{npc:7854}, à l'intérieur",
		["{object:3202} flight master"] = "Maître de vol de Grom'gol",
		["{quest:7738}, a rare drop"] = "{quest:7738}, butin rare",
} end)()
t.guides["forever/horde/40-50/04-tanaris"] = (function() return {
		["Back north, just south of {area:976}, use the {item:8524} now: the two-hour timer starts. The Blisterpaw Hyenas, Glasshide Basilisks and Scorpid Hunters share the dunes here. Each can drop an untested sample: use it, and it either passes as an acceptable one or is lost. Keep killing until you have eight of each."] = "De retour au nord, juste au sud de {area:976}, utilisez maintenant la {item:8524} : le délai de deux heures commence. Les Hyènes Pattes-cloques, les Basilics Peau-de-verre et les Chasseurs scorpides se partagent les dunes ici. Chacun peut lâcher un échantillon non testé : utilisez-le, il se révèle soit acceptable, soit perdu. Continuez à tuer jusqu'à en avoir huit de chaque.",
		["Below ground"] = "Sous terre",
		["Boat to {area:16727}"] = "Bateau pour {area:16727}",
		["Careful: Shadow Mages (level 42-43) call a Voidwalker while out of combat and attack with Immolate and {spell:686}. Thieves can Disarm you, Rogues move around in Sneak, and Assassins use Execute once you are at 20% health or less."] = "Attention : les Mages des ombres (niveau 42-43) invoquent un Marcheur du Vide hors combat et attaquent avec Immolation et {spell:686}. Les Malandrins peuvent vous désarmer, les Voleurs se déplacent camouflés, et les Assassins utilisent Exécution une fois que vous êtes à 20 % de vie ou moins.",
		["Dark Iron Lookouts"] = "Guetteurs Sombrefer",
		["Fly to {area:976}"] = "Prendre un vol pour {area:976}",
		["Further south, Junior Surveyor Scrimshank's gear lies at the mouth of a Centipaar hive.\nCareful: One bug guards the gear. Many bugs patrol the tunnels, some of them level 50, so fights often pull extra adds."] = "Plus au sud, l'équipement du géomètre débutant Scrimshank se trouve à l'entrée d'une ruche Centipaar.\nAttention : un insecte garde l'équipement. De nombreux insectes patrouillent dans les tunnels, certains de niveau 50, les combats attirent donc souvent des monstres en plus.",
		["His next request needs the {item:10552} from elite cultists: leave it."] = "Sa demande suivante exige le {item:10552} sur des cultistes élites : laissez-la.",
		["Into {zone:1427}"] = "Vers la {zone:1427}",
		["Keep the Model 4711-FTZ Power Source Bilgewhizzle gave you: it starts {quest:654}, a two-hour timer, so use it on the way back north from Scrimshank's hive."] = "Gardez la Source d'énergie modèle 4711-FTZ que Bilgewhizzle vous a donnée : elle lance {quest:654}, avec un délai de deux heures, alors utilisez-la en revenant vers le nord depuis la ruche de Scrimshank.",
		["OOX-17/TN"] = "OOX-17/TN",
		["Only with the distress beacon: OOX-17/TN sits south-east of Scrimshank's hive. Escort it north to {area:977}; its reward waits with Oglethorpe in {area:35}.\nCareful: The escort has two ambushes. Three level 47 scorpids attack near the start. Near the end, by the beach, three Wastewander humans attack: one mage and two assassins, around level 44."] = "Seulement avec la balise de détresse : OOX-17/TN se trouve au sud-est de la ruche de Scrimshank. Escortez-le vers le nord jusqu'à {area:977} ; sa récompense vous attend auprès d'Oglethorpe, à {area:35}.\nAttention : l'escorte comporte deux embuscades. Trois scorpides de niveau 47 attaquent près du départ. Vers la fin, près de la plage, trois humains Bat-le-désert attaquent : un mage et deux assassins, autour du niveau 44.",
		["Only with the {item:11818}: back east to the {object:173265} at the dig site."] = "Seulement avec la {item:11818} : retournez à l'est jusqu'aux {object:173265} du site de fouilles.",
		["Ride north-west across the gorge; {area:1446} is the scaffolded camp in the north-west."] = "Traversez la gorge vers le nord-ouest ; {area:1446} est le camp entouré d'échafaudages au nord-ouest.",
		["Scrimshank's gear"] = "Équipement d'analyse de Scrimshank",
		["South of the {area:982} the Dunemaul ogres hold their compound, with {npc:12046} at its eastern end. Dig up {quest:3161} ornaments between the fights."] = "Au sud du {area:982}, les ogres Cognedune tiennent leur camp, avec {npc:12046} à son extrémité est. Déterrez des ornements ({quest:3161}) entre les combats.",
		["The Dark Iron Lookouts stand on the ridges around the sentry towers south of the Cauldron; about one in ten carries the {item:18960}."] = "Les Guetteurs Sombrefer se tiennent sur les crêtes autour des tours de guet au sud du Chaudron ; environ un sur dix porte la {item:18960}.",
		["The Dark Iron Steamsmiths work the furnaces in the middle of the Cauldron; half of them carry a {item:10551}, one in ten the {item:18959}. Slaves, Slavers and Taskmasters carry daggers too."] = "Les Forge-vapeur Sombrefer travaillent aux fourneaux au milieu du Chaudron ; la moitié d'entre eux portent une {item:10551}, un sur dix la {item:18959}. Les Esclaves, les Esclavagistes et les Sous-chefs portent aussi des dagues.",
		["The Steamsmiths' furnaces"] = "Les fourneaux des Forge-vapeur",
		["The {area:247}"] = "{area:247}",
		["The {object:179827} board"] = "Le panneau {object:179827}",
		["Use the {item:8524}"] = "Utilisez la {item:8524}",
		["West along the road south; {npc:7771} camps by the ruins at the {area:1938}. Put on his {item:9978}: it shows the buried ornaments, here and around the {area:983}."] = "À l'ouest, le long de la route du sud ; {npc:7771} campe près des ruines : {area:1938}. Équipez son {item:9978} : il montre les ornements enterrés, ici et autour de {area:983}.",
		["West of Gadgetzan, use the {item:8584} beside the water hole in the troll camp."] = "À l'ouest de Gadgetzan, utilisez le {item:8584} près du point d'eau du camp troll.",
		["West of the compound the cactus creatures fill the valley; only the Dew Collectors carry a dew gland. Most mobs in {zone:1446} can drop OOX-17/TN's distress beacon, rarely: keep it if you see one.\nCareful: The other thistleshrub mobs in the area are level 49-50 and wander a lot, so you can easily pull extra mobs."] = "À l'ouest de l'enceinte, les créatures cactus remplissent la vallée ; seuls les Collecteurs de rosée portent une glande à rosée. La plupart des monstres de {zone:1446} peuvent lâcher, rarement, la balise de détresse d'OOX-17/TN : gardez-la si vous en voyez une.\nAttention : les autres chardonniers de la zone sont de niveau 49-50 et se déplacent beaucoup, il est donc facile d'attirer des monstres en plus.",
		["West, the Centipaar insects swarm around their hives; any of them drops the parts.\nCareful: Centipaar Swarmers cast {npc:4196} both in and out of combat, which brings small adds that interrupt you."] = "À l'ouest, les insectes Centipaar grouillent autour de leurs ruches ; n'importe lequel lâche les pièces.\nAttention : les Traînards Centipaar lancent {npc:4196} en combat comme hors combat, ce qui fait venir de petits monstres qui vous interrompent.",
		["for {npc:7010} in {zone:1454}, around level 50"] = "pour {npc:7010} à {zone:1454}, vers le niveau 50",
		["the {item:8526} grows in the {zone:1425}, around level 48"] = "la {item:8526} pousse dans {zone:1425}, vers le niveau 48",
		["the {object:173265}"] = "les {object:173265}",
		["{area:1099} flight master"] = "Maître de vol de {area:1099}",
		["{area:1938}: kill these as you meet them"] = "{area:1938} : tuez-les au passage",
		["{item:11818}, a rare drop"] = "{item:11818}, butin rare",
		["{item:8623}, a rare drop"] = "{item:8623}, butin rare",
		["{npc:5594}, inside"] = "{npc:5594}, à l'intérieur",
		["{npc:5955} waits in the valley. Walk him all the way to his wife {npc:6015} in {area:977}, north-east across the desert: stay close, slow down for him and fight off what attacks him. Do not mount or hearth out of his reach. {npc:8579} stands in the port too."] = "{npc:5955} attend dans la vallée. Accompagnez-le jusqu'à sa femme {npc:6015} à {area:977}, au nord-est à travers le désert : restez près de lui, ralentissez pour lui et repoussez ce qui l'attaque. Ne montez pas en selle et n'utilisez pas votre pierre de foyer hors de sa portée. {npc:8579} se tient aussi dans le port.",
		["{npc:5955}'s escort"] = "Escorte de {npc:5955}",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}, à côté du maître des coursiers du vent",
		["{quest:3362}: kill these as you meet them"] = "{quest:3362} : tuez-les au passage",
		["{zone:1427}: kill these as you meet them"] = "{zone:1427} : tuez-les au passage",
} end)()
t.guides["forever/horde/40-50/05-the-hinterlands"] = (function() return {
		["Back west to {area:350}; rangers and marksmen stay near the lodge, scouts and outrunners on the slopes south of it."] = "Retournez à l'ouest jusqu'à {area:350} ; les Forestiers et Tireurs d'élite du Haut-val restent près du gîte, les Eclaireurs et Estafettes du Haut-val sur les pentes au sud.",
		["Careful: Stealthed wolves and griffons roam the {area:1883} area."] = "Attention : des loups et des griffons camouflés rôdent dans les environs de {area:1883}.",
		["East of the village, the violet flower grows in the hills."] = "À l'est du village, le Tragan violet pousse dans les collines.",
		["Fly to {area:272}"] = "Prendre un vol pour {area:272}",
		["Fly to {area:75}"] = "Prendre un vol pour {area:75}",
		["Follow the roads east across the {zone:1425} to the troll village on the eastern coast."] = "Suivez les routes vers l'est à travers les {zone:1425} jusqu'au village troll de la côte est.",
		["Highvale"] = "Haut-val",
		["His next request, going on to the {area:355}, is for a group."] = "Sa demande suivante, qui mène à {area:355}, est pour un groupe.",
		["Level 49.02"] = "Niveau 49.02",
		["North along the coast, {npc:14731}'s picnic basket is on the small island; a {npc:14748} guards it."] = "Au nord le long de la côte, le panier de pique-nique de {npc:14731} est sur la petite île ; un {npc:14748} le garde.",
		["OOX-09/HL"] = "OOX-09/HL",
		["On the top floor"] = "Au dernier étage",
		["Only with the distress beacon: the robot sits at the head of the river west of {area:351}. Escort it east to the shore beyond the {area:307}; its reward waits with Oglethorpe in {area:35}.\nCareful: Two ambushes spawn during the escort: first three wildkin owlbeasts, then three trolls. Before each, the robot halts and announces it senses danger. Oozes, stealthed wolves and a large turtle along the path can join fights, and they respawn even if cleared beforehand."] = "Seulement avec la balise de détresse : le robot se trouve à la source de la rivière, à l'ouest de {area:351}. Escortez-le vers l'est jusqu'au rivage au-delà de {area:307} ; sa récompense vous attend auprès d'Oglethorpe, à {area:35}.\nAttention : deux embuscades surviennent pendant l'escorte : d'abord trois chouettards, puis trois trolls. Avant chacune, le robot s'arrête et annonce qu'il sent un danger. Des limons, des loups camouflés et une grande tortue le long du chemin peuvent se joindre aux combats, et ils réapparaissent même si vous les avez éliminés avant.",
		["Ride all the way west to the Wildhammer town of {area:348} and place the message by the well in its centre. The town is full of Alliance guards: get in, place it and get out."] = "Allez tout à l'ouest jusqu'à {area:348}, la ville des Wildhammer, et déposez le message près du puits en son centre. La ville est pleine de gardes de l'Alliance : entrez, déposez-le et repartez.",
		["Ride back north to the bloodmages."] = "Retournez au nord jusqu'aux mages de sang.",
		["Ride north-east from {area:272} into the {zone:1425} and east along the road; {npc:7801} camps on the hill south of the elves' {area:350}."] = "Depuis {area:272}, allez au nord-est jusqu'aux {zone:1425}, puis à l'est le long de la route ; {npc:7801} campe sur la colline au sud de {area:350}, le gîte des elfes.",
		["Ride west out of {area:75} and south through the canyon into the {zone:1419}; the two bloodmages stand by the road just inside."] = "Sortez de {area:75} par l'ouest et descendez le canyon vers le sud jusqu'à {zone:1419} ; les deux mages de sang se tiennent au bord de la route, juste à l'entrée.",
		["South of the lodge the Witherbark trolls hold their villages. Every one of them carries a skull: with twenty, use {item:15002} to make the Laden Pike, then plant it inside the village."] = "Au sud du gîte, les trolls Witherbark tiennent leurs villages. Chacun porte un crâne : avec vingt crânes, utilisez {item:15002} pour obtenir la Pique de Nimboya préparée, puis plantez-la dans le village.",
		["South-west again, the exile hides by the ruins of {area:353}."] = "De nouveau au sud-ouest, l'exilé se cache près des ruines de {area:353}.",
		["The Highvale elves camp around {area:350}. Burn the report, the notes and the records in their camps. {npc:7780} is held inside the lodge: lead him out and fight off the ambush on the way.\nCareful: Groups of about three elves ambush the escort, usually twice."] = "Les elfes de Highvale campent autour de {area:350}. Brûlez le rapport, les notes et les registres dans leurs camps. {npc:7780} est retenu dans le pavillon : faites-le sortir et repoussez l'embuscade en chemin.\nAttention : des groupes d'environ trois elfes attaquent l'escorte, généralement deux fois.",
		["The bloodmages"] = "Les mages de sang",
		["The crates of {item:8684} lie around the abandoned Horde camp at {area:351}, among the oozes."] = "Les caisses de {item:8684} se trouvent autour du camp abandonné de la Horde à {area:351}, parmi les limons.",
		["The five quests share the same parts: gather them all in one sweep. West of the road the {npc:5982} vultures, Starving Snickerfangs, Scorpok Stingers and Deatheye basilisks share the hills.\nEast of the road the Ashmane boars and Grunters root on the slopes beside the Redstone basilisks. Stay away from the level 52 Helboars further south.\nCareful: Scorpok Stingers use {spell:5416}; {npc:8301} adds Knockdown."] = "Les cinq quêtes demandent les mêmes morceaux : ramassez-les tous en un seul passage. À l'ouest de la route, les vautours {npc:5982}, les Raillecrocs affamées, les Aiguillonneurs scorpok et les basilics Deatheye se partagent les collines.\nÀ l'est de la route, les sangliers Ashmane et les Grogneurs fouillent les pentes à côté des basilics Redstone. Restez à l'écart des Sangliers infernaux de niveau 52 plus au sud.\nAttention : les Aiguillonneurs scorpok utilisent {spell:5416} ; {npc:8301} y ajoute Renversement.",
		["The secret lies on the {area:307}, above the beach."] = "Le Secret de Rin'ji se trouve sur {area:307}, au-dessus de la plage.",
		["Their follow-ups ask for the same parts again for a buff item and pay no experience: leave them."] = "Leurs quêtes suivantes redemandent les mêmes morceaux pour un objet d'amélioration et ne rapportent pas d'expérience : laissez-les.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:7977} is a level 48 elite: most classes solo it at level 50, but you may need help. Skip it if you are alone: the route has you grind the XP back.\n{npc:7977} walks the shore below the {area:307}, from the arrow south to about 75,66 and north to about 82,52: if she isn't at the arrow, follow the shore."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:7977} est une élite de niveau 48 : la plupart des classes la tuent seules au niveau 50, mais vous aurez peut-être besoin d'aide. Passez-la si vous êtes seul : la route vous fait regagner cette expérience en tuant des monstres.\n{npc:7977} arpente le rivage au pied de {area:307}, de la flèche vers le sud jusqu'à environ 75,66 et vers le nord jusqu'à environ 82,52 : si elle n'est pas à la flèche, suivez le rivage.",
		["Underwater"] = "Sous l'eau",
		["West of the island, the Vilebranch scalpers hold the temples of {area:1884} and {area:1917}. Slagtree's tools lie at one of the temples.\nThe Silvermane Stalkers, Savage Owlbeasts and Razorbeak Skylords share the hills between the temples and {area:351}. Use the {item:9618} on the owlbeasts you kill. The Skylords also drop Long Elegant Feathers: keep ten for {npc:14738}'s second message.\nCareful: Silvermane Stalkers are level 47-48 and stay stealthed while out of combat. Up close they use {spell:7367}. When a {npc:2925} falls to 50% health or lower, it calls for help from anything within 25 yd."] = "À l'ouest de l'île, les scalpeurs Vilebranch tiennent les temples de {area:1884} et de {area:1917}. Les outils de Slagtree se trouvent près de l'un des temples.\nLes Traqueurs Crins-d'argent, les Chouettards sauvages et les Seigneurs du ciel Bec-rasoir se partagent les collines entre les temples et {area:351}. Utilisez le {item:9618} sur les chouettards que vous tuez. Les Seigneurs du ciel lâchent aussi des Longues plumes élégantes : gardez-en dix pour le second message de {npc:14738}.\nAttention : les Traqueurs Crins-d'argent sont de niveau 47-48 et restent camouflés hors combat. De près, ils utilisent {spell:7367}. Quand un {npc:2925} tombe à 50 % de vie ou moins, il appelle à l'aide tout ce qui se trouve à moins de 25 m.",
		["for {npc:6986} in {zone:1454}, around level 50"] = "pour {npc:6986} à {zone:1454}, vers le niveau 50",
		["for {npc:7825} in the {zone:1458}, around level 50"] = "pour {npc:7825} à {zone:1458}, vers le niveau 50",
		["grind on {npc:2505}"] = "tuez en boucle : {npc:2505}",
		["{area:1440}: kill these as you meet them"] = "{area:1440} : tuez-les au passage",
		["{area:1446} flight master"] = "Maître de vol de {area:1446}",
		["{area:1917}: kill these as you meet them"] = "{area:1917} : tuez-les au passage",
		["{area:307}: kill these as you meet them"] = "{area:307} : tuez-les au passage",
		["{area:3317} flight master"] = "Maître de vol de {area:3317}",
		["{area:348} well"] = "Puits de {area:348}",
		["{area:355}: kill these as you meet them"] = "{area:355} : tuez-les au passage",
		["{item:8704}, a rare drop"] = "{item:8704}, butin rare",
		["{npc:14731}'s lunch"] = "Le repas de {npc:14731}",
		["{npc:14731}, inside"] = "{npc:14731}, à l'intérieur",
		["{npc:14757}, at the top of {area:354}"] = "{npc:14757}, au sommet de {area:354}",
		["{npc:7801}'s camp"] = "Camp de {npc:7801}",
} end)()
t.guides["forever/horde/40-50/06-azshara"] = (function() return {
		["\"Sea Wolf\" MacKinley, on the top floor"] = "« Loup de mer » MacKinley, au dernier étage",
		["Back north-east to {npc:8420}."] = "Retournez au nord-est voir {npc:8420}.",
		["Back to {area:1099}"] = "Retour à {area:1099}",
		["Back to {npc:11548} at the shrine; stay west of the {area:3137} guards."] = "Retournez voir {npc:11548} au sanctuaire ; restez à l'ouest des gardes de {area:3137}.",
		["Back to {object:3202}"] = "Retour à {object:3202}",
		["Below ground"] = "Sous terre",
		["Class trainer"] = "Maître de classe",
		["Continue south to {area:35}. {npc:7406} has his workshop on the upper ring of the bay."] = "Continuez au sud jusqu'à {area:35}. {npc:7406} a son atelier sur le cercle supérieur de la baie.",
		["Fly to {area:1099}"] = "Prendre un vol pour {area:1099}",
		["Fly to {area:1637}"] = "Prendre un vol pour {area:1637}",
		["Fly to {area:1638}"] = "Prendre un vol pour {area:1638}",
		["Fly to {area:35}"] = "Prendre un vol pour {area:35}",
		["Fly to {area:976}"] = "Prendre un vol pour {area:976}",
		["Fly to {object:3202}"] = "Prendre un vol pour {object:3202}",
		["Fly to {zone:1456}; it is on the way to {area:1099}. No flight path there yet? Fly to {area:378} and ride west through {zone:1412}. Hamuul and {npc:4046} are on the {area:1639}; Druids and Paladins train here ({npc:3033}, {npc:246344})."] = "Volez jusqu'aux {zone:1456} ; c'est sur le chemin du {area:1099}. Pas encore de trajet aérien ? Volez jusqu'au {area:378} et allez vers l'ouest à travers {zone:1412}. Hamuul et {npc:4046} sont sur la {area:1639} ; les Druides et les Paladins s'entraînent ici ({npc:3033}, {npc:246344}).",
		["Follow the road north to {area:1237}, the Horde camp."] = "Suivez la route vers le nord jusqu'à {area:1237}, le camp de la Horde.",
		["Frayfeather Hippogryphs"] = "Hippogryphes Aigreplume",
		["Hippogryph nests"] = "Nids d'hippogryphes",
		["Keep the deliveries for {npc:4046}, {npc:8659} and {npc:6522}: you pass {zone:1456}, {zone:1454} and the {zone:1458} later."] = "Gardez les livraisons pour {npc:4046}, {npc:8659} et {npc:6522} : vous passerez plus tard par {zone:1456}, {zone:1454} et {zone:1458}.",
		["Keep {npc:8659}'s payment and Ag'tor's {quest:3504}: they go back to {area:1237} on a later visit."] = "Gardez le paiement de {npc:8659} et {quest:3504} d'Ag'tor : ils retournent à {area:1237} lors d'une visite ultérieure.",
		["Keep {quest:3444}: {npc:7771}'s chest is opened on a later visit."] = "Gardez {quest:3444} : le coffre de {npc:7771} s'ouvre lors d'une visite ultérieure.",
		["On the way through {zone:1454} to the flight master, step into the Drag: {npc:7010} takes the insect report from {zone:1446}, and its experience shortens the top-up to 50 in {zone:1447}."] = "En traversant {zone:1454} vers le maître de vol, passez par la Herse : {npc:7010} prend le rapport sur les insectes de {zone:1446}, et son expérience raccourcit la mise à niveau jusqu'à 50 en {zone:1447}.",
		["Paladin trainer"] = "Maître des paladins",
		["Ride east along the road out of Splintertree. {npc:11548} waits at the {area:1235} just off the road, a few steps west of the Alliance's {area:3137}: come in from the west and keep clear of the Azshara Sentinels and Jarrodenus (elite)."] = "Chevauchez vers l'est sur la route en quittant Bois-brisé. {npc:11548} attend au {area:1235}, juste à côté de la route, à quelques pas à l'ouest de la {area:3137} de l'Alliance : arrivez par l'ouest et évitez les Sentinelles d'Azshara ({npc:11276}) et Jarrodenus (élite).",
		["Ride into {zone:1447}"] = "Entrer en {zone:1447}",
		["Ride north-east to the goblin's camp on the cliffs above the {area:1227}."] = "Allez au nord-est jusqu'au camp du gobelin sur les falaises au-dessus de {area:1227}.",
		["Ride south along the road to the {area:1938}; {npc:7771} camps beside it. From here the road west leads down into {zone:1449}, where the next guide starts."] = "Suivez la route vers le sud jusqu'à {area:1938} ; {npc:7771} campe à côté. De là, la route vers l'ouest descend dans {zone:1449}, où commence le guide suivant.",
		["Ride south-west to the ruins. The four tablets lie among the ruins, guarded by Spitelash naga; any Siren or Myrmidon can carry {npc:8420}'s rune."] = "Allez au sud-ouest jusqu'aux ruines. Les quatre tablettes s'y trouvent, gardées par les nagas Fouette-bile ; toute Sirène ou tout Myrmidon Fouette-bile peut porter la rune de {npc:8420}.",
		["Ride west back to {area:1237}."] = "Retournez à l'ouest jusqu'à {area:1237}.",
		["Sprite Darters"] = "Fées fléchetteuses",
		["The Bloodsail ships"] = "Les navires de la Voile sanglante",
		["The Droffers' shop is a few steps further into the Drag."] = "La boutique des Droffers est à quelques pas plus loin dans la Herse.",
		["The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north."] = "Les fantômes bien-nés hantent les ruines juste au nord du sanctuaire ; les satyres Haldarr campent un peu plus au nord.",
		["The Sea Elementals and Sea Sprays wash along the shore around the dock.\nThe Land Walkers and Cliff Giants roam the hills north of the dock. Zap each one with {item:18904} first: shrunken, they are no longer elite. Every zapped giant drops residue; use the Muisek Vessel on its body too."] = "Les Élémentaires marins et les Embruns ondoient le long du rivage autour du quai.\nLes Marcheurs des terres et les Géants des falaises parcourent les collines au nord du quai. Frappez d'abord chacun avec l'{item:18904} : une fois rapetissés, ils ne sont plus élites. Chaque géant rapetissé lâche du résidu ; utilisez aussi le Récipient de Muisek sur son corps.",
		["The Thunderhead Hippogryphs fly over the hills just south of {area:1237}."] = "Les Hippogryphes Tête-tonnerre survolent les collines juste au sud de {area:1237}.",
		["The blood elves' camp lies just south of {npc:8420}. His four pieces of equipment lie in the crates around the camp."] = "Le camp des elfes de sang se trouve juste au sud de {npc:8420}. Ses quatre pièces d'équipement sont dans les caisses autour du camp.",
		["The faerie dragons flit around the woods just west of the camp. Use the vessel on each one you kill."] = "Les dragons féériques voltigent dans les bois juste à l'ouest du camp. Utilisez le récipient sur chacun de ceux que vous tuez.",
		["The hippogryph nests are on the hills to the south, around the {area:2522}; each holds an egg for the {object:142071}."] = "Les nids d'hippogryphes se trouvent sur les collines au sud, autour des {area:2522} ; chacun contient un œuf pour l'{object:142071}.",
		["The hippogryphs nest on the hills south-west of the camp. Kill one, then use the Muisek Vessel on its body."] = "Les hippogryphes nichent sur les collines au sud-ouest du camp. Tuez-en un, puis utilisez le récipient miniaturisé sur son corps.",
		["The treants wander the forest roads between the camp and the middle of {zone:1444}; there are only a few, so look along the paths."] = "Les tréants errent sur les routes forestières entre le camp et le centre de {zone:1444} ; ils sont peu nombreux, cherchez le long des chemins.",
		["The {object:142071}, in the middle of town"] = "L'{object:142071}, au centre de la ville",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:818} (level 47 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back.\nCareful: Two elite caster guards, around level 45, stand with {npc:818} and join the fight together with him."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:818} (élite de niveau 47) demande un groupe de 2. Passez-le si vous êtes seul : la route vous fait regagner cette expérience en tuant des monstres.\nAttention : deux gardes élites lanceurs de sorts, autour du niveau 45, se tiennent avec {npc:818} et se joignent au combat avec lui.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:8552} needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {quest:8552} demande un groupe de 2. Passez-la si vous êtes seul : la route vous fait regagner cette expérience en tuant des monstres.",
		["To {object:3202}"] = "Vers {object:3202}",
		["Undamaged Hippogryph Feathers"] = "Plumes d'hippogryphe sans défaut",
		["Upstairs"] = "À l'étage",
		["Wandering Forest Walkers"] = "Marcheurs des bois errants",
		["Xylem's tower stands on the cliff just north of {area:1237}; the path winds up its north side."] = "La tour de Xylem se dresse sur la falaise juste au nord de {area:1237} ; le chemin monte en lacets par son flanc nord.",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["grind on {npc:6125}"] = "tuez en boucle : {npc:6125}",
		["{area:1099} flight master"] = "Maître de vol de {area:1099}",
		["{area:1108}: kill these as you meet them"] = "{area:1108} : tuez-les au passage",
		["{area:1221}: kill these as you meet them"] = "{area:1221} : tuez-les au passage",
		["{area:1236}: kill these as you meet them"] = "{area:1236} : tuez-les au passage",
		["{area:1237} flight master"] = "Maître de vol de {area:1237}",
		["{area:35} flight master"] = "Maître de vol de {area:35}",
		["{area:75} flight master"] = "Maître de vol de {area:75}",
		["{npc:246344} in {zone:1456}; {zone:1454} has no paladin trainer"] = "{npc:246344} aux {zone:1456} ; {zone:1454} n'a pas de maître des paladins",
		["{npc:5594}, inside"] = "{npc:5594}, à l'intérieur",
		["{npc:6117} walks around {area:1235}: look inside the circle on the map"] = "{npc:6117} se promène autour de {area:1235} : cherchez dans le cercle sur la carte",
		["{npc:6986}, the Drag"] = "{npc:6986}, la Herse",
		["{npc:7010}, the Drag"] = "{npc:7010}, la Herse",
		["{npc:7010}, the Drag: if you still carry it"] = "{npc:7010}, la Herse : si vous l'avez encore",
		["{npc:7406}, inside"] = "{npc:7406}, à l'intérieur",
		["{npc:7776}: the bears are in {zone:1448}"] = "{npc:7776} : les ours sont à {zone:1448}",
		["{npc:7876}'s tar and Pestlezugg's samples come from {zone:1449}."] = "Le goudron de {npc:7876} et les échantillons de l'Alchimiste Pestlezugg viennent de {zone:1449}.",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}, à côté du maître des coursiers du vent",
		["{npc:8395}, at the east edge of the camp: no experience, only a teleport to Azshara Tower"] = "{npc:8395}, à la lisière est du camp : pas d'expérience, seulement une téléportation vers la tour d'Azshara",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}, {object:172960}",
		["{object:3202} flight master"] = "Maître de vol de Grom'gol",
		["{quest:3761} is gathered in the next guide; {npc:4046}'s payment goes back to {npc:8587} later."] = "{quest:3761} se récolte dans le guide suivant ; le paiement de {npc:4046} retourne à {npc:8587} plus tard.",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
		["{zone:1456} flight master"] = "Maître de vol des {zone:1456}",
} end)()
t.guides["forever/horde/50-60/01-un-goro-crater"] = (function() return {
		["Back a few steps west to Felstone Farm, the first farm along the road; {npc:10778} waits in the house."] = "Revenez quelques pas à l'ouest jusqu'à la ferme Felstone, la première ferme le long de la route ; {npc:10778} attend dans la maison.",
		["Back north-east to {area:251}."] = "Retournez au nord-est à la {area:251}.",
		["Back to {area:976}"] = "Retour à {area:976}",
		["Below ground"] = "Sous terre",
		["Boat to {area:16727}"] = "Bateau pour {area:16727}",
		["Bridge into {area:254}"] = "Pont vers le {area:254}",
		["Careful: Gorishi Workers may call for help within 25 yd when below 45% health; silithids cast {spell:8137} and Tunnelers and the Hive Guard use {spell:14120}."] = "Attention : les Ouvriers Gorishi peuvent appeler à l'aide à moins de 25 m sous 45 % de vie ; les silithides lancent {spell:8137}, et les Tunneliers et le Garde de la ruche utilisent {spell:14120}.",
		["Careful: Gorishi Workers that drop below 45% health have a 50% chance to call for help from allies within 25 yd."] = "Attention : les Ouvriers Gorishi qui passent sous 45 % de vie ont 50 % de chances d'appeler à l'aide leurs alliés à moins de 25 m.",
		["Cross the south of the crater to the pylon on the western cliffs."] = "Traversez le sud du cratère jusqu'au pylône sur les falaises de l'ouest.",
		["Eastern Pylon"] = "Pylône est",
		["Fly to {area:1497}"] = "Prendre un vol pour {area:1497}",
		["Fly to {area:272}"] = "Prendre un vol pour {area:272}",
		["Follow the cliffs south to {quest:3821}, the Firegut ogres' hill. {npc:9136}'s remains lie at its foot."] = "Longez les falaises vers le sud jusqu'au {quest:3821}, la colline des ogres Brûlentrailles. Les restes de {npc:9136} gisent à son pied.",
		["From here on pick up every Power Crystal (blue, green, red, yellow) and every {quest:3761} pile you pass: 25 soil in all, 20 for Hamuul and 5 for Pestlezugg."] = "Dès maintenant, ramassez chaque Cristal de puissance (bleu, vert, rouge, jaune) et chaque tas de {quest:3761} sur votre route : 25 terres en tout, 20 pour Hamuul et 5 pour Pestlezugg.",
		["From the {area:152}, follow the road east into the {zone:1422}. The Scarlet Crusade's tents stand just past Felstone Farm, between {area:199} and {area:200}. Torch the command tent with the {object:176092} and plant the Scourge banner."] = "Depuis la {area:152}, suivez la route vers l'est jusqu'aux {zone:1422}. Les tentes de la Croisade écarlate se dressent juste après la ferme Felstone, entre {area:199} et {area:200}. Incendiez la tente de commandement avec la {object:176092} et plantez la bannière du Fléau.",
		["From the {area:1938} ride west to the long ramp that winds down into {zone:1449}, then follow the crater's north wall to {area:541}, a camp in the cliff caves. Everyone here is neutral."] = "Depuis le {area:1938}, chevauchez vers l'ouest jusqu'à la longue rampe qui descend dans le {zone:1449}, puis longez la paroi nord du cratère jusqu'au {area:541}, un camp dans les grottes de la falaise. Tout le monde ici est neutre.",
		["Gorillas"] = "Gorilles",
		["Inside"] = "À l'intérieur",
		["Into the {zone:1427}"] = "Vers la {zone:1427}",
		["Into {zone:1449}"] = "Vers le {zone:1449}",
		["Keep the parcel: {npc:10781} is in the {zone:1458}. Keep {quest:5901}: its termite mounds are in {area:2627}, on the next guide's ride to Tirion. The next guide starts with {npc:10739} by the {area:202}, south-east of here."] = "Gardez le colis : le {npc:10781} est à {zone:1458}. Gardez {quest:5901} : ses termitières se trouvent à {area:2627}, sur le trajet du guide suivant vers Tirion. Le guide suivant commence avec {npc:10739} près de {area:202}, au sud-est d'ici.",
		["Keep {npc:10267}'s letter: {quest:4808} is in {area:2255}, {zone:1452}."] = "Gardez la Lettre de {npc:10267} : {quest:4808} est à {area:2255}, {zone:1452}.",
		["Keep {npc:9118}'s {quest:4147} and {npc:8737}'s letter for later guides."] = "Gardez la quête {quest:4147} de {npc:9118} et la lettre de {npc:8737} pour des guides ultérieurs.",
		["Lar'korwi Mates"] = "Compagnes de Lar'korwi ({npc:9683})",
		["Lashers and Threshers"] = "Flagellants et Batteurs",
		["Leave the {zone:1458} and ride east along the road through {zone:1420} to the {area:152}, the Forsaken fort on the border."] = "Quittez {zone:1458} et suivez la route vers l'est à travers les {zone:1420} jusqu'à la {area:152}, le fort réprouvé de la frontière.",
		["Leave {zone:2548} on foot to the north-west, north of {area:16685}, into the {zone:1418}."] = "Quittez {zone:2548} à pied vers le nord-ouest, au nord de {area:16685}, pour entrer dans les {zone:1418}.",
		["North of Torwa, a dead Threshadon lies by the water."] = "Au nord de Torwa, un battrodon mort gît au bord de l'eau.",
		["Northern Pylon"] = "Pylône nord",
		["Out of the refuge"] = "Hors du refuge",
		["Power Crystals and soil"] = "Cristaux de puissance et terre",
		["Pterrordax"] = "Pterreurdactyles",
		["Ride down the east side of the crater to the pylon on the eastern cliffs."] = "Descendez le côté est du cratère jusqu'au pylône sur les falaises de l'est.",
		["Ride north along the east side. Bloodpetal Lashers and Threshers fill the jungle."] = "Allez vers le nord le long du côté est. Les Flagellants et les Batteurs Pétale-de-sang remplissent la jungle.",
		["Ride north back to {area:541}."] = "Retournez au nord jusqu'au {area:541}.",
		["Ride south-west to {area:537}, the volcano in the middle of the crater. Bloodpetal Flayers grow around its foot.\nSouth of the hot springs, Stegodons graze and Dinosaur Bones drop from them or lie on the ground; Diemetradons nearby carry the scales {npc:9998} wants. Ravasaurs hunt in packs in the south-west: their claws are for {npc:8659}, and now and then one carries a Mangled Journal (a rare drop: take its quest only if you get one). Avoid Gruff, a level 57 Stegodon.\nRide south-west along the western cliffs. {npc:9167} fly over the west side, and Bloodpetal Trappers grow in the same jungle."] = "Allez vers le sud-ouest jusqu'à {area:537}, le volcan au milieu du cratère. Les Écorcheurs Pétale-de-sang poussent à son pied.\nAu sud des sources chaudes, les stégodons paissent et les Os de dinosaure tombent sur eux ou jonchent le sol ; les diémétradons tout proches portent les écailles que veut {npc:9998}. Les ravasaures chassent en meute au sud-ouest : leurs griffes sont pour {npc:8659}, et de temps en temps l'un d'eux porte un Journal abîmé (butin rare : ne prenez sa quête que si vous en obtenez un). Évitez Gruff, un stégodon de niveau 57.\nAllez vers le sud-ouest le long des falaises de l'ouest. Des {npc:9167} survolent le côté ouest, et les Trappeurs Pétale-de-sang poussent dans la même jungle.",
		["Ride west to the dig site. {npc:7039} golems (53) stomp around it and drop the shards often; the {quest:4296} stands in its middle among the Thaurissan dwarves. Copy it.\nBlack Broodlings nest in the hills just east of {area:251}. Use {npc:10267}'s {item:12284} on a broodling when it is almost dead to capture its essence."] = "Allez vers l'ouest jusqu'au site de fouilles. Des golems {npc:7039} (53) piétinent les environs et lâchent souvent les éclats ; la {quest:4296} se dresse au milieu, parmi les nains de Thaurissan. Copiez-la.\nLes Rejetons noirs nichent dans les collines juste à l'est de {area:251}. Utilisez l'{item:12284} de {npc:10267} sur un rejeton presque mort pour capturer son essence.",
		["Scarlet forward camp"] = "Camp avancé écarlate",
		["Stegodons and ravasaurs"] = "Stégodons et ravasaures",
		["Take a {object:176092} from the crate next to Derrington for {quest:5096}, done on the way back. Equip the {quest:5405}: Scourgestones only drop while you wear it."] = "Prenez une {object:176092} dans la caisse à côté de Derrington pour {quest:5096}, à faire au retour. Équipez la {quest:5405} : les Pierres du Fléau ne tombent que si vous la portez.",
		["Take the pass out of {area:340}'s west side into the {zone:1427}, then ride south across the gorge to the long bridge into {area:254}. Inside, follow the chain walkways down and leave through the southern exit; stay off the paths to the dungeon portals."] = "Prenez le col à l'ouest de {area:340} vers la {zone:1427}, puis traversez la gorge vers le sud jusqu'au long pont qui mène au {area:254}. À l'intérieur, descendez les passerelles à chaînes et sortez par le sud ; évitez les chemins vers les portails de donjon.",
		["The Lar'korwi Mates prowl the jungle north-west of {npc:9619}."] = "Les Compagnes de Lar'korwi ({npc:9683}) rôdent dans la jungle au nord-ouest de {npc:9619}.",
		["The crystal clusters stand all over the crater, many around {area:537}. Take a few extra of each colour for the pylons."] = "Les amas de cristaux se dressent partout dans le cratère, beaucoup autour de {area:537}. Prenez-en quelques-uns de plus de chaque couleur pour les pylônes.",
		["The expedition's crate sits at an abandoned camp in the eastern jungle."] = "La caisse de l'expédition se trouve dans un camp abandonné de la jungle de l'est.",
		["The expedition's lost equipment lies in the south-west jungle."] = "L'équipement perdu de l'expédition se trouve dans la jungle du sud-ouest.",
		["The gorillas live on the north-east plateau. Stay out of the deepest cave: {npc:9622} lives there."] = "Les gorilles vivent sur le plateau du nord-est. N'entrez pas dans la grotte la plus profonde : {npc:9622} y vit.",
		["The mountain lets you out beside {area:252}, full of 55-57 orcs. Follow the road east along the northern cliffs to the Horde camp at {area:251}."] = "La montagne débouche près du {area:252}, plein d'orcs de niveau 55-57. Suivez la route vers l'est le long des falaises du nord jusqu'au camp de la Horde à la {area:251}.",
		["The pylon stands on the slope east of the refuge."] = "Le pylône se dresse sur la pente à l'est du refuge.",
		["The raft lies on the shore of the south-eastern lake; the small pack sits in the water beside it."] = "Le radeau est sur la rive du lac du sud-est ; le petit paquetage est dans l'eau à côté.",
		["The tar pits lie just south of the refuge. Tar Beasts, Lurkers and Creepers drop the {item:11834}."] = "Les fosses de goudron se trouvent juste au sud du refuge. Les Bêtes du goudron, les Rôdeurs et les Rampants lâchent le {item:11834}.",
		["Theodora's next errand goes to Lotwil east of town and then into {area:1584}: skip it."] = "La course suivante de Theodora mène à Lotwil, à l'est de la ville, puis dans {area:1584} : passez-la.",
		["To {area:976}"] = "Vers {area:976}",
		["Underwater"] = "Sous l'eau",
		["Upstairs"] = "À l'étage",
		["Use the Mangled Journal to start it"] = "Utilisez Un journal abîmé pour la commencer",
		["Western Pylon"] = "Pylône ouest",
		["grind on Pterrordax"] = "tuez en boucle : ptérreurdactyles",
		["grind on {npc:6511}"] = "tuez en boucle : {npc:6511}",
		["grind on {npc:6551}"] = "tuez en boucle : {npc:6551}",
		["{area:250}: kill these as you meet them"] = "{area:250} : tuez-les au passage",
		["{area:272} flight master"] = "Maître de vol de {area:272}",
		["{area:340} flight master"] = "Maître de vol de {area:340}",
		["{area:538}: kill these as you meet them"] = "{area:538} : tuez-les au passage",
		["{item:11116}, a rare drop"] = "{item:11116}, butin rare",
		["{npc:10879}, the {object:36078}, beside the bat master"] = "{npc:10879}, {object:36078}, près du maître des chauves-souris",
		["{npc:5594}, inside"] = "{npc:5594}, à l'intérieur",
		["{npc:6522}, the {object:36073}"] = "{npc:6522}, {object:36073}",
		["{npc:7825} stands in the {object:36082}."] = "{npc:7825} se tient dans le {object:36082}.",
		["{npc:8390}, the Apothecarium: the vials fill in {zone:1447} later"] = "{npc:8390}, l'Apothicarium : les fioles se remplissent plus tard en {zone:1447}",
		["{npc:9117}, at the back of the cave; below ground"] = "{npc:9117}, au fond de la grotte ; sous terre",
		["{npc:9117}, below ground"] = "{npc:9117}, sous terre",
		["{npc:9618}, just outside"] = "{npc:9618}, juste dehors",
		["{npc:9619} camps in the south-east corner of the crater."] = "{npc:9619} campe dans le coin sud-est du cratère.",
		["{npc:9623} then wants a {item:10561}, an {skill:202} item. Skip it unless you have one."] = "{npc:9623} veut ensuite une {item:10561}, un objet d'{skill:202}. Passez cette quête sauf si vous en avez une.",
		["{npc:9623}, the robot on the plateau; below ground"] = "{npc:9623}, le robot sur le plateau ; sous terre",
		["{npc:9998}, at the entrance"] = "{npc:9998}, à l'entrée",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}, à l'entrée du refuge",
		["{object:175894}, beside the house; inside"] = "{object:175894}, à côté de la maison ; à l'intérieur",
		["{quest:3822} walks the caves and mine tunnels of {quest:3821}; if he isn't home, clear the ogres around the entrances until he comes back."] = "{quest:3822} arpente les grottes et galeries de mine du {quest:3821} ; s'il est absent, tuez les ogres autour des entrées jusqu'à son retour.",
		["{zone:1449}: kill these as you meet them"] = "{zone:1449} : tuez-les au passage",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
} end)()
t.guides["forever/horde/50-60/02-felwood"] = (function() return {
		["Back north to {area:1763}. Fill {npc:10922}'s canteen at the corrupted moonwell in the middle of the southern camp."] = "Retournez au nord jusqu'à {area:1763}. Remplissez la gourde de {npc:10922} au puits de lune corrompu au milieu du camp sud.",
		["Below ground"] = "Sous terre",
		["Class trainer"] = "Maître de classe",
		["Cross the river east into {area:2627}, the ruined town in the north-west of the {zone:1423}. {npc:12384} sits in a hut at its edge."] = "Traversez la rivière vers l'est jusqu'à {area:2627}, la ville en ruine au nord-ouest des {zone:1423}. {npc:12384} est assis dans une hutte à sa lisière.",
		["Derrington's watchtowers, Vandis' cauldron and {npc:11615}'s barrel are done on a later visit: keep them."] = "Les tours de guet de Derrington, le chaudron de Vandis et le tonneau de {npc:11615} se font lors d'une visite ultérieure : gardez-les.",
		["Diseased Grizzlies"] = "Grizzlys malades",
		["Diseased Wolves"] = "Loups malades",
		["Druid trainer"] = "Maître des druides",
		["East of Bloodvenom Post, the cratered vale where the Entropic Beasts and Horrors roam. Kill two of each, then walk to each of the three fel-water craters."] = "À l'est du Poste de la Vénéneuse, le val criblé de cratères où errent les Bêtes d'entropie et les Horreurs. Tuez-en deux de chaque, puis allez à chacun des trois cratères d'eau gangrenée.",
		["Fly to {area:431}"] = "Prendre un vol pour {area:431}",
		["Follow the road north-west. The south of {area:1763}, around its corrupted moonwell, is held by Shadow Council cultists, adepts, guardsmen and their hounds."] = "Suivez la route vers le nord-ouest. Le sud de {area:1763}, autour de son puits de lune corrompu, est tenu par des cultistes, adeptes, gardes du Conseil des ombres et leurs molosses.",
		["He camps by the {area:202}, south-east of {area:200}."] = "Il campe près du {area:202}, au sud-est de {area:200}.",
		["Inside"] = "À l'intérieur",
		["Keep the branch: {npc:5770} is in {zone:1456}."] = "Gardez la branche : {npc:5770} est à {zone:1456}.",
		["Keep {quest:5158}: {npc:5901} is in the {zone:1413}."] = "Gardez {quest:5158} : {npc:5901} est dans {zone:1413}.",
		["Keep {quest:6164}: {npc:12384} takes it back on the {zone:1423} guide's {area:2627} stop."] = "Gardez {quest:6164} : {npc:12384} le reprend lors de l'étape {area:2627} du guide des {zone:1423}.",
		["Keep {quest:8465} for {zone:1452}."] = "Gardez {quest:8465} pour {zone:1452}.",
		["Knights and magi work the {area:192}; the medics and hunters camp south of it."] = "Chevaliers et mages travaillent au {area:192} ; les médecins et chasseurs campent au sud.",
		["Level 52.63"] = "Niveau 52.63",
		["Level 53.34"] = "Niveau 53.34",
		["Level 54.7"] = "Niveau 54.7",
		["Level 54.87"] = "Niveau 54.87",
		["Northern crater"] = "Cratère nord",
		["Paladin trainer"] = "Maître des paladins",
		["Ride back south past {area:1763} to the corrupted moonwell of the Jadefire satyrs and fill {npc:9996}'s flasket there."] = "Retournez vers le sud en passant {area:1763} jusqu'au puits de lune corrompu des satyres Jadefeu et remplissez-y la flasque de {npc:9996}.",
		["Ride back west over the river and on to the {area:192}; {npc:11610} hides on the hill north-east of it."] = "Retraversez la rivière vers l'ouest et continuez jusqu'au {area:192} ; {npc:11610} se cache sur la colline au nord-est.",
		["Ride north along the eastern hills; {npc:1855} lives in a small house by the {area:2619}, at the border with the {zone:1423}."] = "Chevauchez vers le nord le long des collines de l'est ; {npc:1855} vit dans une petite maison au bord de {area:2619}, à la frontière des {zone:1423}.",
		["Ride north up the road again."] = "Remontez la route vers le nord.",
		["Ride south-west past Felstone Farm and follow the road west back to the {area:152}."] = "Chevauchez vers le sud-ouest en passant la ferme des Felstone et suivez la route vers l'ouest jusqu'à {area:152}.",
		["Ride the road south through {zone:1448} to the Sanctuary."] = "Suivez la route vers le sud à travers {zone:1448} jusqu'au Sanctuaire.",
		["Ror stands at the far south end of {area:1761}."] = "Ror se tient à l'extrême sud du {area:1761}.",
		["Scarlet Crusade"] = "Croisade écarlate",
		["Southern crater"] = "Cratère sud",
		["Southern {area:1763}"] = "Sud de {area:1763}",
		["Take the kitten to the same moonwell and release it there with {item:12565}; once it has turned into a {npc:10042}, bring it back to {npc:9996} and click on it to hand it over."] = "Emmenez le chaton au même puits de lune et relâchez-le là avec {item:12565} ; une fois changé en {npc:10042}, ramenez-le à {npc:9996} et cliquez dessus pour le lui remettre.",
		["The Deadwood furbolg village just west of the tunnel. {npc:9462} (56) stands among them. {npc:11557}, a friendly furbolg, sits at the north end of the village."] = "Le village des furbolgs Mort-bois juste à l'ouest du tunnel. {npc:9462} (56) se tient parmi eux. {npc:11557}, un furbolg amical, est assis à l'extrémité nord du village.",
		["The Horde camp just north of {area:1763}."] = "Le camp de la Horde juste au nord de {area:1763}.",
		["The Jadefire moonwell"] = "Le puits de lune des Jadefeu",
		["The book lies in the ruined inn of {area:2627}; the undead in the town are 54-56, so pull them one at a time.\nThe Large Termite Mounds stand all over the hills east of {area:2627}. Use the {item:15042} on each mound you pass."] = "Le livre se trouve dans l'auberge en ruine de {area:2627} ; les morts-vivants de la ville sont de niveau 54-56, attirez-les donc un par un.\nLes Grandes termitières sont dispersées sur les collines à l'est de {area:2627}. Utilisez le {item:15042} sur chaque termitière que vous croisez.",
		["The diary lies in the farmhouse, the cabinet stands inside and the outhouse is behind it. A {npc:10816} carries the outhouse key; {npc:10836} comes out when you open the outhouse and carries the cabinet key."] = "Le journal se trouve dans la ferme, le meuble est à l'intérieur et les latrines sont derrière. Un {npc:10816} porte la clé des latrines ; {npc:10836} sort quand vous ouvrez les latrines et porte la clé du meuble.",
		["The druids' camp is just past the border."] = "Le camp des druides se trouve juste après la frontière.",
		["The road ends at {npc:15395}, outside the {area:1769} tunnel in the far north-east."] = "La route se termine à {npc:15395}, devant le tunnel du {area:1769}, à l'extrême nord-est.",
		["The wolves roam the fields between Andorhal, {area:200} and the {area:202}. Finish them on the ride back east."] = "Les loups parcourent les champs entre Andorhal, {area:200} et le {area:202}. Finissez-les sur le chemin du retour vers l'est.",
		["The {area:1763} moonwell"] = "Le puits de lune de {area:1763}",
		["Upstairs"] = "À l'étage",
		["Western crater"] = "Cratère ouest",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["grind on {npc:10605}"] = "tuez en boucle : {npc:10605}",
		["grind on {npc:1816}"] = "tuez en boucle : {npc:1816}",
		["grind on {npc:1826}"] = "tuez en boucle : {npc:1826}",
		["grind on {npc:7101}"] = "tuez en boucle : {npc:7101}",
		["grind on {npc:7125}"] = "tuez en boucle : {npc:7125}",
		["grind on {npc:7153}"] = "tuez en boucle : {npc:7153}",
		["grind on {npc:7155}"] = "tuez en boucle : {npc:7155}",
		["grind on {npc:7156}"] = "tuez en boucle : {npc:7156}",
		["grind on {npc:8957}"] = "tuez en boucle : {npc:8957}",
		["{area:200} farmhouse"] = "Ferme de {area:200}",
		["{area:2627}: kill these as you meet them"] = "{area:2627} : tuez-les au fil de vos rencontres",
		["{item:12565}, at the Jadefire moonwell"] = "{item:12565}, au puits de lune des Jadefeu",
		["{npc:10306}: the owlbeasts are in {zone:1452}"] = "{npc:10306} : les chouettards sont à {zone:1452}",
		["{npc:11016}, below ground"] = "{npc:11016}, sous terre",
		["{npc:11020}, below ground"] = "{npc:11020}, sous terre",
		["{npc:11554}, at the south edge of the camp"] = "{npc:11554}, à la lisière sud du camp",
		["{npc:11557}: keep 30 {quest:6031} for him; he trades only at Neutral with the Timbermaw; below ground"] = "{npc:11557} : gardez 30 {quest:6031} pour lui ; il n'échange qu'à partir de Neutre auprès des Grumegueules ; sous terre",
		["{npc:11558}: the Timbermaw speak to you only from Neutral; walks around here: look inside the circle on the map"] = "{npc:11558} : les Grumegueules ne vous parlent qu'à partir de Neutre ; patrouille par ici : regardez dans le cercle sur la carte",
		["{npc:1855}'s hunts are in the {zone:1423}: keep them for later."] = "Les chasses de {npc:1855} se font dans les {zone:1423} : gardez-les pour plus tard.",
		["{npc:3034} in {zone:1412}; {zone:1454} has no druid trainer"] = "{npc:3034} ({zone:1412}) ; {zone:1454} n'a pas de maître des druides",
		["{npc:8659} takes the ravasaur claws from Un'Goro; he stands in the {object:172960}, a short walk from the middle of the city."] = "{npc:8659} prend les griffes de ravasaure d'Un'Goro ; il se tient dans {object:172960}, à courte distance du centre de la ville.",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}, {object:172960}",
		["{npc:9529}, on the west side of the Sanctuary"] = "{npc:9529}, à l'ouest du Sanctuaire",
		["{npc:9529}, on the west side of the camp"] = "{npc:9529}, à l'ouest du camp",
		["{npc:9996}'s kitten"] = "Le chaton de {npc:9996}",
		["{quest:5408}: the {area:2627} undead drop them while you wear the {item:12846}"] = "{quest:5408} : les morts-vivants de {area:2627} les laissent tomber tant que vous portez la {item:12846}",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
} end)()
t.guides["forever/horde/50-60/03-winterspring"] = (function() return {
		["Back south to {npc:7775}. Keep the elixir and don't drink it yet: it kills you, and that is how you meet Gaeriyan by {area:976} later."] = "Retournez au sud voir {npc:7775}. Gardez l'élixir et ne le buvez pas encore : il vous tue, et c'est ainsi que vous rencontrerez Gaeriyan près de {area:976} plus tard.",
		["Below ground"] = "Sous terre",
		["Both {item:14047} donations are handed in later in the route: save sixty {item:14047} for each if you want them."] = "Les deux dons d'{item:14047} se rendent plus loin dans le parcours : gardez soixante {item:14047} pour chacun si vous les voulez.",
		["Chillwind chimaeras"] = "Chimères Frisevent",
		["Fly to {area:1099}"] = "Volez jusqu'au {area:1099}",
		["Fly to {area:1637}"] = "Volez jusqu'à {area:1637}",
		["Fly to {area:1638}"] = "Volez jusqu'à {area:1638}",
		["Gregor's quests lead to other zones: keep them."] = "Les quêtes de Gregor mènent à d'autres zones : gardez-les.",
		["Ice Thistle yetis"] = "Yétis Chardon de glace",
		["In the {object:172958}."] = "Dans {object:172958}.",
		["In the {object:172961}. Each donation takes sixty Wool, Silk or Mageweave from your bags: hand in what you carry, skip the rest."] = "Dans {object:172961}. Chaque don prend soixante étoffes de laine, de soie ou de tisse-mage dans vos sacs : rendez celles que vous avez sur vous, ignorez les autres.",
		["Into {zone:1452}"] = "Vers {zone:1452}",
		["Level 55.04"] = "Niveau 55.04",
		["Linken's letter"] = "La lettre de Linken",
		["Matriarchs and Patriarchs hit hard: pull them one at a time."] = "Les Matriarches et Patriarches frappent fort : attirez-les un par un.",
		["Pathfinders, Den Watchers and Totemics share the furbolg camps around the hot springs; Ragged Owlbeasts roam the slopes between them. Kill Totemics first. Save every {item:14047} you loot for Meilosh."] = "Guides, Protecteurs et Totémiques se partagent les camps de furbolgs autour des sources chaudes ; des Chouettards éreintés parcourent les pentes entre eux. Tuez d'abord les Totémiques. Gardez chaque {item:14047} ramassée pour Meilosh.",
		["Pristine Yeti Horns"] = "Cornes de yéti en parfait état ({item:12367})",
		["Raging Owlbeasts"] = "Chouettards enragés ({npc:7451})",
		["The chimaeras roam the snowfields south and west of {area:2255}. Stay clear of {area:2245}'s cave: its blue dragonkin are elite."] = "Les chimères parcourent les champs de neige au sud et à l'ouest de {area:2255}. Évitez la grotte de {area:2245} : ses draconiens bleus sont élites.",
		["The furbolg village fills the valley north-east of {area:2255}. Kill Shamans first; they heal. {npc:10738} in the cave at the back is elite: stay out."] = "Le village furbolg occupe la vallée au nord-est de {area:2255}. Tuez d'abord les Chamans ; ils soignent. {npc:10738}, dans la grotte du fond, est un élite : n'y allez pas.",
		["The yeti hills start just south-east of {area:2255}. Every yeti drops fur; only Matriarchs and Patriarchs drop horns, so keep those for after the turn-in."] = "Les collines des yétis commencent juste au sud-est de {area:2255}. Chaque yéti lâche de la fourrure ; seuls les Matriarches et Patriarches lâchent des cornes, gardez donc celles-ci pour après la remise de quête.",
		["The {item:11242} grows inside a ruined building north of {npc:7775}'s camp, east of the harpies' {area:1114}: climb in through the broken part of its wall."] = "La {item:11242} pousse dans un bâtiment en ruine au nord du camp de {npc:7775}, à l'est de {area:1114} des harpies : entrez par la partie effondrée de son mur.",
		["Umi's third prank targets goblins in {area:976} and Un'Goro: keep it for later."] = "La troisième farce d'Umi vise les gobelins de {area:976} et d'Un'Goro : gardez-la pour plus tard.",
		["grind on {npc:7460}"] = "tuez en boucle : {npc:7460}",
		["{area:2246}: kill these as you meet them"] = "{area:2246} : tuez-les au passage",
		["{area:2255} flight master"] = "Maître de vol de {area:2255}",
		["{area:2408} flight master"] = "Maître de vol de {area:2408}",
		["{item:11243}, {npc:7775}'s reward"] = "{item:11243}, récompense de {npc:7775}",
		["{npc:10431}, inside"] = "{npc:10431}, à l'intérieur",
		["{npc:3033} on {area:1639}; {npc:246344}"] = "{npc:3033} sur la {area:1639} ; {npc:246344}",
		["{quest:1123} waits in {zone:1450}: keep it for later."] = "{quest:1123} attend à {zone:1450} : gardez-la pour plus tard.",
		["{quest:3909} comes from {npc:7775} in {zone:1444}, later in this guide."] = "{quest:3909} vient de {npc:7775} en {zone:1444}, plus loin dans ce guide.",
		["{quest:5084} is turned in at the {object:176091} in {zone:1448}, on a later trip."] = "{quest:5084} se rend au {object:176091} en {zone:1448}, lors d'un voyage ultérieur.",
		["{quest:8471}, a rare drop from the Winterfall furbolgs"] = "{quest:8471}, un butin rare des furbolgs Tombe-hiver",
		["{zone:1456} flight master"] = "Maître de vol : {zone:1456}",
} end)()
t.guides["forever/horde/50-60/04-azshara"] = (function() return {
		["Cleansed Water goes to the {area:2479} in {zone:1448}: keep it for later."] = "L'eau purifiée retourne à {area:2479}, à {zone:1448} : gardez-la pour plus tard.",
		["Fly to {area:1237}"] = "Prendre un vol pour {area:1237}",
		["Fly to {area:1637}"] = "Prendre un vol pour {area:1637}",
		["Fly to {area:392}"] = "Prendre un vol pour {area:392}",
		["Fly to {zone:1454} and train."] = "Volez jusqu'à {zone:1454} et entraînez-vous.",
		["Fly to {zone:1454}; {npc:4485} is in the {object:172958}."] = "Volez jusqu'à {zone:1454} ; {npc:4485} se trouve dans {object:172958}.",
		["Inside"] = "À l'intérieur",
		["Into {zone:1411}"] = "Vers {zone:1411}",
		["Lady Sylvanas holds the {object:36126}."] = "Dame Sylvanas se tient dans {object:36126}.",
		["Liv's workshop is at the north end of {area:392}'s docks; {object:149036} stands inside it."] = "L'atelier de Liv Rizzlefix se trouve au bout nord des quais de {area:392} ; le {object:149036} est à l'intérieur.",
		["Only with {quest:79095} from {area:159}'s alchemy shop in your bags (the Library Books guide)"] = "Seulement avec {quest:79095} de la boutique d'alchimie de {area:159} dans vos sacs (le guide des Livres de la bibliothèque)",
		["Paladin trainer"] = "Maître des paladins",
		["Ride back west to {area:1237}."] = "Retournez à l'ouest jusqu'à {area:1237}.",
		["Ride east to the ruins on the coast. Fill Cuely's four vials at the tide pools along the shore; Spitelash naga patrol between them."] = "Allez à l'est jusqu'aux ruines sur la côte. Remplissez les quatre fioles du Chimiste Cuely aux bassins le long du rivage ; des nagas Fouette-bile patrouillent entre eux.",
		["Rimtori's camp is at the east end of the base camp. Read the {object:151286} there, then kill the Magus.\nCareful: Which crystal is linked to Rimtori is random. Each of the other two summons a hostile infernal instead."] = "Le camp de Rimtori se trouve à l'extrémité est du camp de base. Lisez le {object:151286} sur place, puis tuez le magus.\nAttention : le cristal lié à Rimtori est choisi au hasard. Chacun des deux autres invoque à la place un infernal hostile.",
		["The blood elves camp on the cliffs in the north-east, by the {area:1227}."] = "Les elfes de sang campent sur les falaises au nord-est, près de {area:1227}.",
		["Upstairs"] = "À l'étage",
		["Zeppelin to {zone:1458}"] = "Zeppelin pour {zone:1458}",
		["{area:1237} flight master"] = "Maître de vol de {area:1237}",
		["{npc:10778}'s farm is the first one east of the {area:152}. Jabbering Ghouls on the farm carry the other half of her charm; {npc:11075} guards the cauldron in the field.\nCareful: One or two undead usually fight alongside him, and more cauldron lords can attack after you use the cauldron."] = "La ferme de {npc:10778} est la première à l'est de {area:152}. Les Goules jacassantes de la ferme portent l'autre moitié de son porte-bonheur ; {npc:11075} garde le chaudron dans le champ.\nAttention : un ou deux morts-vivants combattent généralement à ses côtés, et d'autres seigneurs du chaudron peuvent attaquer après que vous avez utilisé le chaudron.",
		["{npc:15188}, {object:172957}: keep it for {zone:1451}"] = "{npc:15188}, {object:172957} : gardez-la pour {zone:1451}",
		["{npc:246344} in {zone:1456}; {zone:1454} has no paladin trainer"] = "{npc:246344} ({zone:1456}) ; {zone:1454} n'a pas de maître des paladins",
		["{npc:256386}'s crates"] = "Les caisses de {npc:256386}",
		["{npc:5901} camps on the shore just north of {area:392}."] = "{npc:5901} Waterseer campe sur le rivage, juste au nord de {area:392}.",
		["{npc:8393}, beside him"] = "{npc:8393}, à côté de lui",
		["{npc:8403}, nearby"] = "{npc:8403}, tout près",
		["{npc:8578}'s camp"] = "Le camp de {npc:8578}",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}, {object:172960}",
		["{quest:5050} goes back to {npc:10778} in the {zone:1422}: keep it."] = "{quest:5050} se rend à {npc:10778}, dans {zone:1422} : gardez-la.",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
} end)()
t.guides["forever/horde/50-60/05-eastern-plaguelands"] = (function() return {
		["Back through the tunnel and take the {zone:1452} exit, then ride south to {area:2246}."] = "Repassez par le tunnel et prenez la sortie vers {zone:1452}, puis allez au sud jusqu'à {area:2246}.",
		["Back to {area:2268}"] = "Retour à {area:2268}",
		["Below ground"] = "Sous terre",
		["Both quests lead to {zone:1451}: keep them."] = "Les deux quêtes mènent à {zone:1451} : gardez-les.",
		["Careful: {npc:10411} goes invisible when out of combat and calls Rockwing Gargoyles once a fight starts. Only 3 exist and they respawn every 15 min."] = "Attention : {npc:10411} devient invisible hors combat et appelle des Gargouilles aile-de-roc dès qu'un combat commence. Il n'en existe que 3 et elles réapparaissent toutes les 15 min.",
		["Class trainer"] = "Maître de classe",
		["Drink the {item:11243} at the graveyard just east of {area:976}: it kills you, and only as a ghost can you see {npc:9299}, in a rocky crevice in the hills due north of it. Talk to him there, then run back to your body and resurrect: the Conspicuous Gravestone he sends you to stands in that graveyard."] = "Buvez l'{item:11243} au cimetière juste à l'est de {area:976} : il vous tue, et ce n'est que sous forme de fantôme que vous pouvez voir {npc:9299}, dans une crevasse rocheuse des collines plein nord. Parlez-lui là-bas, puis retournez à votre corps et ressuscitez : la Pierre tombale remarquable où il vous envoie se trouve dans ce cimetière.",
		["Fly to {area:1497}"] = "Prendre un vol pour {area:1497}",
		["Fly to {area:1638}"] = "Prendre un vol pour {area:1638}",
		["Fly to {area:1997}"] = "Prendre un vol pour {area:1997}",
		["Fly to {area:2268}"] = "Prendre un vol pour {area:2268}",
		["Fly to {area:272}"] = "Prendre un vol pour {area:272}",
		["Fly to {area:541}"] = "Prendre un vol pour {area:541}",
		["Fly to {area:976}"] = "Prendre un vol pour {area:976}",
		["Follow the road east from the {zone:1422}, over the river and across the whole {zone:1423}, to the {object:92525}'s chapel in the far east."] = "Suivez la route vers l'est depuis {zone:1422}, franchissez la rivière et traversez tout {zone:1423} jusqu'à la chapelle de {object:92525}, à l'extrême est.",
		["Free Darrowshire Spirits: talk to them"] = "Libérez les Esprits de Darrowshire : parlez-leur",
		["Frenzied Plaguehounds and Monstrous Plaguebats share the fields around {area:2272} and {area:2271}, south of {area:2273}."] = "Les Chiens pestiférés frénétiques et les Chauves-souris pestiférées monstrueuses se partagent les champs autour de {area:2272} et de {area:2271}, au sud de {area:2273}.",
		["Go through {area:1769} and take the {zone:1450} branch of the tunnel. {npc:11801} is in {area:2361}."] = "Traversez {area:1769} et prenez l'embranchement du tunnel vers {zone:1450}. {npc:11801} Saturna se trouve à {area:2361}.",
		["Inside"] = "À l'intérieur",
		["Keep {quest:5152}: {npc:10927} lives at {area:197} in the {zone:1422}."] = "Gardez {quest:5152} : {npc:10927} habite à {area:197}, dans {zone:1422}.",
		["Moontouched Owlbeasts"] = "Chouettards lunaires",
		["Only if a {quest:8471} dropped for you: {npc:11558} waits at the {zone:1448} entrance of {area:1769}, and speaks to you only at Neutral with the Timbermaw."] = "Seulement si l'objet de la quête {quest:8471} est tombé pour vous : {npc:11558} attend à l'entrée de {area:1769} côté {zone:1448}, et ne vous parle qu'au niveau Neutre auprès des Grumegueules.",
		["Plaguehound Runts and Plaguebats roam the hills north of the {area:2260}, Carrion Grubs crawl among them; work north toward {area:2627}."] = "Les Chiens pestiférés chétifs et les Chauves-souris pestiférées parcourent les collines au nord de {area:2260}, et des Larves putrides rampent parmi eux ; progressez vers le nord en direction de {area:2627}.",
		["Ride back south to {area:272} and fly to {area:2268}."] = "Redescendez vers le sud jusqu'à {area:272} et prenez un vol pour {area:2268}.",
		["Ride east to {area:2255} and north out of it; the Moontouched Owlbeasts roam the hills of {area:2241}'s southern slopes. Pull them one at a time."] = "Allez à l'est jusqu'à {area:2255} et sortez-en par le nord ; les Chouettards lunaires rôdent dans les collines des pentes sud de {area:2241}. Attirez-les un par un.",
		["Ride north up the road from {area:272}. {npc:10927}'s house stands by the road at {area:197}, and {npc:10936}'s monument is in the graveyard behind it."] = "Remontez la route vers le nord depuis {area:272}. La maison de {npc:10927} se trouve au bord de la route à {area:197}, et le monument de {npc:10936} est dans le cimetière derrière.",
		["Ride north-west into Andorhal. {npc:10667} waits in the ruined inn on the west side of town; the skeletons inside are 54-57, so keep to the edges."] = "Allez au nord-ouest jusqu'à Andorhal. {npc:10667} attend dans l'auberge en ruine, à l'ouest de la ville ; les squelettes à l'intérieur sont de niveau 54-57, restez donc sur les bords.",
		["Ride south from the lodge to {area:2264}, on the road. {item:15447} spoils within ten minutes: kill the town's Scourge quickly and grind the seven pieces with the {item:15454} at once.\nCareful: Unseen Servants call for help within 25 yd once they drop to 40% health. Out of combat they also turn invisible with {spell:10228}. If a call for help happens inside the town, a large number of mobs can join the fight. Fighting near the outskirts lowers this risk.\nWith {quest:5211} in your log (from {npc:11063} at the start of this guide), the Scourge around the town leave Darrowshire Spirits: talk to each one to free it. Free them before you start on the {item:15447}."] = "Depuis le pavillon, allez au sud par la route jusqu'à {area:2264}. {item:15447} se gâte en dix minutes : tuez vite le Fléau de la ville et broyez aussitôt les sept morceaux avec {item:15454}.\nAttention : les Serviteurs invisibles appellent à l'aide à moins de 25 m dès qu'ils tombent à 40 % de vie. Hors combat, ils deviennent aussi invisibles avec {spell:10228}. Si un appel à l'aide a lieu dans la ville, un grand nombre de monstres peut rejoindre le combat. Combattre en périphérie réduit ce risque.\nSi vous avez {quest:5211} dans votre journal (donnée par {npc:11063} au début de ce guide), le Fléau autour de la ville laisse des Esprits de Darrowshire : parlez à chacun pour le libérer. Libérez-les avant de commencer à récolter {item:15447}.",
		["Ride west to the {area:2260}."] = "Allez à l'ouest jusqu'à {area:2260}.",
		["Scare {npc:7583} with {item:12928}"] = "Effrayez {npc:7583} avec {item:12928}",
		["The Annals lie among the Musty Tomes in Andorhal's town hall; open them until you find the right one."] = "Les Annales se trouvent parmi les Tomes moisis de l'hôtel de ville d'Andorhal ; ouvrez-les jusqu'à trouver le bon.",
		["The doll's head and its two sides lie in the houses around {npc:10926}; join them from your bags."] = "La tête de la poupée et ses deux côtés se trouvent dans les maisons autour de {npc:10926} ; assemblez-les depuis vos sacs.",
		["The high elf Rangers, Pathstriders and Woodsmen guard the lodge by {area:2275}; the Registry lies inside. Rangers reach 60: pull one at a time. Noxious Plaguebats fly over the fields on the way.\nThe skull sits in the {area:2622}, among Blighted Horrors and Plague Monstrosities."] = "Les Forestiers, Éclaireurs et Bûcherons hauts-elfes gardent le pavillon près de {area:2275} ; le registre se trouve à l'intérieur. Les Forestiers montent jusqu'au niveau 60 : attirez-les un par un. Des Chauves-souris pestiférées nuisibles survolent les champs en chemin.\nLe crâne se trouve dans {area:2622}, parmi les Horreurs corrompues et les Monstruosités de la peste.",
		["The pass from Un'Goro comes out at {area:3077}, the graveyard in north-east {zone:1451}. {npc:13220} stands among the graves."] = "Le col venant d'Un'Goro débouche sur {area:3077}, le cimetière du nord-est de {zone:1451}. {npc:13220} se tient parmi les tombes.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:11897} is a level 60 elite: most classes solo it at level 62, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:11897} est un élite de niveau 60 : la plupart des classes en viennent à bout seules au niveau 62, mais vous aurez peut-être besoin d'aide. Passez-le si vous êtes seul : le parcours vous fait regagner cette expérience en tuant des monstres.",
		["To {area:197}"] = "Vers {area:197}",
		["Underwater"] = "Sous l'eau",
		["Upstairs"] = "À l'étage",
		["Use {item:12928} on {npc:7583}, the goblin girl in {area:976}. {npc:10977} and {npc:10978} are scared later in the route."] = "Utilisez {item:12928} sur {npc:7583}, la petite gobeline de {area:976}. {npc:10977} et {npc:10978} seront effrayés plus loin dans le parcours.",
		["Zaeldarr lurks just west of {area:2262}."] = "Zaeldarr rôde juste à l'ouest de {area:2262}.",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["a message for {npc:11063} at {area:2268}"] = "un message pour {npc:11063} à {area:2268}",
		["{area:2255} flight master"] = "Maître de vol de {area:2255}",
		["{area:2268} flight master"] = "Maître de vol de {area:2268}",
		["{area:2277}: kill these as you meet them"] = "{area:2277} : tuez-les au passage",
		["{area:272} flight master"] = "Maître de vol de {area:272}",
		["{area:976} flight master"] = "Maître de vol de {area:976}",
		["{npc:10926}'s ghost stands in the ruins of {area:2262}, in the south-west."] = "Le fantôme de {npc:10926} se tient dans les ruines de {area:2262}, au sud-ouest.",
		["{npc:10927}, upstairs"] = "{npc:10927}, à l'étage",
		["{npc:11140} the ghost stands by a hut in {area:2627}, in the north-west corner."] = "Le fantôme {npc:11140} se tient près d'une cabane à {area:2627}, dans le coin nord-ouest.",
		["{npc:11558} walks around here: look inside the circle on the map"] = "{npc:11558} se promène par ici : cherchez dans le cercle sur la carte",
		["{npc:15193}'s champion holds the {area:2260} farmhouse, north of the {area:2261}."] = "Le champion de {npc:15193} occupe la ferme de {area:2260}, au nord de {area:2261}.",
		["{npc:3033} on {area:1639}; {npc:246344}"] = "{npc:3033} sur {area:1639} ; {npc:246344}",
		["{npc:7771} camps by the {area:1336} road, south of {area:976}."] = "{npc:7771} Rivetseeker campe près de la route de {area:1336}, au sud de {area:976}.",
		["{npc:8565} walks around {area:2276}: look inside the circle on the map"] = "{npc:8565} se promène autour de {area:2276} : cherchez dans le cercle sur la carte",
		["{quest:3914} goes back to {npc:8737} in Un'Goro: keep it."] = "{quest:3914} se rend à {npc:8737}, dans le Cratère d'Un'Goro : gardez-la.",
		["{quest:5168}'s items lie in the later Plaguelands zones: keep it."] = "Les objets de {quest:5168} se trouvent dans les zones des Maleterres visitées plus tard : gardez-la.",
		["{quest:5211}'s spirits come with the {area:2264} stop later in this guide: keep it."] = "Les esprits de {quest:5211} viennent avec l'étape de {area:2264}, plus loin dans ce guide : gardez-la.",
		["{zone:1423}: kill these as you meet them"] = "{zone:1423} : tuez-les au passage",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
		["{zone:1456} flight master"] = "Maître de vol : {zone:1456}",
} end)()
t.guides["forever/horde/50-60/06-silithus"] = (function() return {
		["A torn scroll lies at the entrance of the {area:2261}, the crypt south of the {area:2260}."] = "Un parchemin déchiré se trouve à l'entrée de {area:2261}, la crypte au sud de {area:2260}.",
		["Andorhal watchtowers and silos"] = "Tours de guet et silos d'Andorhal",
		["Back to Southwind and climb the tower. Stirring the hive at the top brings out Hive'Ashi Ambushers; one carries the {item:17346}."] = "Retournez à Sudevent et montez dans la tour. Remuer la ruche au sommet fait sortir des Embusquées de la Ruche'Ashi ({npc:13301}) ; l'une porte {item:17346}.",
		["Back to {area:3425}"] = "Retour au {area:3425}",
		["Below ground"] = "Sous terre",
		["Careful: Un'Goro Gorillas (level 50-51) call for help from allies within 20 yd once they drop to 25% health. There is a cave full of apes in the area, and fighting there brings many adds."] = "Attention : les Gorilles d'Un'Goro (niveau 50-51) appellent à l'aide leurs alliés à moins de 20 m dès qu'ils tombent à 25 % de vie. Une grotte pleine de singes se trouve dans le coin, et y combattre attire de nombreux renforts.",
		["Class trainer"] = "Maître de classe",
		["Dredge Crushers and Pincers"] = "Écraseurs térébrants et Pinceurs",
		["Dredge Strikers, Stonelash Scorpids and Sand Skitterers share the sands just north of the hold."] = "Frappeurs térébrants, Scorpides Cinglepierre et Glisseuses du sable se partagent les sables juste au nord du fort.",
		["East along the road, {npc:11077} guards the cauldron at {area:200}."] = "Plus à l'est sur la route, {npc:11077} garde le chaudron des {area:200}.",
		["Escort {npc:9999}"] = "Escortez {npc:9999}",
		["Flayers and Rock Stalkers"] = "Écorcheurs et Traqueuses des rochers",
		["Fly to {area:1637}"] = "Prendre un vol pour {area:1637}",
		["Fly to {area:976}. Still carrying {quest:2741}? The machine stands in the middle of town."] = "Volez jusqu'à {area:976}. Vous avez toujours {quest:2741} ? La machine se dresse au milieu de la ville.",
		["Hameya hides among the Mossflayer trolls of {area:2273}, in the north-east corner.\nCareful: The trolls along the path to {area:2273} are level 57-59. They run away at low health and call for help, so they often bring adds with them."] = "Hameya se cache parmi les trolls Mossflayer de {area:2273}, dans le coin nord-est.\nAttention : les trolls le long du chemin vers {area:2273} sont de niveau 57-59. Ils s'enfuient quand leur vie est basse et appellent à l'aide, ils ramènent donc souvent des renforts.",
		["Hameya's mound"] = "Le monticule d'Hameya",
		["Hameya's scroll"] = "Le parchemin d'Hameya",
		["Head north along the western dunes; Dredge Crushers and Stonelash Pincers range from here back toward the hold."] = "Remontez vers le nord le long des dunes de l'ouest ; les Ecraseurs térébrants et les Pinceurs Cinglepierre rôdent d'ici jusqu'au fort.",
		["Inside"] = "À l'intérieur",
		["Into {zone:1422}"] = "Vers {zone:1422}",
		["Into {zone:1423}"] = "Vers {zone:1423}",
		["Keep the bait: {npc:9684} is level 56, and the second loop passes his lair."] = "Gardez l'appât : {npc:9684} est de niveau 56, et la deuxième boucle passe par son repaire.",
		["Keep {quest:3942}: {npc:9116} is at the {area:2479}, on the next guide's way through {zone:1448}."] = "Gardez {quest:3942} : {npc:9116} se trouve au {area:2479}, sur le chemin du guide suivant à travers {zone:1448}.",
		["Lead {npc:9999} north to {area:541}. When he faints, use {item:11804} on him to wake him."] = "Menez {npc:9999} vers le nord jusqu'au {area:541}. Quand il s'évanouit, utilisez {item:11804} sur lui pour le réveiller.",
		["Level 59.14"] = "Niveau 59.14",
		["Mark {npc:10902} with the {item:12815}"] = "Marquez {npc:10902} avec {item:12815}",
		["Mark {npc:10903} with the {item:12815}"] = "Marquez {npc:10903} avec {item:12815}",
		["Mark {npc:10904} with the {item:12815}"] = "Marquez {npc:10904} avec {item:12815}",
		["Mark {npc:10905} with the {item:12815}"] = "Marquez {npc:10905} avec {item:12815}",
		["Paladin trainer"] = "Maître des paladins",
		["Pamela and the {area:2261}"] = "Pamela et {area:2261}",
		["Radley and Durgen"] = "Radley et Durgen",
		["Ride east to {area:537}, climb it and use {npc:10541} at the lava vent near the top, then ride back west to {npc:10302}."] = "Chevauchez vers l'est jusqu'à {area:537}, grimpez-y et utilisez {npc:10541} sur la cheminée de lave près du sommet, puis revenez vers l'ouest jusqu'à {npc:10302}.",
		["Ride east to {npc:1855}'s hut by the {area:2619} and hear him out."] = "Allez vers l'est jusqu'à la cabane de {npc:1855}, au bord de {area:2619}, et écoutez-le.",
		["Ride north-east to {area:3077}; you leave {zone:1451} through the pass beside it."] = "Allez vers le nord-est jusqu'au cimetière ({area:3077}) ; vous quittez {zone:1451} par le col tout proche.",
		["Ride north-east to {area:3447}."] = "Allez vers le nord-est jusqu'à {area:3447}.",
		["Ride north-west to {npc:1855}'s hut."] = "Allez vers le nord-ouest jusqu'à la cabane de {npc:1855}.",
		["Ride south into Andorhal. {npc:10667} waits in the ruined inn on the west side of town. Stand in the doorway of each of the four towers with the {item:12815} to mark it; keep to the edges of town. Use the {item:12627} by the silos in the middle of town to bring out Temporal Parasites."] = "Allez vers le sud jusqu'à Andorhal. {npc:10667} attend dans l'auberge en ruine à l'ouest de la ville. Placez-vous sur le seuil de chacune des quatre tours avec {item:12815} pour la marquer ; restez en bordure de la ville. Utilisez {item:12627} près des silos au centre de la ville pour faire apparaître des Parasites temporels.",
		["Ride south-east to {area:3447} under the Un'Goro cliffs."] = "Allez vers le sud-est jusqu'à {area:3447}, au pied des falaises d'Un'Goro.",
		["Ride south-west to {npc:10667} in Andorhal."] = "Allez vers le sud-ouest jusqu'à {npc:10667}, à Andorhal.",
		["Ride to {area:2262} in the south-west; Pamela plays among the houses. {npc:11886} lurks in the {area:2261}, the crypt just west of the town.\nCareful: About four non-elite adds come with Mercutio. They walk to the grave instead of appearing on the spot."] = "Chevauchez jusqu'à {area:2262}, au sud-ouest ; Pamela joue entre les maisons. {npc:11886} rôde dans {area:2261}, la crypte juste à l'ouest de la ville.\nAttention : environ quatre renforts non élites arrivent avec Mercutio. Ils marchent jusqu'à la tombe au lieu d'apparaître sur place.",
		["Ride west to the Horde camp north of {area:2744}."] = "Allez vers l'ouest jusqu'au camp de la Horde au nord de la {area:2744}.",
		["Scourge Champions"] = "Champions du Fléau",
		["Scourge Champions roam the {area:2270}, north of the chapel. Pass {npc:11063}'s {item:13156} over each one you kill: the skulls that resonate are the ones he wants."] = "Les Champions du Fléau parcourent {area:2270}, au nord de la chapelle. Passez {item:13156} de {npc:11063} sur chacun de ceux que vous tuez : les crânes qui résonnent sont ceux qu'il veut.",
		["Silithyst geysers erupt across the southern desert. Walk into the Silithyst one leaves behind and carry it to the Horde's Silithyst Extractor at Kirika's camp; fighting or mounting drops it."] = "Des Geysers de silithyste jaillissent dans le désert du sud. Marchez dans le silithyste qu'ils laissent et portez-le à l'extracteur de silithyste de la Horde, au camp de Kirika ; combattre ou monter en selle vous le fait lâcher.",
		["Stonelash Flayers and Rock Stalkers roam the dunes south-west of Kirika's camp."] = "Les Ecorcheurs Cinglepierre et les Traqueuses des rochers parcourent les dunes au sud-ouest du camp de Kirika.",
		["The glowing tablet fragments lie around the Twilight camp in the far north-west; the Dust Stormers and Desert Rumblers there drop them too."] = "Les fragments de tablette luisants se trouvent autour du camp du Crépuscule, tout au nord-ouest ; les Tempétueux de poussière et Grondeurs du désert du coin en lâchent aussi.",
		["The libram lies further north, on the way to {area:190}."] = "Le libram se trouve plus au nord, sur la route de {area:190}.",
		["The satchel lies in the mountains of the far south, past Bronzebeard's Encampment. Deathclasp, an elite scorpid, patrols near it: grab it while he is away."] = "La sacoche se trouve dans les montagnes de l'extrême sud, au-delà du Campement de Bronzebeard. Poigne-de-mort, un scorpide élite, patrouille à proximité : prenez-la pendant qu'il s'éloigne.",
		["The shield lies at {area:201}, south of {npc:1855}'s hut."] = "Le bouclier se trouve à {area:201}, au sud de la cabane de {npc:1855}.",
		["The spare texts from the cultists"] = "Les textes en trop des cultistes",
		["Twilight Vanguard"] = "Avant-garde du Crépuscule",
		["Underwater"] = "Sous l'eau",
		["Upstairs"] = "À l'étage",
		["Use {npc:10980} on {npc:10977}"] = "Utilisez {npc:10980} sur {npc:10977}",
		["Zeppelin to {zone:1458}"] = "Zeppelin pour {zone:1458}",
		["grind on {npc:10717}"] = "tuez en boucle : {npc:10717}",
		["{area:190}'s Scarlets are level 58-60. Ride in to the high point marked on your map, look over the town, and get out.\nCareful: Sentinels posted at the gate can detect stealthed players. Additional sentinels are found within the town, and an elite walks a patrol route nearby."] = "Les Écarlates de {area:190} sont de niveau 58-60. Entrez jusqu'au point haut marqué sur votre carte, observez la ville, puis repartez.\nAttention : les sentinelles postées à la porte peuvent détecter les joueurs camouflés. D'autres sentinelles se trouvent dans la ville, et un élite patrouille à proximité.",
		["{area:976} flight master"] = "Maître de vol de {area:976}",
		["{npc:10302} sends you to {npc:9298} in {zone:1452}: keep it."] = "{npc:10302} vous envoie voir {npc:9298} au {zone:1452} : gardez-la.",
		["{npc:10302} the goblin sits at {area:543}, just east of the pylon."] = "Le gobelin {npc:10302} est assis à {area:543}, juste à l'est du pylône.",
		["{npc:10667}'s Battle of Darrowshire ends against elites. Skip it."] = "La bataille de Comté-de-Darrow, quête de {npc:10667}, se termine contre des élites. Passez-la.",
		["{npc:10667}, upstairs"] = "{npc:10667}, à l'étage",
		["{npc:11613} stands east of the lumber camp; {npc:11611} guards the road north-east of {npc:11610}, toward {area:190}.\nCareful: Guards stand at the tower's base and one more circles it on patrol. Clear them before you engage Durgen so they don't join the fight."] = "{npc:11613} se tient à l'est du camp de bûcherons ; {npc:11611} garde la route au nord-est de {npc:11610}, en direction de {area:190}.\nAttention : des gardes se tiennent au pied de la tour et un autre en fait le tour en patrouille. Éliminez-les avant d'engager Durgen pour qu'ils ne rejoignent pas le combat.",
		["{npc:11741} walks around {area:2738}: look inside the circle on the map"] = "{npc:11741} se promène autour de {area:2738} : cherchez dans le cercle sur la carte",
		["{npc:15200} holds the camp in the west."] = "{npc:15200} tient le camp de l'ouest.",
		["{npc:15306}, on the west side of the Hold"] = "{npc:15306}, du côté ouest du fort",
		["{npc:246344} in {zone:1456}; {zone:1454} has no paladin trainer"] = "{npc:246344} ({zone:1456}) ; {zone:1454} n'a pas de maître des paladins",
		["{npc:9117}, below ground"] = "{npc:9117}, sous terre",
		["{npc:9619} now asks for {npc:9622}'s pelt, back in the north-east cave: skip it."] = "{npc:9619} demande maintenant la peau d'{npc:9622}, dans la grotte du nord-est : passez-la.",
		["{npc:9684}'s lair is just south of the pylon. Use {npc:9619}'s bait there; {npc:9684} is level 56 and hits hard, so start at full health."] = "Le repaire de {npc:9684} est juste au sud du pylône. Utilisez-y l'appât de {npc:9619} ; {npc:9684} est de niveau 56 et frappe fort, commencez donc avec toute votre vie.",
		["{npc:9999} sits on the ridge, lost and exhausted."] = "{npc:9999} est assis sur la crête, perdu et épuisé.",
		["{zone:1449}: kill these as you meet them"] = "{zone:1449} : tuez-les au passage",
		["{zone:1451}: kill these as you meet them"] = "{zone:1451} : tuez-les au passage",
} end)()
t.guides["forever/horde/50-60/07-felwood"] = (function() return {
		["Any Winterfall furbolg can carry the beads; the camps just south of {npc:11556} are the closest."] = "N'importe quel furbolg Tombe-hiver peut porter les perles ; les camps juste au sud de {npc:11556} sont les plus proches.",
		["Back into the Timbermaw tunnel and take the {zone:1452} exit; {npc:9298} camps by the hot springs just outside."] = "Retournez dans le tunnel des Grumegueules et prenez la sortie de {zone:1452} ; {npc:9298} campe près des sources chaudes juste dehors.",
		["Back south to the Sanctuary, a short ride."] = "Retournez au sud au Sanctuaire d'émeraude, un court trajet.",
		["Below ground"] = "Sous terre",
		["Class trainer"] = "Maître de classe",
		["Corrupted Soul Shards from the cultists, {quest:5887}"] = "Fragments d'âme corrompus sur les cultistes, {quest:5887}",
		["Dungeon instead of grinding"] = "Donjon au lieu de tuer des monstres",
		["Fly to {area:431}"] = "Prendre un vol pour {area:431}",
		["Fly to {area:431} and ride north-west along the road out of {zone:1440} into {zone:1448}. The {area:2479} is the druids' camp just past the border."] = "Volez jusqu'au {area:431} et suivez la route vers le nord-ouest pour quitter {zone:1440} et entrer dans {zone:1448}. Le camp des druides juste après la frontière est {area:2479}.",
		["From Krakle in Un'Goro"] = "De la part de Krakle, à Un'Goro",
		["Frostfire Winterfall camp"] = "Camp Tombe-hiver des sources chaudes",
		["Grind to 60"] = "Monter au niveau 60",
		["In the {object:172961}."] = "Dans {object:172961}.",
		["In {zone:1454}: fly from {area:2255}"] = "Pour {zone:1454} : volez depuis {area:2255}",
		["In {zone:1456}: fly from {area:2255}"] = "Pour {zone:1456} : volez depuis {area:2255}",
		["Level 59.9"] = "Niveau 59.9",
		["On the way back south to {npc:10922}, {npc:9529} takes the shards on the west side of the Sanctuary."] = "En redescendant au sud vers {npc:10922}, {npc:9529} prend les fragments du côté ouest du Sanctuaire d'émeraude.",
		["Optional. Running {area:2279}, {area:2057}, Lower Blackrock Spire or {area:1584} with a group instead of grinding gets you there faster."] = "Facultatif. Faire {area:2279}, {area:2057}, le bas du Pic Rochenoire ou {area:1584} en groupe au lieu de tuer des monstres vous y amène plus vite.",
		["Optional: with a group, a 55-60 dungeon replaces the grind below."] = "Facultatif : en groupe, un donjon 55-60 remplace l'enchaînement de monstres ci-dessous.",
		["Ride back west to {area:2246}."] = "Revenez vers l'ouest jusqu'à {area:2246}.",
		["Ride east along the road to {area:2255}."] = "Suivez la route vers l'est jusqu'à {area:2255}.",
		["Ride east, then south down {area:2249}. The Frostmaul giants there are elite level 59: keep to the middle and keep moving. The strange source is at the mouth of {area:2256}, at the south end."] = "Chevauchez vers l'est, puis descendez {area:2249} vers le sud. Les géants Cognegivre y sont des élites de niveau 59 : restez au milieu et ne vous arrêtez pas. L'étrange source se trouve à l'entrée de {area:2256}, à l'extrémité sud.",
		["Ride north along the road, past {area:1763}, to {area:1997}."] = "Suivez la route vers le nord, après {area:1763}, jusqu'au {area:1997}.",
		["Ride north-west to {area:1763}. The four braziers stand among the Shadow Council's buildings; use the Cleansed Water on each one.\nCareful: Shadow Council mobs of level 53-55 fill the cave and often come in large linked groups, many with stuns. A group of 2-3 players is recommended."] = "Chevauchez vers le nord-ouest jusqu'à {area:1763}. Les quatre braseros se dressent parmi les bâtiments du Conseil des ombres ; utilisez l'Eau purifiée sur chacun d'eux.\nAttention : des monstres du Conseil des ombres de niveau 53-55 remplissent la grotte et viennent souvent en grands groupes liés, beaucoup avec des étourdissements. Un groupe de 2-3 joueurs est recommandé.",
		["South to the Sanctuary once more."] = "Retournez encore au sud au Sanctuaire d'émeraude.",
		["The quests run out here. Rabid Shardtooths prowl {area:2249} in southern {zone:1452}, south of the road from {area:2255}."] = "Il n'y a plus de quêtes ici. Les Crocs acérés enragés rôdent dans la {area:2249}, au sud de {zone:1452}, au sud de la route depuis {area:2255}.",
		["The {area:2479}"] = "{area:2479}",
		["Through the Timbermaw tunnel to {zone:1450}. {npc:11939} reads in a house in {area:2361}."] = "Traversez le tunnel des Grumegueules jusqu'à {zone:1450}. {npc:11939} lit dans une maison de {area:2361}.",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["grind on {npc:7446} at {area:2249}, {zone:1452}"] = "tuez des {npc:7446} dans la {area:2249}, {zone:1452}",
		["{npc:10306}'s next {quest:4741} would bring you back here from {zone:1452}. Skip it."] = "La quête suivante de {npc:10306}, {quest:4741}, vous ramènerait ici depuis {zone:1452}. Passez-la.",
		["{npc:11558} walks around here: look inside the circle on the map"] = "{npc:11558} se promène par ici : cherchez dans le cercle sur la carte",
		["{npc:11801}'s Shards of the Felvine needs {area:2577}. Skip it."] = "Le Fragment de la Gangrevigne de {npc:11801} demande {area:2577}. Passez-la.",
		["{npc:11939} walks around {area:2361}: look inside the circle on the map"] = "{npc:11939} se promène autour de {area:2361} : cherchez dans le cercle sur la carte",
		["{npc:9116}'s Silver Heart needs an {item:11173} from northern {zone:1448} and a ride back here. Skip it."] = "Le Coeur d'argent d'{npc:9116} demande un {item:11173} du nord de {zone:1448} et un retour ici. Passez-la.",
		["{npc:9116}, inside"] = "{npc:9116}, à l'intérieur",
		["{npc:9298} next sends you after {npc:10738}, an elite in his cave. Skip it."] = "{npc:9298} vous envoie ensuite contre {npc:10738}, un élite dans sa grotte. Passez-la.",
		["{npc:9861}, {npc:9860} and {npc:9517} wait at the back of {area:1770}, the cave in {area:1763}'s north. Clear the tunnel as you go.\nCareful: The three bosses fight as a group. Kill the nearby mobs first so you don't pull extra enemies."] = "{npc:9861}, {npc:9860} et {npc:9517} attendent au fond de {area:1770}, la grotte au nord de {area:1763}. Nettoyez le tunnel en avançant.\nAttention : les trois boss combattent ensemble. Tuez d'abord les monstres proches pour ne pas attirer d'ennemis en plus.",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
} end)()
t.guides["forever/horde/orc/01-durotar"] = (function() return {
		["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "Les Scorpides blindés rampent dans les plaines à l'ouest de {area:362}. Apprivoisez-en un, puis retournez voir {npc:3171}.",
		["Back to the Den"] = "Retour à l'Antre",
		["Back to {area:362}."] = "Retournez à {area:362}.",
		["Back to {zone:1411}"] = "Retour en {zone:1411}",
		["Below ground"] = "Sous terre",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}."] = "Les sectateurs de la Lame ardente tiennent les grottes de {quest:827} ; chacun d'eux peut laisser tomber un {item:4871}. {npc:3204}, un démoniste de niveau 14, se tient au fond et laisse tomber l'{item:4903}.",
		["Class trainer"] = "Maître de classe",
		["Deathskip to Northern Durotar"] = "Mort volontaire jusqu'au nord de Durotar",
		["Deathskip to {area:367}"] = "Mort volontaire jusqu'à {area:367}",
		["Die to the mobs at 52.0,21.4 ({npc:3118}): a death there sends you to this graveyard. Release your spirit and take the {npc:6491}'s resurrection."] = "Laissez-vous tuer par les monstres en 52.0,21.4 ({npc:3118}) : mourir là vous envoie à ce cimetière. Libérez votre esprit et acceptez la résurrection du {npc:6491}.",
		["Die to the mobs at 66.9,87.2 ({npc:3206}): a death there sends you to this graveyard. Release your spirit and take the {npc:6491}'s resurrection."] = "Laissez-vous tuer par les monstres en 66.9,87.2 ({npc:3206}) : mourir là vous envoie à ce cimetière. Libérez votre esprit et acceptez la résurrection du {npc:6491}.",
		["Druid trainer"] = "Maître des druides",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "Les Traqueurs corrompus parcourent la pente sous la grotte, du côté nord de la vallée.",
		["Free {npc:275811} and see her safely out of the crag"] = "Libérez {npc:275811} et escortez-la hors de la Combe",
		["Head north-east to the road toward {zone:1454}. {npc:3293} camps beside it; the stolen sacks lie along the road south of him."] = "Allez vers le nord-est jusqu'à la route d'{zone:1454}. {npc:3293} campe à côté ; les sacs volés sont éparpillés le long de la route au sud de lui.",
		["Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. {quest:826} and Minshina's cage are on the southernmost isle."] = "Dirigez-vous vers le sud à travers les îles. Les idoles des loas sont éparpillées sur les îles du sud ; les Trolls vaudous et les Trolls maléficiés les gardent et laissent tomber les Pendentifs maléficiés. {quest:826} et la cage de Minshina se trouvent sur l'île la plus au sud.",
		["Inside"] = "À l'intérieur",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "Dans la grotte, allez tout droit à la première bifurcation, puis à droite, et suivez le ruisseau sur votre gauche jusqu'à la cascade : la pioche brille près de l'eau, derrière une colonne de roche.",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "Dans la grotte, longez la paroi de droite tout du long, en passant le ruisseau : {npc:3183} attend au fond.",
		["Level 10"] = "Niveau 10",
		["Mage trainer"] = "Maître des mages",
		["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "La hutte de Misha se trouve au sud des lézards. Les crocilisques le long de {area:814}, à l'ouest, portent l'{item:4891}.",
		["Paladin trainer"] = "Maître des paladins",
		["Prickly pears"] = "Figues de Barbarie",
		["Quilboars and scouts hold the huts west of town; dustrunners and battleguards hold the camps farther west."] = "Les Hurans et les Eclaireurs Tranchecrin tiennent les huttes à l'ouest de la ville ; les Lève-poussière et les Gardes de guerre tiennent les camps plus à l'ouest.",
		["Savages and Storm Witches nest in {area:370}, east of {npc:3293}. A Storm Witch drops the {item:277661}. Shamans: the Burning Blade Cultists by {area:371}, at the ravine's south end, drop the {item:6652}."] = "Sauvages et Sorcières des tempêtes Terrevent nichent dans {area:370}, à l'est de {npc:3293}. Une Sorcière des tempêtes lâche {item:277661}. Chamans : les Sectateurs de la Lame ardente près de {area:371}, au bout sud du ravin, lâchent {item:6652}.",
		["Spitelash naga"] = "Nagas Fouette-bile",
		["Tame it with the {item:15908}"] = "Apprivoisez-le avec le {item:15908}",
		["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}. {npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "Le donjon se dresse sur la côte au sud-est de {area:362}. La hache, l'arc et le bouclier des pillards traînent aux abords. Les Marins et Soldats de marine de Kul Tiras laissent tomber les {item:4870}. {npc:3192} attend au sommet du donjon ; sa clé ouvre le coffre à côté de lui, qui contient la {item:4881}.",
		["The prickly pears grow among the quilboar huts just west of town."] = "Les figues de Barbarie poussent parmi les huttes des huran juste à l'ouest de la ville.",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "Les armes traînent autour de l'Antre et du terrain d'entraînement ; les Sangliers tachetés parcourent tout le fond de la vallée.",
		["The {object:58595} stands in {area:817}, among the cultists you just fought."] = "La {object:58595} se trouve dans {area:817}, parmi les sectateurs que vous venez de combattre.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, beside the road north to {zone:1454}; any of them can drop a {item:6486}. {npc:5810} takes it when the next guide passes {area:379}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Les Lézards-tonnerre et les Foudroyants paissent sur {area:369}, à côté de la route du nord vers {zone:1454} ; chacun d'eux peut laisser tomber une {item:6486}. {npc:5810} la prend quand le guide suivant passe par {area:379}.\nAttention : Halikor, un élite de niveau 12, rôde sur {area:369} parmi les lézards : repérez-le avant d'attirer quoi que ce soit.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, just west and south-west of {npc:3293}.\nFizzle holds the Burning Blade camp on {area:369}, north-west of {area:362}. Hunters: tame a {npc:3099} with the {item:15908} on the way.\nCareful: Burning Blade cultists surround Fizzle, some linked so they aggro in pairs, and they respawn quickly.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Lézards-tonnerre et Foudroyants paissent sur {area:369}, juste à l'ouest et au sud-ouest de {npc:3293}.\nFizzle tient le camp de la Lame ardente sur {area:369}, au nord-ouest de {area:362}. Chasseurs : apprivoisez un {npc:3099} avec {item:15908} en chemin.\nAttention : des sectateurs de la Lame ardente entourent Fizzle, certains liés pour attaquer par paires, et ils réapparaissent vite.\nAttention : Halikor, un élite de niveau 12, rôde sur {area:369} parmi les lézards : repérez-le avant d'attirer quoi que ce soit.",
		["To {zone:1454}"] = "Vers {zone:1454}",
		["Top up here to level 10: {quest:840}, at {area:362}, needs level 10."] = "Montez ici jusqu'au niveau 10 : {quest:840}, à {area:362}, demande le niveau 10.",
		["Training weapons and boars"] = "Armes d'entraînement et sangliers",
		["Underwater"] = "Sous l'eau",
		["Upstairs"] = "À l'étage",
		["Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there.\nDurotar Tigers roam the isle as well as the shore south of Sen'jin, and the Taillasher eggs sit in nests on the isles and along the beach."] = "Traversez à gué jusqu'à l'île de l'Écho la plus au nord. La Matriarche rôde parmi les raptors.\nDes Tigres de Durotar parcourent l'île ainsi que le rivage au sud de Sen'jin, et les œufs de Fouette-queue reposent dans des nids sur les îles et le long de la plage.",
		["Wake {quest:5441} with the {item:16114}"] = "Réveillez {quest:5441} avec la {item:16114}",
		["West over the {area:814} bridge, past {area:379} and on along the ridge: {npc:5907} stands alone above the Razormane camp."] = "Allez vers l'ouest par le pont de {area:814}, passez {area:379} et continuez le long de la crête : {npc:5907} se tient seul au-dessus du camp Tranchecrin.",
		["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Tant que vous y êtes : apprenez les Bâtons auprès de {npc:2704} ({object:172958}, 10 pièces d'argent) ; l'arme de mêlée d'un chasseur compte surtout pour ses caractéristiques, et les armes à deux mains en apportent le plus.",
		["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Tant que vous y êtes : apprenez les Bâtons auprès de {npc:2704} ({object:172958}, 10 pièces d'argent) ; un bâton apporte plus de caractéristiques de sorts qu'une arme à une main pendant la montée de niveau.",
		["grind on {npc:3111}"] = "tuez en boucle : {npc:3111}",
		["the {object:654925} on the ground beside her"] = "le {object:654925} par terre à côté d'elle",
		["{area:363}: kill these as you meet them"] = "{area:363} : tuez-les au passage",
		["{area:366} lies west of Sen'jin. The three attack plans sit on the ground among the centaur tents. {npc:275811} is held at the crag as well."] = "{area:366} se trouve à l'ouest de Sen'jin. Les trois plans d'attaque sont posés au sol parmi les tentes des centaures. {npc:275811} est aussi retenue à la Combe.",
		["{area:368}: kill these as you meet them"] = "{area:368} : tuez-les au passage",
		["{area:369}: kill these as you meet them"] = "{area:369} : tuez-les au passage",
		["{area:373}: kill these as you meet them"] = "{area:373} : tuez-les au passage",
		["{area:817}'s mouth"] = "Entrée de {area:817}",
		["{npc:10176}, where you start"] = "{npc:10176}, à votre point de départ",
		["{npc:11378}, at the lumber pile east of the Den"] = "{npc:11378}, près du tas de bois à l'est de l'Antre",
		["{npc:246344} in {zone:1456}; {area:362} has no paladin trainer"] = "{npc:246344} ({zone:1456}) ; {area:362} n'a pas de maître des paladins",
		["{npc:246344} in {zone:1456}; {area:363} has no paladin trainer"] = "{npc:246344} ({zone:1456}) ; {area:363} n'a pas de maître des paladins",
		["{npc:265809} camps just south of {area:362}. Sit by his campfire (/sit) until the {spell:1229451} buff appears. With a profession learned, {npc:265809} also offers its Camping 101, which its trainer takes: in {area:362} or in {zone:1454} at the start of the next guide."] = "{npc:265809} campe juste au sud de {area:362}. Asseyez-vous près de son feu de camp (/sit) jusqu'à ce que l'effet {spell:1229451} apparaisse. Si vous avez appris un métier, {npc:265809} propose aussi sa quête Camping 101, que reçoit le maître de ce métier : à {area:362} ou à {zone:1454}, au début du guide suivant.",
		["{npc:265809}'s campfire"] = "Feu de camp de {npc:265809}",
		["{npc:265809}: for {npc:11025}"] = "{npc:265809} : pour {npc:11025}",
		["{npc:265809}: for {npc:11046}"] = "{npc:265809} : pour {npc:11046}",
		["{npc:265809}: for {npc:11066}"] = "{npc:265809} : pour {npc:11066}",
		["{npc:265809}: for {npc:2855}"] = "{npc:265809} : pour {npc:2855}",
		["{npc:265809}: for {npc:3175}"] = "{npc:265809} : pour {npc:3175}",
		["{npc:265809}: for {npc:3365}"] = "{npc:265809} : pour {npc:3365}",
		["{npc:265809}: for {npc:3404}"] = "{npc:265809} : pour {npc:3404}",
		["{npc:265809}: for {npc:5943}"] = "{npc:265809} : pour {npc:5943}",
		["{npc:265809}: for {npc:7088}"] = "{npc:265809} : pour {npc:7088}",
		["{npc:266881}: enchanters only, the residue is disenchanted from Hexed Pendants"] = "{npc:266881} : enchanteurs uniquement, le résidu s'obtient en désenchantant des Pendentifs maléficiés",
		["{npc:266940}, inside"] = "{npc:266940}, à l'intérieur",
		["{npc:266940}, on the east side of town; inside"] = "{npc:266940}, du côté est de la ville ; à l'intérieur",
		["{npc:275657} stands on the shore east of {area:362}. The trident, banner and dagger lie on the beach around him."] = "{npc:275657} se tient sur le rivage à l'est de {area:362}. Le trident, la bannière et la dague traînent sur la plage autour de lui.",
		["{npc:275666}, a young sea giant, walks {zone:1411}'s north coast, north of the naga beach. {npc:275666} is elite: grouping up is advised."] = "{npc:275666}, un jeune géant des mers, arpente la côte nord de {zone:1411}, au nord de la plage des nagas. {npc:275666} est élite : il est conseillé de se grouper.",
		["{npc:3034} in {zone:1412}; {area:362} has no druid trainer"] = "{npc:3034} ({zone:1412}) ; {area:362} n'a pas de maître des druides",
		["{npc:3034} in {zone:1412}; {area:363} has no druid trainer"] = "{npc:3034} ({zone:1412}) ; {area:363} n'a pas de maître des druides",
		["{npc:3102} hooves"] = "Sabots de {npc:3102}",
		["{npc:3142}, back in {area:362}"] = "{npc:3142}, de retour à {area:362}",
		["{npc:3142}: {npc:275666}, an elite sea giant"] = "{npc:3142} : {npc:275666}, un géant des mers élite",
		["{npc:3143} stands just inside the cave mouth; {npc:3159} at the back of the cave behind him."] = "{npc:3143} se tient juste à l'entrée de la grotte ; {npc:3159} au fond de la grotte, derrière lui.",
		["{npc:3143} waits inside the Den, the building just west of {npc:10176}."] = "{npc:3143} attend dans l'Antre, le bâtiment juste à l'ouest de {npc:10176}.",
		["{npc:3143}, inside"] = "{npc:3143}, à l'intérieur",
		["{npc:3147}, in the watchtower"] = "{npc:3147}, dans la tour de guet",
		["{npc:3153}, the warrior trainer beside the Den"] = "{npc:3153}, le maître des guerriers à côté de l'Antre",
		["{npc:3154}, the hunter trainer beside the Den"] = "{npc:3154}, le maître des chasseurs à côté de l'Antre",
		["{npc:3155}, the rogue trainer in the Den"] = "{npc:3155}, le maître des voleurs dans l'Antre",
		["{npc:3156}, the warlock trainer at the back of the cave"] = "{npc:3156}, le maître des démonistes au fond de la grotte",
		["{npc:3157}, the shaman trainer beside the Den"] = "{npc:3157}, le maître des chamans à côté de l'Antre",
		["{npc:3159}, at the back of the cave; below ground"] = "{npc:3159}, au fond de la grotte ; sous terre",
		["{npc:3169}, inside"] = "{npc:3169}, à l'intérieur",
		["{npc:3171}: {npc:3352} in {zone:1454} teaches {spell:5149}"] = "{npc:3171} : {npc:3352}, à {zone:1454}, enseigne {spell:5149}",
		["{npc:3191}: Camping 101 asks you to learn it"] = "{npc:3191} : la quête Camping 101 vous demande de l'apprendre",
		["{npc:3287} lies wounded at the foot of the hills north-west of the Den."] = "{npc:3287} gît blessé au pied des collines au nord-ouest de l'Antre.",
		["{npc:3294}, by the inn"] = "{npc:3294}, près de l'auberge",
		["{npc:5875} stands in the {object:172960}, the canyon under the {object:172982}. Hand him the {item:6535}, then use the {item:7464} on the summoning circle beside him and defeat the voidwalker to bind it."] = "{npc:5875} se tient dans {object:172960}, le canyon sous {object:172982}. Remettez-lui {item:6535}, puis utilisez les {item:7464} sur le cercle d'invocation à côté de lui et vainquez le marcheur du Vide pour le lier.",
		["{npc:5880}, the mage trainer in Sen'jin"] = "{npc:5880}, le maître des mages de Sen'jin",
		["{npc:5884} in {zone:1411}; {area:362} has no mage trainer"] = "{npc:5884} ({zone:1411}) ; {area:362} n'a pas de maître des mages",
		["{npc:5884}, the mage trainer, at the entrance to the Den"] = "{npc:5884}, le maître des mages, à l'entrée de l'Antre",
		["{npc:5887} stands outside the Den. {area:639} is the hill just south of it: drink the {item:6635} there to see the {npc:5891}, then take the {item:6656} back to {npc:5887}."] = "{npc:5887} se tient devant l'Antre. {area:639} est la colline juste au sud : buvez-y le {item:6635} pour voir la {npc:5891}, puis rapportez le {item:6656} à {npc:5887}.",
		["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887} : {npc:5873} et votre {item:5175}",
		["{npc:5891}, on {area:639}"] = "{npc:5891}, sur {area:639}",
		["{npc:6786} stands on the road at the valley's eastern exit."] = "{npc:6786} se tient sur la route, à la sortie est de la vallée.",
		["{npc:6928}, inside"] = "{npc:6928}, à l'intérieur",
		["{npc:9796}, by the cooking fire"] = "{npc:9796}, près du feu de cuisine",
		["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828} campe sur la colline à l'ouest de la plage des nagas, au sud de {quest:827}.",
		["{zone:1454}'s main gate is just west of {area:817}. {npc:5875} stands in the {object:172960}, the canyon under the {object:172982}."] = "La porte principale d'{zone:1454} se trouve juste à l'ouest de {area:817}. {npc:5875} se tient dans {object:172960}, le canyon sous {object:172982}.",
} end)()
t.guides["forever/horde/skyborne/01-zephras-isle"] = (function() return {
		["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "/sit près du feu de camp de {npc:263664} jusqu'à obtenir {spell:1229451}",
		["Aanders and the fallen guards are just south-west of the tower. Take Raani's feather and the Shadowsong signet from the bodies."] = "Aanders et les gardes tombés sont juste au sud-ouest de la tour. Prenez la Plume porte-bonheur de Raani et la chevalière Shadowsong sur les corps.",
		["Back at {quest:92529}: Stormcallers and {npc:251662} fill the village, the Supply Caches stand among the houses and {npc:251966} waits at its south-east end."] = "De retour à {quest:92529} : des Mande-foudre al'aketh et {npc:251662} emplissent le village, les Caches de fournitures ({object:576179}) se trouvent entre les maisons et {npc:251966} attend à son extrémité sud-est.",
		["Back to {area:16635}"] = "Retour à {area:16635}",
		["Back to {area:16638}"] = "Retour à {area:16638}",
		["Back to {npc:268592}. Wait for him to light the {npc:268762}, then carry the flame straight to the {npc:268679} beside {npc:252382} in {area:16638} before the timer runs out."] = "Retournez voir {npc:268592}. Attendez qu'il allume {npc:268762}, puis portez la flamme directement jusqu'à {npc:268679}, à côté de {npc:252382} à {area:16638}, avant la fin du temps imparti.",
		["Below ground"] = "Sous terre",
		["Boro and {npc:251373}, while you stand beside them"] = "Boro et {npc:251373}, en restant à côté d'eux",
		["Cast {spell:1259686} near the {object:460001}"] = "Lancez {spell:1259686} près de la Convergence élémentaire",
		["Class trainer"] = "Maître de classe",
		["Find {npc:258130}"] = "Trouvez {npc:258130}",
		["Follow the road south to {area:16624}, in the middle of the isle. {npc:251523} stands on its east side, {npc:251902} in the middle, {npc:254089} just north-west of her, {npc:263664} by the campfire on the west side. With a profession learned, {npc:263664} also offers its Camping 101: its trainer stands in the village."] = "Suivez la route vers le sud jusqu'à {area:16624}, au milieu de l'île. {npc:251523} se tient du côté est, {npc:251902} au milieu, {npc:254089} juste au nord-ouest d'elle, {npc:263664} près du feu de camp du côté ouest. Une fois un métier appris, {npc:263664} propose aussi la quête Camping 101 correspondante : son maître se tient dans le village.",
		["Head north into {area:16631}; {npc:257944} camps at its southern edge."] = "Allez vers le nord dans la {area:16631} ; {npc:257944} campe à sa lisière sud.",
		["Head north-east to the {area:17675}. The Al'Aketh camp is just west of it, with {npc:252666} at its north end. Every cultist can drop a windstone charm."] = "Dirigez-vous vers le nord-est jusqu'à {area:17675}. Le camp al'aketh se trouve juste à l'ouest, avec {npc:252666} à son extrémité nord. Chaque sectateur peut lâcher un charme de pierre de vent.",
		["Head south-west to the {area:17674}. {npc:252155} is at the top; the {item:254871} lies beside him."] = "Allez au sud-ouest jusqu'à la {area:17674}. {npc:252155} est au sommet ; {item:254871} se trouve à côté de lui.",
		["Heal the injured druids in the Nightfang Den"] = "Soignez les druides blessés dans la tanière des Crocs-de-la-nuit",
		["Innkeeper {npc:255940}, by the west gate"] = "L'aubergiste {npc:255940}, près de la porte ouest",
		["Into {zone:1412}"] = "Vers {zone:1412}",
		["Into {zone:1413}"] = "Vers les {zone:1413}",
		["Jump off the top of the watchtower and use {spell:1259416} to float down to {npc:251361}, west of the tower."] = "Sautez du haut de la tour de guet et utilisez {spell:1259416} pour descendre en planant jusqu'à {npc:251361}, à l'ouest de la tour.",
		["Leave {zone:2521} to {zone:1412}"] = "Quittez {zone:2521} pour {zone:1412}",
		["Listen to {npc:252448}'s story"] = "Écoutez l'histoire de {npc:252448}",
		["Listen to {npc:256083}"] = "Écoutez {npc:256083}",
		["Northern {zone:1412}"] = "Nord de {zone:1412}",
		["On your way north from Valennia, {npc:255853} waits by the falls north-east of you, just north of the {area:17675}: from the ridge above them, glide down with {spell:1259416}."] = "En repartant vers le nord depuis Valennia, {npc:255853} attend près des chutes au nord-est, juste au nord de {area:17675} : depuis la crête qui les surplombe, descendez en planant avec {spell:1259416}.",
		["Pesky Cirrusflies and {npc:250873} roam the grove just south-east of the village."] = "Des Mouches-cirrus agaçantes et des {npc:250873} parcourent le bosquet juste au sud-est du village.",
		["Portal to {area:16630}"] = "Portail vers {area:16630}",
		["Raw Windstones"] = "Pierres de vent brutes ({object:613286})",
		["Shen'dar bounty board"] = "Tableau des primes de Shen'dar",
		["Skyhoppers"] = "Sauteciels",
		["Skyhoppers hop about the fields just west of Valennia."] = "Des Sauteciels ({npc:251727}) sautillent dans les champs juste à l'ouest de Valennia.",
		["Spread the {item:278078} off {area:1641}"] = "Répandez l'{item:278078} depuis {area:1641}",
		["Stormapples and flutterfly dust lie all over the orchard; Hungry Bandits raid it. Galestriders graze in the fields east of it. The broken construct floats at the orchard's north edge."] = "Des Pommes d’orage mûres et de la Poussière de voltemouche jonchent le verger ; des Bandits affamés ({npc:252802}) le pillent. Des trotteurs des trombes paissent dans les champs à l'est. L'assemblage brisé flotte à la lisière nord du verger.",
		["Take the Portal to {area:16630} in the shrine up to the heights. Fight east along the ledge to the Peacekeepers at its end, ride the wind current up to the upper terrace and tell {npc:252475} you are ready. Leave the {object:617084} up there alone until Rohash has withdrawn; then it takes you straight back to town."] = "Prenez le portail vers {area:16630} dans le sanctuaire pour monter sur les hauteurs. Frayez-vous un chemin vers l'est le long de la corniche jusqu'aux Gardiens de la paix au bout, empruntez le courant d'air jusqu'à la terrasse supérieure et dites à {npc:252475} que vous êtes prêt. Ne touchez pas au portail vers Valanaar là-haut tant que Rohash ne s'est pas retiré ; ensuite, il vous ramène directement en ville.",
		["Take {item:277267} to {npc:268592} at the Shrine of Flames, south-west of {area:16638}, then head west into the {area:16623}: {npc:268605}'s home is in the hills south of the Windsong Crawlers' lakes."] = "Apportez {item:277267} à {npc:268592} au sanctuaire des Flammes, au sud-ouest de {area:16638}, puis partez vers l'ouest dans {area:16623} : la demeure de {npc:268605} se trouve dans les collines au sud des lacs des Clampants chantevent.",
		["Tame {npc:250874}"] = "Apprivoisez : {npc:250874}",
		["Tame {npc:251707}"] = "Apprivoisez : {npc:251707}",
		["Tame {npc:254588}"] = "Apprivoisez : {npc:254588}",
		["Tell {npc:252800} you're ready"] = "Dites à {npc:252800} que vous êtes prêt",
		["The Al'Aketh camp"] = "Le camp al'aketh",
		["The Enchanted Gyrozephyrs lie under water far to the north, east of {area:16624} and south-west of {area:16625}."] = "Les Gyrozéphyrs enchantés reposent sous l'eau loin au nord, à l'est de {area:16624} et au sud-ouest de {area:16625}.",
		["The Highwayman Bandits hold the hills north of {area:16663}; they drop the Blood-Stained Bandit Masks."] = "Les Bandits de grand chemin tiennent les collines au nord de {area:16663} ; ils lâchent les Masques de bandit tachés de sang.",
		["The Raw Windstones are blue crystals on the slopes around the village."] = "Les Pierres de vent brutes ({object:613286}) sont des cristaux bleus sur les pentes autour du village.",
		["The apprentices practise north-east of the village.\nThe bandit camps are north-east of the village; \"Badwind\" Bennic holds the top camp. Bandits carry the stolen windstones."] = "Les apprentis s'entraînent au nord-est du village.\nLes camps de bandits se trouvent au nord-est du village ; \"Badwind\" Bennic tient le camp du haut. Les bandits portent les pierres de vent volées.",
		["The hippogryph nests are north-west of the {area:17674}, west of {quest:92529}. The Matriarch sits at their western end; {item:263493} lies on the ground around the nests."] = "Les nids d'hippogriffes se trouvent au nord-ouest de {area:17674}, à l'ouest de {quest:92529}. La Matriarche se tient à leur extrémité ouest ; {item:263493} jonche le sol autour des nids.",
		["The orchard"] = "Le verger",
		["The queen hovers at the south-east end of the grove, on your way back from the stones."] = "La reine plane à l'extrémité sud-est du bosquet, sur le chemin du retour depuis les pierres.",
		["The standing stones"] = "Les pierres dressées",
		["The turncoat"] = "Le traître",
		["The {area:16629}"] = "{area:16629}",
		["The {area:16629} is north of {area:16638}. Fight through the guards up to {npc:253576} at its east side."] = "Le {area:16629} est au nord de {area:16638}. Frayez-vous un chemin à travers les gardes jusqu'à {npc:253576}, du côté est.",
		["The {area:17674}"] = "{area:17674}",
		["The {area:17675}"] = "{area:17675}",
		["The {item:260881} lies in a cave in the hills north-west of {npc:256083}."] = "{item:260881} se trouve dans une grotte des collines au nord-ouest de {npc:256083}.",
		["The {object:148418}"] = "{object:148418}",
		["To {zone:1454}"] = "Vers {zone:1454}",
		["Underwater"] = "Sous l'eau",
		["Upstairs"] = "À l'étage",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "Utilisez l'{item:278078} sur le tapis et le brûleur de cérémonie, sur la falaise sud de {area:1641}.",
		["Warlock trainer"] = "Maître des démonistes",
		["While you're here: learn Staves from {npc:11869} (10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Tant que vous y êtes : apprenez les Bâtons auprès de {npc:11869} (10 pièces d'argent) ; l'arme de mêlée d'un chasseur compte surtout pour ses caractéristiques, et les armes à deux mains en apportent le plus.",
		["While you're here: learn {spell:199} from {npc:11869} (10 silver); two-handers level a Warrior fastest."] = "Tant que vous y êtes : apprenez {spell:199} auprès de {npc:11869} (10 pièces d'argent) ; les armes à deux mains font monter un guerrier le plus vite.",
		["You leave the isle for good. {npc:259119} waits where the airship lands."] = "Vous quittez l'île pour de bon. {npc:259119} attend là où se pose le dirigeable.",
		["You wake in {area:16635}, in the north of the isle. {npc:251362} stands by the path, {npc:251361} at the village centre."] = "Vous vous réveillez à {area:16635}, au nord de l'île. {npc:251362} se tient près du chemin, {npc:251361} au centre du village.",
		["drink the {item:6635} at the {area:16988}, just east of the village, to see the {npc:251166}"] = "buvez {item:6635} à {area:16988}, juste à l'est du village, pour voir la {npc:251166}",
		["search the dead cultist in the house"] = "fouillez le cultiste mort dans la maison",
		["search the wardrobe"] = "fouillez l'armoire",
		["talk to {npc:251684}"] = "parlez à {npc:251684}",
		["talk to {npc:251902}"] = "parlez à {npc:251902}",
		["talk to {npc:251968}"] = "parlez à {npc:251968}",
		["talk to {npc:252155}"] = "parlez à {npc:252155}",
		["talk to {npc:252476}"] = "parlez à {npc:252476}",
		["talk to {npc:253844}"] = "parlez à {npc:253844}",
		["talk to {npc:257554}"] = "parlez à {npc:257554}",
		["tame one with {npc:252389}'s first {item:15908} while you are among them"] = "apprivoisez-en un avec le premier {item:15908} de {npc:252389} pendant que vous êtes parmi eux",
		["the bounty board"] = "le tableau des primes",
		["{area:16622}: kill these as you meet them"] = "{area:16622} : tuez-les au passage",
		["{area:16623}: kill these as you meet them"] = "{area:16623} : tuez-les au passage",
		["{area:16624} hand-ins"] = "Quêtes à rendre à {area:16624}",
		["{area:16624} turn-ins"] = "Quêtes à rendre à {area:16624}",
		["{area:16624}: kill these as you meet them"] = "{area:16624} : tuez-les au passage",
		["{area:16626}: kill these as you meet them"] = "{area:16626} : tuez-les au passage",
		["{area:16631}: kill these as you meet them"] = "{area:16631} : tuez-les au passage",
		["{area:16635} turn-ins"] = "Quêtes à rendre à {area:16635}",
		["{area:16663} is west of {area:16638} along the coast road."] = "Le {area:16663} est à l'ouest de {area:16638}, sur la route côtière.",
		["{item:251924}: the Al'Aketh in {npc:252095}'s camp carry it"] = "{item:251924} : les Al'aketh du camp près de {npc:252095} le portent",
		["{item:265105} grows around {npc:257944}'s camp and Shriekings fly over it. The Al'Aketh camp east of her holds the {item:265141}."] = "{item:265105} pousse autour du camp d'{npc:257944} et des criailleuses le survolent. Le camp al'aketh à l'est d'elle contient {item:265141}.",
		["{item:278079}, from {npc:3014}"] = "{item:278079}, chez {npc:3014}",
		["{item:278080}, from {npc:3012}"] = "{item:278080}, chez {npc:3012}",
		["{item:278081}, from {npc:3005}"] = "{item:278081}, chez {npc:3005}",
		["{item:278083}, from {npc:3027}"] = "{item:278083}, chez {npc:3027}",
		["{npc:2127} in {zone:1420}; {area:16638} has no warlock trainer"] = "{npc:2127} ({zone:1420}) ; {area:16638} n'a pas de maître des démonistes",
		["{npc:249363} stands at the {area:17678}, east of the village. {npc:251143} and Al'Aketh Converts gather just north of her. The {object:460001} is just north-east of her: cast your {spell:1259686} racial ability next to it."] = "{npc:249363} se tient près de {area:17678}, à l'est du village. Des {npc:251143} et des Convertis al'aketh se rassemblent juste au nord d'elle. La Convergence élémentaire se trouve juste au nord-est d'elle : lancez votre technique raciale {spell:1259686} à côté.",
		["{npc:250926} prowl the slopes south-west of the village, on the way to {npc:252095}.\nThe Ursera den is west of the village. {npc:251115}, their matriarch, sits at its far end."] = "Des {npc:250926} rôdent sur les pentes au sud-ouest du village, sur le chemin de {npc:252095}.\nLa tanière des Ursera se trouve à l'ouest du village. {npc:251115}, leur matriarche, se tient tout au fond.",
		["{npc:251361}'s errands"] = "Les commissions de {npc:251361}",
		["{npc:251361}: a note from your trainer"] = "{npc:251361} : un mot de votre maître",
		["{npc:251361}: examine the {item:282418}"] = "{npc:251361} : examinez {item:282418}",
		["{npc:251361}: read the {item:9547}"] = "{npc:251361} : lisez {item:9547}",
		["{npc:251361}: the {item:4100}"] = "{npc:251361} : {item:4100}",
		["{npc:251373}, the druid trainer, on the ground floor of the tree behind {npc:251361}"] = "{npc:251373}, le maître des druides, au rez-de-chaussée de l'arbre derrière {npc:251361}",
		["{npc:251374}, beside {npc:251361}"] = "{npc:251374}, à côté de {npc:251361}",
		["{npc:251374}: {npc:5873} and your {item:5175}"] = "{npc:251374} : {npc:5873} et votre {item:5175}",
		["{npc:251376}, beside {npc:251361}"] = "{npc:251376}, à côté de {npc:251361}",
		["{npc:251389}, in the watchtower"] = "{npc:251389}, dans la tour de guet",
		["{npc:251523} waits in {area:16624} for what you found in the wardrobe."] = "{npc:251523} attend à {area:16624} ce que vous avez trouvé dans l'armoire.",
		["{npc:251905}, {npc:251906}, {npc:251991}, {npc:252172} and {npc:251523} all stand in {area:16624}. If you are still short of {item:5469}, the Galestriders graze just south of the village."] = "{npc:251905}, {npc:251906}, {npc:251991}, {npc:252172} et {npc:251523} se tiennent tous à {area:16624}. S'il vous manque encore de la {item:5469}, les Trotteurs des trombes paissent juste au sud du village.",
		["{npc:251905}: Camping 101 asks you to learn it"] = "{npc:251905} : la quête Camping 101 vous demande de l'apprendre",
		["{npc:251964}, in the watchtower"] = "{npc:251964}, dans la tour de guet",
		["{npc:251968} sends you on to Kalimdor. Once you have trained, board the skycutter at the dock on {area:16638}'s south-west edge: it flies to northern {zone:1412}, where {npc:259119} waits."] = "{npc:251968} vous envoie vers Kalimdor. Une fois entraîné, montez à bord du coupe-ciel au quai, à la lisière sud-ouest de {area:16638} : il vole jusqu'au nord de {zone:1412}, où {npc:259119} vous attend.",
		["{npc:252095} waits in {area:16622}, south-west of the village. The Al'Aketh camp is just beyond her; {npc:256935} leads it.\nCareful: {npc:256935} casts shocks; drag him clear of the other cultists before fighting so they don't join in."] = "{npc:252095} attend à {area:16622}, au sud-ouest du village. Le camp al'aketh se trouve juste derrière elle ; {npc:256935} le dirige.\nAttention : {npc:256935} lance des horions ; éloignez-le des autres sectateurs avant de le combattre pour qu'ils ne s'en mêlent pas.",
		["{npc:252359} stands on {area:16638}'s east side. {npc:255853} waits by the falls just north of the {area:17675}: leave town to the north, climb the ridge east of the road and glide down to him with {spell:1259416}."] = "{npc:252359} se tient du côté est de {area:16638}. {npc:255853} attend près des chutes juste au nord de {area:17675} : quittez la ville par le nord, grimpez sur la crête à l'est de la route et descendez en planant jusqu'à lui avec {spell:1259416}.",
		["{npc:252377} stands beside {npc:256083}, just north-west of {area:16638}."] = "{npc:252377} se tient à côté de {npc:256083}, juste au nord-ouest de {area:16638}.",
		["{npc:252377}, beside {npc:256083}: {quest:94003}"] = "{npc:252377}, à côté de {npc:256083} : {quest:94003}",
		["{npc:252382}, beside {npc:251968}: {quest:97243}"] = "{npc:252382}, à côté de {npc:251968} : {quest:97243}",
		["{npc:252382}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:252382} : {npc:2523}, votre {item:5176} et {item:263412}",
		["{npc:252383}, upstairs"] = "{npc:252383}, à l'étage",
		["{npc:252389} takes back the first {item:15908} and hands you two more, one at a time: Ornery Galestriders and Vuldren Alphas roam the fields just north of her. Tame each with its rod and bring the rod back to her. {npc:254411}, beside her, teaches {spell:5149}."] = "{npc:252389} reprend le premier {item:15908} et vous en donne deux autres, l'un après l'autre : des Trotteurs des trombes hargneux et des Alphas vuldrènes parcourent les champs juste au nord d'elle. Apprivoisez chacun avec son bâtonnet et rapportez-lui le bâtonnet. {npc:254411}, à côté d'elle, enseigne {spell:5149}.",
		["{npc:252389}, a few steps west of {npc:257006}: {quest:94978}, the first rod"] = "{npc:252389}, à quelques pas à l'ouest de {npc:257006} : {quest:94978}, le premier bâtonnet",
		["{npc:252448} and {npc:256083}"] = "{npc:252448} et {npc:256083}",
		["{npc:252476}, upstairs"] = "{npc:252476}, à l'étage",
		["{npc:253372}, inside"] = "{npc:253372}, à l'intérieur",
		["{npc:253590}, upstairs"] = "{npc:253590}, à l'étage",
		["{npc:253622}, {npc:258130} and {npc:258134} are in the cult camp east of {npc:257944}. {npc:254151} stands at its edge. Haalien also drops a {quest:94490}: read it to start the next quest. For {quest:94489}, enter the Nightfang Den, heal 7 injured druids and find {npc:258130}."] = "{npc:253622}, {npc:258130} et {npc:258134} sont dans le camp du culte à l'est d'{npc:257944}. {npc:254151} se tient à sa lisière. Haalien lâche aussi {quest:94490} : lisez-la pour commencer la quête suivante. Pour {quest:94489}, entrez dans la tanière des Crocs-de-la-nuit, soignez 7 druides blessés et trouvez {npc:258130}.",
		["{npc:254344}, beside {npc:251968}"] = "{npc:254344}, à côté de {npc:251968}",
		["{npc:254589} lurks south of the village, among the Prideclaws. {npc:254589} is elite: grouping up is advised."] = "{npc:254589} rôde au sud du village, parmi les Fièregriffes. {npc:254589} est un élite : mieux vaut être en groupe.",
		["{npc:256083} stands in the {area:16626} just north-west of town."] = "{npc:256083} se tient dans les {area:16626}, juste au nord-ouest de la ville.",
		["{npc:256247} waits on the road north of {area:16638}, towards the {area:16629}."] = "{npc:256247} attend sur la route au nord de {area:16638}, en direction du {area:16629}.",
		["{npc:257006} and {npc:252448}"] = "{npc:257006} et {npc:252448}",
		["{npc:257006} waits inside a house on {area:16638}'s western edge; {npc:252448} is close by."] = "{npc:257006} attend dans une maison à la lisière ouest de {area:16638} ; {npc:252448} est tout près.",
		["{npc:257006}, inside"] = "{npc:257006}, à l'intérieur",
		["{npc:257196} holds the {item:263993} on the west side of the shrine."] = "{npc:257196} tient {item:263993} du côté ouest du sanctuaire.",
		["{npc:257554} and {npc:263113} stand at the top of the watchtower, a few steps north-east of {npc:251368}."] = "{npc:257554} et {npc:263113} se tiennent au sommet de la tour de guet, à quelques pas au nord-est de {npc:251368}.",
		["{npc:257944} again"] = "De nouveau {npc:257944}",
		["{npc:257944}, last time"] = "{npc:257944}, une dernière fois",
		["{npc:258443} has her lair in a cave in the bluffs just south of the turncoat's house, where the {area:16623} meet the {area:16626}."] = "{npc:258443} a son repaire dans une grotte des falaises juste au sud de la maison du traître, là où {area:16623} rejoignent {area:16626}.",
		["{npc:259118}, by the landing: for {npc:3033} in {zone:1456}"] = "{npc:259118}, près de l'aire d'atterrissage : pour {npc:3033} à {zone:1456}",
		["{npc:268592}, at the Shrine of Flames just south-east of the orchard"] = "{npc:268592}, au sanctuaire des Flammes juste au sud-est du verger",
		["{npc:268602}, on the hill west of the falls just north of the watchtower"] = "{npc:268602}, sur la colline à l'ouest des chutes, juste au nord de la tour de guet",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068} veut de l'encens tauren : achetez ses quatre ingrédients à {npc:3014} l'herboriste, {npc:3012} la fournisseuse en enchantement, {npc:3005} le fournisseur en travail du cuir et {npc:3027} le fournisseur en cuisine, puis combinez-les en {item:278078}.",
		["{quest:92529} lies south of Shen'dar. {npc:257065} meets you at its edge; search the wardrobe in the house behind him."] = "{quest:92529} se trouve au sud de Shen’dar. {npc:257065} vous attend à son entrée ; fouillez l'armoire de la maison derrière lui.",
} end)()
t.guides["forever/horde/tauren/01-mulgore"] = (function() return {
		["/sit by Kaga's campfire until you get {spell:1229451}"] = "/sit près du feu de camp de Kaga jusqu'à obtenir {spell:1229451}",
		["Back east to {area:358}: the Bristleback Shamans stand among the quilboar there."] = "Retournez à l'est jusqu'à {area:358} : les Chamans Dos-hirsute s'y tiennent parmi les huran.",
		["Back north-west up to {area:221}."] = "Remontez vers le nord-ouest jusqu'à {area:221}.",
		["Back south-east to the {area:396}."] = "Retournez au sud-est jusqu'au {area:396}.",
		["Back to {npc:5888} in the camp. The {npc:5891} waits on the mesa east of the camp: drink the {item:6635} there to see it, then take the {item:6656} back to the Seer."] = "Retournez voir {npc:5888} au camp. La {npc:5891} attend sur la mesa à l'est du camp : buvez-y le {item:6635} pour la voir, puis rapportez le {item:6656} à la prophétesse.",
		["Back west to the camp."] = "Retournez à l'ouest jusqu'au camp.",
		["Battleboars graze north of the shrine; the Bristleback quilboar hold the ravine to the north-east. {npc:8554} stands at its eastern end, and the {object:3076} lies on the ground in the camp."] = "Les Sangliers de guerre paissent au nord du sanctuaire ; les huran Dos-hirsute tiennent le ravin au nord-est. {npc:8554} se tient à son extrémité est, et la {object:3076} gît par terre dans le camp.",
		["Below ground"] = "Sous terre",
		["Class trainer"] = "Maître de classe",
		["Class turn-in in {area:1638}"] = "Quête de classe à rendre à {area:1638}",
		["Cross north-west past {zone:1456} to the {area:398} in the far north of {zone:1412}."] = "Traversez vers le nord-ouest au-delà de {zone:1456} jusqu'au {area:398}, à l'extrême nord de {zone:1412}.",
		["Deathskip to {area:220}"] = "Mort volontaire jusqu'à {area:220}",
		["Die to the mobs at 63.7,78.4 ({npc:2954}): a death there sends you to this graveyard. Release your spirit and take the {npc:6491}'s resurrection."] = "Laissez-vous tuer par les monstres en 63.7,78.4 ({npc:2954}) : mourir là vous envoie à ce cimetière. Libérez votre esprit et acceptez la résurrection du {npc:6491}.",
		["Follow the road north out of {area:220}. {npc:265810} waits on the road just south of {area:222}; /sit by her campfire until you get {spell:1229451}. With a profession learned, Kaga also offers its Camping 101, which its trainer takes: in Bloodhoof or on the {zone:1456} stop."] = "Suivez la route vers le nord pour quitter {area:220}. {npc:265810} attend sur la route juste au sud de {area:222} ; /sit près de son feu de camp jusqu'à obtenir {spell:1229451}. Si vous avez appris un métier, Kaga propose aussi sa quête Camping 101, que reçoit le maître de ce métier : à Sabot-de-Sang ou lors de l'étape à {zone:1456}.",
		["Galak centaurs"] = "Centaures galak",
		["Head north to {area:225}, east of {zone:1456}. {npc:3233} stands at the foot of the rocks; the Bristleback Interlopers dig at the burial ground and the {npc:2994} waits on top."] = "Allez au nord jusqu'à {area:225}, à l'est de {zone:1456}. {npc:3233} se tient au pied des rochers ; les Intrus Dos-hirsute creusent dans le cimetière et l'{npc:2994} attend au sommet.",
		["Inside"] = "À l'intérieur",
		["Into {zone:1412}"] = "Vers {zone:1412}",
		["Into {zone:1413}"] = "Vers les {zone:1413}",
		["Prairie Wolf Alphas roam among the wolves on the plains around {npc:275789} and the Galak camp to the east."] = "Les Loups Alpha des prairies rôdent parmi les loups dans les plaines autour de {npc:275789} et du camp galak à l'est.",
		["Prairie Wolves and Adult Plainstriders roam the plains around the village."] = "Les Loups des prairies et les Trotteurs des plaines adultes parcourent les plaines autour du village.",
		["Ride a lift up to the mesas. {npc:2995} keeps the wind riders on the central rise; {npc:3057} stands in the great tent there."] = "Prenez un ascenseur jusqu'aux mesas. {npc:2995} s'occupe des coursiers du vent sur le piton central ; {npc:3057} se tient dans la grande tente.",
		["Rogue trainer"] = "Maître des voleurs",
		["Spread the {item:278078} off {area:1641}"] = "Répandez l'{item:278078} depuis {area:1641}",
		["Tame it with the {item:15908}"] = "Apprivoisez-le avec le {item:15908}",
		["The Palemane gnolls hold {area:818}, south of the digsite and west of Bloodhoof. {npc:272203} is held in their camp: lead him out."] = "Les gnolls crin-pâle tiennent {area:818}, au sud du site de fouilles et à l'ouest de Sabot-de-Sang. {npc:272203} est retenu dans leur camp : escortez-le dehors.",
		["The Seer's tent stands at the foot of the cougars' hills."] = "La tente du prophète se dresse au pied des collines des pumas.",
		["The Windfury harpies hold {area:819}, north and west of the well."] = "Les harpies Furie-des-vents tiennent {area:819}, au nord et à l'ouest du puits.",
		["The dwarves of the {area:404} carry the Prospector's Picks. Smash them at the dwarves' forge in the digsite."] = "Les nains du {area:404} portent les Piolets de prospecteur. Brisez-les à la forge des nains, sur le site de fouilles.",
		["The goblins work the mine in the hills north-east of the well. {quest:765} stands in the back of the mine; his {item:281031} start {quest:98424}, and the other pages lie inside the mine."] = "Les gobelins exploitent la mine dans les collines au nord-est du puits. {quest:765} se tient au fond de la mine ; ses {item:281031} lancent {quest:98424}, et les autres pages se trouvent dans la mine.",
		["The incense burns out in ten minutes: run straight east along the southern hills to the {object:660739}."] = "L'encens se consume en dix minutes : courez tout droit vers l'est le long des collines du sud jusqu'au {object:660739}.",
		["The shrine of An'she and Mu'sha"] = "Le sanctuaire d'An'she et Mu'sha",
		["The stone stands in the pass out of {zone:1412}, on your way east. Use the {item:15710} there and defeat Lunaclaw."] = "La pierre se dresse dans le col qui sort de {zone:1412}, sur votre route vers l'est. Utilisez-y la {item:15710} et vainquez Lunegriffe.",
		["The wrecked caravan lies north-west of the centaurs, east of the road to {zone:1456}."] = "La caravane détruite se trouve au nord-ouest des centaures, à l'est de la route de {zone:1456}.",
		["The {object:177525}"] = "{object:177525}",
		["To {zone:1454}"] = "Vers {zone:1454}",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "Utilisez l'{item:278078} sur le tapis et le brûleur de cérémonie, sur la falaise sud de {area:1641}.",
		["Warlock trainer"] = "Maître des démonistes",
		["While you're here: learn Staves from {npc:11869} (10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Tant que vous y êtes : apprenez les Bâtons auprès de {npc:11869} (10 pièces d'argent) ; l'arme de mêlée d'un chasseur compte surtout pour ses caractéristiques, et les armes à deux mains en apportent le plus.",
		["While you're here: learn {spell:199} from {npc:11869} (10 silver); two-handers level a Warrior fastest."] = "Tant que vous y êtes : apprenez {spell:199} auprès de {npc:11869} (10 pièces d'argent) ; les armes à deux mains font monter un guerrier le plus vite.",
		["You start on the mesa of {area:221}. {npc:2980} and the chief stand by the big tent in the middle."] = "Vous commencez sur la mesa de {area:221}. {npc:2980} et le chef se tiennent près de la grande tente au centre.",
		["{area:220}: kill these as you meet them"] = "{area:220} : tuez-les au passage",
		["{area:474}: kill these as you meet them"] = "{area:474} : tuez-les au passage",
		["{item:278079}, from {npc:3014}"] = "{item:278079}, chez {npc:3014}",
		["{item:278080}, from {npc:3012}"] = "{item:278080}, chez {npc:3012}",
		["{item:278081}, from {npc:3005}"] = "{item:278081}, chez {npc:3005}",
		["{item:278083}, from {npc:3027}"] = "{item:278083}, chez {npc:3027}",
		["{item:4703}, at the digsite forge"] = "{item:4703}, à la forge du site de fouilles",
		["{item:5203}: Flatland Prowlers roam the plains around {area:225}"] = "{item:5203} : les Rôdeurs des basses plaines parcourent les plaines autour de {area:225}",
		["{npc:10378}, beside {npc:3418}"] = "{npc:10378}, à côté de {npc:3418}",
		["{npc:265810}: for {npc:10278}"] = "{npc:265810} : pour {npc:10278}",
		["{npc:265810}: for {npc:11047}"] = "{npc:265810} : pour {npc:11047}",
		["{npc:265810}: for {npc:11051}"] = "{npc:265810} : pour {npc:11051}",
		["{npc:265810}: for {npc:11071}"] = "{npc:265810} : pour {npc:11071}",
		["{npc:265810}: for {npc:3001}"] = "{npc:265810} : pour {npc:3001}",
		["{npc:265810}: for {npc:3013}"] = "{npc:265810} : pour {npc:3013}",
		["{npc:265810}: for {npc:3069}"] = "{npc:265810} : pour {npc:3069}",
		["{npc:265810}: for {npc:5938}"] = "{npc:265810} : pour {npc:5938}",
		["{npc:265810}: for {npc:5939}"] = "{npc:265810} : pour {npc:5939}",
		["{npc:265810}: for {npc:6290}"] = "{npc:265810} : pour {npc:6290}",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068} veut de l'encens tauren : achetez ses quatre ingrédients à {npc:3014} l'herboriste, {npc:3012} la fournisseuse en enchantement, {npc:3005} le fournisseur en travail du cuir et {npc:3027} le fournisseur en cuisine, puis combinez-les en {item:278078}.",
		["{npc:277154} runs around the village: give him the {item:287505}"] = "{npc:277154} court dans le village : donnez-lui {item:287505}",
		["{npc:277182} stands at the north edge of the village. Kyle wants {item:287505} from plainstriders."] = "{npc:277182} se tient au bord nord du village. Kyle veut de la {item:287505} prise sur les trotteurs des plaines.",
		["{npc:277182}, at the north end of the village"] = "{npc:277182}, à l'extrémité nord du village",
		["{npc:2948}, for Hamuul in {zone:1456}"] = "{npc:2948}, pour Hamuul à {zone:1456}",
		["{npc:2950} walks around {area:16677}: look inside the circle on the map"] = "{npc:2950} se promène autour de {area:16677} : cherchez dans le cercle sur la carte",
		["{npc:2951}, below ground"] = "{npc:2951}, sous terre",
		["{npc:2981}, inside"] = "{npc:2981}, à l'intérieur",
		["{npc:2984} stands at the edge of the {area:404}, south of the well."] = "{npc:2984} se tient au bord du {area:404}, au sud du puits.",
		["{npc:2988} walks around here: look inside the circle on the map"] = "{npc:2988} se promène par ici : cherchez dans le cercle sur la carte",
		["{npc:2991} sits by the tent on the camp's eastern edge; the {object:2907} stands next to her."] = "{npc:2991} est assise près de la tente au bord est du camp ; {object:2907} est posée à côté d'elle.",
		["{npc:2993}, for {npc:3057} in {zone:1456}"] = "{npc:2993}, pour {npc:3057} à {zone:1456}",
		["{npc:3033} trains druids in the Cenarion Circle's tent on {area:1639}."] = "{npc:3033} entraîne les druides dans la tente du Cercle cénarien sur {area:1639}.",
		["{npc:3039}, beside {npc:3041}"] = "{npc:3039}, à côté de {npc:3041}",
		["{npc:3059}, the warrior trainer; inside"] = "{npc:3059}, le maître des guerriers ; à l'intérieur",
		["{npc:3060}, the druid trainer beside him"] = "{npc:3060}, le maître des druides à côté de lui",
		["{npc:3061}, the hunter trainer"] = "{npc:3061}, la maîtresse des chasseurs",
		["{npc:3062}, the shaman trainer in camp"] = "{npc:3062}, la maîtresse des chamans au camp",
		["{npc:3063}'s quest: beat three Novice Warriors (or players in duels) next to him."] = "Quête de {npc:3063} : battez trois Guerriers novices (ou des joueurs en duel) à côté de lui.",
		["{npc:3065} stands at the north end of {area:222}. Tame with the {item:15908}: an {npc:2956} on the plains, a {npc:2959} north of the village, a {npc:2970} to the north-west."] = "{npc:3065} se tient à l'extrémité nord de {area:222}. Apprivoisez avec {item:15908} : un {npc:2956} dans les plaines, un {npc:2959} au nord du village, un {npc:2970} au nord-ouest.",
		["{npc:3067}: Camping 101 asks you to learn it"] = "{npc:3067} : la quête Camping 101 vous demande de l'apprendre",
		["{npc:3069}, beside {npc:3067}: {quest:97934}"] = "{npc:3069}, à côté de {npc:3067} : {quest:97934}",
		["{npc:3155} in {zone:1411}; {zone:1412} has no rogue trainer"] = "{npc:3155} ({zone:1411}) ; {zone:1412} n'a pas de maître des voleurs",
		["{npc:3156} in {zone:1411}; {zone:1412} has no warlock trainer"] = "{npc:3156} ({zone:1411}) ; {zone:1412} n'a pas de maître des démonistes",
		["{npc:3209} walks around {area:221}: look inside the circle on the map"] = "{npc:3209} se promène autour de {area:221} : cherchez dans le cercle sur la carte",
		["{npc:3209}, next to {npc:2980}; walks around {area:221}: look inside the circle on the map"] = "{npc:3209}, à côté de {npc:2980} ; se promène dans {area:221} : cherchez à l'intérieur du cercle sur la carte",
		["{npc:3222} walks around {area:222}: look inside the circle on the map"] = "{npc:3222} se promène autour de {area:222} : cherchez dans le cercle sur la carte",
		["{npc:3418} stands at {area:378}, where the road from {zone:1412} meets the {area:458} north to the Crossroads."] = "{npc:3418} se tient au {area:378}, là où la route venant de {zone:1412} rejoint la {area:458} qui monte au nord vers la Croisée.",
		["{npc:3418}: for {npc:3429} at the Crossroads"] = "{npc:3418} : pour {npc:3429} à la Croisée",
		["{npc:3429}, by the wind rider tower"] = "{npc:3429}, près de la tour des coursiers du vent",
		["{npc:3615}, the wind rider master"] = "{npc:3615}, le maître des coursiers du vent",
		["{npc:5888} stands in {area:221}. {quest:1516} needs level 4, which you reach with the turn-ins here."] = "{npc:5888} se tient au {area:221}. {quest:1516} requiert le niveau 4, que vous atteignez avec les quêtes rendues ici.",
		["{npc:5888}: {npc:5873} and your {item:5175}"] = "{npc:5888} : {npc:5873} et votre {item:5175}",
		["{npc:5906}, a few steps from {npc:5543} on {area:1640}"] = "{npc:5906}, à quelques pas de {npc:5543} sur {area:1640}",
		["{npc:6290}, beside {npc:3067}: {quest:97936}"] = "{npc:6290}, à côté de {npc:3067} : {quest:97936}",
		["{npc:6746}, at the south end of the central rise: the hearth from {quest:5922} brings you back here"] = "{npc:6746}, à l'extrémité sud du piton central : la pierre de foyer après {quest:5922} vous ramène ici",
		["{npc:6746}: {quest:5926}, for {npc:3033} on {area:1639}"] = "{npc:6746} : {quest:5926}, pour {npc:3033} sur {area:1639}",
		["{npc:6775} stands at the west end of the camp, at the north-west corner of the hills where the Mountain Cougars prowl: take his quest, then hunt the cougars south through the hills towards the Seer's tent at their foot."] = "{npc:6775} se tient à l'extrémité ouest du camp, à l'angle nord-ouest des collines où rôdent les Pumas des montagnes : prenez sa quête, puis chassez les pumas vers le sud à travers les collines, jusqu'à la tente du prophète à leur pied.",
		["{npc:8359}, by the wind riders on the central rise"] = "{npc:8359}, près des coursiers du vent sur le piton central",
		["{quest:96130}, a lone wolf, prowls the plains west of the village. Prairie Stalkers and Flatland Cougars roam the plains north and west of it."] = "{quest:96130}, un loup solitaire, rôde dans les plaines à l'ouest du village. Les Traqueurs des prairies et les Pumas des basses plaines parcourent les plaines au nord et à l'ouest du village.",
		["{zone:1412}: kill these as you meet them"] = "{zone:1412} : tuez-les au passage",
} end)()
t.guides["forever/horde/troll/01-durotar"] = (function() return {
		["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "Les Scorpides blindés rampent dans les plaines à l'ouest de {area:362}. Apprivoisez-en un, puis retournez voir {npc:3171}.",
		["Back to the Den"] = "Retour à l'Antre",
		["Back to {area:362}."] = "Retournez à {area:362}.",
		["Back to {zone:1411}"] = "Retour en {zone:1411}",
		["Below ground"] = "Sous terre",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}."] = "Les sectateurs de la Lame ardente tiennent les grottes de {quest:827} ; chacun d'eux peut laisser tomber un {item:4871}. {npc:3204}, un démoniste de niveau 14, se tient au fond et laisse tomber l'{item:4903}.",
		["Class trainer"] = "Maître de classe",
		["Deathskip to Northern Durotar"] = "Mort volontaire jusqu'au nord de Durotar",
		["Die to the mobs at 52.0,21.4 ({npc:3118}): a death there sends you to this graveyard. Release your spirit and take the {npc:6491}'s resurrection."] = "Laissez-vous tuer par les monstres en 52.0,21.4 ({npc:3118}) : mourir là vous envoie à ce cimetière. Libérez votre esprit et acceptez la résurrection du {npc:6491}.",
		["Druid trainer"] = "Maître des druides",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "Les Traqueurs corrompus parcourent la pente sous la grotte, du côté nord de la vallée.",
		["Follow the road east out of the valley to {area:367} on the coast."] = "Suivez la route vers l'est hors de la vallée jusqu'au {area:367}, sur la côte.",
		["Free {npc:275811} and see her safely out of the crag"] = "Libérez {npc:275811} et escortez-la hors de la Combe",
		["Head north-east to the road toward {zone:1454}. {npc:3293} camps beside it; the stolen sacks lie along the road south of him."] = "Allez vers le nord-est jusqu'à la route d'{zone:1454}. {npc:3293} campe à côté ; les sacs volés sont éparpillés le long de la route au sud de lui.",
		["Heal and fortify {npc:12430}"] = "Soignez et fortifiez {npc:12430}",
		["Inside"] = "À l'intérieur",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "Dans la grotte, allez tout droit à la première bifurcation, puis à droite, et suivez le ruisseau sur votre gauche jusqu'à la cascade : la pioche brille près de l'eau, derrière une colonne de roche.",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "Dans la grotte, longez la paroi de droite tout du long, en passant le ruisseau : {npc:3183} attend au fond.",
		["Level 10"] = "Niveau 10",
		["Mage trainer"] = "Maître des mages",
		["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "La hutte de Misha se trouve au sud des lézards. Les crocilisques le long de {area:814}, à l'ouest, portent l'{item:4891}.",
		["Paladin trainer"] = "Maître des paladins",
		["Prickly pears"] = "Figues de Barbarie",
		["Quilboars and scouts hold the huts west of town; dustrunners and battleguards hold the camps farther west."] = "Les Hurans et les Eclaireurs Tranchecrin tiennent les huttes à l'ouest de la ville ; les Lève-poussière et les Gardes de guerre tiennent les camps plus à l'ouest.",
		["Savages and Storm Witches nest in {area:370}, east of {npc:3293}. A Storm Witch drops the {item:277661}. Shamans: the Burning Blade Cultists by {area:371}, at the ravine's south end, drop the {item:6652}."] = "Sauvages et Sorcières des tempêtes Terrevent nichent dans {area:370}, à l'est de {npc:3293}. Une Sorcière des tempêtes lâche {item:277661}. Chamans : les Sectateurs de la Lame ardente près de {area:371}, au bout sud du ravin, lâchent {item:6652}.",
		["Spitelash naga"] = "Nagas Fouette-bile",
		["Tame it with the {item:15908}"] = "Apprivoisez-le avec le {item:15908}",
		["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}. {npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "Le donjon se dresse sur la côte au sud-est de {area:362}. La hache, l'arc et le bouclier des pillards traînent aux abords. Les Marins et Soldats de marine de Kul Tiras laissent tomber les {item:4870}. {npc:3192} attend au sommet du donjon ; sa clé ouvre le coffre à côté de lui, qui contient la {item:4881}.",
		["The prickly pears grow among the quilboar huts just west of town."] = "Les figues de Barbarie poussent parmi les huttes des huran juste à l'ouest de la ville.",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "Les armes traînent autour de l'Antre et du terrain d'entraînement ; les Sangliers tachetés parcourent tout le fond de la vallée.",
		["The {object:58595} stands in {area:817}, among the cultists you just fought."] = "La {object:58595} se trouve dans {area:817}, parmi les sectateurs que vous venez de combattre.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, beside the road north to {zone:1454}; any of them can drop a {item:6486}. {npc:5810} takes it when the next guide passes {area:379}.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Les Lézards-tonnerre et les Foudroyants paissent sur {area:369}, à côté de la route du nord vers {zone:1454} ; chacun d'eux peut laisser tomber une {item:6486}. {npc:5810} la prend quand le guide suivant passe par {area:379}.\nAttention : Halikor, un élite de niveau 12, rôde sur {area:369} parmi les lézards : repérez-le avant d'attirer quoi que ce soit.",
		["Thunder Lizards and Lightning Hides graze on {area:369}, just west and south-west of {npc:3293}.\nFizzle holds the Burning Blade camp on {area:369}, north-west of {area:362}. Hunters: tame a {npc:3099} with the {item:15908} on the way.\nCareful: Burning Blade cultists surround Fizzle, some linked so they aggro in pairs, and they respawn quickly.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Lézards-tonnerre et Foudroyants paissent sur {area:369}, juste à l'ouest et au sud-ouest de {npc:3293}.\nFizzle tient le camp de la Lame ardente sur {area:369}, au nord-ouest de {area:362}. Chasseurs : apprivoisez un {npc:3099} avec {item:15908} en chemin.\nAttention : des sectateurs de la Lame ardente entourent Fizzle, certains liés pour attaquer par paires, et ils réapparaissent vite.\nAttention : Halikor, un élite de niveau 12, rôde sur {area:369} parmi les lézards : repérez-le avant d'attirer quoi que ce soit.",
		["To {zone:1454}"] = "Vers {zone:1454}",
		["Top up here to level 10: {quest:840}, at {area:362}, needs level 10."] = "Montez ici jusqu'au niveau 10 : {quest:840}, à {area:362}, demande le niveau 10.",
		["Training weapons and boars"] = "Armes d'entraînement et sangliers",
		["Underwater"] = "Sous l'eau",
		["Upstairs"] = "À l'étage",
		["Wake {quest:5441} with the {item:16114}"] = "Réveillez {quest:5441} avec la {item:16114}",
		["West over the {area:814} bridge, past {area:379} and on along the ridge: {npc:5907} stands alone above the Razormane camp."] = "Allez vers l'ouest par le pont de {area:814}, passez {area:379} et continuez le long de la crête : {npc:5907} se tient seul au-dessus du camp Tranchecrin.",
		["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Tant que vous y êtes : apprenez les Bâtons auprès de {npc:2704} ({object:172958}, 10 pièces d'argent) ; l'arme de mêlée d'un chasseur compte surtout pour ses caractéristiques, et les armes à deux mains en apportent le plus.",
		["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Tant que vous y êtes : apprenez les Bâtons auprès de {npc:2704} ({object:172958}, 10 pièces d'argent) ; un bâton apporte plus de caractéristiques de sorts qu'une arme à une main pendant la montée de niveau.",
		["grind on {npc:3111}"] = "tuez en boucle : {npc:3111}",
		["the {object:654925} on the ground beside her"] = "le {object:654925} par terre à côté d'elle",
		["{area:363}: kill these as you meet them"] = "{area:363} : tuez-les au passage",
		["{area:366} lies west of Sen'jin. The three attack plans sit on the ground among the centaur tents. {npc:275811} is held at the crag as well."] = "{area:366} se trouve à l'ouest de Sen'jin. Les trois plans d'attaque sont posés au sol parmi les tentes des centaures. {npc:275811} est aussi retenue à la Combe.",
		["{area:368}: kill these as you meet them"] = "{area:368} : tuez-les au passage",
		["{area:369}: kill these as you meet them"] = "{area:369} : tuez-les au passage",
		["{area:373}: kill these as you meet them"] = "{area:373} : tuez-les au passage",
