		["{npc:3706}, in the barracks beside {npc:266940}"] = "{npc:3706}, dans la caserne à côté de {npc:266940}",
		["{npc:3707}, the priest trainer at the Den"] = "{npc:3707}, le maître des prêtres à l'Antre",
		["{npc:3707}, the priest trainer at the Den: for {npc:3706} in {area:362}"] = "{npc:3707}, le maître des prêtres à l'Antre : pour {npc:3706} à {area:362}",
		["{npc:5875} stands in the {object:172960}, the canyon under the {object:172982}. Hand him the {item:6535}, then use the {item:7464} on the summoning circle beside him and defeat the voidwalker to bind it."] = "{npc:5875} se tient dans {object:172960}, le canyon sous {object:172982}. Remettez-lui {item:6535}, puis utilisez les {item:7464} sur le cercle d'invocation à côté de lui et vainquez le marcheur du Vide pour le lier.",
		["{npc:5880}, the mage trainer in Sen'jin"] = "{npc:5880}, le maître des mages de Sen'jin",
		["{npc:5884} in {zone:1411}; {area:362} has no mage trainer"] = "{npc:5884} ({zone:1411}) ; {area:362} n'a pas de maître des mages",
		["{npc:5887} stands outside the Den. {area:639} is the hill just south of it: drink the {item:6635} there to see the {npc:5891}, then take the {item:6656} back to {npc:5887}."] = "{npc:5887} se tient devant l'Antre. {area:639} est la colline juste au sud : buvez-y le {item:6635} pour voir la {npc:5891}, puis rapportez le {item:6656} à {npc:5887}.",
		["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887} : {npc:5873} et votre {item:5175}",
		["{npc:5891}, on {area:639}"] = "{npc:5891}, sur {area:639}",
		["{npc:6786} stands on the road at the valley's eastern exit."] = "{npc:6786} se tient sur la route, à la sortie est de la vallée.",
		["{npc:6928}, inside"] = "{npc:6928}, à l'intérieur",
		["{npc:9796} stands just outside the Den's entrance."] = "{npc:9796} se tient juste devant l'entrée de l'Antre.",
		["{npc:9796}, by the cooking fire"] = "{npc:9796}, près du feu de cuisine",
		["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828} campe sur la colline à l'ouest de la plage des nagas, au sud de {quest:827}.",
		["{zone:1454}'s main gate is just west of {area:817}. {npc:5875} stands in the {object:172960}, the canyon under the {object:172982}."] = "La porte principale d'{zone:1454} se trouve juste à l'ouest de {area:817}. {npc:5875} se tient dans {object:172960}, le canyon sous {object:172982}.",
} end)()
t.guides["forever/horde/undead/01-tirisfal-glades"] = (function() return {
		["/sit by her campfire until you get {spell:1229451}"] = "/sit près de son feu de camp jusqu'à obtenir {spell:1229451}",
		["Ask {npc:10666} for his report"] = "Demandez son rapport à {npc:10666}",
