		["{npc:1537} walks around here: look inside the circle on the map"] = "{npc:1537} se promène par ici : cherchez dans le cercle sur la carte",
		["{npc:1560}, in the inn"] = "{npc:1560}, dans l'auberge",
		["{npc:1569}, inside"] = "{npc:1569}, à l'intérieur",
		["{npc:1569}: the scroll for {npc:244808}"] = "{npc:1569} : le parchemin pour {npc:244808}",
		["{npc:1570}, in the church"] = "{npc:1570}, dans l'église",
		["{npc:1655}; upstairs"] = "{npc:1655} ; à l'étage",
		["{npc:1661}, beside the church; inside"] = "{npc:1661}, à côté de l'église ; à l'intérieur",
		["{npc:1661}, inside"] = "{npc:1661}, à l'intérieur",
		["{npc:1667} stands at the south end of the Scarlet farm.\nCareful: He is flanked by two Scarlet guards, one a convert and the other an initiate, who may join the fight."] = "{npc:1667} se tient à l'extrémité sud de la ferme écarlate.\nAttention : il est flanqué de deux gardes écarlates, un converti et un initié, qui peuvent rejoindre le combat.",
		["{npc:1675} walks around {area:164}: look inside the circle on the map"] = "{npc:1675} se promène autour de {area:164} : cherchez dans le cercle sur la carte",
		["{npc:2114}, beside Johaan: {quest:97957}"] = "{npc:2114}, à côté de Johaan : {quest:97957}",
		["{npc:2119}, the warrior trainer; inside"] = "{npc:2119}, le maître des guerriers ; à l'intérieur",
		["{npc:2122}, the rogue trainer"] = "{npc:2122}, maître des voleurs",
		["{npc:2123}, the priest trainer in the church"] = "{npc:2123}, maître des prêtres, dans l'église",
		["{npc:2123}, the priest trainer in the church, sends you to {npc:2129} in {area:159}. Train {spell:613} (Rank 2) from him now: the wounded guard Beryl sends you to needs it."] = "{npc:2123}, maître des prêtres dans l'église, vous envoie voir {npc:2129} à {area:159}. Apprenez dès maintenant {spell:613} (rang 2) auprès de lui : le garde blessé vers qui Beryl vous envoie en a besoin.",
		["{npc:2123}: for {npc:2129} in {area:159}"] = "{npc:2123} : pour {npc:2129} à {area:159}",
		["{npc:2124}, the mage trainer, in the church"] = "{npc:2124}, maître des mages, dans l'église",
		["{npc:2126}, the warlock trainer"] = "{npc:2126}, maître des démonistes",
		["{npc:2128}: {npc:4568} in the {zone:1458} takes it"] = "{npc:2128} : {npc:4568}, à {zone:1458}, s'en charge",
		["{npc:2129}, upstairs"] = "{npc:2129}, à l'étage",
		["{npc:2129}, upstairs: the {item:16607}"] = "{npc:2129}, à l'étage : {item:16607}",
		["{npc:2132}, beside Johaan: {quest:97951}"] = "{npc:2132}, à côté de Johaan : {quest:97951}",
		["{npc:2132}, beside Johaan; inside"] = "{npc:2132}, à côté de Johaan ; à l'intérieur",
		["{npc:2132}, inside"] = "{npc:2132}, à l'intérieur",
		["{npc:244808}, inside"] = "{npc:244808}, à l'intérieur",
		["{npc:244808}: {spell:635}, once five {npc:259377} are healed"] = "{npc:244808} : {spell:635}, une fois cinq {npc:259377} soignés",
		["{npc:246152}, the Paladin trainer"] = "{npc:246152}, maître des paladins",
		["{npc:246152}, the Paladin trainer: {quest:91282}, to {quest:96899}"] = "{npc:246152}, la maîtresse des paladins : {quest:91282}, vers {quest:96899}",
		["{npc:246349} waits at the keep's gate beside Leonid."] = "{npc:246349} attend à la porte du donjon, à côté de Leonid.",
		["{npc:246378}, inside the keep"] = "{npc:246378}, à l'intérieur du donjon",
		["{npc:246389} and {npc:259190}"] = "{npc:246389} et {npc:259190}",
		["{npc:259190} and {npc:246389} at the forest's edge, {npc:246349} at the gate, {npc:246393} and {npc:246394} nearby, {npc:246378} inside."] = "{npc:259190} et {npc:246389} à la lisière de la forêt, {npc:246349} à la porte, {npc:246393} et {npc:246394} tout près, {npc:246378} à l'intérieur.",
		["{npc:275954}, on the top floor"] = "{npc:275954}, au dernier étage",
		["{npc:3523}, by the road west of {area:159}: {quest:97961}"] = "{npc:3523}, au bord de la route à l'ouest de {area:159} : {quest:97961}",
		["{npc:5759}, by the bar: {quest:97955}"] = "{npc:5759}, près du comptoir : {quest:97955}",
		["{npc:6289}, beside {npc:3549}: {quest:97960}"] = "{npc:6289}, à côté de {npc:3549} : {quest:97960}",
		["{npc:6784}, by the farmhouse: talk to him for the duel; he offers it once {npc:5688} has his letter"] = "{npc:6784}, près de la ferme : parlez-lui pour le duel ; il le propose une fois que {npc:5688} a reçu sa lettre",
		["{object:1661} is under the {area:153}, beside the zeppelin towers. {npc:5675} is in the {object:36082}: use the {item:6284} on the summoning circle beside him and defeat the voidwalker. {npc:4606} is in the {object:36070}. {npc:4568} is in the {object:36082} too."] = "{object:1661} est sous les {area:153}, à côté des tours des zeppelins. {npc:5675} est dans le {object:36082} : utilisez les {item:6284} sur le cercle d'invocation à côté de lui et battez le marcheur du Vide. {npc:4606} est dans le {object:36070}. {npc:4568} est aussi dans le {object:36082}.",
		["{object:178090} is in the {area:154} graveyard, beside the church."] = "{object:178090} est dans le cimetière de {area:154}, à côté de l'église.",
		["{object:37098} stands beside {npc:1662} at the camp's south end."] = "{object:37098} se trouve à côté de {npc:1662}, à l'extrémité sud du camp.",
		["{quest:90902}: the {npc:259377} lie around the church. Heal five of them with {spell:635}."] = "{quest:90902} : les {npc:259377} sont étendus autour de l'église. Soignez-en cinq avec {spell:635}.",
		["{quest:91208}: the {npc:246143} fled into the hills west of the church, on the way to {area:155}."] = "{quest:91208} : le {npc:246143} s'est enfui dans les collines à l'ouest de l'église, sur le chemin de {area:155}.",
		["{zone:1420}: kill these as you meet them"] = "{zone:1420} : tuez-les au passage",
} end)()
t.guides["forever/legacy/legacy-challenges"] = (function() return {
		["Adventure: explore the world map"] = "Aventure : explorer la carte du monde",
		["Adventure: {npc:16042}"] = "Aventure : {npc:16042}",
		["Adventure: {quest:8999} (Alliance)"] = "Aventure : {quest:8999} (Alliance)",
		["Adventure: {quest:9007} (Horde)"] = "Aventure : {quest:9007} (Horde)",
		["All 13 Hyjal Summit bosses are a point. Hyjal Summit is a new 20-player Forever raid at the top of {zone:2482}, near Nordrassil, open from 9 December; its bosses are not in our data, so tick it off once all 13 are down."] = "Les 13 boss du sommet d'Hyjal rapportent un point. Le sommet d'Hyjal est un nouveau raid de Forever à 20 joueurs au sommet de {zone:2482}, près de Nordrassil, ouvert à partir du 9 décembre ; ses boss sont absents de nos données, cochez-le donc une fois les 13 vaincus.",
		["All 8 Barrow Deeps bosses are a point. Barrow Deeps is a new 10-player Forever raid beneath {zone:2482}, entered from {zone:2482}, {zone:1452} or {area:1216} and open from 9 December; its bosses are not in our data, so tick it off once all 8 are down."] = "Les 8 boss de Barrow Deeps rapportent un point. Barrow Deeps est un nouveau raid de Forever à 10 joueurs sous {zone:2482}, accessible depuis {zone:2482}, {zone:1452} ou {area:1216} et ouvert à partir du 9 décembre ; ses boss sont absents de nos données, cochez-le donc une fois les 8 vaincus.",
		["City of Dalaran (Forever's, {zone:1416}): {npc:246020}"] = "Cité de Dalaran (celle de Forever, {zone:1416}) : {npc:246020}",
		["Classes give 27 points: every class reaching 25, 45 and 60. They count once per class across your account, so a second character of a class you already raised adds nothing; a new class does. The first character to reach 25 usually unlocks the Legacy System itself."] = "Les classes donnent 27 points : chaque classe atteignant les niveaux 25, 45 et 60. Elles comptent une fois par classe sur tout votre compte : un deuxième personnage d'une classe déjà montée n'ajoute rien, une nouvelle classe si. Le premier personnage à atteindre le niveau 25 débloque généralement le système d'Héritage lui-même.",
		["Classes: level 25"] = "Classes : niveau 25",
		["Classes: level 45"] = "Classes : niveau 45",
		["Classes: level 60"] = "Classes : niveau 60",
		["Dire Maul East"] = "Hache-tripes Est",
		["Dire Maul North"] = "Hache-tripes Nord",
		["Dire Maul West"] = "Hache-tripes Ouest",
		["Dungeons: level 15-25"] = "Donjons : niveau 15-25",
		["Dungeons: level 26-45"] = "Donjons : niveau 26-45",
		["Dungeons: level 46-60"] = "Donjons : niveau 46-60",
		["Each crafting profession gives 3 points, at 150, 225 and 300. Ranks count once per profession across your account. Follow the Polestar guide \"{skill:171} 1-300\" (Professions). A crafting profession at 150 also unlocks the Legacy System."] = "Chaque métier d'artisanat donne 3 points, à 150, 225 et 300. Les rangs comptent une fois par métier sur tout votre compte. Suivez le guide Polestar \"{skill:171} 1-300\" (Métiers). Un métier d'artisanat à 150 débloque aussi le système d'Héritage.",
		["Exalted with each of the four battleground factions is worth a point. Follow the Polestar Reputation guides Warsong Gulch Reputation, Arathi Basin Reputation, Alterac Valley Reputation and Darkspear Islands Reputation (Forever's new battleground, open from level 30). The Diplomat Legacy perk increases reputation gains."] = "Être exalté auprès de chacune des quatre factions de champ de bataille rapporte un point. Suivez les guides de réputation de Polestar : réputation du Goulet des Chanteguerres, du bassin Arathi, de la vallée d'Alterac et des îles Sombrelance (le nouveau champ de bataille de Forever, ouvert dès le niveau 30). L'avantage d'Héritage Diplomate augmente les gains de réputation.",
		["Exploring the entire world map on one character is a point, and it can also unlock the Legacy System. It must all be on the same character. Forever's new zones are part of the map: the {zone:2548}, {zone:2652} and {zone:2482}, a level 60 zone."] = "Explorer toute la carte du monde avec un personnage rapporte un point, et peut aussi débloquer le système d'Héritage. Tout doit être fait avec le même personnage. Les nouvelles zones de Forever font partie de la carte : {zone:2548}, {zone:2652} et {zone:2482}, une zone de niveau 60.",
		["Follow the Polestar Exploration guides: Exploration: Eastern Kingdoms 1-30, 30-45 and 45-60, and Exploration: Kalimdor 1-30, 30-45 and 45-60. They track every area as you discover it. Exploration: Zephras Isle covers the Skyborne island; whether its map counts towards this challenge is not confirmed yet."] = "Suivez les guides d'exploration de Polestar : Exploration : Royaumes de l'Est 1-30, 30-45 et 45-60, et Exploration : Kalimdor 1-30, 30-45 et 45-60. Ils suivent chaque lieu à mesure que vous le découvrez. Exploration : île de Zephras couvre l'île des Skyborne ; on ne sait pas encore si sa carte compte pour ce défi.",
		["Follow the Polestar guide \"{skill:164} 1-300\" (Professions)."] = "Suivez le guide Polestar \"{skill:164} 1-300\" (Métiers).",
		["Follow the Polestar guide \"{skill:165} 1-300\" (Professions)."] = "Suivez le guide Polestar \"{skill:165} 1-300\" (Métiers).",
		["Follow the Polestar guide \"{skill:197} 1-300\" (Professions)."] = "Suivez le guide Polestar \"{skill:197} 1-300\" (Métiers).",
		["Follow the Polestar guide \"{skill:202} 1-300\" (Professions)."] = "Suivez le guide Polestar \"{skill:202} 1-300\" (Métiers).",
		["Follow the Polestar guide \"{skill:333} 1-300\" (Professions)."] = "Suivez le guide Polestar \"{skill:333} 1-300\" (Métiers).",
		["Killing {npc:10184} is a point. {area:2159} is a 40-player raid in {zone:1445}, open from 9 December. Every raider needs the {item:16309} in the bags: the Alliance chain starts with Dragonkin Menace in the {zone:1428}, the Horde chain with Blood and Thunder in {area:340} ({zone:1418}); both end in Upper Blackrock Spire with {npc:10363}."] = "Tuer {npc:10184} rapporte un point. {area:2159} est un raid à 40 joueurs dans {zone:1445}, ouvert à partir du 9 décembre. Chaque membre du raid doit avoir {item:16309} dans ses sacs : la chaîne de l'Alliance commence par La menace des draconiens dans {zone:1428}, celle de la Horde par Blood and Thunder à {area:340} ({zone:1418}) ; les deux se terminent dans le pic Rochenoire supérieur avec {npc:10363}.",
		["Legacy Challenges"] = "Défis d'Héritage",
		["Level 45 with this character's class."] = "Niveau 45 avec la classe de ce personnage.",
		["Level 60 with this character's class."] = "Niveau 60 avec la classe de ce personnage.",
		["Lower {area:1583}"] = "Bas du {area:1583}",
		["PvP: Field of Honor"] = "JcJ : Champ d'honneur",
		["PvP: battleground reputations (Alliance)"] = "JcJ : réputations des champs de bataille (Alliance)",
		["PvP: battleground reputations (Horde)"] = "JcJ : réputations des champs de bataille (Horde)",
		["PvP: honor ranks"] = "JcJ : rangs d'honneur",
		["Raids: Barrow Deeps"] = "Raids : Barrow Deeps",
		["Raids: Hyjal Summit"] = "Raids : Hyjal Summit",
		["Raids: {npc:10184}"] = "Raids : {npc:10184}",
		["Ranks 3, 7, 10, 13 and 14 are a point each. Polestar cannot read your highest rank yet, so tick each one off yourself. Forever's honor rules for reaching a rank have not been published in detail; in Classic, ranks come from your weekly honor standing, and 13-14 take many weeks of top standing."] = "Les rangs 3, 7, 10, 13 et 14 valent un point chacun. Polestar ne peut pas encore lire votre rang le plus élevé : cochez-les vous-même. Les règles d'honneur de Forever pour atteindre un rang n'ont pas été publiées en détail ; dans Classic, les rangs dépendent de votre classement d'honneur hebdomadaire, et les rangs 13-14 demandent de nombreuses semaines en tête du classement.",
		["The Field of Honor PvP season has weekly journey quests; finishing the ones for weeks 4, 7 and 10 is a point each. These quests are new in Forever and not in our data, so tick each one off yourself."] = "La saison JcJ Champ d'honneur propose des quêtes de parcours hebdomadaires ; terminer celles des semaines 4, 7 et 10 vaut un point chacune. Ces quêtes sont nouvelles dans Forever et absentes de nos données : cochez-les vous-même.",
		["The final boss of every level 15-25 dungeon earns one point together. {area:2437} and Forever's {area:16919} (in {zone:1455}) count as one: either final boss does. Tick each boss off when you kill it, and check the in-game Legacy panel for the list."] = "Le dernier boss de chaque donjon de niveau 15-25 rapporte, tous ensemble, un point. {area:2437} et {area:16919} de Forever (à {zone:1455}) comptent pour un seul : l'un ou l'autre dernier boss suffit. Cochez chaque boss quand vous le tuez, et consultez la liste dans le panneau d'Héritage en jeu.",
		["The final boss of every level 26-45 dungeon earns one point together. The Drowned City and {area:17780} (in the {zone:2548}) are new in Forever and not in our data: tick them off yourself."] = "Le dernier boss de chaque donjon de niveau 26-45 rapporte, tous ensemble, un point. Drowned City et {area:17780} (dans {zone:2548}) sont nouveaux dans Forever et absents de nos données : cochez-les vous-même.",
		["The final boss of every level 46-60 dungeon earns one point together. Alcaz Prison, {area:1216} and the {area:16985} are new in Forever and not in our data: tick them off yourself."] = "Le dernier boss de chaque donjon de niveau 46-60 rapporte, tous ensemble, un point. Alcaz Prison, {area:1216} et {area:16985} sont nouveaux dans Forever et absents de nos données : cochez-les vous-même.",
		["The {npc:16042} questline is a point. It is the level 60 dungeon-set chain, from An Earnest Proposition to your class's {quest:8999}: {npc:16013} ({zone:1455}) or {npc:16012} ({zone:1454}) send you through In Search of Anthion and Anthion's Parting Words to {npc:16033} at {area:254}, whose Three Kings of Flame, the Left and Right Pieces of Lord Valthalak's Amulet, Final Preparations and {quest:8995} end with {quest:8996}. {quest:8997} then leads to {quest:8999}."] = "La suite de quêtes de {npc:16042} rapporte un point. C'est la chaîne des ensembles de donjon de niveau 60, d'Une proposition sérieuse jusqu'à {quest:8999} de votre classe : {npc:16013} ({zone:1455}) ou {npc:16012} ({zone:1454}) vous envoient, par À la recherche d'Anthion et Les adieux d'Anthion, jusqu'à {npc:16033} à {area:254}, dont Les trois rois des flammes, les fragments gauche et droit de l'amulette du seigneur Valthalak, Derniers préparatifs et {quest:8995} se terminent par {quest:8996}. {quest:8997} mène ensuite à {quest:8999}.",
		["This step cannot check the whole map by itself yet; it becomes a tracked goal once the Legacy achievement ids are recorded."] = "Cette étape ne peut pas encore vérifier toute la carte d'elle-même ; elle deviendra un objectif suivi une fois les identifiants des hauts faits d'Héritage enregistrés.",
		["Tradeskills: {skill:164}"] = "Métiers : {skill:164}",
		["Tradeskills: {skill:165}"] = "Métiers : {skill:165}",
		["Tradeskills: {skill:171}"] = "Métiers : {skill:171}",
		["Tradeskills: {skill:197}"] = "Métiers : {skill:197}",
		["Tradeskills: {skill:202}"] = "Métiers : {skill:202}",
		["Tradeskills: {skill:333}"] = "Métiers : {skill:333}",
		["Upper {area:1583}"] = "Haut du {area:1583}",
		["all 13 Hyjal Summit bosses"] = "les 13 boss du Sommet d’Hyjal",
		["all 8 Barrow Deeps bosses"] = "les 8 boss des Profondeurs des Tertres",
		["enemy players and finish the Field of Honor week 10 journey quest"] = "des joueurs ennemis et terminer la quête de parcours de la semaine 10 du Champ d'honneur",
		["enemy players and finish the Field of Honor week 4 journey quest"] = "des joueurs ennemis et terminer la quête de parcours de la semaine 4 du Champ d'honneur",
		["enemy players and finish the Field of Honor week 7 journey quest"] = "des joueurs ennemis et terminer la quête de parcours de la semaine 7 du Champ d'honneur",
		["enemy players for honor until PvP Rank 10"] = "des joueurs ennemis pour l'honneur jusqu'au rang JcJ 10",
		["enemy players for honor until PvP Rank 13"] = "des joueurs ennemis pour l'honneur jusqu'au rang JcJ 13",
		["enemy players for honor until PvP Rank 14"] = "des joueurs ennemis pour l'honneur jusqu'au rang JcJ 14",
		["enemy players for honor until PvP Rank 3"] = "des joueurs ennemis pour l'honneur jusqu'au rang JcJ 3",
		["enemy players for honor until PvP Rank 7"] = "des joueurs ennemis pour l'honneur jusqu'au rang JcJ 7",
		["the final boss of Alcaz Prison"] = "le dernier boss d'Alcaz Prison",
		["the final boss of the Drowned City"] = "le dernier boss de Drowned City",
		["the final boss of the {area:16985}"] = "le dernier boss de {area:16985}",
		["the final boss of {area:1216}"] = "le dernier boss de {area:1216}",
		["the final boss of {area:17780}"] = "le dernier boss de {area:17780}",
		["{area:153} (Forever's, {zone:1420}): {npc:256035}"] = "{area:153} (celles de Forever, {zone:1420}) : {npc:256035}",
		["{area:16919}: {npc:261319} (or {area:2437})"] = "{area:16919} : {npc:261319} (ou {area:2437})",
		["{area:17732} (Forever's): {npc:260326}"] = "{area:17732} (celui de Forever) : {npc:260326}",
		["{area:2279}, Live side"] = "{area:2279}, côté vivant",
		["{area:2279}, Undead side"] = "{area:2279}, côté mort-vivant",
		["{area:2437}: {npc:11519} (or {area:16919})"] = "{area:2437} : {npc:11519} (ou {area:16919})",
		["{area:718} (appears after the {npc:3678}'s event)"] = "{area:718} (apparaît après l'événement du {npc:3678})",
		["{area:796}: Armory"] = "{area:796} : armurerie",
		["{area:796}: Cathedral"] = "{area:796} : cathédrale",
		["{area:796}: Graveyard"] = "{area:796} : cimetière",
		["{area:796}: Library"] = "{area:796} : bibliothèque",
		["{npc:16012} then offers your class's {quest:9007}, the last quest of the challenge: it takes your class's dungeon-set helm and chest and upgrades them."] = "{npc:16012} propose ensuite {quest:9007} de votre classe, la dernière quête du défi : elle prend le casque et le plastron de l'ensemble de donjon de votre classe et les améliore.",
		["{npc:16013} then offers your class's {quest:8999}, the last quest of the challenge: it takes your class's dungeon-set helm and chest and upgrades them."] = "{npc:16013} propose ensuite {quest:8999} de votre classe, la dernière quête du défi : elle prend le casque et le plastron de l'ensemble de donjon de votre classe et les améliore.",
		["{npc:16033} offers it once {quest:8996} is turned in"] = "{npc:16033} la propose une fois {quest:8996} rendue",
		["{npc:16073}, inside Upper Blackrock Spire after Mea Culpa (no spawn in the data: the arrow leads to {npc:16033}'s {area:254})"] = "{npc:16073}, dans le haut du Pic Rochenoire après Mea culpa (aucun point d'apparition dans les données : la flèche mène à {npc:16033}, au {area:254})",
} end)()
t.guides["forever/miscellaneous/cozy-sleeping-bag"] = (function() return {
		["A hundred paces north"] = "Cent pas vers le nord",
		["A trail of hidden notes across both continents: the {item:211527} at the end, a 12-slot {item:221498} on the way."] = "Une piste de notes cachées sur les deux continents : {item:211527} au bout, et {item:221498} de 12 emplacements en chemin.",
		["Careful: off the dam's ledge you land in the river below it, in the {zone:1437}. Climb out on its west bank well before the waterfall at about 65,77: the fall kills. Then head north-west to the road and follow it north over {area:880} into Arathi.\nAt the gate in {area:1057} between Arathi and {area:287}, turn north and follow the wall on the {area:287} side to a fallen cart leaning against it. Jump up the cart and its ladder onto the wall, then over the rocks to the hidden camp. Some characters cannot fit under the cargo netting at the camp; another race or a smaller form gets through."] = "Attention : depuis la corniche du barrage, vous tombez dans la rivière en contrebas, dans les {zone:1437}. Sortez-en par la rive ouest bien avant la cascade, vers 65,77 : la chute est mortelle. Partez ensuite vers le nord-ouest jusqu'à la route et suivez-la vers le nord par {area:880} jusqu'en Arathi.\nÀ la porte de {area:1057}, entre Arathi et {area:287}, tournez vers le nord et suivez le mur côté {area:287} jusqu'à une charrette renversée appuyée contre lui. Sautez sur la charrette et son échelle pour monter sur le mur, puis passez par les rochers jusqu'au camp caché. Certains personnages ne passent pas sous le filet de chargement du camp ; une autre race ou une forme plus petite passe.",
		["Fallen cart"] = "Charrette renversée",
		["Its twin in the {zone:1413}"] = "Sa jumelle dans {zone:1413}",
		["Its twin in {zone:1436}"] = "Sa jumelle dans {zone:1436}",
		["North of Honor's Stand"] = "Au nord d'Honor's Stand",
		["Path into the hills"] = "Sentier vers les collines",
		["Round {area:1702}"] = "Contourner {area:1702}",
		["The chain opens at level 14. A burned-out campfire in the southern {zone:1413}, with a nailed plank beside it."] = "La chaîne s'ouvre au niveau 14. Un feu de camp éteint dans le sud de {zone:1413}, avec une planche clouée à côté.",
		["The chain opens at level 14. A burned-out campfire in western {zone:1436}, with a nailed plank beside it."] = "La chaîne s'ouvre au niveau 14. Un feu de camp éteint dans l'ouest de {zone:1436}, avec une planche clouée à côté.",
		["The dam in {zone:1432}"] = "Le barrage du {zone:1432}",
		["The figurine is on a ledge just below the top of the {area:146}, on its north face. Step off slowly; walking backwards keeps you from overshooting the ledge."] = "La figurine se trouve sur une corniche juste sous le sommet de {area:146}, sur sa face nord. Descendez lentement ; marcher à reculons évite de dépasser la corniche.",
		["The hidden camp"] = "Le camp caché",
		["The next hideout is a small camp in the hills north-west of {area:460}, in the middle of the {zone:1442}. Leave the road where a path climbs west into the hills and follow it to the camp; the {object:424005} lies on a crate beside its tent."] = "La cachette suivante est un petit camp dans les collines au nord-ouest de {area:460}, au milieu de {zone:1442}. Quittez la route là où un sentier monte vers l'ouest dans les collines et suivez-le jusqu'au camp ; {object:424005} est posé sur une caisse à côté de la tente.",
		["The note in the {zone:1413}"] = "La note de {zone:1413}",
		["The note in {zone:1436}"] = "La note de {zone:1436}",
		["The note's \"twin land\" is the {zone:1413}: the same burned-out campfire stands in the southern {zone:1413}."] = "La \"terre jumelle\" de la note, c'est {zone:1413} : le même feu de camp éteint se trouve dans le sud de {zone:1413}.",
		["The note's \"twin land\" is {zone:1436}: the same burned-out campfire stands in western {zone:1436}."] = "La \"terre jumelle\" de la note, c'est {zone:1436} : le même feu de camp éteint se trouve dans l'ouest de {zone:1436}.",
		["The road west runs through {area:1702}, a Horde post; this way goes round it."] = "La route vers l'ouest traverse {area:1702}, un poste de la Horde ; ce chemin le contourne.",
		["Walk north through the camp and drop carefully down the steep slope to the {object:424012} on the ledge below. A missed jump only slides you down: hug the cliff and walk back up."] = "Traversez le camp vers le nord et descendez prudemment la pente raide jusqu'au {object:424012} sur la corniche en contrebas. Un saut raté vous fait seulement glisser : longez la falaise et remontez à pied.",
} end)()
t.guides["forever/miscellaneous/library-books"] = (function() return {
		["At {area:118}, the dig in the middle of the {zone:1437}."] = "À {area:118}, le chantier de fouilles au milieu de la zone ({zone:1437}).",
		["At {area:233}, the mage village in south-eastern Silverpine."] = "À {area:233}, le village de mages au sud-est de la forêt des Pins-Argentés.",
		["Beside a tent entrance in the troll village in south-eastern Arathi."] = "À côté de l'entrée d'une tente du village troll, au sud-est d'Arathi.",
		["Cave mouth at {area:387}"] = "Entrée de la grotte à {area:387}",
		["Down the stairs at the {area:443} in northern {zone:1439}."] = "En bas des escaliers de {area:443}, dans le nord de {zone:1439}.",
		["Eight more books lie in level 55-60 zones; the mage trainers beside the librarians take them, not the librarians. {item:228141} lies on a table in the ruined keep on {area:2298}, above {area:2057} (outside the dungeon); {item:228132} at {area:199}."] = "Huit autres livres se trouvent dans des zones de niveau 55-60 ; ce sont les maîtres des mages à côté des bibliothécaires qui les prennent, pas les bibliothécaires. {item:228141} est posé sur une table du donjon en ruine de {area:2298}, au-dessus de {area:2057} (hors du donjon) ; {item:228132} à {area:199}.",
		["From level 20, with 20 different books handed in, {npc:211033} offers {quest:79536}: {item:281634} or {item:281635}."] = "À partir du niveau 20, une fois 20 livres différents rendus, {npc:211033} propose {quest:79536} : {item:281634} ou {item:281635}.",
		["From level 35, with 25 different books handed in, {npc:211033} offers the second {quest:79536}: {item:277254}, {item:277258} or {item:277260} (level 40 to equip)."] = "À partir du niveau 35, une fois 25 livres différents rendus, {npc:211033} propose la deuxième {quest:79536} : {item:277254}, {item:277258} ou {item:277260} (niveau 40 pour l'équiper).",
		["Halfway up the {area:91}, east of {area:87}. Nothing hostile inside."] = "À mi-hauteur de {area:91}, à l'est de {area:87}. Rien d'hostile à l'intérieur.",
		["Hand in the books so far. {npc:211022} keeps the library in the {object:36082}. He offers each book's quest while the book is in your bags: take it and hand it in, one at a time, so your quest log stays free. Skip the books you did not find."] = "Rendez les livres trouvés jusqu'ici. {npc:211022} tient la bibliothèque dans {object:36082}. Il propose la quête de chaque livre tant que le livre est dans vos sacs : acceptez-la et rendez-la, une à la fois, pour garder votre journal de quêtes libre. Ignorez les livres que vous n'avez pas trouvés.",
		["Hand in the books so far. {npc:211033} keeps the library at the top of the Wizard's Sanctum in the {object:2101}. He offers each book's quest while the book is in your bags: take it and hand it in, one at a time, so your quest log stays free. Skip the books you did not find."] = "Rendez les livres trouvés jusqu'ici. {npc:211033} tient la bibliothèque au sommet du Sanctum des sorciers, dans {object:2101}. Il propose la quête de chaque livre tant que le livre est dans vos sacs : acceptez-la et rendez-la, une à la fois, pour garder votre journal de quêtes libre. Ignorez les livres que vous n'avez pas trouvés.",
		["Hand in this part's books. {npc:211022} keeps the library in the {object:36082}. He offers each book's quest while the book is in your bags: take it and hand it in, one at a time, so your quest log stays free. Skip the books you did not find."] = "Rendez les livres de cette partie. {npc:211022} tient la bibliothèque dans {object:36082}. Il propose la quête de chaque livre tant que le livre est dans vos sacs : acceptez-la et rendez-la, une à la fois, pour garder votre journal de quêtes libre. Ignorez les livres que vous n'avez pas trouvés.",
		["Hand in this part's books. {npc:211033} keeps the library at the top of the Wizard's Sanctum in the {object:2101}. He offers each book's quest while the book is in your bags: take it and hand it in, one at a time, so your quest log stays free. Skip the books you did not find."] = "Rendez les livres de cette partie. {npc:211033} tient la bibliothèque au sommet du Sanctum des sorciers, dans {object:2101}. Il propose la quête de chaque livre tant que le livre est dans vos sacs : acceptez-la et rendez-la, une à la fois, pour garder votre journal de quêtes libre. Ignorez les livres que vous n'avez pas trouvés.",
		["In the troll ruins of {area:353}, in the south of the {zone:1425}."] = "Dans les ruines trolls de {area:353}, dans le sud de la zone ({zone:1425}).",
		["Inside a crypt near the middle of the zone, reached from the path to its south."] = "Dans une crypte près du centre de la zone, accessible par le sentier au sud.",
		["Inside a hut on the {area:2097} mesa."] = "Dans une hutte sur le plateau de {area:2097}.",
		["Inside the first tower of the ogre fort at {area:1357}, in the middle of the zone."] = "Dans la première tour du fort des ogres de {area:1357}, au milieu de la zone.",
		["Inside {area:254}, not in a dungeon: the book lies on the altar in {npc:8888}'s tomb, near {npc:14387}. The waypoint marks the mountain."] = "Dans {area:254}, pas dans un donjon : le livre repose sur l'autel du tombeau de {npc:8888}, près de {npc:14387}. Le point de passage marque la montagne.",
		["Level 60 books: {area:1769}"] = "Livres de niveau 60 : {area:1769}",
		["Level 60 books: {area:2255}"] = "Livres de niveau 60 : {area:2255}",
		["Level 60 books: {area:254}"] = "Livres de niveau 60 : {area:254}",
		["Level 60 books: {zone:1422}"] = "Livres de niveau 60 : {zone:1422}",
		["Level 60 books: {zone:1423}"] = "Livres de niveau 60 : {zone:1423}",
		["Library Books"] = "Livres de la bibliothèque",
		["Lost books and scrolls all over the world: each pays experience at the library, and 10, 20 and 25 of them earn a necklace, a ring and an off-hand."] = "Des livres et parchemins perdus aux quatre coins du monde : chacun rapporte de l'expérience à la bibliothèque, et 10, 20 et 25 d'entre eux vous valent un collier, un anneau et un objet tenu en main gauche.",
		["On a barrel in a tent at {area:2537}, in the far south-east of the zone."] = "Sur un tonneau dans une tente de {area:2537}, tout au sud-est de la zone.",
		["On a bench beside the {area:310} entrance, in the middle of the zone."] = "Sur un banc à côté de l'entrée de {area:310}, au milieu de la zone.",
		["On a bookshelf in the middle building of the pirate camp on the eastern coast."] = "Sur une bibliothèque dans le bâtiment central du camp pirate de la côte est.",
		["On a crate in the {area:1236}, in the far west of {zone:1447}."] = "Sur une caisse dans {area:1236}, tout à l'ouest d'{zone:1447}.",
		["On a shelf in {area:159}'s apothecary."] = "Sur une étagère de la boutique d'apothicaire de {area:159}.",
		["On a table inside a tent near the middle of the zone."] = "Sur une table dans une tente près du centre de la zone.",
		["On the ground at the eastern side of the murloc camp in north-eastern Dustwallow."] = "Au sol, du côté est du camp murloc au nord-est du marécage d'Âprefange.",
		["On the top walkway of the {area:1477}, outside the dungeon."] = "Sur la passerelle supérieure de {area:1477}, à l'extérieur du donjon.",
		["Rumi of Gnomeregan"] = "Rumi de Gnomeregan",
		["Scrolls in the Mo'grosh ogre cave in the north-east. The ogres in the cave are level 18-19 elites: grouping up is advised. (Rumi of Gnomeregan also lies in {area:144}, if you missed it at {area:108}.)"] = "Des parchemins dans la grotte des ogres Mo'grosh, au nord-est. Les ogres de la grotte sont des élites de niveau 18-19 : il est conseillé de se grouper. (Rumi de Gnomeregan se trouve aussi à {area:144}, si vous l'avez manqué à {area:108}.)",
		["The level 60 books: {npc:5497}"] = "Les livres de niveau 60 : {npc:5497}",
		["The level 60 books: {npc:7825}"] = "Les livres de niveau 60 : {npc:7825}",
		["The library: first books"] = "La bibliothèque : premiers livres",
		["The library: first books (Horde)"] = "La bibliothèque : premiers livres (Horde)",
		["The library: second books"] = "La bibliothèque : deuxièmes livres",
		["The library: second books (Horde)"] = "La bibliothèque : deuxièmes livres (Horde)",
		["The library: third books"] = "La bibliothèque : troisièmes livres",
		["The library: third books (Horde)"] = "La bibliothèque : troisièmes livres (Horde)",
		["The scrolls lie underground, in the cave below {area:387} by the {area:718} entrance, not inside the dungeon. Go in at the cave mouth in the oasis and follow the cave down; the arrow points at the scrolls from the surface."] = "Les parchemins se trouvent sous terre, dans la grotte sous {area:387} près de l'entrée de {area:718}, pas dans le donjon. Entrez par l'entrée de la grotte dans l'oasis et descendez la grotte ; la flèche indique les parchemins depuis la surface.",
		["The second {quest:79536}"] = "La deuxième {quest:79536}",
		["The spellbook lies in the {area:2098}, the crypt in north-western {zone:1431}. Undead fill it; a corpse run works if you are low."] = "Le grimoire se trouve dans {area:2098}, la crypte au nord-ouest de {zone:1431}. Elle est remplie de morts-vivants ; si votre niveau est bas, un aller-retour en fantôme fait l'affaire.",
		["The {area:718}' cave"] = "La grotte de {area:718}",
		["The {object:405149} is the stone tablet leaning against the wall in the {object:172961}, on the way to the mage trainers. Use it to take the book."] = "Le {object:405149} est la tablette de pierre appuyée contre le mur dans {object:172961}, sur le chemin des maîtres des mages. Utilisez-la pour prendre le livre.",
		["Two books: one in a house at {area:20}, one at {area:108} (Alliance only)."] = "Deux livres : l'un dans une maison de {area:20}, l'autre à {area:108} (Alliance uniquement).",
		["With 10 different books handed in, the librarian offers {quest:78150}: a choice of two necklaces ({item:277203} or {item:277204}). Take it when it appears."] = "Une fois 10 livres différents rendus, le bibliothécaire propose {quest:78150} : un choix entre deux colliers ({item:277203} ou {item:277204}). Acceptez-la quand elle apparaît.",
		["{item:228134} lies inside the {area:1769} tunnel between {zone:1448} and {zone:1452}."] = "{item:228134} se trouve dans le tunnel de {area:1769}, entre {zone:1448} et {zone:1452}.",
		["{item:228135} is inside {area:2268}. {item:228138} lies at {area:2264}; other copies lie elsewhere in the zone (one by the {area:2279} gates), and you can take only one. {item:228140} is on a table in {area:2277}: wait for the patrolling elite to clear the creatures beside it and walk on."] = "{item:228135} se trouve dans {area:2268}. {item:228138} se trouve à {area:2264} ; d'autres exemplaires sont ailleurs dans la zone (un près des portes de {area:2279}), et vous ne pouvez en prendre qu'un. {item:228140} est sur une table à {area:2277} : attendez que l'élite qui patrouille élimine les créatures à côté et poursuive son chemin.",
		["{item:228136} sits on a shelf behind the alchemy supplier in {area:2255}."] = "{item:228136} est posé sur une étagère derrière le fournisseur d'alchimie de {area:2255}.",
		["{npc:5497}, the mage trainer beside {npc:211033} in the Wizard's Sanctum, takes the level 60 books: she offers each book's quest while the book is in your bags. Hand in {item:228132}, {item:228138} and {item:228140} the same way (their quests are not in Polestar's data yet)."] = "{npc:5497}, la maîtresse des mages à côté de {npc:211033} dans le Sanctum des sorciers, prend les livres de niveau 60 : elle propose la quête de chaque livre tant que le livre est dans vos sacs. Rendez {item:228132}, {item:228138} et {item:228140} de la même façon (leurs quêtes ne sont pas encore dans les données de Polestar).",
		["{npc:7825}, beside {npc:211022} in the {object:36082}, takes the level 60 books: each book's quest is offered while the book is in your bags. Take and hand them in one at a time (Polestar cannot track these quests for the Horde yet)."] = "{npc:7825}, à côté de {npc:211022} dans {object:36082}, prend les livres de niveau 60 : la quête de chaque livre est proposée tant que le livre est dans vos sacs. Acceptez-les et rendez-les une à la fois (Polestar ne peut pas encore suivre ces quêtes pour la Horde).",
} end)()
t.guides["forever/miscellaneous/stalk-with-the-earthmother"] = (function() return {
		["Back to {npc:205729} in {zone:1456}. He gives you the {item:206176} for his next test."] = "Retournez voir {npc:205729} aux {zone:1456}. Il vous donne le {item:206176} pour son épreuve suivante.",
		["Windfury Cones"] = "Cônes Furie-des-vents",
		["Windfury Cones lie on the ground under the harpies' nest trees on {area:819}, north-west of {zone:1456}; the harpies do not drop them. The Windfury Sorceresses (level 9-10) and Matriarchs (10-11) there stand close together: pick the cones from the edges. Once you have eight, use the {item:206176} to grind them."] = "Les Cônes Furie-des-vents gisent au sol sous les arbres à nids des harpies, sur la {area:819}, au nord-ouest des {zone:1456} ; les harpies n'en lâchent pas. Les Ensorceleuses (niveau 9-10) et les Matriarches (10-11) Furie-des-vents s'y tiennent serrées : ramassez les cônes sur les bords. Une fois que vous en avez huit, utilisez le {item:206176} pour les broyer.",
} end)()
