		["{npc:14903}: {item:19598}, Honored"] = "{npc:14903} : {item:19598}, Honoré",
		["{npc:14903}: {item:19599}, Revered"] = "{npc:14903} : {item:19599}, Révéré",
		["{npc:14903}: {item:19600}, Exalted"] = "{npc:14903} : {item:19600}, Exalté",
		["{npc:14903}: {quest:8049}, Friendly"] = "{npc:14903} : {quest:8049}, Amical",
		["{npc:14903}: {quest:8049}, Honored"] = "{npc:14903} : {quest:8049}, Honoré",
		["{npc:14903}: {quest:8050}, Revered"] = "{npc:14903} : {quest:8050}, Révéré",
		["{npc:14903}: {quest:8051}, Exalted"] = "{npc:14903} : {quest:8051}, Exalté",
		["{npc:14903}: {quest:8106}, Friendly"] = "{npc:14903} : {quest:8106}, Amical",
		["{npc:14903}: {quest:8106}, Honored"] = "{npc:14903} : {quest:8106}, Honoré",
		["{npc:14903}: {quest:8107}, Revered"] = "{npc:14903} : {quest:8107}, Révéré",
		["{npc:14903}: {quest:8108}, Exalted"] = "{npc:14903} : {quest:8108}, Exalté",
		["{npc:14904}: {quest:8110}, Friendly"] = "{npc:14904} : {quest:8110}, Amical",
		["{npc:14904}: {quest:8110}, Honored"] = "{npc:14904} : {quest:8110}, Honoré",
		["{npc:14904}: {quest:8111}, Revered"] = "{npc:14904} : {quest:8111}, Révéré",
		["{npc:14904}: {quest:8112}, Exalted"] = "{npc:14904} : {quest:8112}, Exalté",
		["{npc:14904}: {quest:8116}, Friendly"] = "{npc:14904} : {quest:8116}, Amical",
		["{npc:14904}: {quest:8116}, Honored"] = "{npc:14904} : {quest:8116}, Honoré",
		["{npc:14904}: {quest:8117}, Revered"] = "{npc:14904} : {quest:8117}, Révéré",
		["{npc:14904}: {quest:8118}, Exalted"] = "{npc:14904} : {quest:8118}, Exalté",
		["{npc:14905}: {item:19618}, Friendly"] = "{npc:14905} : {item:19618}, Amical",
		["{npc:14905}: {item:19618}, Honored"] = "{npc:14905} : {item:19618}, Honoré",
		["{npc:14905}: {item:19619}, Revered"] = "{npc:14905} : {item:19619}, Révéré",
		["{npc:14905}: {item:19620}, Exalted"] = "{npc:14905} : {item:19620}, Exalté",
		["{npc:14905}: {quest:8141}, Friendly"] = "{npc:14905} : {quest:8141}, Amical",
		["{npc:14905}: {quest:8141}, Honored"] = "{npc:14905} : {quest:8141}, Honoré",
		["{npc:14905}: {quest:8142}, Revered"] = "{npc:14905} : {quest:8142}, Révéré",
		["{npc:14905}: {quest:8143}, Exalted"] = "{npc:14905} : {quest:8143}, Exalté",
		["{npc:15042} takes an {item:18331}, Rapidity or Focus for the {item:22635} head and leg enchant: 200 reputation each, again and again. The Arcanum binds to you, so it never sells: {npc:14368} in the library of {area:2577} makes it from the matching Libram ({area:2577} drops, and on the auction house), a {item:18335} and Large Brilliant Shards, plus {item:12735}, two {item:12938} or two {item:12753}. {npc:14921} trades {quest:8196} for an Honor Token."] = "{npc:15042} prend un {item:18331}, de rapidité ou de focalisation contre l'enchantement de tête et de jambes de la {item:22635} : 200 de réputation chacun, encore et encore. L'arcanum est lié à vous et ne se vend donc jamais : {npc:14368}, dans la bibliothèque de {area:2577}, le fabrique à partir du libram correspondant (butin de {area:2577}, et à l'hôtel des ventes), d'un {item:18335} et de grands éclats brillants, plus {item:12735}, deux {item:12938} ou deux {item:12753}. {npc:14921} échange {quest:8196} contre une marque d'honneur.",
		["{npc:15042}'s enchants, from Friendly"] = "Les enchantements de {npc:15042}, dès Amical",
		["{npc:15042}'s head and leg enchants, from Friendly"] = "Les enchantements de tête et de jambes de {npc:15042}, dès Amical",
		["{npc:15042}, a spirit just inside {area:19}'s entrance, trades your class's head and leg enchant for a {item:22637} ({npc:11380} or {npc:11382}, about 90%) and your class's {item:19813} (the Jinxed Hoodoo Piles scattered through {area:19}, now and then from its trash): 100 reputation each, as often as you like."] = "{npc:15042}, un esprit juste après l'entrée de {area:19}, échange l'enchantement de tête et de jambes de votre classe contre une {item:22637} ({npc:11380} ou {npc:11382}, environ 90 %) et la {item:19813} de votre classe (les piles de déchets ensorcelées éparpillées dans {area:19}, et parfois les monstres de base) : 100 de réputation chacun, autant de fois que vous voulez.",
		["{npc:15042}: idol and doll, 100"] = "{npc:15042} : idole et poupée, 100",
		["{npc:15070}: 3 coins, 25 and a token"] = "{npc:15070} : 3 pièces, 25 et une marque",
		["{quest:8196}: one {item:19858}"] = "{quest:8196} : une {item:19858}",
		["{quest:8243}: one token"] = "{quest:8243} : une marque",
		["{quest:8246}: 15 Honor Tokens"] = "{quest:8246} : 15 marques d'honneur",
} end)()

Polestar.RegisterGuideTexts("frFR", "guides", t)
